window.PROTO = {"generated": "2026-09-28", "taxonomy": {"fields": [{"id": "score", "en": "Scores & Instructions", "zh": "乐谱与指令", "desc_en": "The artist writes instructions; other people carry them out, and each execution is the work. From telephone paintings and Fluxus event scores to Sol LeWitt's wall drawings.", "desc_zh": "艺术家写下指令，由别人去执行，每一次执行就是作品本身。从电话绘画、激浪派事件乐谱到索尔·勒维特的墙绘。", "subs": [{"id": "execution", "en": "Instructions for Execution", "zh": "交由他人执行的指令", "desc_en": "Works that exist as a set of instructions and are made, again and again, by assistants, owners or institutions.", "desc_zh": "以一组指令的形式存在、由助手、藏家或机构一次次制作出来的作品。"}, {"id": "event-scores", "en": "Event Scores & Fluxus", "zh": "事件乐谱与激浪派", "desc_en": "Short written scores for actions and events that anyone can perform.", "desc_zh": "写给行动和事件的简短乐谱，任何人都可以表演。"}, {"id": "public-instructions", "en": "Instructions for the Public", "zh": "写给公众的指令", "desc_en": "Instructions addressed to readers, visitors and strangers, who become the performers.", "desc_zh": "写给读者、观众和陌生人的指令，他们因此成为表演者。"}, {"id": "constraints", "en": "Constraints, Chance & Games", "zh": "约束、偶然与游戏", "desc_en": "Rule systems, constraints and chance procedures that generate outcomes the author does not control.", "desc_zh": "生成作者无法控制之结果的规则系统、约束和偶然程序。"}]}, {"id": "social", "en": "Social Protocols & Economies", "zh": "社会协议与另类经济", "desc_en": "Rules for groups, exchanges and contracts in physical space: social sculpture, performance protocols, mail-art networks and artist-made economies.", "desc_zh": "在物理空间中为群体、交换与契约设计的规则：社会雕塑、表演协议、邮件艺术网络，以及艺术家设计的经济。", "subs": [{"id": "collective-action", "en": "Social Sculpture & Collective Action", "zh": "社会雕塑与集体行动", "desc_en": "Works made by many people acting together under one rule: planting, walking, moving, gathering.", "desc_zh": "由许多人在同一条规则下共同行动而完成的作品：种树、行走、搬运、聚集。"}, {"id": "performance", "en": "Performance Protocols", "zh": "表演协议", "desc_en": "Performances where the audience's actions, bounded by the artist's rules, make the piece.", "desc_zh": "观众在艺术家规则之内的行动构成作品的表演。"}, {"id": "correspondence", "en": "Mail Art & Correspondence Networks", "zh": "邮件艺术与通信网络", "desc_en": "Artworks that travel through the post and grow as each recipient adds to them and sends them on.", "desc_zh": "通过邮政流转、每个收件人添加内容再寄出而不断生长的作品。"}, {"id": "economies", "en": "Contracts, Currencies & Exchange", "zh": "契约、货币与交换", "desc_en": "Artist-designed contracts, receipts, currencies and exchange rituals: the pre-blockchain ancestors of tokens and royalties.", "desc_zh": "艺术家设计的契约、收据、货币与交换仪式：代币和版税在区块链出现之前的前身。"}]}, {"id": "network", "en": "Network & Crowd Protocols", "zh": "网络与群体协议", "desc_en": "Rules posted to a network and played by thousands or millions of people: telematic art, crowdsourced works and collective online experiments.", "desc_zh": "发布到网络上、由成千上万人参与的规则：远程通信艺术、众包作品和集体网络实验。", "subs": [{"id": "telematic", "en": "Telematic & Early Network Art", "zh": "远程通信与早期网络艺术", "desc_en": "Works for modems, bulletin boards, robots and the early web that let distant participants act together.", "desc_zh": "为调制解调器、电子公告板、机器人和早期网络而作，让远方的参与者共同行动的作品。"}, {"id": "crowdsourced", "en": "Crowdsourced Works", "zh": "众包作品", "desc_en": "An assignment or task sent to a crowd; the collected responses are the work.", "desc_zh": "把一个任务派发给人群，收集到的回应就是作品。"}, {"id": "collective-games", "en": "Collective Canvases & Games", "zh": "集体画布与游戏", "desc_en": "Shared canvases, buttons and games where one simple rule meets a very large crowd.", "desc_zh": "共享画布、按钮和游戏：一条简单的规则遇上非常庞大的人群。"}, {"id": "open-infrastructure", "en": "Open Infrastructure & Commons", "zh": "开放基础设施与公地", "desc_en": "Artist-built infrastructures, file drops and commons that strangers maintain and use.", "desc_zh": "由艺术家搭建、由陌生人维护和使用的基础设施、文件投放点与公地。"}]}, {"id": "onchain", "en": "Smart-Contract Art", "zh": "智能合约艺术", "desc_en": "Artworks whose rules run in a smart contract: supply, burning, merging, transfer, taxes and co-authorship enforced on-chain, and shaped by what collectors do.", "desc_zh": "规则运行在智能合约里的作品：供应、销毁、合并、转移、税费与共同创作都在链上执行，并由藏家的行为塑造。", "subs": [{"id": "supply", "en": "Supply, Burn & Merge", "zh": "供应、销毁与合并", "desc_en": "Open editions, burning, merging and composites: the final form is set by how many people buy, burn or combine.", "desc_zh": "开放版数、销毁、合并与合成：最终形态取决于多少人购买、销毁或组合。"}, {"id": "ownership", "en": "Ownership & Transfer Rules", "zh": "所有权与转移规则", "desc_en": "Contracts that change what owning means: always for sale, must be passed on, dies if held, changes with its owner.", "desc_zh": "改变“拥有”含义的合约：永远在售、必须转手、持有即死亡、随持有者而改变。"}, {"id": "co-authored", "en": "Programmable & Co-authored Works", "zh": "可编程与共同创作的作品", "desc_en": "Works whose layers, parameters or worlds are written by their holders and by the community that builds on them.", "desc_zh": "图层、参数或世界由持有者和在其上继续创作的社区写成的作品。"}, {"id": "provenance", "en": "Early Tokens & Provenance", "zh": "早期代币与来源", "desc_en": "The first crypto-art tokens, registries and claim mechanics, before the 2021 boom.", "desc_zh": "2021 年热潮之前最早的加密艺术代币、登记簿和认领机制。"}]}, {"id": "autonomous", "en": "Autonomous Entities & DAOs", "zh": "自治实体与 DAO", "desc_en": "Artworks that own themselves, reproduce, or are governed by their community: self-owning forests, blockchain life forms, autonomous artists and art DAOs.", "desc_zh": "拥有自己、自我繁殖或由社区治理的作品：自我拥有的森林、区块链生命形式、自治艺术家与艺术 DAO。", "subs": [{"id": "self-owning", "en": "Self-owning Life & Nature", "zh": "自我拥有的生命与自然", "desc_en": "Forests, plants and life forms that hold their own money, sell their own output and reproduce through contracts.", "desc_zh": "持有自己的钱、出售自己的产出、通过合约繁殖的森林、植物与生命形式。"}, {"id": "autonomous-artists", "en": "Autonomous & Collective Artists", "zh": "自治与集体艺术家", "desc_en": "Artist identities run by a machine and a voting community, or licensed to the public under community rules.", "desc_zh": "由机器和投票社区运行、或在社区规则下向公众授权的艺术家身份。"}, {"id": "dao", "en": "DAOs & Collective Governance", "zh": "DAO 与集体治理", "desc_en": "Art projects where token holders vote, fund and decide: daily auctions, artist careers run by shareholders, collective purchases.", "desc_zh": "代币持有者投票、出资和决策的艺术项目：每日拍卖、由股东决定的艺术生涯、集体收购。"}]}, {"id": "theory", "en": "Theory & Texts", "zh": "理论与文本", "desc_en": "Books, essays and research programmes that define protocols, systems and participation in art.", "desc_zh": "界定艺术中的协议、系统与参与的书籍、文章与研究计划。", "subs": [{"id": "systems", "en": "Systems & Protocol Theory", "zh": "系统与协议理论", "desc_en": "Texts on systems aesthetics, protocols and control in networks.", "desc_zh": "关于系统美学、协议与网络中控制的文本。"}, {"id": "participation", "en": "Participation & Relational Art", "zh": "参与与关系艺术", "desc_en": "Texts on participatory, relational and social practice art.", "desc_zh": "关于参与式艺术、关系艺术和社会实践艺术的文本。"}, {"id": "crypto-theory", "en": "Crypto Art & Protocol Research", "zh": "加密艺术与协议研究", "desc_en": "Books, anthologies and research programmes on blockchain art, DAOs and protocols.", "desc_zh": "关于区块链艺术、DAO 与协议的书籍、文集和研究计划。"}]}], "mechanisms": [["instruction", "Instruction & score", "指令与乐谱"], ["participation", "Open participation", "开放参与"], ["constraint", "Rules & constraints", "规则与约束"], ["chance", "Chance & randomness", "偶然与随机"], ["circulation", "Circulation & passing on", "流转与传递"], ["exchange", "Market & exchange", "市场与交换"], ["currency", "Currency & value", "货币与价值"], ["contract", "Contract & certificate", "契约与证书"], ["scarcity", "Supply & scarcity", "供应与稀缺"], ["burn", "Burn & destruction", "销毁"], ["merge", "Merge & composite", "合并与合成"], ["co-authorship", "Co-authorship & derivatives", "共同创作与衍生"], ["governance", "Voting & governance", "投票与治理"], ["autonomy", "Self-ownership & autonomy", "自我拥有与自治"], ["time", "Time, decay & death", "时间、衰变与死亡"]], "substrates": [["text", "Text & paper", "文本与纸面"], ["body", "Bodies & space", "身体与空间"], ["post", "Post & mail", "邮政"], ["network", "Internet & platforms", "互联网与平台"], ["bitcoin", "Bitcoin & Counterparty", "比特币与 Counterparty"], ["ethereum", "Ethereum & L2s", "以太坊与二层网络"], ["tezos", "Tezos", "Tezos"], ["other-chain", "Other chains", "其他链"], ["ai", "AI & machine", "人工智能与机器"]], "kinds": [["artwork", "Artwork", "艺术作品"], ["score", "Score & instruction set", "乐谱与指令集"], ["series", "Series & collection", "系列与合集"], ["platform", "Platform & protocol", "平台与协议"], ["game", "Game & experiment", "游戏与实验"], ["organization", "DAO & organization", "DAO 与组织"], ["publication", "Book & essay", "书与文章"]], "collections": [{"id": "the-scores-project", "type": "survey", "en": "The Scores Project", "zh": "《乐谱计划》", "desc_en": "Open-access book edited by Michael Gallope, Natilee Harren and John Hicks (Getty Research Institute, 2025): eleven essays on experimental notation in music, art, poetry and dance, 1950–1975, from Feldman and Cage to Brecht, Knowles, Shiomi and Kaprow.", "desc_zh": "由 Michael Gallope、Natilee Harren 与 John Hicks 编辑的开放获取书籍（盖蒂研究所，2025）：十一篇文章讨论 1950—1975 年间音乐、艺术、诗歌与舞蹈中的实验记谱，从费尔德曼、凯奇到布雷希特、诺尔斯、盐见允枝子和卡普罗。", "url": "https://www.getty.edu/publications/scores/"}]}, "creators": [{"id": "async-art", "links": {"site": "https://async.art", "x": "https://x.com/asyncart"}, "connected_to": ["matt-kane"], "name": "Async Art", "kind": "company", "role": "Programmable art platform", "role_zh": "可编程艺术平台", "bio": "Async Art is an Ethereum platform launched in February 2020 by Conlan Rios, Lisa Liang and Nathan Clapp. It splits an artwork into a Master token and separately owned Layer tokens whose owners can change the image.", "bio_zh": "Async Art 是 2020 年 2 月由 Conlan Rios、Lisa Liang 和 Nathan Clapp 推出的以太坊平台。它把一件作品拆成一个 Master 代币和多个分别持有的 Layer 代币，Layer 的持有者可以改变整幅图像。", "why": "It turned co-ownership into co-authorship: each collector of a layer controls part of a shared picture within limits the artist set.", "why_zh": "它把共同持有变成了共同创作：每位图层藏家都能在艺术家设定的范围内控制共享画面的一部分。", "discovered_via": "seed", "work_count": 3}, {"id": "matt-kane", "links": {"site": "https://mattkane.com", "x": "https://x.com/mattkaneartist"}, "connected_to": ["async-art"], "name": "Matt Kane", "kind": "person", "role": "Artist and programmer", "role_zh": "艺术家、程序员", "bio": "Chicago-born artist who writes his own software to make layered, data-driven digital paintings. He contributed to Async Art's First Supper and made the Bitcoin-driven Right Place & Right Time.", "bio_zh": "出生于芝加哥的艺术家，自己编写软件来制作多层、由数据驱动的数字绘画。他参与了 Async Art 的 First Supper，并创作了由比特币行情驱动的 Right Place & Right Time。", "why": "His programmable paintings are drawn each day by the collective behaviour of a market rather than by the artist's hand.", "why_zh": "他的可编程绘画每天由市场的集体行为而不是艺术家的手来“绘制”。", "discovered_via": "async-art", "work_count": 2}, {"id": "dom-hofmann", "links": {"site": "https://www.lootproject.com", "x": "https://x.com/dhof", "wikipedia": "https://en.wikipedia.org/wiki/Dom_Hofmann"}, "connected_to": [], "name": "Dom Hofmann", "kind": "person", "role": "Software developer and artist; co-founder of Vine", "role_zh": "软件开发者、艺术家；Vine 联合创始人", "bio": "Co-founder of Vine who, in 2021, released Blitmap, a pixel-art collection remixed by its community, and Loot, eight thousand on-chain text lists of adventurer gear with no images or rules attached.", "bio_zh": "Vine 的联合创始人。2021 年他发布了由社区混编的像素艺术合集 Blitmap，以及 Loot：八千份存储在链上的冒险者装备文字清单，不附图像，也不附任何规则。", "why": "He showed that a deliberately unfinished on-chain primitive can hand world-building to everyone who holds or builds on it.", "why_zh": "他证明了一个刻意“未完成”的链上原语可以把构建世界的工作交给所有持有者和在其上继续开发的人。", "discovered_via": "seed", "work_count": 2}, {"id": "mathcastles", "links": {"site": "https://mathcastles.xyz", "x": "https://x.com/mathcastles"}, "connected_to": [], "name": "Mathcastles", "kind": "studio", "role": "On-chain art studio (Xaltgeist and 0x113d)", "role_zh": "链上艺术工作室（Xaltgeist 与 0x113d）", "bio": "A pseudonymous two-person studio, Xaltgeist and 0x113d, that builds fully on-chain art systems. Its best-known work is Terraforms (2021), a 20-level on-chain structure of land parcels.", "bio_zh": "一个由两位化名成员 Xaltgeist 与 0x113d 组成的工作室，专门构建完全在链上运行的艺术系统。其代表作是 Terraforms（2021），一座由地块组成、共 20 层的链上结构。", "why": "Terraforms gives each holder a piece of a shared on-chain world they can repaint and lock back into the contract.", "why_zh": "Terraforms 让每位持有者拥有共享链上世界的一块，并可以重新绘制它、再写回合约。", "discovered_via": "seed", "work_count": 1}, {"id": "harm-van-den-dorpel", "links": {"site": "https://harm.work", "wikipedia": "https://en.wikipedia.org/wiki/Harm_van_den_Dorpel"}, "connected_to": [], "name": "Harm van den Dorpel", "kind": "person", "role": "Artist; co-founder of left gallery", "role_zh": "艺术家；left gallery 联合创始人", "based": "Berlin, DE", "based_zh": "柏林，德国", "bio": "Dutch artist working with software, genetic algorithms and blockchains; co-founder of left gallery, an early platform for selling code-based art. He has bred populations of images since Death Imitates Language (2016).", "bio_zh": "荷兰艺术家，用软件、遗传算法和区块链创作；left gallery 的联合创始人，该画廊是较早出售代码艺术的平台。自 Death Imitates Language（2016）起，他一直在“培育”图像种群。", "why": "His evolving token populations make ownership part of an ongoing breeding and archiving process.", "why_zh": "他不断演化的代币种群，让“拥有”成为持续繁殖与存档过程的一部分。", "discovered_via": "seed", "work_count": 1}, {"id": "suum-cuique-labs", "links": {"site": "https://www.thehashmasks.com", "x": "https://x.com/TheHashmasks"}, "connected_to": [], "name": "Suum Cuique Labs", "kind": "company", "role": "Studio behind Hashmasks", "role_zh": "Hashmasks 的创作团队", "based": "Zug, CH", "based_zh": "楚格，瑞士", "bio": "Swiss studio that released Hashmasks in 2021: 16,384 digital portraits painted by about 70 artists, which owners can name permanently by burning a dedicated token.", "bio_zh": "瑞士工作室，2021 年发布 Hashmasks：由约 70 位艺术家绘制的 16,384 幅数字肖像，持有者可以通过销毁专用代币为其永久命名。", "why": "It made naming, a collector's act, into the part of the work that decides its meaning and rarity.", "why_zh": "它把“命名”这一藏家行为变成了决定作品意义和稀缺性的部分。", "discovered_via": "seed", "work_count": 1}, {"id": "tyler-hobbs", "links": {"site": "https://www.tylerxhobbs.com", "x": "https://x.com/tylerxhobbs"}, "connected_to": ["dandelion-wist-mane"], "name": "Tyler Hobbs", "kind": "person", "role": "Generative artist", "role_zh": "生成艺术家", "based": "Austin, US", "based_zh": "奥斯汀，美国", "bio": "Generative artist working with algorithms, plotters and paint, known for Fidenza (2021). With Dandelion Wist Mané he made QQL (2022), where collectors search the algorithm and choose what gets minted.", "bio_zh": "使用算法、绘图仪和颜料创作的生成艺术家，以 Fidenza（2021）闻名。他与 Dandelion Wist Mané 合作的 QQL（2022）让藏家亲自探索算法、决定铸造哪一幅。", "why": "QQL moved curation of a generative algorithm from the artist to the collectors.", "why_zh": "QQL 把生成算法的策展权从艺术家手中交给了藏家。", "discovered_via": "seed", "work_count": 1}, {"id": "dandelion-wist-mane", "links": {"site": "https://qql.art"}, "connected_to": ["tyler-hobbs"], "name": "Dandelion Wist Mané", "kind": "person", "role": "Software engineer and generative artist", "role_zh": "软件工程师、生成艺术家", "bio": "Software engineer and generative artist who created TensorBoard at Google Brain and co-created SourceCred at Protocol Labs before co-creating QQL with Tyler Hobbs.", "bio_zh": "软件工程师和生成艺术家，曾在 Google Brain 创建 TensorBoard，在 Protocol Labs 共同创建 SourceCred，之后与 Tyler Hobbs 共同创作 QQL。", "why": "Brought ideas from contribution-tracking systems into a generative artwork where the collector becomes co-creator.", "why_zh": "把贡献追踪系统的思路带进生成艺术，让藏家成为共同创作者。", "discovered_via": "tyler-hobbs", "work_count": 1}, {"id": "sam-spratt", "links": {"site": "https://samspratt.com", "x": "https://x.com/SamSpratt"}, "connected_to": [], "name": "Sam Spratt", "kind": "person", "role": "Painter and digital artist", "role_zh": "画家、数字艺术家", "bio": "Digital painter whose LUCI series (ten paintings, 613 masks and accompanying psalms) grows through games that collectors play inside the story.", "bio_zh": "数字画家，其 LUCI 系列（十幅画作、613 个面具及配套诗篇）通过藏家在故事中参与的游戏不断生长。", "why": "He turns collectors into players whose written contributions and votes are folded back into the paintings.", "why_zh": "他把藏家变成玩家，并把他们的书写与投票重新织入画作。", "discovered_via": "seed", "work_count": 2}, {"id": "alexis-andre", "links": {"x": "https://x.com/MacTuitui"}, "connected_to": [], "name": "Alexis André", "kind": "person", "role": "Generative artist and researcher", "role_zh": "生成艺术家、研究者", "based": "Tokyo, JP", "based_zh": "东京，日本", "bio": "French generative artist and researcher based in Tokyo. His Art Blocks project Friendship Bracelets (2022) was given free to Art Blocks holders to keep one and give one away.", "bio_zh": "常驻东京的法国生成艺术家和研究者。他在 Art Blocks 上的项目 Friendship Bracelets（2022）免费发放给 Art Blocks 持有者：留一个，送一个。", "why": "Friendship Bracelets used a generative drop as an instruction to give and to make something by hand.", "why_zh": "Friendship Bracelets 把一次生成艺术发放变成了“赠送”和“亲手编织”的指令。", "discovered_via": "seed", "work_count": 1}, {"id": "dark-forest-team", "links": {"site": "https://zkga.me", "x": "https://x.com/darkforest_eth", "github": "https://github.com/darkforest-eth"}, "connected_to": [], "name": "Dark Forest team (Brian Gu, Alan Luo et al.)", "kind": "collective", "role": "Developers of the zkSNARK game Dark Forest", "role_zh": "零知识证明游戏 Dark Forest 的开发团队", "bio": "Small team led by Brian Gu (gubsheep) that built Dark Forest (2020), a real-time strategy game that runs entirely on an Ethereum-compatible chain and hides the map with zero-knowledge proofs.", "bio_zh": "由 Brian Gu（gubsheep）带领的小团队，于 2020 年打造 Dark Forest：一款完全在以太坊兼容链上运行、用零知识证明隐藏地图的即时战略游戏。", "why": "Dark Forest showed that an on-chain rule set can host a persistent world whose history is written by its players and their bots.", "why_zh": "Dark Forest 证明了一套链上规则可以承载一个由玩家及其机器人书写历史的持续世界。", "discovered_via": "seed", "work_count": 1}, {"id": "basepaint", "links": {"site": "https://basepaint.xyz", "x": "https://x.com/basepaint_xyz", "github": "https://github.com/BasePaint"}, "connected_to": [], "name": "BasePaint", "kind": "collective", "role": "Team behind the BasePaint daily canvas", "role_zh": "BasePaint 每日画布的创作团队", "bio": "Small team that launched BasePaint on the Base network in August 2023; its contracts were written mainly by the developer w1nt3r. Every day strangers paint one shared pixel canvas that is then sold as an open edition.", "bio_zh": "2023 年 8 月在 Base 网络上推出 BasePaint 的小团队，合约主要由开发者 w1nt3r 编写。每天，陌生人共同在同一块像素画布上作画，画完后以开放版数出售。", "why": "It turns a collective canvas into a daily contract that pays each painter in proportion to the pixels they placed.", "why_zh": "它把集体画布变成一份每日合约，按每位画手落下的像素数给他们分成。", "discovered_via": "seed", "work_count": 1}, {"id": "pak", "links": {"x": "https://x.com/muratpak", "wikipedia": "https://en.wikipedia.org/wiki/Pak_(creator)"}, "connected_to": [], "name": "Pak", "kind": "anonymous", "role": "Anonymous digital artist and system designer", "bio": "Anonymous digital creator who also built the image-curating bot Archillect (2014). Between 2020 and 2022 Pak released a run of sales and contracts on Nifty Gateway, Sotheby's and their own sites: open editions, the ASH burn token, Lost Poets, Merge and Censored.", "why": "Pak turned sale formats and contract rules (open editions, burning, merging, one-token-per-wallet) into the artwork itself, so that what tens of thousands of buyers did is the finished piece.", "role_zh": "匿名数字艺术家、系统设计者", "bio_zh": "匿名数字创作者，2014 年做过图像策展机器人 Archillect。2020 至 2022 年间，Pak 在 Nifty Gateway、苏富比和自建网站上接连推出一系列发售与合约：开放版数、ASH 销毁代币、Lost Poets、Merge 和 Censored。", "why_zh": "Pak 把发售形式和合约规则（开放版数、销毁、合并、每个钱包只能持有一枚）本身做成作品，数万名买家的行为就是作品的最终形态。", "discovered_via": "seed", "work_count": 7}, {"id": "jack-butcher", "links": {"site": "https://jack.art", "x": "https://x.com/jackbutcher"}, "connected_to": [], "name": "Jack Butcher", "kind": "person", "role": "Conceptual artist, founder of Visualize Value", "bio": "Artist and founder of Visualize Value, known for works built from simple signs (a checkmark, a receipt, a trademark symbol). Since 2023 he has made editions whose images and supply are changed by collectors, often with developer Jalil Wahdatehagh.", "why": "Checks and Opepen made compositing-by-burning and holder opt-in into widely copied protocol forms, and his later works keep testing how a buyer's choice changes a shared work.", "role_zh": "观念艺术家，Visualize Value 创始人", "bio_zh": "艺术家，Visualize Value 创始人，作品常由简单符号构成（对勾、收据、商标符号）。自 2023 年起，他常与开发者 Jalil Wahdatehagh 合作，做出一系列由藏家改变图像与供应量的版数作品。", "why_zh": "Checks 和 Opepen 让“烧毁合成”和“持有者自愿加入”成为被广泛模仿的协议形式；他之后的作品继续检验买家的一次选择如何改变一件共有的作品。", "discovered_via": "seed", "work_count": 9}, {"id": "damien-hirst", "links": {"site": "https://www.damienhirst.com", "x": "https://x.com/hirst_official", "wikipedia": "https://en.wikipedia.org/wiki/Damien_Hirst"}, "connected_to": [], "name": "Damien Hirst", "kind": "person", "role": "Artist", "based": "London, UK", "bio": "British artist and a leading figure of the Young British Artists. With HENI he released The Currency (2021), his first NFT project.", "why": "The Currency made each buyer choose between a token and a painting, and destroyed whichever they rejected, so the final shape of 10,000 works was set by collectors.", "role_zh": "艺术家", "bio_zh": "英国艺术家，“英国青年艺术家”群体的代表人物。他与 HENI 合作推出了自己的第一个 NFT 项目 The Currency（2021）。", "why_zh": "The Currency 让每位买家在代币和画作之间二选一，未被选中的一方会被销毁，于是一万件作品最后的样子由藏家决定。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 1}, {"id": "tom-sachs", "links": {"site": "https://www.tomsachsrocketfactory.com", "wikipedia": "https://en.wikipedia.org/wiki/Tom_Sachs"}, "connected_to": [], "name": "Tom Sachs", "kind": "person", "role": "Sculptor", "based": "New York, US", "bio": "American sculptor known for hand-built replicas of space programmes and branded objects. Rocket Factory (2021) is his NFT project, in which collectors assemble rockets from parts that his studio then builds and launches.", "why": "Rocket Factory ties an on-chain merge rule (three parts burned into one rocket) to a physical studio process and public launches.", "role_zh": "雕塑家", "bio_zh": "美国雕塑家，以手工复制太空计划和品牌物件著称。Rocket Factory（2021）是他的 NFT 项目：藏家用零件拼装火箭，再由他的工作室把火箭造出来并发射。", "why_zh": "Rocket Factory 把链上的合并规则（三个零件烧成一枚火箭）与工作室的实体制作和公开发射联系在一起。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}, {"id": "mitchell-f-chan", "links": {"site": "https://chan.gallery/", "x": "https://x.com/mitchellfchan", "github": "https://github.com/mitchellfchan"}, "connected_to": [], "name": "Mitchell F. Chan", "kind": "person", "role": "Artist and game maker", "bio": "Artist working with conceptual art, video games and smart contracts. His 2017 token work Digital Zones of Immaterial Pictorial Sensibility restages Yves Klein's receipt ritual in an Ethereum contract.", "why": "Digital Zones is an early smart contract that encodes an artist's sale ritual, including a burn function any holder can call.", "role_zh": "艺术家、游戏创作者", "bio_zh": "创作涉及观念艺术、电子游戏和智能合约的艺术家。他 2017 年的代币作品 Digital Zones of Immaterial Pictorial Sensibility 把伊夫·克莱因的收据仪式搬进以太坊合约。", "why_zh": "Digital Zones 是较早把艺术家的出售仪式写进智能合约的作品，其中包括任何持有者都能调用的销毁函数。", "discovered_via": "seed", "work_count": 1}, {"id": "allan-kaprow", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Allan_Kaprow"}, "connected_to": ["george-brecht", "john-cage"], "name": "Allan Kaprow", "kind": "person", "role": "Artist and teacher", "based": "New York and California, US", "bio": "American artist (1927–2006) who coined the term 'happening' in 1959 and later moved to small, scored 'activities' for pairs and groups.", "why": "He turned the exhibition into a set of instructions that audiences and volunteers carry out, and treated every remake as a 'reinvention'.", "role_zh": "艺术家、教师", "based_zh": "美国纽约与加利福尼亚", "bio_zh": "美国艺术家（1927–2006），1959 年提出“偶发艺术”（happening）一词，后来转向为两人或小组编写的小规模“活动”乐谱。", "why_zh": "他把展览变成一组由观众和志愿者执行的指令，并把每一次重做都视为一次“再发明”。", "discovered_via": "seed", "work_count": 5}, {"id": "felix-gonzalez-torres", "links": {"site": "https://www.felixgonzalez-torresfoundation.org/", "wikipedia": "https://en.wikipedia.org/wiki/Felix_Gonzalez-Torres"}, "connected_to": [], "name": "Felix Gonzalez-Torres", "kind": "person", "role": "Artist", "based": "New York, US", "bio": "Cuban-born American artist (1957–1996) known for candy spills and paper stacks that visitors may take from and that owners must replenish.", "why": "His works exist as ownership certificates and installation guidelines: the owner rebuilds the piece and the public slowly takes it apart.", "role_zh": "艺术家", "based_zh": "美国纽约", "bio_zh": "古巴出生的美国艺术家（1957–1996），以糖果堆和纸堆作品闻名：观众可以从中拿走，收藏者必须补充。", "why_zh": "他的作品以所有权证书和安装准则的形式存在：收藏者按规则重建作品，公众则一点点把它拿走。", "discovered_via": "seed", "work_count": 3}, {"id": "hans-ulrich-obrist", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Hans_Ulrich_Obrist"}, "connected_to": [], "name": "Hans Ulrich Obrist", "kind": "person", "role": "Curator", "based": "London, UK", "bio": "Swiss curator, artistic director of the Serpentine Galleries in London, who started the instruction exhibition do it with Christian Boltanski and Bertrand Lavier in 1993.", "why": "do it is an exhibition made only of artists' instructions, which each host institution and its public must realise anew.", "role_zh": "策展人", "based_zh": "英国伦敦", "bio_zh": "瑞士策展人，伦敦蛇形画廊艺术总监，1993 年与克里斯蒂安·波尔坦斯基、贝尔特朗·拉维耶一起发起指令展览 do it。", "why_zh": "do it 是一个只由艺术家指令构成的展览，每个接待机构和它的观众都要重新把指令实现出来。", "discovered_via": "seed", "work_count": 2}, {"id": "erwin-wurm", "links": {"site": "https://www.erwinwurm.at/", "wikipedia": "https://en.wikipedia.org/wiki/Erwin_Wurm"}, "connected_to": [], "name": "Erwin Wurm", "kind": "person", "role": "Artist", "based": "Vienna, AT", "bio": "Austrian sculptor whose One Minute Sculptures (1997–) are drawn or written instructions that visitors perform with everyday objects for sixty seconds.", "why": "He made the visitor's body the material of the sculpture and the instruction the lasting part of the work.", "role_zh": "艺术家", "based_zh": "奥地利维也纳", "bio_zh": "奥地利雕塑家，他的《一分钟雕塑》（1997–）是一些画出或写出的指令，观众用日常物品照着做六十秒。", "why_zh": "他把观众的身体变成雕塑的材料，而指令才是作品中持久的部分。", "discovered_via": "seed", "work_count": 1}, {"id": "david-horvitz", "links": {"site": "https://davidhorvitz.com/", "wikipedia": "https://en.wikipedia.org/wiki/David_Horvitz"}, "connected_to": [], "name": "David Horvitz", "kind": "person", "role": "Artist", "based": "Los Angeles, US", "bio": "American artist (born 1982) working with books, mail art, performance and the internet, often through instructions that others carry out.", "why": "He writes simple instructions that travel through networks and crowds, from a freezer meme to bells rung at local noon.", "role_zh": "艺术家", "based_zh": "美国洛杉矶", "bio_zh": "美国艺术家（1982 年生），创作涉及书籍、邮件艺术、表演和互联网，常常通过让别人执行的指令来完成作品。", "why_zh": "他写下简单的指令，让它们在网络和人群中传播：从冰箱表情包到在本地正午敲响的铃。", "discovered_via": "seed", "work_count": 2}, {"id": "brian-eno", "links": {"site": "https://www.brian-eno.net/", "wikipedia": "https://en.wikipedia.org/wiki/Brian_Eno"}, "connected_to": ["peter-schmidt"], "name": "Brian Eno", "kind": "person", "role": "Musician, producer and artist", "based": "London, UK", "bio": "English musician and producer who, with the painter Peter Schmidt, published the card deck Oblique Strategies in 1975.", "why": "Oblique Strategies is a portable rule system: anyone stuck in a creative process draws a card and follows it.", "role_zh": "音乐人、制作人、艺术家", "based_zh": "英国伦敦", "bio_zh": "英国音乐人和制作人，1975 年与画家彼得·施密特合作出版卡片《迂回策略》。", "why_zh": "《迂回策略》是一套可以随身携带的规则系统：任何在创作中卡住的人抽一张卡，然后照做。", "discovered_via": "seed", "work_count": 1}, {"id": "peter-schmidt", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Peter_Schmidt_(artist)"}, "connected_to": ["brian-eno"], "name": "Peter Schmidt", "kind": "person", "role": "Painter", "based": "London, UK", "bio": "German-born British painter (1931–1980) who co-authored Oblique Strategies with Brian Eno.", "why": "Co-author of Oblique Strategies, one of the most widely used instruction decks for creative work.", "role_zh": "画家", "based_zh": "英国伦敦", "bio_zh": "德国出生的英国画家（1931–1980），与布莱恩·伊诺合著《迂回策略》。", "why_zh": "《迂回策略》的共同作者，这是创作领域使用最广的指令卡之一。", "discovered_via": "brian-eno", "work_count": 1}, {"id": "raymond-queneau", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Raymond_Queneau"}, "connected_to": [], "name": "Raymond Queneau", "kind": "person", "role": "Writer", "based": "Paris, FR", "bio": "French novelist and poet (1903–1976) who co-founded Oulipo with François Le Lionnais in 1960.", "why": "His combinatorial sonnet book hands the composition of each poem to the reader, under a strict rhyme constraint.", "role_zh": "作家", "based_zh": "法国巴黎", "bio_zh": "法国小说家、诗人（1903–1976），1960 年与弗朗索瓦·勒利奥内共同创立“潜在文学工场”（Oulipo）。", "why_zh": "他的组合十四行诗集在严格的押韵约束下，把每一首诗的组合交给读者完成。", "discovered_via": "seed", "work_count": 1}, {"id": "roman-ondak", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Roman_Ond%C3%A1k"}, "connected_to": [], "name": "Roman Ondák", "kind": "person", "role": "Artist", "based": "Bratislava, SK", "bio": "Slovak artist (born 1966) whose installations and performances often rely on instructions carried out by museum staff and visitors.", "why": "Measuring the Universe turns a household habit, marking a child's height on a wall, into an instruction that thousands of visitors complete.", "role_zh": "艺术家", "based_zh": "斯洛伐克布拉迪斯拉发", "bio_zh": "斯洛伐克艺术家（1966 年生），他的装置和表演常常依靠美术馆工作人员和观众执行的指令。", "why_zh": "《测量宇宙》把在墙上给孩子量身高这一家庭习惯，变成成千上万名观众共同完成的指令。", "discovered_via": "seed", "work_count": 1}, {"id": "christian-marclay", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Christian_Marclay"}, "connected_to": [], "name": "Christian Marclay", "kind": "person", "role": "Artist and composer", "based": "London, UK and New York, US", "bio": "Swiss-American visual artist and composer who has made many graphic and found scores for musicians to interpret.", "why": "In Graffiti Composition the public writes the score and musicians play it, so both notation and performance come from other people.", "role_zh": "艺术家、作曲家", "based_zh": "英国伦敦与美国纽约", "bio_zh": "瑞士裔美国视觉艺术家、作曲家，创作了许多交给音乐家演绎的图形乐谱和现成乐谱。", "why_zh": "在《涂鸦乐谱》中，公众写下乐谱、音乐家演奏它，记谱和演奏都来自别人。", "discovered_via": "seed", "work_count": 1}, {"id": "anna-halprin", "links": {"site": "https://www.annahalprin.org/", "wikipedia": "https://en.wikipedia.org/wiki/Anna_Halprin"}, "connected_to": ["simone-forti"], "name": "Anna Halprin", "kind": "person", "role": "Dancer and choreographer", "based": "Kentfield, California, US", "bio": "American dancer and choreographer (1920–2021) who developed community dance rituals and, with Lawrence Halprin, the RSVP Cycles scoring method.", "why": "Her Planetary Dance is a movement score that communities around the world perform each year with their own local theme.", "role_zh": "舞者、编舞家", "based_zh": "美国加利福尼亚州肯特菲尔德", "bio_zh": "美国舞者和编舞家（1920–2021），发展了社区舞蹈仪式，并与劳伦斯·哈尔普林一起提出“RSVP 循环”记谱方法。", "why_zh": "她的《行星之舞》是一份动作乐谱，世界各地的社区每年以自己的本地主题来表演它。", "discovered_via": "seed", "work_count": 1}, {"id": "simone-forti", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Simone_Forti"}, "connected_to": ["anna-halprin", "la-monte-young", "yoko-ono"], "name": "Simone Forti", "kind": "person", "role": "Artist, dancer and choreographer", "based": "Los Angeles, US", "bio": "Italian-born American artist and dancer (born 1935) whose Dance Constructions (1960–61) are task-based pieces for groups of performers.", "why": "Her Dance Constructions entered MoMA's collection in 2015 as instructions and teaching rights, so the museum must train new performers to realise them.", "role_zh": "艺术家、舞者、编舞家", "based_zh": "美国洛杉矶", "bio_zh": "意大利出生的美国艺术家和舞者（1935 年生），她的《舞蹈构造》（1960–61）是交给一群表演者完成的任务型作品。", "why_zh": "2015 年《舞蹈构造》以指令和传授权的形式进入 MoMA 收藏，美术馆必须训练新的表演者来实现它们。", "discovered_via": "seed", "work_count": 1}, {"id": "john-baldessari", "links": {"wikipedia": "https://en.wikipedia.org/wiki/John_Baldessari"}, "connected_to": [], "name": "John Baldessari", "kind": "person", "role": "Artist", "based": "Los Angeles, US", "bio": "American conceptual artist (1931–2020) who used photographs, text and hired makers to question authorship in painting.", "why": "His Commissioned Paintings were painted entirely by other people following his set-up, with their names written on the canvas.", "role_zh": "艺术家", "based_zh": "美国洛杉矶", "bio_zh": "美国观念艺术家（1931–2020），用照片、文字和雇来的制作者质疑绘画中的作者身份。", "why_zh": "他的《委托绘画》完全由别人按照他设定的流程画成，画布上写的是画者的名字。", "discovered_via": "seed", "work_count": 1}, {"id": "david-katzive", "links": {}, "connected_to": ["laszlo-moholy-nagy", "sol-lewitt"], "name": "David H. Katzive", "kind": "person", "role": "Curator", "based": "Chicago, US", "bio": "Curator at the Museum of Contemporary Art Chicago who organised Art by Telephone in 1969, under director Jan van der Marck.", "why": "Art by Telephone made the museum staff the executors of works that artists described only by phone.", "role_zh": "策展人", "based_zh": "美国芝加哥", "bio_zh": "芝加哥当代艺术博物馆策展人，1969 年在馆长扬·范德马克任内组织了“电话艺术”展。", "why_zh": "“电话艺术”让美术馆员工成为作品的执行者，而艺术家只通过电话描述作品。", "discovered_via": "laszlo-moholy-nagy", "work_count": 1}, {"id": "laszlo-moholy-nagy", "links": {"wikipedia": "https://en.wikipedia.org/wiki/L%C3%A1szl%C3%B3_Moholy-Nagy"}, "connected_to": [], "name": "László Moholy-Nagy", "kind": "person", "role": "Painter, photographer and Bauhaus teacher", "role_zh": "画家、摄影师、包豪斯教师", "based": "Berlin, DE; Chicago, US", "based_zh": "柏林，德国；芝加哥，美国", "bio": "Hungarian-born artist (1895–1946) who taught at the Bauhaus from 1923 and later founded the New Bauhaus in Chicago. He worked across painting, photography, film, typography and light sculpture.", "bio_zh": "匈牙利出生的艺术家（1895—1946），1923 年起在包豪斯任教，后在芝加哥创办新包豪斯。创作横跨绘画、摄影、电影、字体设计和光雕塑。", "why": "His enamel 'telephone pictures' are an early case of an artist specifying a work as instructions that a factory carries out.", "why_zh": "他的珐琅“电话绘画”是艺术家把作品写成指令、交由工厂执行的早期案例。", "discovered_via": "seed", "work_count": 1}, {"id": "marcel-duchamp", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Marcel_Duchamp"}, "connected_to": [], "name": "Marcel Duchamp", "kind": "person", "role": "Artist", "role_zh": "艺术家", "based": "Paris, FR; New York, US", "based_zh": "巴黎，法国；纽约，美国", "bio": "French-American artist (1887–1968) who introduced the readymade and moved art from the made object to the choice and the idea.", "bio_zh": "法裔美国艺术家（1887—1968），提出“现成品”，把艺术的重心从制作的物件转到选择和观念上。", "why": "With Unhappy Readymade he sent a readymade as instructions by post, to be made by other people and finished by the weather.", "why_zh": "在《不快乐的现成品》中，他把一件现成品写成指令寄出，由别人制作、由天气完成。", "discovered_via": "seed", "work_count": 1}, {"id": "sol-lewitt", "links": {"site": "https://www.cahiersdartinstitute.org/catalogues/sol-lewitt-wall-drawings/description", "wikipedia": "https://en.wikipedia.org/wiki/Sol_LeWitt"}, "connected_to": ["lawrence-weiner"], "name": "Sol LeWitt", "kind": "person", "role": "Conceptual artist", "role_zh": "观念艺术家", "based": "New York and Chester, Connecticut, US", "based_zh": "纽约与康涅狄格州切斯特，美国", "bio": "American artist (1928–2007) and a founder of conceptual art. From 1968 he made about 1,350 wall drawings that exist as written instructions and diagrams, drawn on the wall by other people.", "bio_zh": "美国艺术家（1928—2007），观念艺术的奠基者之一。自 1968 年起创作约 1350 件墙绘，它们以文字指令和示意图的形式存在，由他人画到墙上。", "why": "His wall drawings are the clearest model of art as a score: the owner holds a certificate and instructions, and each installation is a new performance by drafters.", "why_zh": "他的墙绘是“作品即乐谱”最清晰的范例：收藏者持有证书和指令，每一次安装都是绘图员的一次新演奏。", "discovered_via": "seed", "work_count": 11}, {"id": "lawrence-weiner", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Lawrence_Weiner"}, "connected_to": ["sol-lewitt"], "name": "Lawrence Weiner", "kind": "person", "role": "Conceptual artist", "role_zh": "观念艺术家", "based": "New York, US; Amsterdam, NL", "based_zh": "纽约，美国；阿姆斯特丹，荷兰", "bio": "American artist (1942–2021) whose works are statements in language that describe materials and actions, shown as text on walls, in books and in public space.", "bio_zh": "美国艺术家（1942—2021），作品是描述材料与动作的语言陈述，以墙上文字、书籍和公共空间文字的形式出现。", "why": "His 1968 Declaration of Intent hands the decision to build, fabricate or not build a work to whoever receives it.", "why_zh": "他 1968 年的《意图声明》把“自己建造、请人制作或不建造”的决定权交给接收作品的人。", "discovered_via": "seed", "work_count": 1}, {"id": "yoko-ono", "links": {"site": "https://imaginepeace.com", "wikipedia": "https://en.wikipedia.org/wiki/Yoko_Ono"}, "connected_to": ["george-maciunas", "john-cage", "la-monte-young"], "name": "Yoko Ono", "kind": "person", "role": "Artist, musician and peace activist", "role_zh": "艺术家、音乐人、和平活动者", "based": "New York, US", "based_zh": "纽约，美国", "bio": "Japanese-American artist (born 1933) active in the New York and Tokyo avant-garde from the late 1950s and close to Fluxus. Her instruction pieces, performances and participatory installations ask the audience to complete the work.", "bio_zh": "日裔美国艺术家（1933 年生），自 1950 年代末活跃于纽约和东京的前卫艺术圈，与激浪派关系密切。她的指令作品、表演和参与式装置都请观众来完成作品。", "why": "From the 1961 Instruction Paintings to the Wish Trees, she wrote instructions that strangers carry out, often by the thousands.", "why_zh": "从 1961 年的《指令绘画》到《许愿树》，她写下由陌生人执行的指令，参与者常常成千上万。", "discovered_via": "seed", "work_count": 7}, {"id": "john-cage", "links": {"site": "https://johncage.org", "wikipedia": "https://en.wikipedia.org/wiki/John_Cage"}, "connected_to": ["alison-knowles", "christian-wolff", "george-brecht", "la-monte-young"], "name": "John Cage", "kind": "person", "role": "Composer", "based": "New York, US", "bio": "American composer (1912–1992) who used chance operations, indeterminate notation and silence to hand decisions to performers, listeners and the environment.", "why": "His scores turned composition into writing rules for other people, and his New School classes trained the Fluxus generation of event-score writers.", "role_zh": "作曲家", "bio_zh": "美国作曲家（1912—1992），借助偶然程序、不确定记谱和沉默，把决定权交给演奏者、听众和环境。", "why_zh": "他的乐谱把作曲变成为他人写规则，他在新学院的课程培养了一代写事件乐谱的激浪派艺术家。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 5}, {"id": "terry-riley", "links": {"site": "https://terryriley.net", "wikipedia": "https://en.wikipedia.org/wiki/Terry_Riley"}, "connected_to": ["la-monte-young", "pauline-oliveros"], "name": "Terry Riley", "kind": "person", "role": "Composer and performer", "based": "US / Japan", "bio": "American composer (born 1935) associated with early minimalism, known for In C and for long improvised keyboard performances.", "why": "In C is one of the most performed open-ensemble scores: a page of short patterns that any group can play.", "role_zh": "作曲家、演奏家", "bio_zh": "美国作曲家（生于 1935 年），早期极简主义的代表人物，以《In C》和长时间的键盘即兴演奏闻名。", "why_zh": "《In C》是演出最多的开放编制乐谱之一：一页短小的乐句，任何团体都可以演奏。", "based_zh": "美国／日本", "discovered_via": "seed", "work_count": 1}, {"id": "cornelius-cardew", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Cornelius_Cardew"}, "connected_to": ["john-cage", "karlheinz-stockhausen"], "name": "Cornelius Cardew", "kind": "person", "role": "Composer", "based": "London, UK", "bio": "British composer (1936–1981), assistant to Stockhausen, member of the improvising group AMM and co-founder of the Scratch Orchestra.", "why": "He wrote scores for untrained performers and a constitution for an orchestra open to anyone, making the rules of the group part of the music.", "role_zh": "作曲家", "bio_zh": "英国作曲家（1936—1981），曾任施托克豪森的助手，即兴团体 AMM 成员，Scratch Orchestra 的联合创办人。", "why_zh": "他为未受训练的演奏者写乐谱，并为一个向所有人开放的乐团起草章程，把群体的规则也变成了音乐的一部分。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 3}, {"id": "pauline-oliveros", "links": {"site": "https://www.deeplistening.rpi.edu", "wikipedia": "https://en.wikipedia.org/wiki/Pauline_Oliveros"}, "connected_to": ["john-cage", "terry-riley"], "name": "Pauline Oliveros", "kind": "person", "role": "Composer and accordionist", "based": "Kingston, New York, US", "bio": "American composer (1932–2016), co-founder of the San Francisco Tape Music Center and founder of the Deep Listening practice.", "why": "Her Sonic Meditations are text instructions for listening and sounding together that any group, trained or not, can perform.", "role_zh": "作曲家、手风琴演奏家", "bio_zh": "美国作曲家（1932—2016），旧金山磁带音乐中心联合创办人，“深度聆听”实践的创立者。", "why_zh": "她的《声音冥想》是关于共同聆听与发声的文字指令，任何人群无论是否受过训练都可以演出。", "based_zh": "纽约州金斯顿，美国", "discovered_via": "seed", "work_count": 1}, {"id": "karlheinz-stockhausen", "links": {"site": "https://www.karlheinzstockhausen.org", "wikipedia": "https://en.wikipedia.org/wiki/Karlheinz_Stockhausen"}, "connected_to": ["cornelius-cardew"], "name": "Karlheinz Stockhausen", "kind": "person", "role": "Composer", "based": "Kürten, DE", "bio": "German composer (1928–2007), a central figure of postwar electronic and serial music, who in 1968 turned to verbal scores he called intuitive music.", "why": "Aus den sieben Tagen replaced notes with short texts, so the sound depends entirely on how an ensemble interprets them.", "role_zh": "作曲家", "bio_zh": "德国作曲家（1928—2007），战后电子音乐与序列音乐的核心人物，1968 年转向他称为“直觉音乐”的文字乐谱。", "why_zh": "《来自七天》用短文取代音符，声音完全取决于乐团如何诠释这些文字。", "based_zh": "屈尔滕，德国", "discovered_via": "seed", "work_count": 1}, {"id": "la-monte-young", "links": {"wikipedia": "https://en.wikipedia.org/wiki/La_Monte_Young"}, "connected_to": ["george-maciunas", "jackson-mac-low", "john-cage", "terry-riley"], "name": "La Monte Young", "kind": "person", "role": "Composer", "based": "New York, US", "bio": "American composer (born 1935) whose 1960 word scores and sustained-tone music shaped Fluxus and minimalism.", "why": "His Compositions 1960 are one-line instructions that others perform, and his Anthology of Chance Operations gathered the first body of such scores.", "role_zh": "作曲家", "bio_zh": "美国作曲家（生于 1935 年），他 1960 年的文字乐谱和长音音乐影响了激浪派与极简主义。", "why_zh": "他的《1960 年作品》是交给别人演出的单行指令，他编的《偶然操作选集》汇集了第一批此类乐谱。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "jackson-mac-low", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Jackson_Mac_Low"}, "connected_to": ["john-cage", "la-monte-young"], "name": "Jackson Mac Low", "kind": "person", "role": "Poet and composer", "based": "New York, US", "bio": "American poet and composer (1922–2004) who wrote poems and performance pieces by chance operations and systematic procedures.", "why": "Co-publisher of An Anthology of Chance Operations and author of many simultaneities meant to be read aloud by groups.", "role_zh": "诗人、作曲家", "bio_zh": "美国诗人、作曲家（1922—2004），用偶然操作和系统化程序写诗与表演作品。", "why_zh": "《偶然操作选集》的联合出版人，写过许多供群体同时朗读的作品。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}, {"id": "george-brecht", "links": {"wikipedia": "https://en.wikipedia.org/wiki/George_Brecht"}, "connected_to": ["alison-knowles", "george-maciunas", "john-cage"], "name": "George Brecht", "kind": "person", "role": "Artist", "based": "Cologne, DE", "bio": "American artist (1926–2008), trained as a chemist, who invented the event score in John Cage's class and later lived in Germany.", "why": "His printed cards reduced a work to a short instruction that anyone can realize, the basic unit of Fluxus.", "role_zh": "艺术家", "bio_zh": "美国艺术家（1926—2008），原为化学家，在约翰·凯奇的课上发明了“事件乐谱”，后定居德国。", "why_zh": "他的印刷卡片把一件作品压缩成任何人都能实现的简短指令，这是激浪派的基本单元。", "based_zh": "科隆，德国", "discovered_via": "seed", "work_count": 3}, {"id": "alison-knowles", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Alison_Knowles"}, "connected_to": ["benjamin-patterson", "george-brecht", "george-maciunas"], "name": "Alison Knowles", "kind": "person", "role": "Artist and composer", "based": "New York, US", "bio": "American artist (born 1933), a founding member of Fluxus, who made event scores, artist's books and sound works built from everyday materials such as food and beans.", "why": "Her scores Make a Salad and The Identical Lunch turned daily routines into instructions that friends and audiences repeat.", "role_zh": "艺术家、作曲家", "bio_zh": "美国艺术家（生于 1933 年），激浪派创始成员之一，以食物、豆子等日常材料创作事件乐谱、艺术家书和声音作品。", "why_zh": "她的《做一份沙拉》和《相同的午餐》把日常惯例变成朋友与观众可以重复执行的指令。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "george-maciunas", "links": {"wikipedia": "https://en.wikipedia.org/wiki/George_Maciunas"}, "connected_to": ["alison-knowles", "george-brecht", "la-monte-young", "mieko-shiomi"], "name": "George Maciunas", "kind": "person", "role": "Artist, designer and Fluxus organizer", "based": "New York, US", "bio": "Lithuanian-born American artist and designer (1931–1978) who named and organized Fluxus and designed its editions, boxes and kits.", "why": "He packaged other artists' scores as cheap editions for owners to open and perform, turning distribution itself into a rule.", "role_zh": "艺术家、设计师、激浪派组织者", "bio_zh": "立陶宛裔美国艺术家、设计师（1931—1978），为激浪派命名并组织其活动，设计了它的出版物、盒子和套装。", "why_zh": "他把其他艺术家的乐谱包装成廉价版本，由购买者打开并执行，让发行方式本身成为一种规则。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}, {"id": "mieko-shiomi", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Mieko_Shiomi"}, "connected_to": ["george-brecht", "george-maciunas"], "name": "Mieko Shiomi", "kind": "person", "role": "Composer and artist", "based": "Osaka, JP", "bio": "Japanese composer and artist (born 1938), co-founder of Group Ongaku in Tokyo and a member of Fluxus from 1964.", "why": "Her Spatial Poem sent scores by post to people around the world and compiled their reports into a collective poem.", "role_zh": "作曲家、艺术家", "bio_zh": "日本作曲家、艺术家（生于 1938 年），东京“音乐小组”联合创办人，1964 年起参与激浪派。", "why_zh": "她的《空间诗》通过邮寄把乐谱发给世界各地的人，再把他们的回报汇编成一首集体的诗。", "based_zh": "大阪，日本", "discovered_via": "seed", "work_count": 1}, {"id": "benjamin-patterson", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Benjamin_Patterson_(artist)"}, "connected_to": ["alison-knowles", "george-maciunas"], "name": "Benjamin Patterson", "kind": "person", "role": "Double bassist, composer and artist", "based": "Wiesbaden, DE", "bio": "American double bassist and artist (1934–2016), a founding member of Fluxus who took part in the 1962 Wiesbaden festival.", "why": "Paper Piece is a precise score that any group can play with bags and sheets of paper.", "role_zh": "低音提琴手、作曲家、艺术家", "bio_zh": "美国低音提琴手、艺术家（1934—2016），激浪派创始成员，参加了 1962 年威斯巴登艺术节。", "why_zh": "《纸的作品》是一份精确的乐谱，任何团体都能用纸袋和纸张来演奏。", "based_zh": "威斯巴登，德国", "discovered_via": "seed", "work_count": 1}, {"id": "christian-wolff", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Christian_Wolff_(composer)"}, "connected_to": ["cornelius-cardew", "john-cage"], "name": "Christian Wolff", "kind": "person", "role": "Composer", "based": "New Hampshire, US", "bio": "American composer (born 1934), associated with John Cage and Morton Feldman, whose scores coordinate players through cues and listening.", "why": "His Prose Collection gives short verbal rules that any group, including non-musicians, can perform.", "role_zh": "作曲家", "bio_zh": "美国作曲家（生于 1934 年），与约翰·凯奇、莫顿·费尔德曼同属一个圈子，他的乐谱通过提示和聆听协调演奏者。", "why_zh": "他的《散文集》给出简短的文字规则，任何团体包括非音乐人都能演出。", "based_zh": "新罕布什尔州，美国", "discovered_via": "seed", "work_count": 1}, {"id": "frederic-rzewski", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Frederic_Rzewski"}, "connected_to": ["christian-wolff", "cornelius-cardew"], "name": "Frederic Rzewski", "kind": "person", "role": "Composer and pianist", "based": "Brussels, BE", "bio": "American composer and pianist (1938–2021), co-founder of the live-electronic group Musica Elettronica Viva in Rome.", "why": "Les Moutons de Panurge is a simple additive rule for musicians and non-musicians whose errors shape the result.", "role_zh": "作曲家、钢琴家", "bio_zh": "美国作曲家、钢琴家（1938—2021），罗马现场电子乐团 Musica Elettronica Viva 的联合创办人。", "why_zh": "《帕努日的羊群》是一条写给音乐人与非音乐人的简单累加规则，演奏中的失误塑造了最终结果。", "based_zh": "布鲁塞尔，比利时", "discovered_via": "seed", "work_count": 1}, {"id": "joseph-beuys", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Joseph_Beuys"}, "connected_to": [], "name": "Joseph Beuys", "kind": "person", "role": "Artist, teacher and political activist", "based": "Düsseldorf, DE", "bio": "German artist (1921–1986) who extended sculpture to teaching, discussion and political organising under the name social sculpture. He co-founded the Free International University and was an early figure of the German Greens.", "why": "He framed society itself as a sculpture everyone shapes, and built works such as 7000 Eichen whose form depended on public funding and collective planting.", "role_zh": "艺术家、教师与政治行动者", "based_zh": "杜塞尔多夫，德国", "bio_zh": "德国艺术家（1921–1986），以“社会雕塑”之名把雕塑扩展到教学、讨论与政治组织。他参与创立自由国际大学，也是德国绿党的早期人物。", "why_zh": "他把社会本身视为人人参与塑造的雕塑，《7000棵橡树》这样的作品，其形态取决于公众出资和集体种植。", "discovered_via": "seed", "work_count": 2}, {"id": "francis-alys", "links": {"site": "https://francisalys.com/", "wikipedia": "https://en.wikipedia.org/wiki/Francis_Al%C3%BFs"}, "connected_to": [], "name": "Francis Alÿs", "kind": "person", "role": "Artist", "based": "Mexico City, MX", "bio": "Belgian-born artist who has lived in Mexico City since 1986. He works through walks, actions and films, often staged with volunteers, soldiers, children or city workers.", "why": "Many of his actions are one simple rule handed to a crowd (shovel the dune, fall into step, push the rubbish), and the film records what the crowd makes of it.", "role_zh": "艺术家", "based_zh": "墨西哥城，墨西哥", "bio_zh": "出生于比利时，1986 年起定居墨西哥城。他以行走、行动和影像创作，常与志愿者、士兵、儿童或城市工人一同完成。", "why_zh": "他的许多行动只是交给一群人的一条简单规则（铲沙丘、并步齐行、推垃圾），影片记录人群如何把规则变成事件。", "discovered_via": "seed", "work_count": 6}, {"id": "marina-abramovic", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Marina_Abramovi%C4%87"}, "connected_to": [], "name": "Marina Abramović", "kind": "person", "role": "Performance artist", "based": "New York, US", "bio": "Serbian-born performance artist working since the early 1970s with endurance, the body and the relation between performer and audience.", "why": "In Rhythm 0 and The Artist Is Present she set strict rules for the audience and left the outcome to what they chose to do.", "role_zh": "行为艺术家", "based_zh": "纽约，美国", "bio_zh": "出生于塞尔维亚的行为艺术家，自 1970 年代初起以耐力、身体以及表演者与观众的关系为创作核心。", "why_zh": "在《节奏 0》和《艺术家在场》中，她为观众设定严格的规则，把结果交给观众自己的选择。", "discovered_via": "seed", "work_count": 2}, {"id": "tino-sehgal", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Tino_Sehgal"}, "connected_to": [], "name": "Tino Sehgal", "kind": "person", "role": "Artist", "based": "Berlin, DE", "bio": "British-German artist who makes 'constructed situations': works enacted by trained interpreters in conversation or movement with visitors, with no objects and no photographic documentation.", "why": "His works exist only as rules passed on orally to interpreters and buyers, and are sold by spoken contract before a notary.", "role_zh": "艺术家", "based_zh": "柏林，德国", "bio_zh": "英德籍艺术家，创作“建构情境”：由受过训练的诠释者与观众交谈或共同行动来完成的作品，没有实物，也不允许拍照记录。", "why_zh": "他的作品只以口头传给诠释者和买家的规则存在，并在公证人面前以口头合同出售。", "discovered_via": "seed", "work_count": 2}, {"id": "mierle-laderman-ukeles", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Mierle_Laderman_Ukeles"}, "connected_to": [], "name": "Mierle Laderman Ukeles", "kind": "person", "role": "Artist; artist-in-residence of the New York City Department of Sanitation", "based": "New York, US", "bio": "American artist who wrote the Manifesto for Maintenance Art in 1969 and has been the unsalaried artist-in-residence of New York's Department of Sanitation since 1977.", "why": "She turned other people's daily maintenance work into art by rule: a declared hour, a handshake, a ritual repeated with thousands of workers.", "role_zh": "艺术家；纽约市环卫局驻局艺术家", "based_zh": "纽约，美国", "bio_zh": "美国艺术家，1969 年写下《维护艺术宣言》，自 1977 年起担任纽约市环卫局的无薪驻局艺术家。", "why_zh": "她用规则把他人日常的维护劳动变成艺术：一个被宣告的小时、一次握手、与数千名工人重复的仪式。", "discovered_via": "seed", "work_count": 2}, {"id": "tania-bruguera", "links": {"site": "https://taniabruguera.com/", "wikipedia": "https://en.wikipedia.org/wiki/Tania_Bruguera"}, "connected_to": [], "name": "Tania Bruguera", "kind": "person", "role": "Artist and activist", "based": "Havana, CU / Cambridge, US", "bio": "Cuban artist whose 'behaviour art' (arte de conducta) and 'useful art' (arte útil) place audiences in political situations and build lasting social institutions.", "why": "Her works hand the microphone, the crowd or the community centre to the public and let their actions become the piece.", "role_zh": "艺术家与社会行动者", "based_zh": "哈瓦那，古巴／剑桥，美国", "bio_zh": "古巴艺术家，她的“行为艺术”（arte de conducta）与“有用的艺术”（arte útil）把观众置于政治情境之中，并建立持续运作的社会机构。", "why_zh": "她把麦克风、人群或社区中心交给公众，让公众的行动成为作品。", "discovered_via": "seed", "work_count": 3}, {"id": "ai-weiwei", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Ai_Weiwei"}, "connected_to": [], "name": "Ai Weiwei", "kind": "person", "role": "Artist, architect and activist", "based": "Lisbon, PT", "bio": "Chinese artist working across installation, architecture, film and social media, known for large participatory projects and for his critique of state power.", "why": "Fairytale used an open call on his blog to bring 1,001 Chinese citizens to documenta 12, making their journey the work.", "role_zh": "艺术家、建筑师与社会行动者", "based_zh": "里斯本，葡萄牙", "bio_zh": "中国艺术家，创作涵盖装置、建筑、电影与社交媒体，以大型参与式项目和对国家权力的批评著称。", "why_zh": "《童话》通过他博客上的公开征集，把 1001 名中国公民带到第十二届卡塞尔文献展，他们的旅程就是作品。", "discovered_via": "seed", "work_count": 1}, {"id": "jeremy-deller", "links": {"site": "https://www.jeremydeller.org/", "wikipedia": "https://en.wikipedia.org/wiki/Jeremy_Deller"}, "connected_to": [], "name": "Jeremy Deller", "kind": "person", "role": "Artist", "based": "London, UK", "bio": "British artist and Turner Prize winner (2004) who makes processions, re-enactments and public events with large casts of non-professionals.", "why": "He designs the frame (a re-enactment, a card, a silence) and lets hundreds of volunteers carry it into public space.", "role_zh": "艺术家", "based_zh": "伦敦，英国", "bio_zh": "英国艺术家，2004 年特纳奖得主，以大量非专业参与者组织游行、历史重演和公共事件。", "why_zh": "他设计框架（一场重演、一张卡片、一种沉默），再让数百名志愿者把它带进公共空间。", "discovered_via": "seed", "work_count": 2}, {"id": "gillian-wearing", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Gillian_Wearing"}, "connected_to": [], "name": "Gillian Wearing", "kind": "person", "role": "Artist and photographer", "based": "London, UK", "bio": "British artist and Turner Prize winner (1997) working with photography and video on confession, identity and the gap between public and private selves.", "why": "Her Signs series handed the caption to the people in the picture: a single instruction to strangers produced hundreds of self-authored portraits.", "role_zh": "艺术家与摄影师", "based_zh": "伦敦，英国", "bio_zh": "英国艺术家，1997 年特纳奖得主，以摄影和影像探讨告白、身份以及公共自我与私人自我之间的落差。", "why_zh": "她的《标语》系列把图注交给画面中的人：给陌生人的一条指令，产生了数百张由他们自己署名的肖像。", "discovered_via": "seed", "work_count": 1}, {"id": "rirkrit-tiravanija", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Rirkrit_Tiravanija"}, "connected_to": [], "name": "Rirkrit Tiravanija", "kind": "person", "role": "Artist", "based": "New York, US / Chiang Mai, TH", "bio": "Thai artist born in Buenos Aires whose installations since the early 1990s turn galleries into kitchens, living rooms and meeting places.", "why": "His cooking pieces are a standing offer to visitors (free food, a shared table), and the social life that follows is the work.", "role_zh": "艺术家", "based_zh": "纽约，美国／清迈，泰国", "bio_zh": "生于布宜诺斯艾利斯的泰国艺术家，自 1990 年代初起把画廊变成厨房、客厅和聚会场所。", "why_zh": "他的烹饪作品是向观众发出的长期邀请（免费食物、共享餐桌），随之发生的社交生活就是作品。", "discovered_via": "seed", "work_count": 1}, {"id": "lygia-clark", "links": {"site": "https://portal.lygiaclark.org.br/", "wikipedia": "https://en.wikipedia.org/wiki/Lygia_Clark"}, "connected_to": ["helio-oiticica"], "name": "Lygia Clark", "kind": "person", "role": "Artist and therapist", "based": "Rio de Janeiro, BR", "bio": "Brazilian artist (1920–1988), co-founder of Neo-Concretism, who moved from painting to 'propositions' that participants complete with their own bodies, and later to therapy.", "why": "She replaced the art object with an instruction or a shared action; the work happens only when others carry it out.", "role_zh": "艺术家与治疗师", "based_zh": "里约热内卢，巴西", "bio_zh": "巴西艺术家（1920–1988），新具体主义的创始人之一，从绘画转向由参与者用身体完成的“提议”，后来转向治疗实践。", "why_zh": "她用一条指令或一次共同行动取代艺术品；只有别人去做，作品才会发生。", "discovered_via": "seed", "work_count": 2}, {"id": "helio-oiticica", "links": {"wikipedia": "https://en.wikipedia.org/wiki/H%C3%A9lio_Oiticica"}, "connected_to": ["lygia-clark"], "name": "Hélio Oiticica", "kind": "person", "role": "Artist", "based": "Rio de Janeiro, BR", "bio": "Brazilian artist (1937–1980) of the Neo-Concrete movement whose Parangolés, Penetrables and Tropicália turned viewers into wearers, dancers and inhabitants.", "why": "His Parangolé capes exist fully only when someone puts one on and moves; he made them with dancers of the Mangueira samba school.", "role_zh": "艺术家", "based_zh": "里约热内卢，巴西", "bio_zh": "巴西艺术家（1937–1980），新具体主义成员，他的《帕兰戈莱》《可穿透物》和《热带主义》把观众变成穿戴者、舞者和居住者。", "why_zh": "他的《帕兰戈莱》斗篷只有在有人穿上并舞动时才完整存在；它们是与芒格拉桑巴学校的舞者一起完成的。", "discovered_via": "seed", "work_count": 1}, {"id": "guy-debord", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Guy_Debord"}, "connected_to": [], "name": "Guy Debord", "kind": "person", "role": "Writer, filmmaker and founder of the Situationist International", "based": "Paris, FR", "bio": "French theorist (1931–1994), founder of the Letterist International and the Situationist International (1957–1972), author of The Society of the Spectacle.", "why": "He wrote explicit procedures for groups (the dérive) and a rule-based strategy game, treating play and drifting as methods against the spectacle.", "role_zh": "作家、电影人、情境主义国际创始人", "based_zh": "巴黎，法国", "bio_zh": "法国理论家（1931–1994），字母主义国际与情境主义国际（1957–1972）的创始人，著有《景观社会》。", "why_zh": "他为群体写下明确的程序（漂移），也设计了一套规则化的战略游戏，把游戏与漂移当作对抗景观的方法。", "discovered_via": "seed", "work_count": 2}, {"id": "suzanne-lacy", "links": {"site": "https://www.suzannelacy.com/", "wikipedia": "https://en.wikipedia.org/wiki/Suzanne_Lacy"}, "connected_to": [], "name": "Suzanne Lacy", "kind": "person", "role": "Artist and educator", "based": "Los Angeles, US", "bio": "American artist who since the 1970s has staged large public performances with communities, often on women, ageing and violence, and who coined the term 'new genre public art'.", "why": "Her performances give hundreds of participants a score of simple actions and a shared conversation, and broadcast the result.", "role_zh": "艺术家与教育者", "based_zh": "洛杉矶，美国", "bio_zh": "美国艺术家，自 1970 年代起与社群一起完成大型公共表演，常关注女性、衰老与暴力，并提出“新类型公共艺术”一词。", "why_zh": "她的表演给数百名参与者一套简单动作的乐谱和一场共同的对话，再把结果播出。", "discovered_via": "seed", "work_count": 1}, {"id": "thomas-hirschhorn", "links": {"site": "https://www.thomashirschhorn.com/", "wikipedia": "https://en.wikipedia.org/wiki/Thomas_Hirschhorn"}, "connected_to": [], "name": "Thomas Hirschhorn", "kind": "person", "role": "Artist", "based": "Paris, FR", "bio": "Swiss artist who builds temporary structures from cheap materials, including a series of 'monuments' to philosophers built and run with residents of housing estates.", "why": "His monuments are built, staffed and used by the local residents under rules he sets: paid work, daily programme, fixed duration.", "role_zh": "艺术家", "based_zh": "巴黎，法国", "bio_zh": "瑞士艺术家，用廉价材料搭建临时结构，其中包括与公共住宅区居民一起建造和运营的一系列哲学家“纪念碑”。", "why_zh": "他的纪念碑由当地居民在他设定的规则下建造、值守和使用：有报酬的工作、每日节目、固定期限。", "discovered_via": "seed", "work_count": 1}, {"id": "lee-mingwei", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Lee_Mingwei"}, "connected_to": [], "name": "Lee Mingwei", "kind": "person", "role": "Artist", "based": "Paris, FR / Taipei, TW", "bio": "Taiwanese-American artist whose participatory installations are built on gifts, meals, letters and conversations between strangers.", "why": "His works are simple conditions attached to a gift, which visitors carry out of the museum and into the city.", "role_zh": "艺术家", "based_zh": "巴黎，法国／台北", "bio_zh": "台裔美国艺术家，他的参与式装置建立在陌生人之间的礼物、饭食、信件和对话之上。", "why_zh": "他的作品是附在一份礼物上的简单条件，由观众带出美术馆、带进城市去完成。", "discovered_via": "seed", "work_count": 1}, {"id": "collective-actions", "links": {"site": "https://www.collectiveactionsgroup.org/en", "wikipedia": "https://en.wikipedia.org/wiki/Andrei_Monastyrski"}, "connected_to": [], "name": "Collective Actions", "kind": "collective", "role": "Performance group of Moscow Conceptualism", "based": "Moscow, RU", "bio": "Group founded in March 1976 by Andrei Monastyrski, Nikita Alekseev, Georgy Kizevalter and Lev Rubinstein, later joined by Nikolai Panitkov, Elena Elagina, Igor Makarevich, Sergei Romashko and Sabine Hänsgen.", "why": "Their 'Trips Out of Town' invited a circle of viewers into empty fields where the viewers' waiting, walking and testimony became the action, then documented it in samizdat volumes.", "role_zh": "莫斯科观念主义表演团体", "based_zh": "莫斯科，俄罗斯", "bio_zh": "1976 年 3 月由安德烈·莫纳斯蒂尔斯基、尼基塔·阿列克谢耶夫、格奥尔基·基泽瓦尔特和列夫·鲁宾斯坦创立，后来尼古拉·帕尼特科夫、叶莲娜·叶拉金娜、伊戈尔·马卡列维奇、谢尔盖·罗马什科和萨比娜·亨斯根加入。", "why_zh": "他们的“出城之旅”邀请一批观众走进空旷的田野，观众的等待、行走和见证就是行动本身，之后再编入地下出版的文集。", "discovered_via": "seed", "work_count": 1}, {"id": "hans-haacke", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Hans_Haacke"}, "connected_to": [], "name": "Hans Haacke", "kind": "person", "role": "Artist", "based": "New York, US", "bio": "German-born artist who moved from physical and biological systems in the 1960s to 'real-time social systems': polls, visitor profiles and investigations of art-world power.", "why": "His visitor polls make the museum audience produce the work's data, in public, under a question he sets.", "role_zh": "艺术家", "based_zh": "纽约，美国", "bio_zh": "出生于德国的艺术家，1960 年代从物理与生物系统转向“实时社会系统”：民意调查、观众画像，以及对艺术界权力的调查。", "why_zh": "他的观众投票让美术馆观众在他提出的问题下，当众生产作品的数据。", "discovered_via": "seed", "work_count": 1}, {"id": "paul-ramirez-jonas", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Paul_Ram%C3%ADrez_Jonas"}, "connected_to": [], "name": "Paul Ramírez Jonas", "kind": "person", "role": "Artist", "based": "New York, US", "bio": "Artist born in California and raised in Honduras whose public works use civic rituals such as keys, oaths and public speech as materials.", "why": "Key to the City let anyone confer a civic honour on anyone else and turned the key into a pass to a network of sites.", "role_zh": "艺术家", "based_zh": "纽约，美国", "bio_zh": "生于加州、在洪都拉斯长大的艺术家，他的公共作品以钥匙、誓词、公开发言等公民仪式为材料。", "why_zh": "《城市之钥》让任何人都能把一项公民荣誉授予任何人，并把钥匙变成通往一组地点的通行证。", "discovered_via": "seed", "work_count": 1}, {"id": "tom-marioni", "links": {"site": "http://tommarioni.com/", "wikipedia": "https://en.wikipedia.org/wiki/Tom_Marioni"}, "connected_to": [], "name": "Tom Marioni", "kind": "person", "role": "Conceptual artist; founder of the Museum of Conceptual Art", "based": "San Francisco, US", "bio": "American conceptual artist who founded the Museum of Conceptual Art (MOCA) in San Francisco in 1970, which he described as a large-scale social work of art.", "why": "He declared a recurring social gathering an artwork and has kept it running for decades.", "role_zh": "观念艺术家；观念艺术博物馆创始人", "based_zh": "旧金山，美国", "bio_zh": "美国观念艺术家，1970 年在旧金山创立观念艺术博物馆（MOCA），并称之为一件大尺度的社会艺术作品。", "why_zh": "他把一场定期的社交聚会宣布为艺术作品，并让它持续了几十年。", "discovered_via": "seed", "work_count": 1}, {"id": "valie-export", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Valie_Export"}, "connected_to": [], "name": "VALIE EXPORT", "kind": "person", "role": "Artist and filmmaker", "based": "Vienna, AT", "bio": "Austrian artist (1940–2026) and pioneer of feminist performance, Expanded Cinema and video, often working with Peter Weibel in the late 1960s.", "why": "Tapp und Tastkino offered passers-by one rule-bound act of touch in public, making the audience's choice the content of the 'film'.", "role_zh": "艺术家与电影人", "based_zh": "维也纳，奥地利", "bio_zh": "奥地利艺术家（1940–2026），女性主义行为艺术、扩展电影和录像艺术的先驱，1960 年代末常与彼得·魏贝尔合作。", "why_zh": "《触摸电影》在公共场合给路人一个受规则约束的触摸行为，观众的选择就是这部“电影”的内容。", "discovered_via": "seed", "work_count": 1}, {"id": "improv-everywhere", "links": {"site": "https://improveverywhere.com/", "wikipedia": "https://en.wikipedia.org/wiki/Improv_Everywhere"}, "connected_to": [], "name": "Improv Everywhere", "kind": "collective", "role": "Public performance collective founded by Charlie Todd", "based": "New York, US", "bio": "New York group founded by Charlie Todd in 2001 that stages unannounced 'missions' in public places with volunteer 'agents' recruited online.", "why": "Its missions are short written instructions sent to hundreds of volunteers, who carry them out in synchrony among unsuspecting passers-by.", "role_zh": "查理·托德创立的公共表演团体", "based_zh": "纽约，美国", "bio_zh": "查理·托德于 2001 年在纽约创立的团体，在公共场所以网上招募的志愿“特工”执行事先不宣布的“任务”。", "why_zh": "它的任务是发给数百名志愿者的简短书面指令，他们在不知情的路人中同步执行。", "discovered_via": "seed", "work_count": 1}, {"id": "jack-burnham", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Jack_Burnham"}, "connected_to": [], "name": "Jack Burnham", "kind": "person", "role": "Artist, critic and curator", "based": "Chicago, US", "bio": "American artist and critic (1931–2019) who brought systems theory and cybernetics into art criticism in Artforum and curated the 1970 exhibition Software at the Jewish Museum.", "why": "He argued that art was moving from objects to systems of relations between people, machines and institutions.", "role_zh": "艺术家、评论家与策展人", "bio_zh": "美国艺术家与评论家（1931–2019），在《Artforum》上把系统论和控制论引入艺术批评，并于 1970 年在犹太博物馆策划展览 Software。", "why_zh": "他提出艺术正从物体转向由人、机器和机构之间关系构成的系统。", "based_zh": "芝加哥，美国", "discovered_via": "seed", "work_count": 2}, {"id": "roy-ascott", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Roy_Ascott"}, "connected_to": [], "name": "Roy Ascott", "kind": "person", "role": "Artist and theorist of telematic art", "based": "London, UK", "bio": "British artist and educator (born 1934) who developed cybernetic art teaching in the 1960s and telematic network artworks from the late 1970s.", "why": "He framed networked art as distributed authorship, where meaning is made by many participants connected through a network.", "role_zh": "艺术家、远程通信艺术理论家", "bio_zh": "英国艺术家与教育者（1934 年生），1960 年代发展出控制论式的艺术教学，1970 年代末起创作远程通信网络作品。", "why_zh": "他把网络艺术阐释为分布式创作：意义由通过网络相连的众多参与者共同生成。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 1}, {"id": "benjamin-buchloh", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Benjamin_Buchloh"}, "connected_to": ["sol-lewitt"], "name": "Benjamin H. D. Buchloh", "kind": "person", "role": "Art historian", "based": "Cambridge, MA, US", "bio": "German art historian (born 1941) and editor of October, known for his histories of Conceptual art and postwar European art.", "why": "He described Conceptual art as an 'aesthetic of administration': art made of certificates, lists, contracts and bureaucratic procedures.", "role_zh": "艺术史学者", "bio_zh": "德国艺术史学者（1941 年生），《October》编辑，以观念艺术和战后欧洲艺术研究著称。", "why_zh": "他把观念艺术描述为一种“管理美学”：由证书、清单、契约和官僚程序构成的艺术。", "based_zh": "马萨诸塞州剑桥，美国", "discovered_via": "sol-lewitt", "work_count": 1}, {"id": "alexander-galloway", "links": {"site": "http://cultureandcommunication.org/galloway/", "wikipedia": "https://en.wikipedia.org/wiki/Alexander_R._Galloway"}, "connected_to": ["eugene-thacker"], "name": "Alexander R. Galloway", "kind": "person", "role": "Media theorist and programmer", "based": "New York, US", "bio": "American media theorist at New York University and a founding member of the software art collective RSG (Radical Software Group).", "why": "His book Protocol gave art and media theory its working definition of protocol as the form control takes in decentralized networks.", "role_zh": "媒介理论家、程序员", "bio_zh": "美国媒介理论家，任教于纽约大学，软件艺术团体 RSG（Radical Software Group）的创始成员。", "why_zh": "他的《Protocol》一书为艺术与媒介理论提供了“协议”的基本定义：协议是控制在去中心化网络中的存在形式。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "eugene-thacker", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Eugene_Thacker"}, "connected_to": ["alexander-galloway"], "name": "Eugene Thacker", "kind": "person", "role": "Philosopher and media theorist", "based": "New York, US", "bio": "American philosopher and writer, professor at The New School, who has written on biotechnology, networks and the philosophy of horror.", "why": "With Galloway he wrote The Exploit, a theory of how networks are controlled and how they can be resisted from inside their protocols.", "role_zh": "哲学家、媒介理论家", "bio_zh": "美国哲学家与作家，任教于新学院（The New School），著述涉及生物技术、网络与恐怖哲学。", "why_zh": "他与 Galloway 合著《The Exploit》，讨论网络如何被控制，以及如何从协议内部进行抵抗。", "based_zh": "纽约，美国", "discovered_via": "alexander-galloway", "work_count": 1}, {"id": "florian-cramer", "links": {}, "connected_to": [], "name": "Florian Cramer", "kind": "person", "role": "Writer and researcher on code and culture", "based": "Rotterdam, NL", "bio": "German writer and researcher on literature, computing and media culture, long associated with the Piet Zwart Institute and Willem de Kooning Academy in Rotterdam.", "why": "He traced the idea of executable instructions from magic formulas and combinatory poetry to software, linking scores to code.", "role_zh": "代码与文化研究者、作家", "bio_zh": "德国作家与研究者，研究文学、计算与媒介文化，长期任职于鹿特丹 Piet Zwart Institute 和 Willem de Kooning 学院。", "why_zh": "他追溯了“可执行指令”的观念：从咒语和组合诗歌一直到软件，把乐谱与代码联系起来。", "based_zh": "鹿特丹，荷兰", "discovered_via": "seed", "work_count": 1}, {"id": "nicolas-bourriaud", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Nicolas_Bourriaud"}, "connected_to": ["claire-bishop"], "name": "Nicolas Bourriaud", "kind": "person", "role": "Curator and critic", "based": "Paris, FR", "bio": "French curator and writer, co-founder of the Palais de Tokyo, who named the 1990s tendency of artworks built from social encounters 'relational aesthetics'.", "why": "He made human relations and the situations an artist sets up the recognised material of contemporary art.", "role_zh": "策展人、评论家", "bio_zh": "法国策展人与作家，东京宫（Palais de Tokyo）联合创办人，把 1990 年代以社交相遇为材料的艺术倾向命名为“关系美学”。", "why_zh": "他让人际关系以及艺术家设定的情境成为当代艺术公认的材料。", "based_zh": "巴黎，法国", "discovered_via": "seed", "work_count": 1}, {"id": "claire-bishop", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Claire_Bishop"}, "connected_to": ["grant-kester", "nicolas-bourriaud"], "name": "Claire Bishop", "kind": "person", "role": "Art historian and critic", "based": "New York, US", "bio": "British art historian, professor at the CUNY Graduate Center, who writes on participatory art, installation and performance.", "why": "She wrote the standard history and critique of participatory art, asking what audiences actually do and who sets the rules.", "role_zh": "艺术史学者、评论家", "bio_zh": "英国艺术史学者，任教于纽约市立大学研究生中心，研究参与式艺术、装置与表演。", "why_zh": "她写出了参与式艺术的标准历史与批评，追问观众实际做了什么、规则由谁设定。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 2}, {"id": "grant-kester", "links": {}, "connected_to": ["claire-bishop"], "name": "Grant Kester", "kind": "person", "role": "Art historian", "based": "San Diego, US", "bio": "American art historian at the University of California, San Diego, who studies collaborative and socially engaged art.", "why": "He described 'dialogical art', where the work is a structured conversation between an artist and a community.", "role_zh": "艺术史学者", "bio_zh": "美国艺术史学者，任教于加州大学圣地亚哥分校，研究协作式与社会介入式艺术。", "why_zh": "他提出“对话性艺术”：作品是艺术家与社区之间一场有结构的对话。", "based_zh": "圣地亚哥，美国", "discovered_via": "claire-bishop", "work_count": 1}, {"id": "ruth-catlow", "links": {"site": "https://ruthcatlow.net/", "wikipedia": "https://en.wikipedia.org/wiki/Ruth_Catlow"}, "connected_to": ["marc-garrett", "penny-rafferty", "primavera-de-filippi"], "name": "Ruth Catlow", "kind": "person", "role": "Artist, curator and co-founder of Furtherfield", "based": "London, UK", "bio": "British artist and curator, co-founder and co-artistic director of Furtherfield, and a leading researcher of blockchain, DAOs and the arts.", "why": "Her edited books set the agenda for artists treating blockchains and DAOs as tools to redesign how art is owned and governed.", "role_zh": "艺术家、策展人，Furtherfield 联合创办人", "bio_zh": "英国艺术家与策展人，Furtherfield 联合创办人及联合艺术总监，是区块链、DAO 与艺术领域的重要研究者。", "why_zh": "她主编的书为“艺术家用区块链和 DAO 重新设计艺术的所有与治理”设定了议程。", "based_zh": "伦敦，英国", "discovered_via": "seed", "work_count": 2}, {"id": "marc-garrett", "links": {}, "connected_to": ["ruth-catlow"], "name": "Marc Garrett", "kind": "person", "role": "Artist, writer and co-founder of Furtherfield", "based": "London, UK", "bio": "British artist, writer and curator who co-founded the London art and technology organisation Furtherfield with Ruth Catlow in 1996.", "why": "He co-edited the first book on what blockchains mean for art production and distribution.", "role_zh": "艺术家、作家，Furtherfield 联合创办人", "bio_zh": "英国艺术家、作家与策展人，1996 年与 Ruth Catlow 共同创办伦敦艺术与技术机构 Furtherfield。", "why_zh": "他参与主编了第一本讨论区块链对艺术生产与传播意味着什么的书。", "based_zh": "伦敦，英国", "discovered_via": "ruth-catlow", "work_count": 1}, {"id": "penny-rafferty", "links": {}, "connected_to": ["ruth-catlow"], "name": "Penny Rafferty", "kind": "person", "role": "Writer and researcher", "bio": "Writer and researcher working on art, blockchain and DAOs, and co-editor of Radical Friends with Ruth Catlow.", "why": "She helped shift the art-and-blockchain debate from NFTs toward DAOs as a way for artists to organise.", "role_zh": "作家、研究者", "bio_zh": "研究艺术、区块链与 DAO 的作家和研究者，与 Ruth Catlow 共同主编《Radical Friends》。", "why_zh": "她推动艺术与区块链的讨论从 NFT 转向 DAO，把 DAO 视为艺术家自我组织的方式。", "discovered_via": "ruth-catlow", "work_count": 1}, {"id": "rhea-myers", "links": {"site": "https://rhea.art/"}, "connected_to": ["ruth-catlow"], "name": "Rhea Myers", "kind": "person", "role": "Artist, writer and hacker", "bio": "Artist, hacker and writer who has made blockchain artworks since 2011, including early smart-contract works and conceptual pieces about value and ownership.", "why": "One of the first artists to treat smart contracts as a conceptual-art medium, and a sharp critic of crypto culture.", "role_zh": "艺术家、作家、黑客", "bio_zh": "艺术家、黑客与作家，自 2011 年起创作区块链艺术，包括早期的智能合约作品以及关于价值与所有权的观念作品。", "why_zh": "她是最早把智能合约当作观念艺术媒介的艺术家之一，也是加密文化的尖锐批评者。", "discovered_via": "seed", "work_count": 1}, {"id": "kei-kreutler", "links": {"site": "https://keikreutler.net/"}, "connected_to": [], "name": "Kei Kreutler", "kind": "person", "role": "Artist, writer and co-founder of Gnosis Guild", "bio": "Artist and writer working on decentralized organisations, co-founder of Gnosis Guild, which builds open tools for DAOs.", "why": "Her essay places DAOs in a longer history of cooperatives and game guilds, giving art DAOs a lineage beyond crypto.", "role_zh": "艺术家、作家，Gnosis Guild 联合创办人", "bio_zh": "研究去中心化组织的艺术家与作家，Gnosis Guild 联合创办人，该团队为 DAO 开发开源工具。", "why_zh": "她的文章把 DAO 放进合作社和游戏公会的长历史里，为艺术 DAO 提供了加密之外的谱系。", "discovered_via": "seed", "work_count": 1}, {"id": "primavera-de-filippi", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Primavera_De_Filippi"}, "connected_to": ["aaron-wright", "ruth-catlow"], "name": "Primavera De Filippi", "kind": "person", "role": "Legal scholar and artist", "based": "Paris, FR", "bio": "Researcher at the CNRS in Paris and faculty associate at Harvard's Berkman Klein Center, who studies blockchain governance and makes artworks such as the blockchain-based flower Plantoid.", "why": "She works on both sides of protocol art: the law of self-executing code and artworks that own and reproduce themselves.", "role_zh": "法学学者、艺术家", "bio_zh": "巴黎法国国家科学研究中心（CNRS）研究员、哈佛 Berkman Klein 中心研究员，研究区块链治理，并创作了基于区块链的机械花 Plantoid 等作品。", "why_zh": "她同时处在协议艺术的两端：研究自动执行代码的法律，也创作能拥有并繁殖自己的作品。", "based_zh": "巴黎，法国", "discovered_via": "seed", "work_count": 1}, {"id": "aaron-wright", "links": {}, "connected_to": ["primavera-de-filippi"], "name": "Aaron Wright", "kind": "person", "role": "Legal scholar", "based": "New York, US", "bio": "American law professor at Cardozo School of Law, where he directs the Tech Startup Clinic, and co-author of Blockchain and the Law.", "why": "He helped define how smart contracts and DAOs relate to legal rules, the frame artists now use for contract-based works.", "role_zh": "法学学者", "bio_zh": "美国法学教授，任教于 Cardozo 法学院并主持其科技创业法律诊所，《Blockchain and the Law》合著者。", "why_zh": "他帮助界定智能合约与 DAO 同法律规则的关系，这正是艺术家创作合约作品时所依托的框架。", "based_zh": "纽约，美国", "discovered_via": "primavera-de-filippi", "work_count": 1}, {"id": "amy-whitaker", "links": {}, "connected_to": [], "name": "Amy Whitaker", "kind": "person", "role": "Researcher in arts entrepreneurship", "based": "New York, US", "bio": "American writer and professor at New York University's Steinhardt School who studies art markets, artists' equity and blockchain.", "why": "She mapped the early uses of blockchain in the arts and proposed shared-equity models that give artists a stake in resales.", "role_zh": "艺术创业研究者", "bio_zh": "美国作家，纽约大学 Steinhardt 学院教授，研究艺术市场、艺术家权益与区块链。", "why_zh": "她梳理了区块链在艺术中的早期用途，并提出让艺术家分享转售收益的共同权益模式。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}, {"id": "summer-of-protocols", "links": {"site": "https://summerofprotocols.com/"}, "connected_to": ["venkatesh-rao"], "name": "Summer of Protocols", "kind": "collective", "role": "Research programme on protocols", "bio": "Research programme commissioned by the Ethereum Foundation in late 2022 that brought researchers, artists and engineers together to study protocols across fields; it ran seasons from 2023 to 2025.", "why": "It built a shared vocabulary for protocols as a designable, cultural form, the ground on which 'protocolized' art and design now stand.", "role_zh": "协议研究计划", "bio_zh": "由以太坊基金会于 2022 年底委托发起的研究计划，把研究者、艺术家和工程师聚在一起跨领域研究协议，2023 至 2025 年每年举办一季。", "why_zh": "它建立了一套把协议视为可设计的文化形式的共同词汇，是“协议化”艺术与设计的理论基础。", "discovered_via": "seed", "work_count": 2}, {"id": "venkatesh-rao", "links": {"site": "https://ribbonfarm.com/", "wikipedia": "https://en.wikipedia.org/wiki/Venkatesh_Rao"}, "connected_to": ["summer-of-protocols"], "name": "Venkatesh Rao", "kind": "person", "role": "Writer and consultant", "bio": "Indian-American writer, founder of the blog Ribbonfarm, and a director of the Summer of Protocols research programme.", "why": "He led the effort to treat protocols as a general subject of study, from traffic rules to blockchains.", "role_zh": "作家、顾问", "bio_zh": "印度裔美国作家，博客 Ribbonfarm 创办人，Summer of Protocols 研究计划的负责人之一。", "why_zh": "他主导把协议作为一个普遍研究对象来看待，从交通规则到区块链。", "discovered_via": "summer-of-protocols", "work_count": 2}, {"id": "jacob-horne", "links": {"site": "https://jacob.energy/", "x": "https://x.com/js_horne"}, "connected_to": [], "name": "Jacob Horne", "kind": "person", "role": "Co-founder of Zora", "bio": "American entrepreneur and co-founder of Zora, an onchain protocol and platform for minting and collecting media.", "why": "His essay Hyperstructures named the idea of protocols that run without their makers, a design goal for many onchain art systems.", "role_zh": "Zora 联合创办人", "bio_zh": "美国创业者，Zora 联合创办人；Zora 是一个用于铸造和收藏媒体的链上协议与平台。", "why_zh": "他的文章《Hyperstructures》提出了“脱离创造者也能持续运行的协议”这一概念，成为许多链上艺术系统的设计目标。", "discovered_via": "seed", "work_count": 1}, {"id": "malte-rauch", "links": {}, "connected_to": [], "name": "Malte Rauch", "kind": "person", "role": "Curator and writer", "bio": "Curator and writer on blockchain art who has worked with Bright Moments and the Verse platform, and wrote the essay for the contract show World Computer Sculpture Garden.", "why": "His essay gives one of the clearest definitions of protocol art as art concerned with the rules that precede and define a computing environment.", "role_zh": "策展人、作家", "bio_zh": "研究区块链艺术的策展人与作家，曾与 Bright Moments 和 Verse 平台合作，为合约展览 World Computer Sculpture Garden 撰写文章。", "why_zh": "他的文章对协议艺术给出了最清晰的定义之一：关注先于并界定计算环境之规则的艺术。", "discovered_via": "seed", "work_count": 1}, {"id": "botao-amber-hu", "links": {"site": "https://botao.hu/"}, "connected_to": [], "name": "Botao Amber Hu", "kind": "person", "role": "Designer and researcher, Reality Design Lab", "bio": "Designer and HCI researcher who leads Reality Design Lab and publishes on protocol art, speculative design, mixed reality and decentralized AI.", "why": "Author of the first peer-reviewed study that defines protocol art through a close reading of Pak's smart-contract works.", "role_zh": "设计师、研究者，Reality Design Lab", "bio_zh": "设计师与人机交互研究者，主持 Reality Design Lab，发表关于协议艺术、思辨设计、混合现实与去中心化 AI 的研究。", "why_zh": "他撰写了第一篇通过细读 Pak 的智能合约作品来界定协议艺术的同行评审论文。", "discovered_via": "seed", "work_count": 2}, {"id": "mat-dryhurst", "links": {"wikipedia": "https://en.wikipedia.org/wiki/Mat_Dryhurst"}, "connected_to": [], "name": "Mat Dryhurst", "kind": "person", "role": "Artist, musician and researcher", "based": "Berlin, DE", "bio": "Artist and researcher who works with Holly Herndon on AI and voice projects such as Holly+, and co-founded Spawning, which builds consent tools for AI training data.", "why": "He argues that artists should design protocols directly, as 'executable critique', rather than make work inside platforms.", "role_zh": "艺术家、音乐人、研究者", "bio_zh": "艺术家与研究者，与 Holly Herndon 合作 Holly+ 等 AI 与声音项目，并联合创办 Spawning，为 AI 训练数据开发授权同意工具。", "why_zh": "他主张艺术家应当直接设计协议，作为“可执行的批判”，而不是在平台内部做作品。", "based_zh": "柏林，德国", "discovered_via": "seed", "work_count": 1}, {"id": "vera-list-center", "links": {"site": "https://www.veralistcenter.org/", "wikipedia": "https://en.wikipedia.org/wiki/Vera_List_Center_for_Art_and_Politics"}, "connected_to": [], "name": "Vera List Center for Art and Politics", "kind": "collective", "role": "Research center at The New School", "based": "New York, US", "bio": "Research and public programme centre at The New School in New York that works on the relation between art and politics through seasonal focus themes.", "why": "Its multi-year focus theme and book As for Protocols treat protocols as shared social forms that artists can rewrite.", "role_zh": "新学院下属研究中心", "bio_zh": "纽约新学院（The New School）下属的研究与公共项目中心，以分季主题研究艺术与政治的关系。", "why_zh": "它多年的焦点主题和《As for Protocols》一书把协议视为艺术家可以重写的共享社会形式。", "based_zh": "纽约，美国", "discovered_via": "seed", "work_count": 1}], "works": [{"id": "jack-butcher--credits", "creator_ids": ["jack-butcher"], "title": "Credits", "year": 2026, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "merge", "currency"], "substrate": "network", "kind": "series", "description": "Each eligible $8 payment through X Money becomes a Credit, an image of four 8 × 8 CMYK grids derived from the transaction ID. Holders can burn 80 Credits to compose a Statement and overprint Statements onto each other.", "description_zh": "每一笔符合条件、通过 X Money 支付的 8 美元都会生成一个 Credit：由交易编号生成的四个 8 × 8 CMYK 网格。持有者可以销毁 80 个 Credit 组成一个 Statement，再把 Statement 相互叠印。", "idea_en": "Payment records as printing plates: collectors spend trust (credits) to make fewer, denser prints.", "idea_zh": "把付款记录当作印版：藏家花掉“信用”，换来更少、更厚重的印张。", "protocol": "A transaction ID is hashed (SHA-256) into 256 bits, split into cyan, magenta, yellow and black 64-bit grids; the timestamp selects which layers show. Burning 80 Credits composes a Statement, one Credit per cell. Overprinting one Statement onto another burns the top one and multiplies the inks. Statements are capped at 1,526 and the minimum is 1.", "protocol_zh": "交易编号经 SHA-256 哈希得到 256 位，分成青、品红、黄、黑四个 64 位网格；时间戳决定显示哪些层。销毁 80 个 Credit 组成一个 Statement，每个 Credit 填一个格子。把一个 Statement 叠印到另一个上，上层被销毁，油墨相乘。Statement 最多 1,526 个，最少 1 个。", "collective": "Credits are being issued from X Money payments; Statement assembly opens on 1 October 2026, so how far collectors will compress the supply is not yet known.", "collective_zh": "Credit 正随着 X Money 付款不断生成；Statement 的组装于 2026 年 10 月 1 日开放，藏家会把供应压缩到什么程度尚不可知。", "keywords": ["X Money", "CMYK", "overprint", "Statement", "SHA-256", "burn"], "images": ["https://jack.art/credits/assets/art-0.svg", "https://jack.art/credits/assets/credit-0.svg"], "source_url": "https://jack.art/credits", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--economy-of-words", "creator_ids": ["jack-butcher"], "title": "Economy of Words", "year": 2026, "field": "onchain", "sub": "ownership", "mechanisms": ["exchange", "scarcity", "contract"], "substrate": "ethereum", "kind": "series", "description": "A card for each of the 2,048 words of the BIP39 seed-phrase list, each graded by a formula and sold in its own auction; winners then chose whether the card would exist as a physical graded card or as a synthetic card on Ethereum.", "description_zh": "为 BIP39 助记词表的 2,048 个单词各做一张卡片，按公式评级，逐一拍卖；得标者再选择这张卡以实体评级卡还是以太坊上的合成卡的形式存在。", "idea_en": "Three hierarchies compete over the same words: a mechanical grade, what bidders pay, and the material form each winner picks.", "idea_zh": "三种等级在同一批单词上竞争：机械评级、竞价者愿付的价格、以及每位得标者选择的材质形态。", "protocol": "Grades (10 bands) come from word length, initial letter, letter values and list position. Each auction opened at $1 and ran 20 hours 48 minutes, extended by late bids. Winners had 2,048 minutes after closing to choose physical or synthetic; the choice then locked.", "protocol_zh": "评级（10 档）由单词长度、首字母、字母分值和在列表中的位置计算。每场拍卖以 1 美元起拍，持续 20 小时 48 分钟，临近结束有出价则延时。得标者在结拍后 2,048 分钟内选择实体或合成形态，之后不可更改。", "collective": "The studio's collector board ranks 331 holders of the 2,048 words by spend and shows the physical/synthetic split; final totals are not yet published.", "collective_zh": "工作室的藏家榜按花费列出 2,048 个单词的 331 位持有者，并显示实体与合成的比例；最终总额尚未公布。", "keywords": ["BIP39", "auction", "grading", "physical or digital", "cards"], "images": ["https://jack.art/eow-hero.webp", "https://jack.art/eow-ui-collectors.webp"], "source_url": "https://jack.art/economy-of-words", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--know-your-collector", "creator_ids": ["jack-butcher"], "title": "Know Your Collector", "year": 2026, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "participation"], "substrate": "ethereum", "kind": "series", "description": "A collection of synthetic portraits in which each participant tuned an invented face (seed, pose, expression, lighting, bands) and publicly linked their chosen configuration to their X account.", "description_zh": "一组合成肖像：每位参与者调节一张虚构的脸（种子、姿态、表情、光线、条纹），并把自己选定的配置公开绑定到自己的 X 账号。", "idea_en": "Reverse KYC: instead of an institution identifying the customer, each collector chooses the invented face that will stand for them.", "idea_zh": "反向的 KYC：不是机构识别客户，而是每位藏家挑选一张代表自己的虚构面孔。", "protocol": "Access came through a patron edition. Each participant configured a portrait rendered with Google's GNM head model, kept one configuration, and posted a public verification code from an established X account, linking an account to a choice.", "protocol_zh": "参与资格来自一个赞助版数。每位参与者用谷歌 GNM 头部模型生成并调整肖像，保留一种配置，再从一个已有的 X 账号发布公开验证码，把账号与选择绑定。", "collective": "The studio's 19 August 2026 export holds 565 saved portraits, each a collector's choice rather than a likeness.", "collective_zh": "工作室 2026 年 8 月 19 日的导出记录共有 565 幅已保存的肖像，每一幅都是一位藏家的选择，而非本人相貌。", "keywords": ["KYC", "synthetic portraits", "GNM", "verification", "identity"], "images": ["https://jack.art/kyc/grid.png"], "source_url": "https://jack.art/kyc", "video": {}, "paper": {}, "also": []}, {"id": "jack-butcher--work-luck-play", "creator_ids": ["jack-butcher"], "title": "Work, Luck, Play", "year": 2026, "field": "social", "sub": "economies", "also": ["onchain"], "mechanisms": ["exchange", "chance", "circulation"], "substrate": "body", "kind": "game", "description": "Silver sculptures and a trading game presented by Silk at Art Basel Hong Kong (March 2026): a dice roll gave each participant six resin dice, and participants traded with each other to complete a set of one to six.", "description_zh": "由 Silk 在香港巴塞尔艺博会（2026 年 3 月）呈现的银雕塑与交换游戏：掷一次普通骰子决定每位参与者得到哪六颗树脂骰子，参与者相互交换，凑齐一到六的整套。", "idea_en": "Separate effort, fixed luck and choices made together: the finished set can only come from trading with strangers.", "idea_zh": "把努力、注定的运气和共同的选择分开：完整的一套只能靠与陌生人交换得来。", "protocol": "A roll of ordinary dice decided which six resin dice a visitor received (Luck's dice carry one number on every face). Participants could trade to assemble 1 through 6 and return for a signed set, or keep an incomplete combination. An online rolling system on Ethereum and a token-burning route to claim a silver die ran alongside.", "protocol_zh": "掷一次普通骰子，决定观众拿到哪六颗树脂骰子（Luck 系列的骰子每一面都是同一个数字）。参与者可以交换凑齐 1 到 6，回来换一套签名套装，也可以保留不完整的组合。同时还有以太坊上的线上掷骰系统，以及通过销毁代币领取银骰子的途径。", "collective": "Fair visitors traded dice among themselves to complete sets, and an accumulating archive ('Luckiest') recorded the rolls; no participant counts have been published.", "collective_zh": "艺博会观众彼此交换骰子来凑齐整套，一个不断累积的档案（“Luckiest”）记录下每次掷骰；参与人数尚未公布。", "keywords": ["dice", "trading", "Art Basel Hong Kong", "Silk", "Asprey Studio", "burn to claim"], "images": ["https://jack.art/play/wlp-thumb.png", "https://jack.art/play/play-dice.webp"], "source_url": "https://jack.art/work-luck-play", "video": {}, "paper": {}}, {"id": "vera-list-center--as-for-protocols", "creator_ids": ["vera-list-center"], "title": "As for Protocols", "year": 2025, "field": "theory", "sub": "systems", "also": ["social"], "mechanisms": ["constraint", "participation"], "substrate": "text", "kind": "publication", "description": "Open-access book edited by Re'al Christian, Carin Kuoni and Eriola Pira (Vera List Center for Art and Politics and Amherst College Press, 2025) with contributions by 24 artists, writers, scholars, musicians, architects and scientists on protocols.", "description_zh": "由 Re'al Christian、Carin Kuoni 与 Eriola Pira 主编的开放获取图书（Vera List 艺术与政治中心与 Amherst College Press，2025），24 位艺术家、作家、学者、音乐人、建筑师和科学家撰文讨论协议。", "idea_en": "Protocols are social forms of care and relation, and artists can write more equitable ones.", "idea_zh": "协议是关于关怀与关系的社会形式，艺术家可以写出更公平的协议。", "protocol": "The book frames protocols as 'systems of language that regulate how we relate to each other' and to technologies, and asks contributors to propose new protocols that are inclusive and equitable.", "protocol_zh": "该书把协议理解为“规范我们如何彼此相处”以及如何与技术相处的语言系统，并邀请撰稿人提出包容而公平的新协议。", "collective": "Contributors include Raven Chacon, Carolina Caycedo, Mary Maggic, Shannon Mattern, Rasheedah Phillips, Leanne Betasamosake Simpson, Ultra-red and Underground Resistance, drawn from the Center's multi-year focus theme.", "collective_zh": "撰稿人包括 Raven Chacon、Carolina Caycedo、Mary Maggic、Shannon Mattern、Rasheedah Phillips、Leanne Betasamosake Simpson、Ultra-red 和 Underground Resistance，来自该中心多年的焦点主题研究。", "keywords": ["protocols", "Vera List Center", "Amherst College Press", "open access", "social practice"], "images": ["https://veralistcenter.wpenginepowered.com/wp-content/uploads/2025/03/AfP_final-cover.png"], "paper": {"url": "https://www.fulcrum.org/concern/monographs/3t945t729", "venue": "Vera List Center for Art and Politics / Amherst College Press, 2025", "title": "As for Protocols"}, "source_url": "https://www.veralistcenter.org/publications/as-for-protocols", "video": {}}, {"id": "jack-butcher--full-set", "creator_ids": ["jack-butcher"], "title": "Full Set", "year": 2025, "field": "onchain", "sub": "supply", "mechanisms": ["scarcity", "participation", "constraint"], "substrate": "ethereum", "kind": "series", "description": "Twenty-seven editions on an Ethereum layer 2 (with Rodeo). The first 26 images were replaced by one shared grid, and the 27th edition decided whether that change would last.", "description_zh": "在以太坊二层网络上发行（与 Rodeo 合作）的 27 个版数。前 26 张图像被替换成一张共享网格，而第 27 个版数决定这一改变能否保留。", "idea_en": "A single collecting threshold that can rewrite, or undo, what earlier buyers own.", "idea_zh": "一个收藏门槛，可以改写——也可以撤销——早先买家手中的作品。", "protocol": "On 10 January 2025 Butcher announced that if token 27 sold more than 159,300 editions (the combined count of the first 26), the network grid would remain the artwork; otherwise the first 26 would revert to their original images.", "protocol_zh": "2025 年 1 月 10 日，Butcher 宣布：如果第 27 号代币的售出数量超过 159,300（前 26 个的总和），网格就成为最终作品；否则前 26 个将恢复原来的图像。", "collective": "Buyers of token 27 decided the outcome for holders of all earlier works. A progress post followed on 11 January, and the studio catalogue reports that the threshold was passed (the crossing transaction has not been published).", "collective_zh": "第 27 号代币的买家替所有早期作品的持有者决定了结果。1 月 11 日有进度帖，工作室图录称门槛已被越过（越过门槛的那笔交易尚未公开）。", "keywords": ["threshold", "mutable metadata", "Rodeo", "layer 2", "grid"], "images": ["https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/1737348451051-J8FGEY2AZNQTBMQAGJ6E/thumb.png"], "source_url": "https://jack.art/full-set", "video": {}, "paper": {}, "also": []}, {"id": "sam-spratt--masquerade", "creator_ids": ["sam-spratt"], "title": "LUCI: Chapter 6 – X. Masquerade / Masks of Luci", "year": 2025, "field": "onchain", "sub": "co-authored", "mechanisms": ["participation", "circulation", "co-authorship"], "substrate": "ethereum", "kind": "series", "description": "Chapter 6 of LUCI: 613 Masks of Luci that all began bare and took their final form from what their wearers wrote during the Masquerade, alongside the painting X. Masquerade.", "description_zh": "LUCI 第六章：613 个 Masks of Luci 起初全部是空白的，最终形态取决于佩戴者在 Masquerade 期间写下的内容，并配有画作 X. Masquerade。", "idea_en": "Each mask is shaped by the person who wears it: participation is the brush.", "idea_zh": "每个面具由佩戴它的人塑造：参与就是画笔。", "protocol": "Every Player from The Monument Game who kept custody of their ticket could claim a Mask in February 2025, and also held a Guest-list spot that allowed one more Mask to be bought: they could invite a Guest, collect it themselves, or release it to a public drawing. Masks started bare; Spratt read each wearer's Observation, Discussion and Revision, deliberated alone with the author and with the Council, and made each Mask to suit its wearer.", "protocol_zh": "凡仍持有 The Monument Game 门票的 Player，均可在 2025 年 2 月领取一个面具，并获得一个 Guest 名额，可再购买一个面具：邀请一位客人收藏、自己收藏，或放入公开抽签。面具起初是空白的；Spratt 阅读每位佩戴者的 Observation、Discussion 与 Revision，分别与作者本人以及与 Council 一起讨论，再为每位佩戴者制作面具。", "collective": "Hundreds of written contributions shaped 613 unique masks, each carrying one wearer's observation on the world; invitations passed masks from Players to new Guests.", "collective_zh": "数百份书面贡献塑造出 613 个独一无二的面具，每个都承载着一位佩戴者对世界的观察；邀请机制让面具从 Player 传递给新的客人。", "keywords": ["LUCI", "Masks of Luci", "Masquerade", "Sam Spratt", "invitation"], "images": ["https://storage.googleapis.com/luci-bc460.firebasestorage.app/artworks_sizes/2000/X_Masquerade.webp", "https://storage.googleapis.com/luci-bc460.firebasestorage.app/masks_sizes/1200/359.webp"], "source_url": "https://samspratt.com/6/masks/", "contract_url": "https://etherscan.io/address/0x4440732b0d85e2a77dcb2caedfd940154241249a", "video": {}, "paper": {}, "also": []}, {"id": "mat-dryhurst--protocol-art", "creator_ids": ["mat-dryhurst"], "title": "Protocol Art", "year": 2025, "field": "theory", "sub": "crypto-theory", "mechanisms": ["governance", "co-authorship", "constraint"], "substrate": "text", "kind": "publication", "description": "Lecture published by Carrier Bag in October 2025 in which Dryhurst argues that the most consequential aesthetic decisions now happen at the level of protocols, and that artists should design protocols instead of commenting on platforms.", "description_zh": "Carrier Bag 于 2025 年 10 月发布的讲座。Dryhurst 认为，如今最重要的审美决定发生在协议层面，艺术家应当设计协议，而不是评论平台。", "idea_en": "Build the protocol as 'executable critique': a rule set others can use that carries your values downstream.", "idea_zh": "把协议当作“可执行的批判”来建造：一套别人可以使用、并把你的价值观带到下游的规则。", "protocol": "Dryhurst uses his and Holly Herndon's projects as examples: Holly+, which lets anyone use Herndon's voice model under shared rules, the opt-out tool haveibeentrained.com, and Public Diffusion, a model trained only on public-domain data.", "protocol_zh": "Dryhurst 以他和 Holly Herndon 的项目为例：让任何人都能在共同规则下使用 Herndon 声音模型的 Holly+、退出工具 haveibeentrained.com，以及只用公有领域数据训练的模型 Public Diffusion。", "collective": "The talk extends the protocol-art discussion from smart contracts to AI: the work is judged by what other people make and decide under the rules it sets.", "collective_zh": "这场讲座把协议艺术的讨论从智能合约扩展到 AI：作品的价值取决于其他人在它设定的规则下做出和决定了什么。", "keywords": ["protocol art", "Holly+", "Spawning", "AI", "executable critique"], "video": {"url": "https://carrier-bag.net/wp-content/uploads/2025/09/mat_protocol_art_720p.mp4", "platform": "mp4", "id": "https://carrier-bag.net/wp-content/uploads/2025/09/mat_protocol_art_720p.mp4", "thumbnail": "", "embeddable": true}, "paper": {"url": "https://carrier-bag.net/video/protocol-art/", "venue": "Carrier Bag, 2025 (lecture)", "title": "Protocol Art"}, "source_url": "https://carrier-bag.net/video/protocol-art/", "images": [], "also": []}, {"id": "botao-amber-hu--protocol-futuring", "creator_ids": ["botao-amber-hu"], "title": "Protocol Futuring: Speculating Second-Order Dynamics of Protocols in Sociotechnical Infrastructural Futures", "year": 2025, "field": "theory", "sub": "crypto-theory", "mechanisms": ["constraint", "time", "co-authorship"], "substrate": "text", "kind": "publication", "description": "CHI 2026 paper by Botao Amber Hu, Samuel Chua and Helena Rong that proposes 'protocol futuring', a design method that uses protocols as the material of speculative design, tested in a relay workshop on millennial-scale knowledge preservation.", "description_zh": "Botao Amber Hu、Samuel Chua 与 Helena Rong 发表于 CHI 2026 的论文，提出“协议未来化”：一种把协议作为思辨设计材料的设计方法，并通过一场关于千年尺度知识保存的接力工作坊加以检验。", "idea_en": "Speculate on protocols, not products: watch how rules drift when they pass between groups and generations.", "idea_zh": "去推演协议而不是产品：观察规则在群体与世代之间传递时如何漂移。", "protocol": "In the Knowledge Futurama workshop, teams inherited partially formed protocol designs from earlier teams and had to reinterpret and extend them, a relay rule that made drift, jamming and adversarial readings visible.", "protocol_zh": "在 Knowledge Futurama 工作坊中，各团队从前一组那里继承尚未完成的协议设计，必须重新诠释并延续它；这种接力规则让规则的漂移、卡滞与对抗性解读变得可见。", "collective": "The multi-team relay produced protocols that changed through ambiguous handovers, shifting norms and simulated crises; the paper offers the method to HCI and design researchers studying long-lived infrastructures.", "collective_zh": "多团队接力产出的协议在含糊的交接、变化的规范和模拟危机中不断改变；论文把这一方法提供给研究长寿命基础设施的人机交互与设计研究者。", "keywords": ["protocol futuring", "speculative design", "CHI 2026", "infrastructure", "Knowledge Futurama"], "paper": {"url": "https://arxiv.org/abs/2512.06108", "doi": "10.1145/3772318.3790527", "arxiv": "2512.06108", "venue": "CHI 2026", "title": "Protocol Futuring: Speculating Second-Order Dynamics of Protocols in Sociotechnical Infrastructural Futures"}, "source_url": "https://doi.org/10.1145/3772318.3790527", "video": {}, "images": [], "also": []}, {"id": "botao-amber-hu--protocol-as-poetry", "creator_ids": ["botao-amber-hu"], "title": "Protocol as Poetry: A Case Study of Pak's Smart Contract-Based Protocol Art", "year": 2025, "field": "theory", "sub": "crypto-theory", "also": ["onchain"], "mechanisms": ["contract", "participation", "co-authorship"], "substrate": "text", "kind": "publication", "description": "Peer-reviewed paper (ARTECH 2025) that analyses Pak's smart-contract works, from The Fungible and Merge (2021) to Censored (2022) and Not Found (2023), and proposes seven characteristics of protocol art.", "description_zh": "同行评审论文（ARTECH 2025），分析 Pak 的智能合约作品，从 The Fungible 和 Merge（2021）到 Censored（2022）和 Not Found（2023），并提出协议艺术的七个特征。", "idea_en": "In protocol art the smart contract is the medium and collective participation is the message.", "idea_zh": "在协议艺术中，智能合约是媒介，集体参与是讯息。", "protocol": "The paper names seven traits: system-centric composition, autonomous governance, distributed agency and communal authorship, temporal dynamism, economy-driven engagement, poetic messages embedded in interaction rituals, and composability.", "protocol_zh": "论文归纳出七个特征：以系统而非物件为中心的构成、自治治理、分布式能动性与共同作者身份、时间上的动态性、由经济驱动的参与、嵌入互动仪式的诗意讯息，以及可组合性。", "collective": "It is one of the first academic studies to use the term 'protocol art' (or 'protocolism') for smart-contract works and distinguishes it from conceptual, generative, participatory and performance art.", "collective_zh": "这是最早用“协议艺术”（或“协议主义”）来指称智能合约作品的学术研究之一，并将其与观念艺术、生成艺术、参与式艺术和表演艺术区分开来。", "keywords": ["protocol art", "Pak", "Merge", "smart contracts", "annotated portfolio"], "paper": {"url": "https://arxiv.org/abs/2505.12393", "doi": "10.1145/3773699.3773918", "arxiv": "2505.12393", "venue": "ARTECH 2025, 12th International Conference on Digital and Interactive Arts", "title": "Protocol as Poetry: A Case Study of Pak's Smart Contract-Based Protocol Art"}, "source_url": "https://doi.org/10.1145/3773699.3773918", "video": {}, "images": []}, {"id": "jack-butcher--self-checkout", "creator_ids": ["jack-butcher"], "title": "Self Checkout", "year": 2025, "field": "social", "sub": "economies", "also": ["onchain"], "mechanisms": ["exchange", "participation", "currency"], "substrate": "body", "kind": "artwork", "description": "A retail checkout installed at Art Basel Miami Beach (Zero 10, December 2025): visitors pay what they choose and receive a thermal receipt, which is the artwork, while a split-flap display shows the artist's running balance.", "description_zh": "装在迈阿密巴塞尔艺博会（Zero 10，2025 年 12 月）里的一套自助收银台：观众自定金额付款，拿到一张热敏收据——收据就是作品；翻牌显示屏实时显示艺术家的收支余额。", "idea_en": "Take the jibe that an NFT is 'just a receipt' literally, and make every payment lengthen the work and move a public balance.", "idea_zh": "把“NFT 不过是一张收据”这句讽刺当真：每一笔付款都让作品变长，并推动一个公开的余额。", "protocol": "Three in-person kiosks and one kiosk for remote orders accept any amount; each dollar adds length to the printed receipt. Each receipt carries a printed seed phrase giving access to a non-transferable digital companion on Ethereum. Online and in-person payments feed the same displayed balance, which started from the artist's own exhibition costs.", "protocol_zh": "三台现场终端和一台远程订单终端接受任意金额；每一美元都会让打印出的收据更长。每张收据印有一组助记词，可访问以太坊上一个不可转让的数字伴生物。线上与现场付款汇入同一个公开余额，而余额的起点是艺术家自己承担的参展成本。", "collective": "Fair visitors and remote buyers paid varying amounts, lined up for signatures and pushed the displayed balance; press reports gave interim figures only, so no final total is recorded here.", "collective_zh": "艺博会观众和远程买家付出不同金额、排队求签名，并推动显示屏上的余额变化；媒体只报道了中途数字，因此这里不记录最终总额。", "keywords": ["receipt", "pay what you want", "Art Basel Miami Beach", "Zero 10", "Visualize Value", "split-flap"], "images": ["https://jack.art/self-checkout-receipts.png", "https://jack.art/self-checkout.jpg"], "source_url": "https://jack.art/self-checkout", "video": {}, "paper": {}}, {"id": "jack-butcher--1-of-1-of", "creator_ids": ["jack-butcher"], "title": "1 of 1 of ?", "year": 2024, "field": "onchain", "sub": "supply", "mechanisms": ["scarcity", "contract"], "substrate": "bitcoin", "kind": "artwork", "description": "One image issued twice in May 2024: as a unique inscription auctioned at Sotheby's and as a 24-hour open edition. The artist promised to sign a physical work once for every open edition sold.", "description_zh": "同一张图像在 2024 年 5 月以两种方式发行：一件在苏富比拍卖的唯一铭文，以及一个 24 小时开放版数。艺术家承诺每卖出一个开放版数，就在一件实体作品上签一次名。", "idea_en": "The crowd sets the edition size, and the edition size sets how much physical labour the artist owes.", "idea_zh": "人群决定版数，版数决定艺术家欠下多少体力劳动。", "protocol": "For 24 hours anyone could collect the open edition; the unique version was auctioned separately the next day. Butcher's release statement committed him to one hand-drawn signature per open edition on an ink-on-Tyvek work (Proof of Work).", "protocol_zh": "24 小时内任何人都可以收藏开放版数；唯一版次日另行拍卖。Butcher 在发布声明中承诺：每个开放版数，他都要在一件 Tyvek 纸上的墨水作品（Proof of Work）上手签一次。", "collective": "Collectors bought 35,262 editions; on 28 May 2024 Butcher reported that all 35,262 signatures were done (artist's report, not an audited ledger).", "collective_zh": "藏家共买下 35,262 个版数；2024 年 5 月 28 日 Butcher 报告 35,262 个签名全部完成（艺术家自述，并非审计记录）。", "keywords": ["open edition", "Sotheby's", "Ordinals", "signatures", "Proof of Work", "Tyvek"], "images": ["https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/1717469192803-L427F6J7HGHFUAQBRQC4/bills.png", "https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/1715790920325-JE3L05XLTD2M7CUGYHJU/1-1-jb.jpg"], "source_url": "https://jack.art/supply", "video": {}, "paper": {}, "also": []}, {"id": "malte-rauch--computation-expanded-field", "creator_ids": ["malte-rauch"], "title": "Computation in the Expanded Field", "year": 2024, "field": "theory", "sub": "crypto-theory", "also": ["onchain"], "mechanisms": ["contract", "constraint", "time"], "substrate": "text", "kind": "publication", "description": "Essay written for World Computer Sculpture Garden, a 'contract show' curated by 0xfff that opened on Ethereum in November 2024, defining protocol art as art that works with the rules that precede and define a computing environment.", "description_zh": "为 0xfff 策划、2024 年 11 月在以太坊上开幕的“合约展”World Computer Sculpture Garden 撰写的文章，把协议艺术定义为处理那些先于并界定计算环境之规则的艺术。", "idea_en": "The blockchain is not a channel for images but the material itself: a set of constraints adopted for art.", "idea_zh": "区块链不是图像的发行渠道，而是材料本身：一组为艺术所采用的约束。", "protocol": "Rauch argues that protocol artists treat distributed computation and its permanence as their medium, writing contracts that act as autonomous works rather than minting images for a marketplace.", "protocol_zh": "Rauch 认为，协议艺术家把分布式计算及其永久性当作媒介，编写作为自治作品运行的合约，而不是为市场铸造图像。", "collective": "The essay accompanies an exhibition that exists as a smart contract with no closing date, with works by artists including Rhea Myers and Sarah Friend, and is cited in academic work on protocol art.", "collective_zh": "这篇文章伴随一个以智能合约形式存在、没有闭幕日期的展览，参展艺术家包括 Rhea Myers 和 Sarah Friend；该文也被协议艺术的学术研究引用。", "keywords": ["protocol art", "World Computer Sculpture Garden", "0xfff", "contract show", "Ethereum"], "paper": {"url": "https://worldcomputersculpture.garden/essay", "venue": "World Computer Sculpture Garden, 2024", "title": "Computation in the Expanded Field"}, "source_url": "https://worldcomputersculpture.garden/", "video": {}, "images": []}, {"id": "basepaint--basepaint", "creator_ids": ["basepaint"], "title": "BasePaint", "year": 2023, "field": "onchain", "sub": "co-authored", "also": ["network"], "mechanisms": ["participation", "co-authorship", "exchange"], "substrate": "ethereum", "kind": "platform", "description": "A daily collaborative pixel canvas on the Base network: each day people holding brushes paint one shared image, and the next day the finished canvas is sold as an open edition whose proceeds go to the painters.", "description_zh": "Base 网络上的每日协作像素画布：每天，持有画笔的人共同绘制同一幅图像；第二天，完成的画布以开放版数出售，收入归画手所有。", "idea_en": "A shared canvas with a clock and a payroll: one picture a day, paid out by pixels painted.", "idea_zh": "一块带时钟和工资单的共享画布：每天一幅画，按所画像素付酬。", "protocol": "Painting requires a Brush token with a daily pixel allowance (trial brushes lose pixels over time). The community votes on the day's theme. Rules: no tracing or recolouring, no promotions or offensive symbols, all art is public domain (CC0). The contract records each painter's pixel count; when the canvas is minted, 90% of mint revenue is split pro rata by pixels and 10% goes to the operators.", "protocol_zh": "作画需要持有 Brush 代币，每支画笔每天有像素额度（试用画笔的像素会随时间减少）。社区投票决定当天主题。规则：不得描摹或重新上色，不得做推广或使用冒犯性符号，所有作品进入公共领域（CC0）。合约记录每位画手的像素数；画布被铸造时，90% 的铸造收入按像素比例分给画手，10% 归运营方。", "collective": "Since August 2023 strangers have produced a new canvas every day, more than a thousand so far, coordinating in chat and live cursors; the BasePaint contract lists over 288,000 token holders on Blockscout.", "collective_zh": "自 2023 年 8 月以来，陌生人每天完成一幅新画布，至今已超过一千幅，他们通过聊天和实时光标协调；Blockscout 显示 BasePaint 合约的代币持有地址超过 28.8 万个。", "keywords": ["BasePaint", "Base", "pixel canvas", "daily", "CC0", "open edition"], "images": ["https://basepaint.xyz/api/art/image?day=1", "https://basepaint.xyz/api/og"], "source_url": "https://basepaint.xyz", "contract_url": "https://basescan.org/address/0xBa5e05cb26b78eDa3A2f8e3b3814726305dcAc83", "code_url": "https://github.com/BasePaint/basepaint-contracts", "video": {}, "paper": {}}, {"id": "jack-butcher--checks", "creator_ids": ["jack-butcher"], "title": "Checks", "year": 2023, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "merge", "scarcity"], "substrate": "ethereum", "kind": "series", "description": "An $8 open edition of 80 checkmarks (January 2023), after Twitter began selling verification. From February 2023 collectors could destroy an edition to get an on-chain Original, then burn Originals into composites with fewer and fewer checks.", "description_zh": "一件 8 美元、画着 80 个对勾的开放版数作品（2023 年 1 月），缘起于推特开始出售认证标志。自 2023 年 2 月起，藏家可以销毁版数换取链上 Original，再把 Originals 烧成对勾越来越少的合成作品。", "idea_en": "Collectors decide which images survive: every composite destroys a work, and choosing not to act is also part of the piece.", "idea_zh": "由藏家决定哪些图像存活：每一次合成都销毁一件作品，而选择不动也是作品的一部分。", "protocol": "Checks – VV Edition was open for 24 hours at $8. Any holder may, with no deadline, burn an Edition to mint an Original with the same token number, rendered as an animated SVG from on-chain data. Two Originals with the same check count can be composited into one: 80 → 40 → 20 → 10 → 5 → 4 → 1 check; the holder picks which token number survives and the parents set the colours. At the last stage 64 single checks make a Black Check, the sum of 4,096 original editions, so at most three can ever exist.", "protocol_zh": "Checks – VV Edition 以 8 美元开放 24 小时。持有者可随时（不设期限）销毁一个 Edition，铸造同编号的 Original，其图像是由链上数据生成的动态 SVG。两个对勾数相同的 Originals 可以合成为一个：80 → 40 → 20 → 10 → 5 → 4 → 1；持有者选择保留哪个编号，颜色由两个“父本”决定。最后一步，64 个单对勾合成一个 Black Check，相当于 4,096 个原始版数，因此最多只能存在三个。", "collective": "16,031 editions were minted in the first 24 hours. By September 2026 about 3,560 Editions had never been migrated and the Originals contract held 5,347 surviving works, so collectors have burned thousands of tokens through migration and compositing (Blockscout).", "collective_zh": "最初 24 小时内共铸造 16,031 个版数。截至 2026 年 9 月，约 3,560 个 Edition 从未迁移，Originals 合约中存活 5,347 件作品——藏家通过迁移与合成已销毁数千枚代币（据 Blockscout）。", "keywords": ["Checks", "VV Edition", "Originals", "compositing", "Black Check", "Jalil Wahdatehagh", "Twitter verification"], "images": ["https://framerusercontent.com/images/Er5ZzBJPeH0FP4XccvWbrg3LU.jpg", "https://framerusercontent.com/images/zn2CN7FtJNuI5Y8lIYniJGsEwI.gif?scale-down-to=1024"], "source_url": "https://jack.art/checks-originals", "contract_url": "https://etherscan.io/address/0x036721e5A769Cc48B3189EFbb9ccE4471E8A48B1", "video": {}, "paper": {}, "also": []}, {"id": "sam-spratt--the-monument-game", "creator_ids": ["sam-spratt"], "title": "LUCI: Chapter 5 – The Monument Game", "year": 2023, "field": "onchain", "sub": "co-authored", "also": ["autonomous"], "mechanisms": ["participation", "governance", "co-authorship"], "substrate": "ethereum", "kind": "game", "description": "Chapter 5 of Sam Spratt's LUCI: a 1-of-1 painting played as a game. 256 Player tickets let holders write an 'observation' onto the painting, and the Council of Luci judged which contributions were best.", "description_zh": "Sam Spratt 的 LUCI 第五章：一幅以游戏方式展开的独版画作。256 张 Player 票让持有者在画面上写下一条“观察”，再由 Council of Luci 评判哪些贡献最好。", "idea_en": "Turn viewers into players who annotate a painting, and let the earlier collectors act as its jury.", "idea_zh": "把观众变成为画作做注解的玩家，让早期藏家担任评审。", "protocol": "In August 2023, 256 Player tickets were sold. Over four days each Player placed one observation, a few sentences or verses, on the painting. The Council of Luci (holders of the Skulls of Luci, 47 of which Spratt had given away as gifts, three held back) voted on the three Players who gave the most, who received the three remaining Skulls.", "protocol_zh": "2023 年 8 月售出 256 张 Player 票。四天内，每位 Player 在画面上放置一条观察，几句话或几行诗。Council of Luci（Skulls of Luci 的持有者；Spratt 曾把其中 47 个作为礼物送出，保留 3 个）投票选出付出最多的三位 Player，他们获得剩下的三个 Skull。", "collective": "Players wrote 256 observations that are inscribed on-chain with the finished 1-of-1, and the Council deliberated and voted on them. The work was later exhibited in Venice in 2024 by 1OF1 and collector Ryan Zurrer.", "collective_zh": "玩家写下的 256 条观察与完成的独版作品一起被铭刻在链上，Council 对其进行讨论和投票。作品后于 2024 年由 1OF1 与藏家 Ryan Zurrer 在威尼斯展出。", "keywords": ["LUCI", "Sam Spratt", "Council of Luci", "Skulls of Luci", "observations"], "images": ["https://storage.googleapis.com/luci-bc460.firebasestorage.app/artworks_sizes/2000/IX_The_Monument_Game.webp"], "source_url": "https://samspratt.com/5/ix/", "contract_url": "https://etherscan.io/address/0xda6558fa1c2452938168ef79dfd29c45aba8a32b", "video": {}, "paper": {}}, {"id": "jack-butcher--opepen-edition", "creator_ids": ["jack-butcher"], "title": "Opepen Edition", "year": 2023, "field": "onchain", "sub": "co-authored", "mechanisms": ["governance", "co-authorship", "chance"], "substrate": "ethereum", "kind": "platform", "description": "16,000 identical tokens (a geometric Pepe) that became a release system: artists propose sets of images, and holders opt their unrevealed tokens into the sets they want to become.", "description_zh": "16,000 枚相同的代币（一个几何化的 Pepe），后来变成一套发布系统：艺术家提交图像套组，持有者把尚未揭示的代币报名进自己想成为的那一套。", "idea_en": "Holders do not vote on proposals; they commit their own token to the image it will become.", "idea_zh": "持有者不是对提案投票，而是把自己的代币押在它将变成的那张图像上。", "protocol": "Opepen was a 60-minute open edition (8 January 2023). Tokens are revealed in sets of 80 with edition groups of 1, 4, 5, 10, 20 and 40. Holders of unrevealed tokens sign messages to opt into a proposed set; a set is released once opt-in demand reaches twice its supply, and tokens are then chosen at random, so opting in does not guarantee an allocation. Since March 2024 each token may opt into one set at a time; anyone may submit a set.", "protocol_zh": "Opepen 是 60 分钟的开放版数（2023 年 1 月 8 日）。代币以每套 80 枚的方式揭示，分为 1、4、5、10、20、40 六个版数组。未揭示代币的持有者通过签名报名某个提案套组；报名量达到供应量的两倍时该套发布，再随机抽取代币，所以报名不保证分配到。自 2024 年 3 月起，每枚代币同一时间只能报名一套；任何人都可以提交套组。", "collective": "Set 001 (8x8, by Butcher) was submitted on 30 April 2023 and reached consensus on 3 May 2023; later sets came from many artists. In September 2026 the contract counted 15,766 tokens held by about 8,500 addresses (Blockscout).", "collective_zh": "Set 001（8x8，Butcher 本人作品）于 2023 年 4 月 30 日提交，5 月 3 日达成共识；此后的套组来自众多艺术家。2026 年 9 月，合约记录 15,766 枚代币，分布在约 8,500 个地址中（据 Blockscout）。", "keywords": ["Opepen", "opt-in", "consensus", "sets", "Pepe", "batz", "Jalil Wahdatehagh"], "images": ["https://opepen.art/og/intro.png", "https://api.opepen.art/v1/render/sets/9dde6d38-2e6b-4e29-8f80-37a4450d49df/og?", "https://images.squarespace-cdn.com/content/v1/6547fdfa39dde777e76d89b5/eed1a6b3-b3a6-45df-89bc-8c9afce766d5/explainer.jpg"], "source_url": "https://jack.art/opepen-edition", "contract_url": "https://etherscan.io/address/0x6339e5E072086621540D0362C4e3Cea0d643E114", "video": {}, "paper": {}, "also": []}, {"id": "rhea-myers--proof-of-work", "creator_ids": ["rhea-myers"], "title": "Proof of Work: Blockchain Provocations 2011–2021", "year": 2023, "field": "theory", "sub": "crypto-theory", "also": ["onchain"], "mechanisms": ["contract", "currency", "autonomy"], "substrate": "text", "kind": "publication", "description": "Book (Urbanomic / Art Editions, 2023) collecting Myers's blockchain artworks from 2011 to 2021 with annotations, alongside her essays, reviews and fiction on crypto culture and art.", "description_zh": "一本书（Urbanomic / Art Editions，2023），收录 Myers 2011 至 2021 年的区块链作品及注释，以及她关于加密文化与艺术的文章、评论和小说。", "idea_en": "Use the tropes of Conceptual art to ask what a blockchain reveals about value and ownership.", "idea_zh": "借用观念艺术的套路，追问区块链揭示了关于价值与所有权的什么。", "protocol": "Many works in the book are small smart contracts or token schemes with a conceptual twist, whose rules collectors and the network carry out; the texts explain each rule and its art-historical reference.", "protocol_zh": "书中许多作品是带有观念转折的小型智能合约或代币机制，其规则由藏家和网络执行；文字部分解释每条规则及其艺术史参照。", "collective": "The book documents a decade of work that anticipated the NFT boom, and was also issued as an NFT special edition by Urbanomic.", "collective_zh": "这本书记录了先于 NFT 热潮的十年创作，Urbanomic 还发行了它的 NFT 特别版。", "keywords": ["Urbanomic", "crypto art", "smart contracts", "Conceptual art", "net.art"], "images": ["https://www.urbanomic.com/wp-content/uploads/2021/10/Front-Cover.jpg"], "paper": {"url": "https://www.urbanomic.com/book/proof-of-work/", "venue": "Urbanomic / Art Editions, 2023", "title": "Proof of Work: Blockchain Provocations 2011–2021"}, "source_url": "https://www.urbanomic.com/book/proof-of-work/", "video": {}}, {"id": "summer-of-protocols--program", "creator_ids": ["summer-of-protocols", "venkatesh-rao"], "title": "Summer of Protocols", "year": 2023, "field": "theory", "sub": "crypto-theory", "mechanisms": ["constraint", "governance", "participation"], "substrate": "text", "kind": "platform", "description": "Research programme commissioned by the Ethereum Foundation that ran seasons in 2023, 2024 and 2025, funding researchers, artists and engineers to study protocols across fields from blockchains to traffic, safety and diplomacy.", "description_zh": "由以太坊基金会委托的研究计划，在 2023、2024、2025 年各举办一季，资助研究者、艺术家和工程师跨领域研究协议，从区块链到交通、安全与外交。", "idea_en": "Treat protocols as a general design material that can be studied, taught and made by artists as well as engineers.", "idea_zh": "把协议当作一种通用的设计材料：它可以被研究、被教授，也可以由艺术家和工程师共同创作。", "protocol": "Each season invited cohorts of researchers to produce essays, artworks and tools under a shared brief; outputs are published openly and discussed in a public forum and newsletter.", "protocol_zh": "每一季邀请一批研究者在共同主题下产出文章、作品和工具；成果公开发布，并在公共论坛和通讯中讨论。", "collective": "SoP23 brought together 12 core and 18 affiliate researchers; across its seasons the programme counts 70-odd alumni and more than 100 research outputs, including the Protocol Reader, the ProtocolKit and a 358-page proto-textbook, and it continues as the Protocol Institute.", "collective_zh": "SoP23 汇集了 12 位核心研究者和 18 位附属研究者；各季累计约 70 位参与者、100 多项研究成果，包括 Protocol Reader、ProtocolKit 和一本 358 页的原型教科书；该计划之后延续为 Protocol Institute。", "keywords": ["Ethereum Foundation", "protocol studies", "Protocol Reader", "Protocol Institute", "Protocolized"], "images": ["https://summerofprotocols.com/wp-content/uploads/2024/03/SoP24-Hero-scaled.webp"], "paper": {"url": "https://summerofprotocols.com/about", "venue": "Summer of Protocols / Ethereum Foundation", "title": "About Summer of Protocols"}, "source_url": "https://summerofprotocols.com/", "video": {}, "also": []}, {"id": "venkatesh-rao--unreasonable-sufficiency", "creator_ids": ["venkatesh-rao", "summer-of-protocols"], "title": "The Unreasonable Sufficiency of Protocols", "year": 2023, "field": "theory", "sub": "crypto-theory", "mechanisms": ["constraint", "governance"], "substrate": "text", "kind": "publication", "description": "Pilot study by Venkatesh Rao, Tim Beiko, Danny Ryan, Josh Stark, Trent Van Epps and Bastian Aue, released in March 2023 to open the Summer of Protocols, that asks why simple protocols coordinate so much complex behaviour.", "description_zh": "由 Venkatesh Rao、Tim Beiko、Danny Ryan、Josh Stark、Trent Van Epps 与 Bastian Aue 撰写的试点研究，2023 年 3 月发布，作为 Summer of Protocols 的开篇，追问为什么简单的协议能协调如此复杂的行为。", "idea_en": "A small set of codified rules can be unreasonably sufficient: it lets large, complex cooperation emerge.", "idea_zh": "一小组成文规则可以“不合理地充分”：它能让大规模的复杂合作涌现出来。", "protocol": "The paper defines a protocol as 'a stratum of codified behavior that allows for the construction or emergence of complex coordinated behaviors at adjacent loci', and describes protocols along dimensions such as generativity, legibility, evolvability, legitimacy, play value and mortality.", "protocol_zh": "论文把协议定义为“一层成文的行为规范，使相邻位置上复杂的协调行为得以构建或涌现”，并从生成性、可读性、可演化性、正当性、游戏价值和寿命等维度描述协议。", "collective": "The text framed the research questions for the first Summer of Protocols cohort and was revised and republished in 2024 as a reference work for the programme.", "collective_zh": "这篇文本为第一届 Summer of Protocols 的研究者设定了研究问题，并于 2024 年修订再版，成为该计划的参考文献。", "keywords": ["Summer of Protocols", "coordination", "Ethereum", "ossification", "protocol theory"], "images": ["https://summerofprotocols.com/wp-content/uploads/2024/03/joshd4078_intricate_flowchart_where_symbols_morph_and_transform_1cccf476-f315-4f8f-881a-dd323482c3b4-jpg.webp"], "paper": {"url": "https://summerofprotocols.com/wp-content/uploads/2024/03/The-Unreasonable-Sufficiency-of-Protocols.pdf", "venue": "Summer of Protocols, 2023 (revised 2024)", "title": "The Unreasonable Sufficiency of Protocols"}, "source_url": "https://summerofprotocols.com/the-unreasonable-sufficiency-of-protocols-web", "video": {}, "also": []}, {"id": "pak--censored", "creator_ids": ["pak"], "title": "Censored", "year": 2022, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "participation", "time"], "substrate": "ethereum", "kind": "series", "description": "An open edition made with Julian Assange (February 2022): for 48 hours anyone could mint a token carrying a message of their own, shown under a black censor bar until Assange was freed.", "description_zh": "与朱利安·阿桑奇合作的开放版数（2022 年 2 月）：48 小时内任何人都可以铸造一枚写有自己留言的代币，留言被黑色审查条遮住，直到阿桑奇获释。", "idea_en": "Every buyer writes part of the work, and a real-world event (a prisoner's release) is the key that reveals it.", "idea_zh": "每位买家写下作品的一部分，而一个现实事件（囚徒获释）是揭开它的钥匙。", "protocol": "During the 48-hour window buyers paid any amount they chose and tokenized a message; there was no limit on the number of messages. Each token stores its text and its initial price on-chain and renders the message covered by a censor bar, with a 'Censored' trait that was to switch off only on Assange's release.", "protocol_zh": "48 小时窗口内，买家自定金额，把一条留言铸成代币，数量不设上限。每枚代币在链上保存文字和初始价格，渲染时留言被审查条遮住；“Censored”属性只有在阿桑奇获释时才会关闭。", "collective": "Tens of thousands of buyers wrote messages (token ids on the contract run past 29,700; initial prices range from 0.01 ETH upward). In June 2024, after Assange's release, Pak uncensored the tokens; the contract lists about 18,500 holders in September 2026 (Blockscout).", "collective_zh": "数万名买家写下留言（合约上的代币编号超过 29,700，初始价格从 0.01 ETH 起不等）。2024 年 6 月阿桑奇获释后，Pak 解除了代币的审查；2026 年 9 月合约约有 18,500 个持有地址（据 Blockscout）。", "keywords": ["Julian Assange", "WikiLeaks", "pay what you want", "open edition", "messages", "uncensored"], "images": ["https://www.artrights.me/wp-content/uploads/2022/02/Censored-By-Pak-Announcement-Website.jpeg", "https://www.cryptoblogs.io/wp-content/uploads/2024/02/Pak-was-here-Website.jpg"], "source_url": "https://www.artrights.me/en/censored-the-nft-project-by-pak-in-collaboration-with-julian-assange/", "contract_url": "https://etherscan.io/address/0xDa22422592Ee3623c8d3c40Fe0059CdEcF30CA79", "video": {}, "paper": {}, "also": []}, {"id": "pak--clock", "creator_ids": ["pak"], "title": "Clock", "year": 2022, "field": "autonomous", "sub": "dao", "also": ["onchain"], "mechanisms": ["time", "governance"], "substrate": "ethereum", "kind": "artwork", "description": "The single-edition token of Censored: a counter of the days Julian Assange had spent in prison, updated daily. It was auctioned in February 2022 and bought by AssangeDAO, a crowd-funded collective.", "description_zh": "Censored 系列中的单版代币：一个每天更新、记录朱利安·阿桑奇在狱中天数的计数器。2022 年 2 月拍卖，由众筹集体 AssangeDAO 买下。", "idea_en": "A 1/1 whose only content is a running count of a political fact, sold so that a crowd had to organise to own it.", "idea_zh": "一件单版作品，内容只是一个政治事实的持续计数；它的出售方式迫使一群人组织起来才能拥有它。", "protocol": "Token #1 of the Censored contract renders the number of days of Assange's imprisonment and changes every day; it was sold at auction to fund Assange's legal defence. The clock was set to stop on his release.", "protocol_zh": "Censored 合约的 1 号代币显示阿桑奇被关押的天数，每天变化；它通过拍卖出售，为阿桑奇的法律辩护筹款。时钟设定在他获释时停止。", "collective": "AssangeDAO pooled ETH from more than 10,000 contributors through Juicebox (as reported by the DAO and press) and won the auction with 16,593 ETH, about $52.8 million at the time. The token now sits in a multisig safe; the clock stopped when Assange was freed in June 2024.", "collective_zh": "AssangeDAO 通过 Juicebox 从一万多名出资者那里汇集 ETH（据该 DAO 与媒体报道），以 16,593 ETH（当时约 5,280 万美元）赢得拍卖。这枚代币现存于一个多签钱包中；2024 年 6 月阿桑奇获释时，时钟停止。", "keywords": ["AssangeDAO", "Juicebox", "Julian Assange", "dynamic NFT", "crowdfund", "Wau Holland Foundation"], "images": ["https://www.cryptoblogs.io/wp-content/uploads/2024/02/One-Thousands-Thirty-Two-Clock-1.jpg"], "source_url": "https://fortune.com/2022/02/09/supporters-of-wikileaks-founder-julian-assange-raise-56-million-to-buy-an-nft-for-his-u-s-extradition-battle/", "contract_url": "https://etherscan.io/nft/0xDa22422592Ee3623c8d3c40Fe0059CdEcF30CA79/1", "video": {}, "paper": {}}, {"id": "alexis-andre--friendship-bracelets", "creator_ids": ["alexis-andre"], "title": "Friendship Bracelets", "year": 2022, "field": "onchain", "sub": "co-authored", "also": ["score"], "mechanisms": ["circulation", "instruction", "participation"], "substrate": "ethereum", "kind": "series", "description": "A free Art Blocks project conceived with Art Blocks founder Snowfro: every holder of an Art Blocks piece could claim two generative bracelets, keep one and give the other away. Each output includes instructions to weave the bracelet by hand from embroidery floss.", "description_zh": "与 Art Blocks 创始人 Snowfro 共同构想的免费 Art Blocks 项目：每位持有 Art Blocks 作品的人可以领取两个生成式手链，自己留一个，把另一个送人。每个作品都附有用绣线亲手编织这条手链的说明。", "idea_en": "A generative artwork that asks to be given away and made by hand.", "idea_zh": "一件要求被赠送、被亲手制作的生成艺术作品。", "protocol": "Wallets holding any Art Blocks token at the 26 October 2022 snapshot could claim two mints for gas only until 10 January 2023. Holders were asked to keep one bracelet and gift the second; the artwork doubles as a pattern using standard embroidery floss colours.", "protocol_zh": "在 2022 年 10 月 26 日快照时持有任何 Art Blocks 代币的钱包，可在 2023 年 1 月 10 日前只付 gas 领取两次铸造。持有者被请求自己留一条、把第二条送人；作品同时也是一份使用标准绣线颜色的编织图样。", "collective": "Roughly 250,000 Art Blocks owners were eligible; bracelets spread as gifts to friends and newcomers, and holders wove physical versions from the on-chain patterns.", "collective_zh": "约 25 万名 Art Blocks 持有者具有领取资格；手链作为礼物流向朋友和新人，持有者还按链上图样编织出实体手链。", "keywords": ["Art Blocks", "Friendship Bracelets", "gift", "Snowfro", "phygital"], "video": {"url": "https://www.youtube.com/watch?v=_DeFATb0QB0", "platform": "youtube", "id": "_DeFATb0QB0", "thumbnail": "https://i.ytimg.com/vi/_DeFATb0QB0/maxresdefault.jpg", "embeddable": true}, "images": ["https://media-proxy.artblocks.io/0x942bc2d3e7a589fe5bd4a5c6ef9727dfd82f5c8a/1575.png", "https://whitehotmagazine.com/images/article_images/article_5567_featured-5.jpg"], "source_url": "https://whitehotmagazine.com/articles/nfts-with-diy-phygital-component/5567", "contract_url": "https://etherscan.io/address/0x942bc2d3e7a589fe5bd4a5c6ef9727dfd82f5c8a", "paper": {}}, {"id": "jacob-horne--hyperstructures", "creator_ids": ["jacob-horne"], "title": "Hyperstructures", "year": 2022, "field": "theory", "sub": "crypto-theory", "mechanisms": ["autonomy", "exchange", "time"], "substrate": "text", "kind": "publication", "description": "Essay published on 16 January 2022 that defines hyperstructures as 'crypto protocols that can run for free and forever, without maintenance, interruption or intermediaries'.", "description_zh": "2022 年 1 月 16 日发表的文章，把“超结构”定义为“能够免费、永久运行，无需维护、不会中断、没有中介的加密协议”。", "idea_en": "Build the protocol so it keeps running after you leave; then others can build on it.", "idea_zh": "把协议做成你离开后仍能运行的样子，别人才能在上面继续建造。", "protocol": "Horne lists the properties of a hyperstructure: unstoppable, free, valuable, expansive, permissionless, positive-sum and credibly neutral, running entirely onchain for as long as its chain exists.", "protocol_zh": "Horne 列出超结构的特性：不可阻止、免费、有价值、可扩展、无需许可、正和、可信中立，完全在链上运行，只要所在的链存在就一直运行。", "collective": "The term spread quickly among onchain builders and artists and shaped Zora's own protocol design; it is often used to describe artworks and platforms meant to outlive their authors.", "collective_zh": "这个词在链上开发者和艺术家中迅速传播，也塑造了 Zora 自身的协议设计；它常被用来描述那些意在比作者存续更久的作品与平台。", "keywords": ["hyperstructures", "Zora", "permissionless", "credible neutrality", "onchain"], "images": ["https://jacob.energy/img/hyper.png"], "paper": {"url": "https://jacob.energy/hyperstructures.html", "venue": "jacob.energy, 2022", "title": "Hyperstructures"}, "source_url": "https://jacob.energy/hyperstructures.html", "video": {}, "also": []}, {"id": "pak--matter", "creator_ids": ["pak"], "title": "Matter* (mass.black)", "year": 2022, "field": "onchain", "sub": "supply", "mechanisms": ["merge", "constraint", "chance"], "substrate": "ethereum", "kind": "game", "description": "A month-long 'treasure hunt' for Merge holders (1–30 April 2022): new Matter* tokens were awarded to Merge tokens that met published criteria about merges and mass at the end snapshot.", "description_zh": "为 Merge 持有者设计的一个月“寻宝”（2022 年 4 月 1 日至 30 日）：按照公布的合并次数与质量标准，在结束快照时符合条件的 Merge 代币获得新的 Matter* 代币。", "idea_en": "Reward specific collective behaviours (merging often, hoarding mass, cannibalising) so holders play the contract as a game.", "idea_zh": "奖励特定的集体行为（频繁合并、囤积质量、互相吞并），让持有者把合约当作游戏来玩。", "protocol": "Tiers of Matter* went to Merge tokens by rule: 'Hunters and Traps' for tokens with 4+ merges, 'Thief's Wise Hands' for mass × merges ≥ 100 (stealing supply from 'Scavenger's Weak Hands', mass ≥ 10), 'Cannibalism' for the most merges, 'Kings of the Hill' for the most mass, 'Titan' for the alpha, 'Three Lucky Giants' at random, and a hidden challenge tier that would unlock only if Merge supply fell below 20,000. Distribution used the end snapshot; one token could win several.", "protocol_zh": "Matter* 各层级按规则发给 Merge 代币：合并 4 次以上得“Hunters and Traps”；质量 × 合并次数 ≥ 100 得“Thief's Wise Hands”（从质量 ≥ 10 的“Scavenger's Weak Hands”中抢走名额）；合并最多得“Cannibalism”；质量最大得“Kings of the Hill”；alpha 得“Titan”；另有随机抽取的“Three Lucky Giants”，以及只有在 Merge 总量跌破 20,000 时才会解锁的隐藏挑战层。按结束快照分发，一枚代币可以赢得多个。", "collective": "The site reports a Matter* supply of 1,481 with 1,395 generated. The 'Thief' tier took all 450 places, so 'Scavenger's Weak Hands' generated none, and the challenge tier stayed locked because Merge supply did not fall below 20,000 during the event.", "collective_zh": "网站显示 Matter* 总量为 1,481，实际生成 1,395 枚。“Thief”层级拿走了全部 450 个名额，因此“Scavenger's Weak Hands”一枚也没有生成；活动期间 Merge 总量没有跌破 20,000，挑战层始终未解锁。", "keywords": ["Merge", "Matter", "Antimatter", "snapshot", "treasure hunt", "mass.black"], "images": ["https://mass.black/mass.black.png"], "source_url": "https://mass.black/", "video": {}, "paper": {}, "also": []}, {"id": "tyler-hobbs--qql", "creator_ids": ["tyler-hobbs", "dandelion-wist-mane"], "title": "QQL", "year": 2022, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "participation", "contract"], "substrate": "ethereum", "kind": "platform", "description": "A generative algorithm published as a public tool: anyone can explore its parameters and save seeds, but only the 999 Mint Pass holders can turn a chosen seed into an official QQL NFT, at any time they like.", "description_zh": "以公共工具形式发布的生成算法：任何人都可以调整参数、保存种子，但只有 999 张 Mint Pass 的持有者能把选中的种子铸成正式的 QQL NFT，而且可以在任何时候铸造。", "idea_en": "Make the collector the curator: the algorithm proposes, the community searches, and the finder is paid.", "idea_zh": "让藏家成为策展人：算法提议，社区搜寻，发现者获得回报。", "protocol": "Each Mint Pass allows one mint with no time limit. A seed embeds the address of whoever created it, and that address receives a 2% royalty on secondary sales of the NFT, so the discoverer, not necessarily the minter, is credited.", "protocol_zh": "每张 Mint Pass 可铸造一次，没有时间限制。种子中嵌入其创建者的地址，该地址在 NFT 二级销售时获得 2% 版税，因此获得回报的是“发现者”，不一定是铸造者。", "collective": "The community generated large numbers of seeds, traded and discussed them on Discord and a subreddit, formed a rotating QQL Council that curates the Seedbox of unminted seeds, and runs monthly themed challenges decided by community vote.", "collective_zh": "社区生成了大量种子，在 Discord 和 subreddit 上交换、讨论；成立轮值的 QQL Council，为尚未铸造的种子策划 Seedbox；并每月举办由社区投票决定的主题挑战。", "keywords": ["QQL", "Tyler Hobbs", "seed", "Mint Pass", "collector as curator"], "video": {"url": "https://www.youtube.com/watch?v=0mjkN2aiax0", "platform": "youtube", "id": "0mjkN2aiax0", "thumbnail": "https://i.ytimg.com/vi/0mjkN2aiax0/maxresdefault.jpg", "embeddable": true}, "images": ["https://img.qql.art/assets/qql-social.png"], "source_url": "https://qql.art/about", "contract_url": "https://etherscan.io/address/0x845dd2a7ee2a92a0518ab2135365ed63fdba0c88", "paper": {}, "also": []}, {"id": "ruth-catlow--radical-friends", "creator_ids": ["ruth-catlow", "penny-rafferty"], "title": "Radical Friends: Decentralised Autonomous Organisations and the Arts", "year": 2022, "field": "theory", "sub": "crypto-theory", "also": ["autonomous"], "mechanisms": ["governance", "contract", "autonomy"], "substrate": "text", "kind": "publication", "description": "Book edited by Ruth Catlow and Penny Rafferty (Torque Editions, 2022) with essays, interviews, exercises and prototypes on DAOs as tools for artists to encode rules, relations and values into shared ventures.", "description_zh": "Ruth Catlow 与 Penny Rafferty 主编的书（Torque Editions，2022），以文章、访谈、练习和原型讨论 DAO 如何让艺术家把规则、关系与价值写进共同事业。", "idea_en": "The most radical blockchain tool for art may be the organisation, not the token.", "idea_zh": "对艺术来说，最激进的区块链工具也许是组织，而不是代币。", "protocol": "The book treats a DAO as a rule set that peers write together and run on a blockchain: who can join, how decisions are made, how money flows. It includes exercises for groups to draft their own.", "protocol_zh": "书中把 DAO 看作同伴们共同编写、运行在区块链上的一组规则：谁可以加入、如何决策、资金如何流动；并附有供团体起草自己规则的练习。", "collective": "It collects more than five years of research by the editors and contributors such as Primavera De Filippi, Ramon Amaro, Mitchell F. Chan and eeefff, and refocused attention from NFTs toward collective organisation in the arts.", "collective_zh": "它汇集了编者及 Primavera De Filippi、Ramon Amaro、Mitchell F. Chan、eeefff 等撰稿人五年多的研究，把关注点从 NFT 转向艺术中的集体组织。", "keywords": ["DAO", "Furtherfield", "Torque Editions", "governance", "art organisations"], "images": ["https://torquetorque.net/wp-content/uploads/1-Radical-Freinds-Full-Cover-1200x833.png"], "paper": {"url": "https://torquetorque.net/publications/radical-friends/", "venue": "Torque Editions, 2022", "title": "Radical Friends: Decentralised Autonomous Organisations and the Arts"}, "source_url": "https://ruthcatlow.net/?works=radical-friends-decentralised-autonomous-organisations-and-the-arts", "video": {}}, {"id": "kei-kreutler--prehistory-of-daos", "creator_ids": ["kei-kreutler"], "title": "A Prehistory of DAOs", "year": 2021, "field": "theory", "sub": "crypto-theory", "mechanisms": ["governance", "currency"], "substrate": "text", "kind": "publication", "description": "Essay published by Gnosis Guild in July 2021, subtitled 'Cooperatives, gaming guilds, and the networks to come', that traces DAOs back to the cooperative movement and online game guilds.", "description_zh": "Gnosis Guild 于 2021 年 7 月发表的文章，副标题为“合作社、游戏公会与即将到来的网络”，把 DAO 的源头追溯到合作社运动和网络游戏公会。", "idea_en": "DAOs are not new: they are cooperatives and guilds with their rules written in code.", "idea_zh": "DAO 并不新：它们是把规则写进代码的合作社和公会。", "protocol": "Kreutler reads DAOs as organisations where a software protocol sets the operating rules, 'placing automation at its center and humans at its edges', and compares them to the Rochdale cooperative principles of 1844 and guilds' loot-sharing systems such as Dragon Kill Points.", "protocol_zh": "Kreutler 把 DAO 理解为由软件协议设定运行规则的组织，“把自动化置于中心、把人置于边缘”，并将其与 1844 年罗奇代尔合作社原则以及“屠龙点数”（DKP）等公会战利品分配制度相比较。", "collective": "The essay and its LisCon talk were widely shared in the 2021 DAO wave and are often cited by art DAOs and researchers looking for a history longer than Ethereum.", "collective_zh": "这篇文章及其在 LisCon 的演讲在 2021 年 DAO 热潮中被广泛传播，常被寻找比以太坊更长历史的艺术 DAO 和研究者引用。", "keywords": ["DAO", "cooperatives", "guilds", "DKP", "Gnosis Guild"], "images": ["https://storage.googleapis.com/papyrus_images/1ec3d26160223fb58c11a916986a6b38312b19eb14dfd8c90454cb312b3a2bea.png"], "video": {"url": "https://vimeo.com/637505710", "platform": "vimeo", "id": "637505710", "thumbnail": "https://i.vimeocdn.com/video/1280725269-66d2701f8b62642a9c11d37b5e8e298b50849752bb4f1e790?f=webp&region=us", "embeddable": true}, "paper": {"url": "https://gnosisguild.mirror.xyz/t4F5rItMw4-mlpLZf5JQhElbDfQ2JRVKAzEpanyxW1Q", "venue": "Gnosis Guild, 2021", "title": "A Prehistory of DAOs: Cooperatives, gaming guilds, and the networks to come"}, "source_url": "https://gnosisguild.mirror.xyz/t4F5rItMw4-mlpLZf5JQhElbDfQ2JRVKAzEpanyxW1Q", "also": []}, {"id": "async-art--async-music", "creator_ids": ["async-art"], "title": "Async Music (programmable music)", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "exchange"], "substrate": "ethereum", "kind": "platform", "description": "Async Art's extension of Layers to sound: musicians upload alternative versions of each stem, and owners of Stem Layer tokens choose which version plays in the song's current Master Track.", "description_zh": "Async Art 把图层机制延伸到声音：音乐人为每条分轨上传多个备选版本，Stem Layer 代币的持有者决定当前 Master Track 中播放哪一版。", "idea_en": "A song that exists as a menu of variants, mixed live by the people who own its stems.", "idea_zh": "一首歌以“变体菜单”的形式存在，由持有分轨的人现场混音。", "protocol": "The musician uploads every variant of each stem. The owner of a Stem Layer NFT selects one variant; the Master Track that everyone hears is the combination of all current selections. Separate Blank Record NFTs let a holder snapshot one audio-visual state of the Master.", "protocol_zh": "音乐人上传每条分轨的所有变体。Stem Layer NFT 的持有者选择其中一个版本；所有人听到的 Master Track 就是全部当前选择的组合。另设 Blank Record NFT，持有者可用它为 Master 的某一个视听状态存档。", "collective": "The first releases came from RAC, Verdigris Ensemble, HMLTD, and Connie Digital with Mighty33; the songs changed whenever stem owners changed their selections.", "collective_zh": "首批发行来自 RAC、Verdigris Ensemble、HMLTD，以及 Connie Digital 与 Mighty33；每当分轨持有者改变选择，歌曲就随之改变。", "keywords": ["Async Music", "stems", "Master Track", "Blank Record", "RAC"], "images": ["https://mma.prnewswire.com/media/1498556/AsyncMusic_Breakdown_Infographic.jpg"], "source_url": "https://www.prnewswire.com/news-releases/the-worlds-first-programmable-music-launch-301279780.html", "video": {}, "paper": {}, "also": []}, {"id": "dom-hofmann--blitmap", "creator_ids": ["dom-hofmann"], "title": "Blitmap", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "merge"], "substrate": "ethereum", "kind": "series", "description": "100 original 32×32 pixel artworks by 17 artists, stored on-chain, from which the community minted 1,600 'siblings' by combining the composition of one original with the palette of another.", "description_zh": "由 17 位艺术家创作、存储在链上的 100 幅 32×32 原创像素画；社区在此基础上把一幅原作的构图与另一幅的配色组合，铸造出 1,600 幅“兄弟姐妹”。", "idea_en": "Give a crowd a small, open set of originals and a recombination rule, and let it grow a universe.", "idea_zh": "给人群一小套开放的原作和一条重组规则，让他们长出一个宇宙。", "protocol": "The originals were written into the contract as data; any sibling is defined by choosing one original's composition and another's colour palette, and minting it creates a new token. Originals and much of what followed were released as open source, so anyone could build on them.", "protocol_zh": "原作以数据形式写入合约；每一幅“兄弟姐妹”都由“一幅原作的构图 + 另一幅原作的配色”定义，铸造后成为一个新代币。原作及后续大部分作品以开源方式发布，任何人都可以在其上创作。", "collective": "Collectors crafted all 1,600 siblings. Artists and fans then extended the world of Caelum with the Blitnauts expansion pack, Sup's androids, comics, cartoons, socks, shoes and toys.", "collective_zh": "藏家组合铸造出全部 1,600 幅兄弟姐妹。随后，艺术家和爱好者用 Blitnauts 扩展包、Sup 的机器人阵营、漫画、动画、袜子、鞋和玩具，把 Caelum 世界继续扩展。", "keywords": ["Blitmap", "pixel art", "remix", "siblings", "open source", "Blitnauts"], "images": ["https://www.blitmap.com/blitmap-collection-small.png", "https://blitmap.com/_next/image?url=%2F_next%2Fstatic%2Fmedia%2Fblitnaut-crop.974e3cca.webp&w=3840&q=75"], "source_url": "https://blitmap.com", "contract_url": "https://etherscan.io/address/0x8d04a8c79ceb0889bdd12acdf3fa9d207ed3ff63", "video": {}, "paper": {}, "also": []}, {"id": "suum-cuique-labs--hashmasks", "creator_ids": ["suum-cuique-labs"], "title": "Hashmasks", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "burn", "currency"], "substrate": "ethereum", "kind": "series", "description": "16,384 digital portraits painted by about 70 artists, sold in early 2021. Owners accrue a Name Changing Token (NCT) and can burn 1,830 NCT to give their mask a unique name stored on-chain.", "description_zh": "约 70 位艺术家绘制的 16,384 幅数字肖像，于 2021 年初发售。持有者会累积 Name Changing Token（NCT），销毁 1,830 NCT 即可为自己的面具起一个存储在链上、独一无二的名字。", "idea_en": "Let the collectors write the titles, and make each title cost something and exist only once.", "idea_zh": "让藏家来写标题，而且每个标题都有成本、全网唯一。", "protocol": "Every mask accrues NCT over time. To name a mask, its owner sends 1,830 NCT to the Hashmasks contract, which burns them and records the name; each name can belong to only one mask at a time.", "protocol_zh": "每个面具都会随时间累积 NCT。要为面具命名，持有者需把 1,830 NCT 发送到 Hashmasks 合约，合约将其销毁并记录名字；同一名字同一时间只能属于一个面具。", "collective": "Owners spent NCT to name their masks; because every name can exist only once, words became contested, and the on-chain naming record became part of each mask's identity and value alongside the artists' images.", "collective_zh": "持有者花费 NCT 为自己的面具命名；由于每个名字只能存在一次，词语变得需要争夺，链上的命名记录与艺术家的图像一起，成为每个面具身份与价值的一部分。", "keywords": ["Hashmasks", "NCT", "naming", "burn", "Suum Cuique"], "video": {"url": "https://www.youtube.com/watch?v=cDz8Y2UPeMg", "platform": "youtube", "id": "cDz8Y2UPeMg", "thumbnail": "https://i.ytimg.com/vi/cDz8Y2UPeMg/hqdefault.jpg", "embeddable": true}, "images": ["https://hashmasksstore.blob.core.windows.net/hashmasks/1.jpg", "https://img.phemex.com/v1/4caf239c/hashmasks-1024x576.jpg"], "source_url": "https://www.thehashmasks.com", "contract_url": "https://etherscan.io/address/0xc2c747e0f7004f9e8817db2ca4997657a7746928", "paper": {}, "also": []}, {"id": "dom-hofmann--loot", "creator_ids": ["dom-hofmann"], "title": "Loot (for Adventurers)", "year": 2021, "field": "onchain", "sub": "co-authored", "also": ["network"], "mechanisms": ["co-authorship", "participation", "constraint"], "substrate": "ethereum", "kind": "series", "description": "8,000 bags of randomly generated adventurer gear, each just a list of eight item names rendered as white text on black and stored on-chain. Stats, images and rules were left out on purpose, and the community built games, art and tokens on top.", "description_zh": "8,000 个随机生成的冒险者装备袋，每个只是写在黑底上的八行白色物品名，完整存储在链上。属性、图像和规则都被刻意省略，社区在其上构建了游戏、艺术和代币。", "idea_en": "Release an unfinished primitive and let everyone else decide what it means.", "idea_zh": "发布一个未完成的原语，让所有人去决定它的意义。", "protocol": "Anyone could claim a bag for free, paying only gas; items were derived from the token id by the contract. The only instruction was: 'Stats, images, and other functionality are intentionally omitted for others to interpret. Feel free to use Loot in any way you want.'", "protocol_zh": "任何人只需支付 gas 即可免费领取一个袋子；物品由合约根据代币编号生成。唯一的说明是：属性、图像和其他功能被刻意省略，留给他人诠释，Loot 可以被随意使用。", "collective": "Holders and outside builders turned the bags into a 'Lootverse': More Loot and Synthetic Loot for everyone, the Genesis Adventurer project, Realms, Banners, Crypts and Caverns dungeon maps, Rings, character art, 3D assets and games, each reading the original bags as canon.", "collective_zh": "持有者和外部开发者把这些袋子扩展成 “Lootverse”：人人可领的 More Loot 和 Synthetic Loot、Genesis Adventurer 项目、Realms、Banners、Crypts and Caverns 地下城地图、Rings、角色画、3D 资产和游戏，都把原始袋子当作设定来源。", "keywords": ["Loot", "Dom Hofmann", "text NFT", "derivatives", "Lootverse", "CC0"], "images": ["https://lootproject.com/meta.png", "https://www.lootproject.com/banners.png", "https://www.lootproject.com/cryptsandcaverns.png"], "source_url": "https://www.lootproject.com", "contract_url": "https://etherscan.io/address/0xff9c1b15b16263c61d017ee9f65c50e4ae0113d7", "video": {}, "paper": {}}, {"id": "pak--lost-poets", "creator_ids": ["pak"], "title": "Lost Poets", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["burn", "co-authorship", "chance"], "substrate": "ethereum", "kind": "game", "description": "A collectible strategy game in acts: 65,536 Pages were sold in September 2021, holders burned Pages to claim AI-generated Poets, then burned more Pages to name their Poets and give them words.", "description_zh": "一个分幕进行的收藏策略游戏：2021 年 9 月售出 65,536 张 Pages，持有者销毁 Pages 领取 AI 生成的 Poets，再继续销毁 Pages 为自己的 Poet 命名、赋予词语。", "idea_en": "Give buyers a fuel (Pages) that can only be spent by destroying it, and let them spend it on authoring the characters they own.", "idea_zh": "给买家一种只能靠销毁来使用的燃料（Pages），让他们用它来书写自己拥有的角色。", "protocol": "Act I sold Pages (an ERC-1155 token) at 0.32 ETH, with 7,586 Pages airdropped to holders of at least 25 ASH. For two weeks one Page could be burned to claim one Poet (ERC-721); after that no more conversions were possible. 1,024 Origin Poets with special permissions were distributed at random. Burning further Pages into a Poet grants a name change and a few words that the holder can write into the Poet's metadata.", "protocol_zh": "第一幕以 0.32 ETH 出售 Pages（ERC-1155 代币），另向持有至少 25 ASH 的地址空投 7,586 张。之后两周内，一张 Page 可销毁换取一个 Poet（ERC-721），期限过后不能再转换。1,024 个拥有特殊权限的 Origin Poet 随机分发。再把 Pages 烧进 Poet，可以获得一次改名机会和几个词，持有者可把这些词写进 Poet 的元数据。", "collective": "All 65,536 Pages sold in about two hours of a planned 48-hour sale. Holders then named their Poets and inscribed short lines (on-chain names include 'The Last Poet' and 'Pope Francis'), so the collection's texts were written by its owners. In September 2026 the Poets contract listed about 5,570 holders (Blockscout).", "collective_zh": "原定 48 小时的发售中，65,536 张 Pages 约两小时售罄。持有者随后给 Poets 起名、刻写短句（链上名称包括“The Last Poet”“Pope Francis”），整套作品的文字由藏家写成。2026 年 9 月，Poets 合约约有 5,570 个持有地址（据 Blockscout）。", "keywords": ["Pages", "Poets", "Origins", "ERC-1155", "naming", "AI portraits", "ASH"], "images": ["https://lostpoets.xyz/img/lostpoets_card.png", "https://d1xxei964ioe0z.cloudfront.net/full/19bbbc3fd5354b3c21fe4bf29703ceb82ddb895eb719aae685e21f38d30619e7.png", "https://d1xxei964ioe0z.cloudfront.net/full/0e1490cb36bb726bb2c26ab21e28f8bdf5bf114cba09e022c5a6d34c364f31e5.png"], "source_url": "https://lostpoets.xyz", "contract_url": "https://etherscan.io/address/0x4b3406a41399c7FD2BA65cbC93697Ad9E7eA61e5", "video": {}, "paper": {}, "also": []}, {"id": "pak--merge", "creator_ids": ["pak"], "title": "Merge", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["merge", "scarcity", "circulation"], "substrate": "ethereum", "kind": "artwork", "description": "An open sale of 'mass' on Nifty Gateway (2–4 December 2021). Each buyer's units became one dynamic token, and any two tokens that meet in the same wallet fuse, so the number of tokens only goes down.", "description_zh": "2021 年 12 月 2 日至 4 日在 Nifty Gateway 上公开出售的“质量”（mass）。每位买家的单位合成一枚动态代币；任何两枚代币只要进入同一个钱包就会融合，所以代币总数只减不增。", "idea_en": "A game of extinction: a contract where every transfer can consume a token, so the market itself shrinks the work toward one survivor.", "idea_zh": "一场灭绝游戏：每次转移都可能吞掉一枚代币，市场本身把作品一步步缩向唯一的幸存者。", "protocol": "During the 48-hour sale anyone could buy any number of mass units; at the end each collector's units were merged into one token. The contract lets an ordinary wallet hold only one token: when a second arrives, the larger mass absorbs the smaller and the smaller is burned (whitelisted addresses such as the Nifty Gateway omnibus are exempt). Each token has one of four classes, drawn as a white, yellow, blue-ringed or red-ringed sphere; the single largest mass is the 'alpha', drawn black with a white ring, and every sphere is sized relative to it.", "protocol_zh": "48 小时发售期间，任何人都可以买任意数量的质量单位；结束时，每位藏家的单位合并为一枚代币。合约规定普通钱包只能持有一枚：第二枚到达时，质量大的吞并质量小的，小的被销毁（Nifty Gateway 托管地址等白名单地址除外）。每枚代币属于四个等级之一，分别画成白色、黄色、蓝环或红环的球体；全场质量最大的一枚是“alpha”，画成带白环的黑球，其余球体的大小都相对它来计算。", "collective": "28,983 collectors spent $91,806,519 on 312,686 units of mass, which became one token each (Nifty Gateway / Gemini). Secondary trading and deliberate merging then consumed tokens: by September 2026 the contract's totalSupply was 18,961, held by about 9,635 addresses (Blockscout).", "collective_zh": "28,983 位藏家花费 91,806,519 美元买下 312,686 个质量单位，每人合成一枚代币（据 Nifty Gateway / Gemini）。此后的二级交易和有意合并不断吞掉代币：截至 2026 年 9 月，合约的 totalSupply 为 18,961，分布在约 9,635 个地址中（据 Blockscout）。", "keywords": ["mass", "alpha", "Nifty Gateway", "open edition", "one token per wallet", "extinction"], "video": {"url": "https://x.com/muratpak/status/1465360503400718342", "platform": "x", "id": "1465360503400718342", "thumbnail": "https://pbs.twimg.com/ext_tw_video_thumb/1465360101871697927/pu/img/zDKrvwxobvS_eHFg.jpg", "embeddable": true}, "images": ["https://images.ctfassets.net/jg6lo9a2ukvr/3W6db5n9dQJBEIUBbs4G0m/341b8cef31c4f63ed4ad3ae61d4a0ce2/Pak_Merge.jpeg"], "source_url": "https://www.gemini.com/blog/paks-merge-drop-on-nifty-gateway-breaks-records-in-largest-ever-public-sale", "contract_url": "https://etherscan.io/address/0xc3f8a0F5841aBFf777d3eefA5047e8D413a1C9AB", "paper": {}, "also": []}, {"id": "harm-van-den-dorpel--mutant-garden-seeder", "creator_ids": ["harm-van-den-dorpel"], "title": "Mutant Garden Seeder", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["time", "chance", "co-authorship"], "substrate": "ethereum", "kind": "series", "description": "512+1 Ethereum tokens, released with Folia, whose images are 'mutants' seeded from blockchain state at birth and then randomly mutating over the following years. A later contract lets holders freeze chosen mutation states as permanent on-chain tokens.", "description_zh": "与 Folia 合作发行的 512+1 个以太坊代币，其图像是在诞生时由区块链状态播种的“突变体”，此后多年随机持续突变。后来的合约让持有者把选定的突变状态凝固为永久的链上代币。", "idea_en": "An artwork that keeps evolving after sale, with owners deciding which moments of its life are preserved.", "idea_zh": "一件售出后仍在演化的作品，由持有者决定它生命中哪些时刻被保存下来。", "protocol": "Each token has a fixed mutation probability; a daemon connected to Ethereum mainnet applies mutations and archives every past state. Through the Mutations contract a holder can mint any past state of their own mutant as a static token, or unlock it so anyone can mint its mutations while the holder receives a payout they set.", "protocol_zh": "每个代币有固定的突变概率；一个连接以太坊主网的守护进程执行突变，并存档所有历史状态。通过 Mutations 合约，持有者可以把自己突变体的任意历史状态铸成静态代币，或将其开放给任何人铸造，并按自己设定的金额获得分成。", "collective": "The 512 tokens sold out within hours in 2021. Holders have since chosen which mutation states to fix on-chain (metadata on-chain, SVGs on Arweave), turning private ownership into collective conservation of the garden.", "collective_zh": "512 个代币于 2021 年在数小时内售罄。此后持有者不断挑选要写入链上的突变状态（元数据在链上，SVG 存于 Arweave），把个人持有变成对这座“花园”的集体保存。", "keywords": ["Mutant Garden", "Folia", "genetic programming", "mutation", "Arweave"], "images": ["https://seeder.mutant.garden/images/mutant-garden-meta-images.jpg", "https://seeder.mutant.garden/images/installationview.jpg"], "source_url": "https://seeder.mutant.garden/about", "contract_url": "https://etherscan.io/address/0x20c70bdfcc398c1f06ba81730c8b52ace3af7cc3", "video": {}, "paper": {}, "also": []}, {"id": "tom-sachs--rocket-factory", "creator_ids": ["tom-sachs"], "title": "Rocket Factory", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["merge", "burn", "chance"], "substrate": "ethereum", "kind": "series", "description": "3,000 NFT rocket parts (nose cones, bodies, tail assemblies) in 30 brand liveries. Collectors combine three parts into a rocket, and may ask the studio to build and launch a physical twin.", "description_zh": "3,000 个 NFT 火箭零件（箭头、箭身、尾翼），共 30 种品牌涂装。藏家把三个零件组合成一枚火箭，还可以请工作室造出实体孪生火箭并发射。", "idea_en": "The collector base, not the artist, decides which of 113,000+ possible rockets get built, and the studio has to follow.", "idea_zh": "由藏家群体而非艺术家决定 113,000 多种可能中哪些火箭被造出来，工作室只能照做。", "protocol": "One nose cone, one body and one tail assembly can be combined into a Completed Rocket NFT; the three component NFTs are burned ('comburning'). Same-brand parts make a Perfect Rocket, mixed parts a Frankenrocket. A rocket holder can choose the Launch Option, after which the studio builds and launches a physical rocket and returns recovered parts in a display box with launch video; the physical twin can also be donated or destroyed.", "protocol_zh": "一个箭头、一个箭身和一个尾翼可以组合成一枚 Completed Rocket NFT，三个零件 NFT 随之销毁（“comburning”）。同品牌零件组成 Perfect Rocket，混搭则是 Frankenrocket。火箭持有者可以选择发射选项：工作室造出实体火箭并发射，把回收的零件装进展示盒、连同发射视频寄回；实体孪生也可以选择捐赠或销毁。", "collective": "Collectors trade parts to chase scarce Perfect Rockets (for example 87 Chanel and 3 Hello Kitty sets exist). By the 2022 Wallpaper* Design Awards there had been seven public launches, including Governors Island in New York, a Miami ballpark and SoHo; LACMA joined with a collaborative Frankenrocket.", "collective_zh": "藏家交换零件以追逐稀有的 Perfect Rocket（例如 Chanel 套件只有 87 套，Hello Kitty 只有 3 套）。到 2022 年 Wallpaper* 设计奖评选时已公开发射七次，地点包括纽约总督岛、迈阿密一座棒球场和苏荷区；洛杉矶郡立美术馆也参与组装了一枚合作 Frankenrocket。", "keywords": ["comburn", "Perfect Rocket", "Frankenrocket", "launch", "LACMA", "physical twin"], "images": ["https://www.tomsachsrocketfactory.com/tsrf.jpeg", "https://unframed.lacma.org/sites/default/files/attachments/TSRF%20LAUNCH%20%281%29.jpg", "https://unframed.lacma.org/sites/default/files/attachments/TSRF%20ROCKETS%20%281%29.jpg"], "source_url": "https://unframed.lacma.org/2021/11/09/nfts-and-museum-tom-sachs-rocket-launch", "video": {}, "paper": {}, "also": []}, {"id": "mathcastles--terraforms", "creator_ids": ["mathcastles"], "title": "Terraforms", "year": 2021, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "time", "constraint"], "substrate": "ethereum", "kind": "series", "description": "11,104 animated land parcels, each a 32×32 grid of characters generated entirely on-chain, stacked into a 20-level structure called the Hypercastle. Owners can switch a parcel to a blank 'daydream' and draw their own terrain back into the contract.", "description_zh": "11,104 块动态地块，每块是一张完全在链上生成的 32×32 字符网格，叠成一座名为 Hypercastle 的 20 层结构。持有者可以把地块切换成空白的“白日梦”状态，再把自己绘制的地形写回合约。", "idea_en": "A shared on-chain landscape whose surface is gradually redrawn by the people who own its pieces.", "idea_zh": "一片共享的链上地景，其表面由各块的持有者逐渐重绘。", "protocol": "Each parcel has a mode set by its owner: terrain (the original generated topography), daydream (a blank slate to draw on) or terraform (the drawing committed on-chain for everyone to see). The contract renders all parcels itself, so the Hypercastle is always the sum of what owners have left in it.", "protocol_zh": "每块地块的模式由持有者设定：terrain（原始生成的地形）、daydream（可以作画的空白）或 terraform（把画作提交上链，所有人可见）。合约自行渲染所有地块，因此 Hypercastle 永远是持有者留下内容的总和。", "collective": "Holders repainted parcels, while community developers built tools such as a 3D Hypercastle explorer; parcels were exhibited as a level-by-level world, for example at Glitch Marfa's e30d gallery in 2023.", "collective_zh": "持有者重绘地块，社区开发者制作了 3D Hypercastle 浏览器等工具；这些地块也作为逐层展开的世界被展出，例如 2023 年 Glitch Marfa 的 e30d 画廊。", "keywords": ["Terraforms", "Mathcastles", "Hypercastle", "on-chain", "ASCII", "land art"], "video": {"url": "https://www.youtube.com/watch?v=U2xTl5pPHwk", "platform": "youtube", "id": "U2xTl5pPHwk", "thumbnail": "https://i.ytimg.com/vi/U2xTl5pPHwk/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.glitchmarfa.com/uploads/glitch_mathcastles3584.gif", "https://www.glitchmarfa.com/uploads/HypercastleStructure.r1.jpg"], "source_url": "https://www.bankless.com/terraforms-explained-is-this-ethereums-best-onchain-art", "contract_url": "https://etherscan.io/address/0x4e1f41613c9084fdb9e34e11fae9412427480e56", "paper": {}, "also": []}, {"id": "damien-hirst--the-currency", "creator_ids": ["damien-hirst"], "title": "The Currency", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "contract", "exchange"], "substrate": "other-chain", "kind": "series", "description": "10,000 NFTs, each tied to a unique hand-painted dot work on paper, released with HENI in July 2021. Each buyer had a year to keep the NFT or swap it for the painting; whichever was not chosen was destroyed.", "description_zh": "与 HENI 合作于 2021 年 7 月发行的 10,000 个 NFT，每个对应一幅独一无二的纸上手绘点画。每位买家有一年时间决定保留 NFT 还是换成画作；没被选中的那一方会被销毁。", "idea_en": "Make every owner choose between the token and the object, and let the sum of those choices decide how much of the work physically survives.", "idea_zh": "让每位藏家在代币与实物之间二选一，这些选择的总和决定作品有多少以实体形式留存。", "protocol": "Holders of each NFT (on the Palm blockchain) could, until 27 July 2022, exchange it for the matching paper work, which burned the NFT; if they kept the NFT, the paper work would be burned. Hirst kept 1,000 works himself and chose the NFT for them, so their papers burned too.", "protocol_zh": "每个 NFT（在 Palm 区块链上）的持有者在 2022 年 7 月 27 日前可以换取对应的纸本作品，此时 NFT 被销毁；若保留 NFT，纸本作品就会被烧掉。赫斯特自己保留了 1,000 件并选择保留 NFT，所以这些纸本也被烧掉。", "collective": "When the exchange period closed, 5,149 holders had chosen the physical work and 4,851 the NFT (HENI). The 4,851 papers were burned publicly during The Currency exhibition at Newport Street Gallery, London, from September to October 2022, starting on 11 October with Hirst's own 1,000.", "collective_zh": "兑换期结束时，5,149 位持有者选择了实物，4,851 位选择了 NFT（据 HENI）。2022 年 9 月至 10 月，这 4,851 张纸本在伦敦 Newport Street Gallery 的 The Currency 展览中被当众焚烧，10 月 11 日从赫斯特自己保留的 1,000 张开始。", "keywords": ["HENI", "Palm", "physical or NFT", "burn", "Newport Street Gallery", "dot paintings"], "video": {"url": "https://www.youtube.com/watch?v=vEsVJJy1od4", "platform": "youtube", "id": "vEsVJJy1od4", "thumbnail": "https://i.ytimg.com/vi/vEsVJJy1od4/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.designboom.com/wp-content/uploads/2022/10/damien-hirst-nft-the-currency-designboom-fb.jpg", "https://static.frieze.com/files/styles/frieze_teaser/public/article/thumbnail/damien-hirst-the-currency-2.jpg?itok=USxR2EYc", "https://resources.heni.com/6190a77a-761c-4cc5-914b-b9c296c09c00.png?width=1024"], "source_url": "https://heni.com/nft/more-info/the-currency", "paper": {}, "also": []}, {"id": "pak--the-fungible", "creator_ids": ["pak"], "title": "The Fungible", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["scarcity", "merge", "exchange"], "substrate": "ethereum", "kind": "series", "description": "Pak's sale with Sotheby's on Nifty Gateway (12–14 April 2021): identical 'cubes' were sold as an open edition for 15 minutes a day, and each buyer's cubes were then packed into NFTs whose image depends on how many they bought.", "description_zh": "Pak 与苏富比在 Nifty Gateway 上的发售（2021 年 4 月 12 日至 14 日）：完全相同的“方块”以开放版数每天只卖 15 分钟，之后每位买家的方块按购买数量打包成不同画面的 NFT。", "idea_en": "Sell a fungible unit and let the quantity each person buys decide which non-fungible artwork they end up holding.", "idea_zh": "卖的是可互换的单位，每人买多少决定他最后拿到哪件不可互换的作品。", "protocol": "Anyone could buy any number of cubes during a 15-minute window each day, at $500, then $1,000, then $1,500. After the sale each buyer's total was split into the largest possible packs: A Cube (1), Five, Ten, Twenty, Fifty, Hundred, Five Hundred and Thousand Cubes (six cubes = one Five Cubes + one A Cube). The top buyer received The Cube, the next 100 buyers received Complexity, and Equilibrium went to four winners of set challenges (puzzle, highest secondary purchase, largest #PakWasHere post, closest estimate of the total).", "protocol_zh": "每天 15 分钟的窗口内，任何人都可以买任意数量的方块，三天价格依次为 500、1000、1500 美元。发售结束后，每位买家的总数被拆成尽可能大的包：A Cube（1）、Five、Ten、Twenty、Fifty、Hundred、Five Hundred 和 Thousand Cubes（买六个 = 一个 Five Cubes 加一个 A Cube）。买得最多的人获得 The Cube，其后 100 人获得 Complexity；Equilibrium 的四个版本分别给解谜者、二级市场最高价买家、#PakWasHere 帖子受众最大者和最接近总成交额的预测者。", "collective": "Buyers took 19,737 cubes on day one, 3,268 on day two and 593 on day three: 23,598 cubes for about $14 million. With the two auctioned 1/1s (The Switch, The Pixel) the sale reached $16.8 million (Sotheby's). Many cube holders later burned their cubes on burn.art to mine ASH.", "collective_zh": "买家第一天买下 19,737 个方块，第二天 3,268 个，第三天 593 个，共 23,598 个，约 1,400 万美元。加上两件拍卖的单版作品（The Switch、The Pixel），整场销售额为 1,680 万美元（据苏富比）。许多方块持有者后来在 burn.art 上销毁方块以挖取 ASH。", "keywords": ["open edition", "Sotheby's", "Nifty Gateway", "cubes", "The Cube", "The Pixel", "The Switch"], "images": ["https://sothebys-com.brightspotcdn.com/06/07/900df8e0456599524176879a8a1e/cube-image.png", "https://sothebys-com.brightspotcdn.com/37/f3/895926734d5c955091dc1b526904/equillibrium.png"], "source_url": "https://www.sothebys.com/en/articles/17-million-realized-in-sothebys-first-nft-sale-with-digital-creator-pak", "contract_url": "https://etherscan.io/address/0xc7cc3e8c6b69dc272ccf64cbff4b7503cbf7c1c5", "video": {}, "paper": {}, "also": []}, {"id": "pak--burn-art-ash", "creator_ids": ["pak"], "title": "burn.art and $ASH", "year": 2021, "field": "onchain", "sub": "supply", "mechanisms": ["burn", "currency", "scarcity"], "substrate": "ethereum", "kind": "platform", "description": "A site where anyone can destroy an NFT and receive ASH, an ERC-20 token that started with zero supply and can only be mined by burning. ASH then became the only currency accepted for some Pak drops.", "description_zh": "一个任何人都可以在上面销毁 NFT、换取 ASH 的网站。ASH 是一种初始供应为零、只能靠销毁挖出的 ERC-20 代币，后来成为部分 Pak 发售唯一接受的货币。", "idea_en": "A currency backed by what its holders have destroyed: every burn makes the remaining works rarer.", "idea_zh": "一种以持有者销毁之物为支撑的货币：每销毁一件，剩下的就更稀少。", "protocol": "Any holder can burn an NFT on burn.art and receive newly minted ASH. The yield follows a bonding curve that falls as supply grows, with two tiers: Pak NFTs start at 1,000 ASH, all other NFTs at 2 ASH; a halving hits every tier at 5 million ASH. Liquidity pools are left to the community. From January 2022 (Chapter One: Carbon) some Pak drops could only be bought or bid on with ASH.", "protocol_zh": "任何持有者都可以在 burn.art 上销毁一件 NFT，换取新铸造的 ASH。产出按供应量递减的联合曲线计算，分两档：Pak 的 NFT 起始为 1000 ASH，其他 NFT 起始为 2 ASH；供应达到 500 万时所有档位减半。流动性池由社区自行建立。自 2022 年 1 月（Chapter One: Carbon）起，部分 Pak 发售只能用 ASH 购买或出价。", "collective": "Collectors burned their own and others' NFTs, above all Fungible cubes, to mine ASH; Carbon's single edition is titled 'Three Thousand Eight Hundred Twenty Five Burned Cubes', and only ASH holders could bid on it. By September 2026 the ASH contract showed about 3.54 million tokens held by about 9,950 addresses (Blockscout).", "collective_zh": "藏家销毁自己和他人的 NFT（尤其是 The Fungible 的方块）来挖 ASH；Carbon 的单版作品题为“Three Thousand Eight Hundred Twenty Five Burned Cubes”（三千八百二十五个被烧掉的方块），只有 ASH 持有者能出价。截至 2026 年 9 月，ASH 合约显示约 354 万枚代币，分布在约 9,950 个地址中（据 Blockscout）。", "keywords": ["ASH", "ERC-20", "burn", "bonding curve", "Carbon", "burn.art"], "images": ["https://burn.art/x.png", "https://burn.art/_next/static/media/burned-cubes.061a79ae.png", "https://burn.art/_next/static/media/carbon.143793db.png"], "source_url": "https://burn.art/about", "contract_url": "https://etherscan.io/address/0x64D91f12Ece7362F91A6f8E7940Cd55F05060b92", "video": {}, "paper": {}, "also": []}, {"id": "async-art--async-art", "creator_ids": ["async-art"], "title": "Async Art (programmable art)", "year": 2020, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "contract", "exchange"], "substrate": "ethereum", "kind": "platform", "description": "An Ethereum platform where an artwork is issued as one Master token plus many Layer tokens. Whoever owns a Layer can switch it between states the artist defined, and the Master image is redrawn from all current choices.", "description_zh": "一个以太坊平台：一件作品被发行为一个 Master 代币和多个 Layer 代币。谁拥有某个图层，谁就能在艺术家预设的状态之间切换它，Master 图像则根据所有当前选择重新绘制。", "idea_en": "Split a picture into parts, sell the parts to different people, and let the picture be whatever their combined choices make it.", "idea_zh": "把一幅画拆成若干部分卖给不同的人，画面就是他们共同选择的结果。", "protocol": "The artist uploads a Master and its Layers and, for each Layer, fixes the allowed abilities (state change, move, rotate, colour, scale, reflect, visibility, opacity) and their ranges. Only the current owner of a Layer token may change that Layer; the Master is rendered from the sum of Layer states. Layers can also be bound to external data such as time or prices.", "protocol_zh": "艺术家上传 Master 及其图层，并为每个图层规定可用的能力（切换状态、移动、旋转、颜色、缩放、镜像、可见性、透明度）及其范围。只有图层代币的当前持有者可以修改该图层；Master 由所有图层状态叠加渲染而成。图层也可以绑定时间、价格等外部数据。", "collective": "Collectors bought individual layers and changed them, so one Master could look different from week to week depending on many owners. Within its first year Async reports being featured at Christie's and selling single works in the six-figure range; in 2021 it extended the model to music stems.", "collective_zh": "藏家分别购买图层并加以改动，同一幅 Master 因多位持有者的操作而每周呈现不同面貌。据 Async 自述，平台上线第一年即登上佳士得，并有单件作品以六位数美元成交；2021 年它把这一模式扩展到音乐分轨。", "keywords": ["Async Art", "Master", "Layer", "programmable art", "ERC-721"], "images": ["https://cdn.prod.website-files.com/65455ae3354eb117950e9025/65455ae3354eb117950e956f_Ntb4F8YJgyXZzHkwbK23tI5zxftuuXN4G-1tYcO-WzIA1o7Aina3L5ppK5B1GSV3KdwGKJJti0pNEisHCAukaDC6jICLGFlA3gZytXu73MA8PFjWlP7O6Dmqf70oczXssInUB8b-ae-PCB0Dpg7xnWvqQUwt_z6a_ZXHDMa3hkc0cV4ioyiVdDflVA.png"], "source_url": "https://opensea.io/blog/articles/async-art-paving-the-way-for-programmable-dynamically-changing-art-on-the-blockchain", "contract_url": "https://etherscan.io/address/0xb6dae651468e9593e4581705a09c10a76ac1e0c8", "video": {}, "paper": {}, "also": []}, {"id": "dark-forest-team--dark-forest", "creator_ids": ["dark-forest-team"], "title": "Dark Forest", "year": 2020, "field": "onchain", "sub": "co-authored", "mechanisms": ["constraint", "participation", "co-authorship"], "substrate": "ethereum", "kind": "game", "description": "A massively multiplayer space-conquest game whose entire state lives in smart contracts; zkSNARKs let players move without revealing where they are, so the universe has a real fog of war.", "description_zh": "一款大型多人太空征服游戏，全部状态都在智能合约里；零知识证明让玩家在不暴露位置的情况下行动，使宇宙拥有真正的战争迷雾。", "idea_en": "Publish the rules of a universe as a contract and let players, their scripts and their alliances write its history.", "idea_zh": "把一个宇宙的规则发布为合约，让玩家、他们的脚本和联盟书写它的历史。", "protocol": "The contract defines an infinite, procedurally generated universe; players must mine hashes locally to discover planets and submit zero-knowledge proofs that each move is valid without revealing coordinates. Rounds were time-boxed with prizes, first on Ropsten (August 2020) and later on xDAI/Gnosis Chain; the open client allowed plugins.", "protocol_zh": "合约定义了一个无限、程序生成的宇宙；玩家须在本地计算哈希来发现行星，并提交零知识证明，证明每一步移动合法而不泄露坐标。比赛按回合进行并设奖金，最初在 Ropsten 测试网（2020 年 8 月），后来迁到 xDAI/Gnosis Chain；开放的客户端允许插件。", "collective": "Players formed alliances, wrote bots and plugins (with community plugin and renderer contests), published strategy guides and even exploits, hosted their own community rounds through Lobbies, and organised themselves in groups such as DFDAO, which ran its own tournaments.", "collective_zh": "玩家结成联盟，编写机器人与插件（社区还举办插件与渲染器竞赛），发表战术指南乃至漏洞利用文章，通过 Lobbies 自行举办社区回合，并组织起 DFDAO 等团体，自办锦标赛。", "keywords": ["Dark Forest", "zkSNARK", "0xPARC", "autonomous worlds", "RTS", "plugins"], "video": {"url": "https://www.youtube.com/watch?v=BLo1r3QhbCU", "platform": "youtube", "id": "BLo1r3QhbCU", "thumbnail": "https://i.ytimg.com/vi/BLo1r3QhbCU/maxresdefault.jpg", "embeddable": true}, "images": ["https://zkga.me/public/og_image.png", "https://blog.zkga.me/img/announcing-df/ui-wip.png"], "source_url": "https://blog.zkga.me/announcing-darkforest", "code_url": "https://github.com/darkforest-eth", "paper": {}, "also": []}, {"id": "async-art--first-supper", "creator_ids": ["async-art", "matt-kane"], "title": "First Supper", "year": 2020, "field": "onchain", "sub": "co-authored", "mechanisms": ["co-authorship", "exchange"], "substrate": "ethereum", "kind": "artwork", "description": "A parody of Leonardo's Last Supper made by 13 crypto artists for Async Art's launch, split into one Master and 22 Layers. Each Layer's owner can move, recolour or swap their part, and the picture is the sum of these choices.", "description_zh": "为 Async Art 上线而作、由 13 位加密艺术家共同完成的《最后的晚餐》戏仿之作，拆分为一个 Master 和 22 个图层。每个图层的持有者都可以移动、改色或切换自己那一部分，画面是这些选择的总和。", "idea_en": "A group portrait whose composition is decided by whoever currently owns each figure.", "idea_zh": "一幅群像，构图由每个人物当下的持有者决定。", "protocol": "Each of the 22 Layers, made by a different artist, has abilities fixed by that artist (rotation, scale, position, visibility, opacity, hue). Only the Layer token's owner can trigger them; for example the owner of MLIBTY's Layer 9 can slide and rotate a giant finger to point at any guest at the table.", "protocol_zh": "22 个图层分别由不同艺术家制作，各自的能力（旋转、缩放、位置、可见性、透明度、色相）由作者设定。只有图层代币持有者可以触发这些能力；例如 MLIBTY 的第 9 层持有者可以平移、旋转一根巨大的手指，让它指向餐桌旁任意一位宾客。", "collective": "The Master auction closed at 103.4 ETH on 28 February 2020 and the 22 Layers sold separately; by April 2020 the layers were held by 10 different collectors, whose changes kept rearranging the scene. Artists included XCOPY, Hackatao, Coldie, Josie Bellini, Alotta Money and Matt Kane.", "collective_zh": "Master 于 2020 年 2 月 28 日以 103.4 ETH 拍出，22 个图层另行出售；到 2020 年 4 月，图层分属 10 位藏家，他们的修改不断重排画面。参与艺术家包括 XCOPY、Hackatao、Coldie、Josie Bellini、Alotta Money 和 Matt Kane。", "keywords": ["Async Art", "Last Supper", "layers", "XCOPY", "Hackatao", "collaboration"], "video": {"url": "https://www.youtube.com/watch?v=KNlDfNLyH5Q", "platform": "youtube", "id": "KNlDfNLyH5Q", "thumbnail": "https://i.ytimg.com/vi/KNlDfNLyH5Q/hqdefault.jpg", "embeddable": true}, "images": ["https://cdn.steemitimages.com/DQmY3iuaoT5XvrLWvrhDjJL2akbgY4BV4yaheFKTJuabAV7/First%20Supper.jpg", "https://cdn.prod.website-files.com/65455ae3354eb117950e9025/65455ae3354eb117950e962f_636d5e387a5de6eea1342db7_63572c4e2c1d1071fb4a9d66_image3.avif"], "source_url": "https://x.com/asyncart/status/1233482051548065793", "contract_url": "https://etherscan.io/address/0xb6dae651468e9593e4581705a09c10a76ac1e0c8", "paper": {}, "also": []}, {"id": "matt-kane--right-place-right-time", "creator_ids": ["matt-kane"], "title": "Right Place & Right Time", "year": 2020, "field": "onchain", "sub": "co-authored", "mechanisms": ["exchange", "time", "contract"], "substrate": "ethereum", "kind": "artwork", "description": "A programmable painting on Async Art made of 24 Layers, one per hour, each redrawn daily from the previous 24 hours of Bitcoin price volatility. It sold for 262 ETH in September 2020.", "description_zh": "Async Art 上的一幅可编程绘画，由 24 个图层组成，每层对应一小时，每天根据前 24 小时的比特币价格波动重新绘制。2020 年 9 月以 262 ETH 售出。", "idea_en": "Let the anonymous crowd of a market paint the picture every day.", "idea_zh": "让市场中匿名的人群每天替你作画。", "protocol": "Kane's algorithm maps each hour of Bitcoin price change to the state of one of 24 Layers, so the composition is set by trading, not by the owner or the artist. A collector agreement adds a second layer: the owner receives 21% of the sales of daily edition NFTs (capped at 210) that record single days of the market.", "protocol_zh": "Kane 的算法把比特币每小时的价格变化映射到 24 个图层之一的状态上，所以构图由交易决定，而不是由持有者或艺术家决定。另有一份藏家协议：持有者可获得每日版 NFT（上限 210 件，每件记录市场的一天）销售额的 21%。", "collective": "The image is produced by the aggregate buying and selling of Bitcoin traders worldwide; the work was planned to run for ten or more years. The artist and its collector framed the revenue share as a new artist–collector partnership model.", "collective_zh": "画面由全球比特币交易者的买卖总和生成；作品计划运行十年以上。艺术家与藏家把这种收益分成称为一种新的艺术家与藏家合作模式。", "keywords": ["Async Art", "Bitcoin", "volatility", "data-driven", "revenue share"], "images": ["https://volatility.art/wp-content/uploads/sites/5/2023/11/bitcoin-volatility-art-by-matt-kane_9-22-2020_10-scaled-1.jpg", "https://mma.prnewswire.com/media/1277260/volatility_art___right_place_and_right_time_by_matt_kane___diagram.jpg"], "source_url": "https://www.prnewswire.com/news-releases/record-cryptoart-sale-matt-kanes-right-place--right-time-a-programmable-artwork-that-changes-with-bitcoin-price-volatility-sells-for-over-100k-on-async-art-301134356.html", "contract_url": "https://etherscan.io/address/0xb6dae651468e9593e4581705a09c10a76ac1e0c8", "video": {}, "paper": {}, "also": []}, {"id": "amy-whitaker--art-and-blockchain", "creator_ids": ["amy-whitaker"], "title": "Art and Blockchain: A Primer, History, and Taxonomy of Blockchain Use Cases in the Arts", "year": 2019, "field": "theory", "sub": "crypto-theory", "mechanisms": ["contract", "exchange", "currency"], "substrate": "text", "kind": "publication", "description": "Peer-reviewed article in Artivate (vol. 8, no. 2, 2019) that explains blockchain for arts readers, gives a history of its uses in art and sorts them into a taxonomy.", "description_zh": "发表于《Artivate》（第 8 卷第 2 期，2019）的同行评审论文，为艺术领域读者讲解区块链，梳理其在艺术中的应用历史，并建立分类。", "idea_en": "Blockchain can change who holds a stake in an artwork, not only how it is sold.", "idea_zh": "区块链改变的不只是作品如何出售，还有谁能在作品中持有份额。", "protocol": "Whitaker classifies use cases (provenance registries, fractional ownership, resale royalties, new funding structures) and discusses how they blur the line between for-profit and nonprofit support for art.", "protocol_zh": "Whitaker 对应用场景进行分类（来源登记、碎片化所有权、转售版税、新的资助结构），并讨论它们如何模糊营利与非营利艺术资助之间的界线。", "collective": "Published before the 2021 NFT boom, the article became an early scholarly reference for art-market and arts-management research on tokens and shared ownership.", "collective_zh": "这篇论文发表于 2021 年 NFT 热潮之前，成为艺术市场与艺术管理领域研究代币和共享所有权的早期学术参考。", "keywords": ["Artivate", "art market", "provenance", "fractional ownership", "resale royalties"], "images": ["https://artivate.org/public/journals/1/article_94_cover_en_US.png"], "paper": {"url": "https://artivate.org/index.php/artivate/article/view/94", "doi": "10.34053/artivate.8.2.2", "venue": "Artivate: A Journal of Entrepreneurship in the Arts 8, no. 2 (2019), pp. 21–46", "title": "Art and Blockchain: A Primer, History, and Taxonomy of Blockchain Use Cases in the Arts"}, "source_url": "https://artivate.org/index.php/artivate/article/view/94", "video": {}, "also": []}, {"id": "primavera-de-filippi--blockchain-and-the-law", "creator_ids": ["primavera-de-filippi", "aaron-wright"], "title": "Blockchain and the Law: The Rule of Code", "year": 2018, "field": "theory", "sub": "crypto-theory", "mechanisms": ["contract", "autonomy", "governance"], "substrate": "text", "kind": "publication", "description": "Book (Harvard University Press, 2018) on how blockchains let rules be written as self-executing code, a new order the authors call 'lex cryptographia', with chapters on smart contracts, DAOs and autonomous systems.", "description_zh": "一本书（哈佛大学出版社，2018），讨论区块链如何让规则以自动执行的代码形式存在，作者称之为“加密法”（lex cryptographia），各章涉及智能合约、DAO 与自治系统。", "idea_en": "When rules run as code, the code becomes a kind of law: design it as carefully as a constitution.", "idea_zh": "当规则以代码运行，代码就成了一种法律：要像设计宪法一样谨慎地设计它。", "protocol": "The authors explain how smart contracts enforce agreements without courts and how DAOs and autonomous agents can hold assets and act under code, and set out where this collides with existing law.", "protocol_zh": "作者解释智能合约如何在没有法院的情况下执行协议，DAO 与自治代理如何在代码之下持有资产和行动，并指出这些与现行法律的冲突之处。", "collective": "The book became a standard reference for law and governance of blockchain systems; De Filippi applies the same ideas in artworks such as Plantoid and in the Radical Friends anthology.", "collective_zh": "这本书成为区块链系统法律与治理的标准参考；De Filippi 也把同样的想法用于 Plantoid 等作品以及《Radical Friends》文集中。", "keywords": ["lex cryptographia", "smart contracts", "DAO", "code is law", "Harvard University Press"], "images": ["https://covers.openlibrary.org/b/isbn/9780674976429-L.jpg"], "paper": {"url": "https://www.hup.harvard.edu/books/9780674241596", "doi": "10.4159/9780674985933", "venue": "Harvard University Press, 2018", "title": "Blockchain and the Law: The Rule of Code"}, "source_url": "https://www.hup.harvard.edu/books/9780674241596", "video": {}, "also": []}, {"id": "ruth-catlow--artists-rethinking-the-blockchain", "creator_ids": ["ruth-catlow", "marc-garrett"], "title": "Artists Re:Thinking the Blockchain", "year": 2017, "field": "theory", "sub": "crypto-theory", "mechanisms": ["currency", "contract", "governance"], "substrate": "text", "kind": "publication", "description": "Anthology edited by Ruth Catlow, Marc Garrett, Nathan Jones and Sam Skinner (Torque Editions with Furtherfield and FACT, 2017), the first book on what blockchain technologies mean for art production and distribution.", "description_zh": "由 Ruth Catlow、Marc Garrett、Nathan Jones 和 Sam Skinner 主编的文集（Torque Editions 联合 Furtherfield 与 FACT，2017），是第一本讨论区块链技术对艺术生产与传播意味着什么的书。", "idea_en": "Ask what a blockchain could do for art beyond selling it: new rules for value, ownership and cooperation.", "idea_zh": "问问区块链除了卖艺术还能做什么：为价值、所有权与合作制定新规则。", "protocol": "The editors commissioned artists and researchers over a 12-month process to test blockchains as a medium; the book's companion interface, Finbook, let readers and bots trade on the value of its chapters.", "protocol_zh": "编者用 12 个月时间委托艺术家和研究者，把区块链当作媒介来测试；配套界面 Finbook 让读者和机器人对书中各章的价值进行交易。", "collective": "Contributors included Rhea Myers, Primavera De Filippi and Jaya Klara Brekke; a free digital edition was launched at Transmediale in February 2018, and the book seeded Furtherfield's DAO research that led to Radical Friends.", "collective_zh": "撰稿人包括 Rhea Myers、Primavera De Filippi 和 Jaya Klara Brekke；免费电子版于 2018 年 2 月在 Transmediale 发布，这本书也开启了 Furtherfield 此后通向《Radical Friends》的 DAO 研究。", "keywords": ["Furtherfield", "FACT", "Torque Editions", "Finbook", "blockchain art"], "images": ["https://torquetorque.net/wp-content/uploads/IMG_2370.jpg"], "paper": {"url": "https://torquetorque.net/publications/artists-rethinking-the-blockchain/", "venue": "Torque Editions / Furtherfield / FACT, Liverpool, 2017", "title": "Artists Re:Thinking the Blockchain"}, "source_url": "https://www.furtherfield.org/artists-rethinking-blockchain/", "video": {}, "also": []}, {"id": "mitchell-f-chan--digital-zones", "creator_ids": ["mitchell-f-chan"], "title": "Digital Zones of Immaterial Pictorial Sensibility", "year": 2017, "field": "onchain", "sub": "provenance", "mechanisms": ["burn", "contract", "scarcity"], "substrate": "ethereum", "kind": "artwork", "description": "An ERC-20 token work deployed on 29 August 2017 and unveiled at InterAccess, Toronto. It restages Yves Klein's Zones of Immaterial Pictorial Sensibility, including a ritual any holder can perform to destroy their token.", "description_zh": "2017 年 8 月 29 日部署、在多伦多 InterAccess 首次展出的 ERC-20 代币作品。它重演伊夫·克莱因的《非物质绘画感性区域》，包括任何持有者都能执行、销毁自己代币的仪式。", "idea_en": "Put an artist's sale ritual in a contract: buyers must deal with the contract directly, and 'owning the immaterial' means burning the receipt.", "idea_zh": "把艺术家的出售仪式写进合约：买家必须直接与合约打交道，“拥有非物质”意味着烧掉收据。", "protocol": "IKB is sold only by calling the contract's buy() function (no front end, on purpose). Supply is capped at 101 tokens in 8 series: Series 0 has 31 tokens at 0.1 ETH, each later series 10 tokens at double the previous price, with later series meant to be released over the artist's lifetime. Every sale is recorded per edition. A holder may call ritual(): the token is burned and half the ETH paid for it is sent to a separate contract called theRiver, echoing Klein throwing half the gold into the Seine.", "protocol_zh": "IKB 只能通过直接调用合约的 buy() 函数购买（刻意不做前端）。总量上限 101 枚，分 8 个系列：第 0 系列 31 枚、每枚 0.1 ETH，之后每个系列 10 枚、价格翻倍，后续系列按计划在艺术家一生中陆续发行。每次出售都按版次记录。持有者可调用 ritual()：代币被销毁，买它所付 ETH 的一半被转入名为 theRiver 的另一个合约，呼应克莱因把一半黄金抛入塞纳河。", "collective": "All Series 0 tokens sold out (artist's README, 2021); buyers had to work out how to call the contract by hand. The contract records each edition's buyer, price and whether it has been ritually burned.", "collective_zh": "第 0 系列全部售罄（艺术家 2021 年的说明）；买家必须自己弄清如何手动调用合约。合约记录了每个版次的买家、价格以及是否已被仪式销毁。", "keywords": ["IKB", "Yves Klein", "ritual", "ERC-20", "theRiver", "InterAccess", "Blue Paper"], "images": ["https://raw.githubusercontent.com/mitchellfchan/IKB/master/IKB_logo.png"], "paper": {"url": "https://github.com/mitchellfchan/IKB/blob/master/Digital-Zones-Of-Immaterial-Pictorial-Sensibility-Blue-Paper.pdf", "doi": "", "arxiv": "", "venue": "Artist whitepaper", "title": "The Blue Paper"}, "source_url": "https://github.com/mitchellfchan/IKB", "contract_url": "https://etherscan.io/address/0x88ae96845e157558ef59e9ff90e766e22e480390", "code_url": "https://github.com/mitchellfchan/IKB", "video": {}, "also": []}, {"id": "yoko-ono--add-colour-refugee-boat", "creator_ids": ["yoko-ono"], "title": "Add Colour (Refugee Boat)", "year": 2016, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "An all-white room with an all-white boat that visitors cover with writing and drawing in blue. The idea goes back to Ono's Add Colour paintings of 1960–66; this version, made in response to refugees crossing the Mediterranean, was first realised in 2016.", "description_zh": "一间全白的房间里放着一艘全白的船，观众用蓝色在上面写字、画画，直到覆盖一切。构想可追溯到小野洋子 1960—66 年的《添加颜色》绘画；这一版本回应了横渡地中海的难民，于 2016 年首次实现。", "idea_en": "A blank space plus one colour rule turns thousands of visitors' marks into a shared statement.", "idea_zh": "一块空白加上一条颜色规则，把成千上万观众的笔迹变成一份共同的表达。", "protocol": "Ono's instruction reads: 'Just blue like the ocean.' Visitors may write or draw anything, but only in blue (and white), on the walls, floor and boat, for the length of the exhibition.", "protocol_zh": "小野洋子的指令是：“只用蓝色，像海洋一样。”观众可以写或画任何内容，但只能用蓝色（和白色），画在墙上、地上和船上，持续整个展期。", "collective": "At each venue, such as Tate Modern in 2024 and Serralves in Porto, visitors gradually turn the room from white to a dense blue surface of messages; the final state is different every time.", "collective_zh": "在每个场馆，例如 2024 年的泰特现代美术馆和波尔图的塞拉尔维斯，观众一点点把白色房间变成布满留言的密集蓝色表面；最终状态每次都不一样。", "keywords": ["refugees", "blue", "participation", "Tate Modern", "Serralves"], "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/_MG_9203_copy_small.width-420.format-jpeg.jpg"], "source_url": "https://www.tate.org.uk/whats-on/tate-modern/yoko-ono/exhibition-guide", "video": {}, "paper": {}}, {"id": "jeremy-deller--were-here-because-were-here", "creator_ids": ["jeremy-deller"], "title": "we're here because we're here", "year": 2016, "field": "social", "sub": "collective-action", "mechanisms": ["instruction", "participation", "circulation"], "substrate": "body", "kind": "artwork", "description": "On 1 July 2016, the centenary of the first day of the Somme, about 1,400 volunteers in First World War uniform appeared unannounced in stations, streets and shopping centres across the UK.", "description_zh": "2016 年 7 月 1 日，索姆河战役首日一百周年，约 1400 名身着一战军装的志愿者未经预告出现在英国各地的车站、街道和商场。", "idea_en": "A silent rule plus a card turns a crowd of volunteers into a nationwide, distributed memorial.", "idea_zh": "一条沉默的规则加一张卡片，让一群志愿者成为遍布全国的分布式纪念碑。", "protocol": "Each volunteer represents one named soldier killed on 1 July 1916; they do not speak; when approached they hand over a card with that soldier's name, age and regiment and the hashtag #wearehere; at intervals they sing 'We're here because we're here'.", "protocol_zh": "每名志愿者代表一名 1916 年 7 月 1 日阵亡、有名有姓的士兵；他们不说话；有人走近时递上一张写有该士兵姓名、年龄、所属部队和 #wearehere 标签的卡片；每隔一段时间唱起“我们在这里因为我们在这里”。", "collective": "Around 1,400 volunteers took part in locations across the UK; members of the public shared thousands of photos under the hashtag. It was commissioned by 14-18 NOW and made with Rufus Norris of the National Theatre.", "collective_zh": "约 1400 名志愿者在英国各地参与；公众以该标签分享了成千上万张照片。作品由 14-18 NOW 委托，与国家剧院的鲁弗斯·诺里斯合作完成。", "keywords": ["14-18 NOW", "Somme", "memorial", "hashtag", "National Theatre"], "video": {"url": "https://vimeo.com/199719532", "platform": "vimeo", "id": "199719532", "thumbnail": "https://i.vimeocdn.com/video/1638527968-770e4cc330a6f22afe4d09e67009deb1045b1e3cbaca23fdbb74ee16ad72cbc9-d?f=webp&amp;region=us", "embeddable": true}, "images": ["https://upload.wikimedia.org/wikipedia/commons/2/23/We%27re_Here_Because_We%27re_Here_-_Kings_Cross.jpg", "https://becausewearehere.co.uk/uploads/sites/13/2016/07/Salisbury-3-Copyright-Adrian-Harris_low-res-1.jpg"], "source_url": "https://becausewearehere.co.uk/", "paper": {}, "also": []}, {"id": "thomas-hirschhorn--gramsci-monument", "creator_ids": ["thomas-hirschhorn"], "title": "Gramsci Monument", "year": 2013, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "time", "exchange"], "substrate": "body", "kind": "artwork", "description": "A plywood and tape structure built and run with residents of Forest Houses, a public housing estate in the Bronx, containing a library, theatre, bar, radio station and daily newspaper dedicated to Antonio Gramsci.", "description_zh": "与布朗克斯公共住宅区 Forest Houses 的居民一起搭建和运营的胶合板加胶带结构，内有图书馆、剧场、酒吧、电台和日报，献给安东尼奥·葛兰西。", "idea_en": "A monument that exists as paid work, daily programme and shared use for a fixed period.", "idea_zh": "一座以有偿工作、每日节目和共同使用的方式、在固定期限内存在的纪念碑。", "protocol": "The monument must be sited in a housing estate with residents' agreement; residents are paid to build and staff it; it is open every day with a fixed programme (lectures, workshops, newspaper, radio) and is dismantled after the set period.", "protocol_zh": "纪念碑必须在征得居民同意的公共住宅区内建造；居民受雇建造和值守；每天开放，有固定节目（讲座、工作坊、报纸、电台），到期即拆除。", "collective": "More than 40 Forest Houses residents were hired, 15 of them to build the structure; from 1 July to 15 September 2013 residents and visitors used it daily for lectures by Marcus Steinweg, children's workshops, radio shows and a newspaper; it was commissioned by Dia Art Foundation.", "collective_zh": "Forest Houses 雇用了 40 多名居民，其中 15 人参与建造；2013 年 7 月 1 日至 9 月 15 日，居民和访客每天在这里听马库斯·施泰因韦格的讲座、参加儿童工作坊、做电台节目和编报纸；作品由迪亚艺术基金会委托。", "keywords": ["Dia Art Foundation", "Bronx", "Forest Houses", "Antonio Gramsci", "monument"], "video": {"url": "https://www.youtube.com/watch?v=O5yyegM2u88", "platform": "youtube", "id": "O5yyegM2u88", "thumbnail": "https://i.ytimg.com/vi/O5yyegM2u88/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.diaart.org/media/w1050h700/webimages/hirschhorn-gramsci-monument-diamond.jpg"], "source_url": "https://www.diaart.org/program/exhibitions-projects/thomas-hirschhorn-gramsci-monument-project", "paper": {}, "also": []}, {"id": "david-horvitz--let-us-keep-our-own-noon", "creator_ids": ["david-horvitz"], "title": "Let us keep our own noon", "year": 2013, "field": "score", "sub": "event-scores", "also": ["social"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "Forty-seven hand bells cast from a melted French church bell of 1742, rung by forty-seven participants at local solar noon; the ringers then walk away from each other until each hears only their own bell.", "description_zh": "四十七个手铃由一口 1742 年的法国教堂钟熔化后铸成，由四十七位参与者在本地太阳正午敲响；随后敲铃人彼此走开，直到每个人只听得见自己的铃声。", "idea_en": "Dispersing a crowd can redistribute time: one shared signal splits into many private ones.", "idea_zh": "把人群散开，也就把时间重新分配了：一个共同的信号分裂成许多私人的信号。", "protocol": "At local noon, the exact midpoint between sunrise and sunset, forty-seven participants begin ringing the bells together, then disperse in different directions, ringing, until they can hear no bell but their own. The title comes from a 19th-century protest against railway standard time.", "protocol_zh": "在本地正午（日出与日落的正中间），四十七位参与者一起开始摇铃，然后一边摇铃一边朝不同方向散开，直到只听得见自己的铃声。标题来自 19 世纪人们抗议铁路标准时间的一句话。", "collective": "Groups of volunteers have performed it at the New Museum in New York and at the National Gallery of Iceland in Reykjavík (2016), each time at that place's own local noon, so the moment of the performance moves with the site.", "collective_zh": "志愿者群体在纽约新美术馆、雷克雅未克冰岛国家美术馆（2016）等地表演过这件作品，每次都按当地的正午进行，因此表演的时刻随地点而变。", "keywords": ["bells", "local noon", "standard time", "New Museum", "performance"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/6/6a/David_Horvitz_at_the_New_Museum%2C_NYAP_ring_the_bells_in_his_piece_%27Let_us_keep_our_own_noon%27_%2814489090112%29.jpg/960px-David_Horvitz_at_the_New_Museum%2C_NYAP_ring_the_bells_in_his_piece_%27Let_us_keep_our_own_noon%27_%2814489090112%29.jpg", "https://images.prismic.io/listasafn-islands/6b8be785-26d0-4457-a3a1-9cf6bb14248d_LET+US+KEEP+OUR+OWN+NOON_+2013++David+Horvitz.jpeg?auto=compress&max-w=1200"], "source_url": "https://www.listasafn.is/en/art/exhibitions/david-horvitz/", "video": {}, "paper": {}}, {"id": "hans-ulrich-obrist--do-it-compendium", "creator_ids": ["hans-ulrich-obrist"], "title": "do it: the compendium", "year": 2013, "field": "theory", "sub": "participation", "also": ["score"], "mechanisms": ["instruction", "participation", "co-authorship"], "substrate": "text", "kind": "publication", "description": "Book (Independent Curators International and D.A.P., 2013) collecting twenty years of the do it exhibition, begun in Paris in 1993, in which artists write instructions that institutions and readers carry out.", "description_zh": "一本书（独立策展人国际与 D.A.P.，2013），汇集始于 1993 年巴黎的展览 do it 二十年的成果：艺术家写下指令，由机构和读者执行。", "idea_en": "An exhibition can travel as a set of instructions and be remade differently each time.", "idea_zh": "展览可以作为一组指令流动，每次都以不同方式被重新制作。", "protocol": "Each artist contributes a written instruction; any host may realise it with local means, and each realisation counts as a version of the work, not a copy.", "protocol_zh": "每位艺术家提供一条书面指令；任何主办方都可以用本地条件实现它，每次实现都算作作品的一个版本，而不是复制品。", "collective": "The compendium prints instructions by 250 artists, 84 of them newly published for the 20th anniversary, together with essays and documentation of past iterations staged by institutions around the world.", "collective_zh": "该书收录了 250 位艺术家的指令，其中 84 条为二十周年新发表，另附文章以及世界各地机构历次实施的记录。", "keywords": ["do it", "instructions", "exhibition format", "Independent Curators International", "Christian Boltanski"], "images": ["https://curatorsintl.org/images/doit_productshot.jpg?w=1600", "https://covers.openlibrary.org/b/isbn/9781938922015-L.jpg"], "paper": {"url": "https://curatorsintl.org/shop/15810-do-it-the-compendium", "venue": "Independent Curators International / D.A.P., 2013", "title": "do it: the compendium"}, "source_url": "https://www.artbook.com/9781938922015.html", "video": {}}, {"id": "claire-bishop--artificial-hells", "creator_ids": ["claire-bishop"], "title": "Artificial Hells: Participatory Art and the Politics of Spectatorship", "year": 2012, "field": "theory", "sub": "participation", "mechanisms": ["participation", "constraint"], "substrate": "text", "kind": "publication", "description": "Book (Verso, 2012) that gives the first historical and theoretical overview of socially engaged participatory art, from Futurist evenings and Situationism to 1960s happenings and recent social practice.", "description_zh": "一本书（Verso，2012），首次对社会介入式参与艺术做了历史与理论的全面梳理：从未来主义之夜、情境主义到 1960 年代偶发艺术和近年的社会实践。", "idea_en": "Judge a participatory work by the tensions its rules create, not only by how nice the collaboration feels.", "idea_zh": "评价参与式作品，要看它的规则制造了怎样的张力，而不只看合作是否愉快。", "protocol": "Bishop analyses how artists 'delegate' performance and set rules for participants, and argues against judging such work only by its ethics; the best works keep a productive discomfort between author and participants.", "protocol_zh": "Bishop 分析艺术家如何“委托”表演、为参与者设定规则，并反对只从伦理角度评价此类作品；她认为最好的作品会在作者与参与者之间保持一种有生产性的不适。", "collective": "The book shaped a decade of debate on social practice and is widely taught; its account of delegated performance applies directly to works where crowds act under an artist's rules.", "collective_zh": "这本书塑造了此后十年关于社会实践的讨论，被广泛用于教学；其关于“委托表演”的论述，直接适用于人群在艺术家规则下行动的作品。", "keywords": ["social practice", "delegated performance", "spectatorship", "Verso", "participatory art"], "images": ["https://www.versobooks.com/cdn/shop/files/getimage_10a3d3bd-a97c-44a2-85dd-b57c2d53fcbc.jpg?v=1790568936"], "paper": {"url": "https://www.versobooks.com/products/2251-artificial-hells", "venue": "Verso, London and New York, 2012", "title": "Artificial Hells: Participatory Art and the Politics of Spectatorship"}, "source_url": "https://www.versobooks.com/products/2251-artificial-hells", "video": {}, "also": []}, {"id": "tino-sehgal--these-associations", "creator_ids": ["tino-sehgal"], "title": "These Associations", "year": 2012, "field": "social", "sub": "performance", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "artwork", "description": "For the Unilever Series in Tate Modern's Turbine Hall, a group of about 70 participants walked, ran, sang and gathered in the hall, and broke off to tell individual visitors personal stories.", "description_zh": "在泰特现代美术馆涡轮大厅的联合利华系列中，约 70 名参与者在大厅里行走、奔跑、歌唱、聚散，并不时离开群体，向个别观众讲述个人故事。", "idea_en": "A crowd choreographed by rules, which dissolves into one-to-one intimacy with strangers.", "idea_zh": "由规则编排的人群，随时化为与陌生人的一对一亲密交谈。", "protocol": "Participants follow a set of oral rules for group movement (slow walking, running, chasing, choral singing) and, at their own choice, stop a visitor to share a story about belonging, arrival or intimacy; nothing is fixed in writing and photography is refused.", "protocol_zh": "参与者遵循一套口头传授的集体移动规则（慢走、奔跑、追逐、合唱），并可自行选择拦下一位观众，讲述一个关于归属、抵达或亲密的故事；没有任何书面固定，也拒绝拍照。", "collective": "Around 70 storytellers recruited from London shared the performance in rotating shifts over the summer of 2012, producing an unrecorded mass of individual encounters.", "collective_zh": "约 70 名从伦敦招募的讲述者在 2012 年夏天轮班完成表演，留下大量没有被记录的个人相遇。", "keywords": ["Tate Modern", "Turbine Hall", "Unilever Series", "storytelling", "crowd"], "paper": {"url": "https://www.theguardian.com/artanddesign/2012/jul/23/tino-sehgal-these-associations-review", "title": "Tino Sehgal: These Associations – review", "venue": "The Guardian"}, "source_url": "https://en.wikipedia.org/wiki/Tino_Sehgal", "video": {}, "images": [], "also": []}, {"id": "tania-bruguera--immigrant-movement-international", "creator_ids": ["tania-bruguera"], "title": "Immigrant Movement International", "year": 2011, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "governance"], "substrate": "body", "kind": "organization", "description": "A storefront community space in Corona, Queens, run as an artwork and a political movement, offering free classes, legal and health services to immigrant residents.", "description_zh": "设在纽约皇后区科罗纳的一处临街社区空间，作为艺术作品和政治运动运营，为移民居民提供免费课程以及法律和健康服务。", "idea_en": "Useful art: an institution whose programme is written by the community it serves.", "idea_zh": "有用的艺术：一个由其服务的社群来编写节目的机构。", "protocol": "The space is free and open to residents; programmes are proposed and taught by residents, artists and service organisations; the artist lives in the neighbourhood during the first year, and the project is transferred to community stewardship.", "protocol_zh": "空间免费向居民开放；课程由居民、艺术家和服务机构提出和讲授；艺术家在第一年住在社区里，之后项目交由社区管理。", "collective": "Residents, mostly Latin American immigrants, ran workshops on English, immigration law, dance, bicycle repair, screen printing and more from 2011 to 2015, in partnership with the Queens Museum and Creative Time; IMI also joined the Occupy Wall Street marches.", "collective_zh": "2011 至 2015 年，以拉美移民为主的居民在这里开设英语、移民法律、舞蹈、自行车维修、丝网印刷等工作坊，合作方为皇后区美术馆和 Creative Time；IMI 也加入了“占领华尔街”的游行。", "keywords": ["arte útil", "Queens Museum", "Creative Time", "Corona", "immigration"], "video": {"url": "https://www.youtube.com/watch?v=9puLh5MCIqk", "platform": "youtube", "id": "9puLh5MCIqk", "thumbnail": "https://i.ytimg.com/vi/9puLh5MCIqk/maxresdefault.jpg", "embeddable": true}, "source_url": "https://queensmuseum.org/program/immigrant-movement-international-2/", "images": [], "paper": {}, "also": []}, {"id": "paul-ramirez-jonas--key-to-the-city", "creator_ids": ["paul-ramirez-jonas"], "title": "Key to the City", "year": 2010, "field": "social", "sub": "performance", "mechanisms": ["participation", "circulation", "exchange"], "substrate": "body", "kind": "artwork", "description": "At a booth in Times Square, members of the public awarded each other a 'key to the city' in a one-to-one ceremony; the key opened locks at more than 20 sites across New York's five boroughs.", "description_zh": "在时代广场的一个授钥亭里，公众在一对一的仪式中互相授予“城市之钥”；这把钥匙能打开纽约五个区 20 多个地点的锁。", "idea_en": "A civic honour made peer-to-peer: anyone can bestow it, and it actually opens doors.", "idea_zh": "把公民荣誉变成点对点：任何人都能授予，而且它真的能开门。", "protocol": "You cannot take a key for yourself: one person must give it to another in a short ceremony, naming why the recipient deserves it; the key then opens participating gates, lockers and doors listed in a guidebook for the summer of the project.", "protocol_zh": "不能给自己拿钥匙：必须由一个人在简短的仪式中把钥匙交给另一个人，并说出对方配得上的理由；在项目期间的夏天，这把钥匙可以打开指南上列出的门、柜和大门。", "collective": "In June 2010 thousands of keys were exchanged in one-to-one ceremonies; recipients then used them to explore community gardens, cemeteries, museums and back doors across the city. Presented by Creative Time with the City of New York.", "collective_zh": "2010 年 6 月，数以千计的钥匙在一对一的仪式中被授出；获赠者随后用它们探访全市的社区花园、墓地、博物馆和后门。由 Creative Time 与纽约市政府联合呈现。", "keywords": ["Creative Time", "Times Square", "keys", "civic ritual", "New York"], "video": {"url": "https://www.youtube.com/watch?v=Kz8ma3oufcw", "platform": "youtube", "id": "Kz8ma3oufcw", "thumbnail": "https://i.ytimg.com/vi/Kz8ma3oufcw/hqdefault.jpg", "embeddable": true}, "images": ["https://creativetime.org/wp-content/uploads/2010/08/2010_KeyToTheCity.jpg"], "source_url": "https://creativetime.org/projects/key-to-the-city/", "paper": {}, "also": []}, {"id": "marina-abramovic--the-artist-is-present", "creator_ids": ["marina-abramovic"], "title": "The Artist Is Present", "year": 2010, "field": "social", "sub": "performance", "mechanisms": ["participation", "constraint", "time"], "substrate": "body", "kind": "artwork", "description": "During her MoMA retrospective (14 March – 31 May 2010) Abramović sat silently at a table in the atrium every day the museum was open, while visitors took turns sitting in the chair opposite for as long as they chose.", "description_zh": "在 MoMA 回顾展期间（2010 年 3 月 14 日至 5 月 31 日），阿布拉莫维奇在博物馆开放的每一天都静坐在中庭的桌旁，观众轮流坐到她对面，想坐多久就坐多久。", "idea_en": "One chair, one rule (sit and look), and a queue that becomes the public face of the work.", "idea_zh": "一把椅子、一条规则（坐下并对视），排队的人群成为作品的公共面孔。", "protocol": "One visitor at a time may sit in the empty chair facing the artist, in silence and without touching; each sitter decides how long to stay; the artist remains seated for the museum's full opening hours.", "protocol_zh": "一次只允许一名观众坐到艺术家对面的空椅上，保持沉默、不得触碰；每人自己决定坐多久；艺术家在博物馆全部开放时间内保持坐姿。", "collective": "Over nearly three months, many hundreds of visitors sat with her, many of them moved to tears, while crowds queued, sometimes overnight; the sitters' faces were photographed and published as part of the work's record.", "collective_zh": "近三个月里，数以百计的观众与她对坐，不少人落泪，排队的人群有时通宵等候；每位对坐者的面孔都被拍下并作为作品记录发布。", "keywords": ["MoMA", "durational", "gaze", "queue", "sitters"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/ArtistIsPresent.jpg/960px-ArtistIsPresent.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/The_Artist_is_present_-_MoMA_%284423713664%29.jpg/960px-The_Artist_is_present_-_MoMA_%284423713664%29.jpg"], "source_url": "https://www.moma.org/calendar/exhibitions/964", "video": {}, "paper": {}, "also": []}, {"id": "tino-sehgal--this-progress", "creator_ids": ["tino-sehgal"], "title": "This Progress", "year": 2010, "field": "social", "sub": "performance", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "artwork", "description": "At the Guggenheim, which Sehgal emptied of all art, visitors walking up Frank Lloyd Wright's ramp were handed from a child to a teenager, a young adult and an older person, each continuing a conversation about progress.", "description_zh": "赛格尔清空了古根海姆美术馆的全部艺术品，沿弗兰克·劳埃德·赖特螺旋坡道上行的观众，依次由一个孩子、一个少年、一个青年和一位年长者接手，延续一场关于“进步”的对话。", "idea_en": "The artwork is a relay of conversation passed between generations and completed by each visitor.", "idea_zh": "作品是一场在几代人之间接力的对话，由每位观众补完。", "protocol": "At the base of the ramp a child asks the visitor what progress is; at set points the conversation is handed on to an older interpreter, who picks up and redirects it; no objects, no photography, no written instructions.", "protocol_zh": "坡道底部，一个孩子问观众什么是进步；在固定位置，对话被交给更年长的诠释者，由他们接过话题并转向；没有物品、不准拍照、没有书面说明。", "collective": "Interpreters of four age groups held thousands of different conversations with visitors over the six-week run; it was the first live work acquired by the Solomon R. Guggenheim Museum.", "collective_zh": "四个年龄层的诠释者在六周展期内与观众进行了数以千计各不相同的对话；它是所罗门·R·古根海姆美术馆收藏的第一件现场作品。", "keywords": ["Guggenheim", "constructed situation", "conversation", "interpreters", "no documentation"], "video": {"url": "https://www.youtube.com/watch?v=m5V2fHB2sFk", "platform": "youtube", "id": "m5V2fHB2sFk", "thumbnail": "https://i.ytimg.com/vi/m5V2fHB2sFk/maxresdefault.jpg", "embeddable": true}, "source_url": "https://www.guggenheim.org/exhibition/tino-sehgal", "images": [], "paper": {}, "also": []}, {"id": "david-horvitz--241543903", "creator_ids": ["david-horvitz"], "title": "241543903", "year": 2009, "field": "score", "sub": "public-instructions", "also": ["network"], "mechanisms": ["instruction", "participation", "circulation"], "substrate": "network", "kind": "artwork", "description": "An instruction posted online in April 2009: photograph your head inside a freezer and tag the picture with the number 241543903, so that a search for the number shows everyone's photos together.", "description_zh": "2009 年 4 月发布在网上的一条指令：拍一张把头伸进冰箱冷冻室的照片，并给它加上标签 241543903，这样搜索这个数字就能看到所有人的照片。", "idea_en": "A meaningless number becomes a shared address where a crowd's photographs gather.", "idea_zh": "一个无意义的数字变成一个共享地址，让人群的照片聚集在一起。", "protocol": "Take a photograph of your head in a freezer. Upload it to the internet. Tag the file with 241543903. The number was made from the serial number of Horvitz's refrigerator and the barcodes of two frozen foods.", "protocol_zh": "拍一张头伸进冷冻室的照片。上传到网上。给文件加上标签 241543903。这个数字由霍维茨冰箱的序列号和两件冷冻食品的条形码拼成。", "collective": "Strangers repeated the pose and the tag; the meme spread on Orkut in Brazil, where Horvitz also had flyers handed out, then to Japan and to Facebook in 2010, and searching the number still returns the collected images.", "collective_zh": "陌生人纷纷模仿这个姿势并加上标签；这个表情包在巴西的 Orkut 上流行（霍维茨还请人在当地散发传单），随后传到日本，2010 年传到 Facebook。至今搜索这个数字仍能看到收集起来的照片。", "keywords": ["meme", "tag", "freezer", "Orkut", "Flickr"], "images": ["https://i.kym-cdn.com/entries/icons/original/000/001/178/241543903_1_.png"], "source_url": "https://en.wikipedia.org/wiki/David_Horvitz", "video": {}, "paper": {}}, {"id": "tania-bruguera--tatlins-whisper-6", "creator_ids": ["tania-bruguera"], "title": "Tatlin's Whisper #6 (Havana Version)", "year": 2009, "field": "social", "sub": "performance", "mechanisms": ["participation", "constraint", "time"], "substrate": "body", "kind": "artwork", "description": "At the 10th Havana Biennial Bruguera set up a podium and open microphone where anyone could speak uncensored for one minute, while performers in military dress placed a white dove on each speaker's shoulder.", "description_zh": "在第十届哈瓦那双年展上，布鲁格拉设置了讲台和开放麦克风，任何人都可以不受审查地发言一分钟，身着军装的表演者会在每位发言者肩上放一只白鸽。", "idea_en": "A one-minute rule turns a stage into a temporary zone of free speech.", "idea_zh": "一分钟的规则把讲台变成一个临时的言论自由区。", "protocol": "Any member of the audience may take the podium; each speaker has exactly one minute; two performers in uniform place a dove on the speaker's shoulder and remove the speaker when time is up; 200 disposable cameras are handed out to the audience.", "protocol_zh": "任何观众都可以走上讲台；每人只有一分钟；两名身着制服的表演者把白鸽放在发言者肩上，时间一到便请其下台；现场向观众发放 200 台一次性相机。", "collective": "On 29 March 2009 at the Centro Wifredo Lam, members of the public, including the blogger Yoani Sánchez, used their minute to call for freedom and democracy; the Cuban authorities denounced the event, and later attempts to restage it in Havana led to Bruguera's arrest.", "collective_zh": "2009 年 3 月 29 日，在威弗雷多·林中心，包括博主约阿尼·桑切斯在内的公众用自己的一分钟呼吁自由与民主；古巴当局谴责了这一活动，后来在哈瓦那重演的尝试导致布鲁格拉被捕。", "keywords": ["Havana Biennial", "free speech", "open microphone", "Cuba", "arte de conducta"], "video": {"url": "https://www.youtube.com/watch?v=CThPLk-hR1w", "platform": "youtube", "id": "CThPLk-hR1w", "thumbnail": "https://i.ytimg.com/vi/CThPLk-hR1w/hqdefault.jpg", "embeddable": true}, "images": ["https://taniabruguera.com/wp-content/uploads/oradorfcr11.jpg", "https://www.guggenheim.org/wp-content/uploads/2009/01/2014.11_01_web-1.jpg"], "source_url": "https://www.guggenheim.org/artwork/33083", "paper": {}, "also": []}, {"id": "lee-mingwei--the-moving-garden", "creator_ids": ["lee-mingwei"], "title": "The Moving Garden", "year": 2009, "field": "social", "sub": "performance", "also": ["score"], "mechanisms": ["instruction", "circulation", "exchange"], "substrate": "body", "kind": "artwork", "description": "A long granite table in the gallery holds hundreds of fresh flowers; visitors may take one on two conditions about what they do with it after leaving the museum.", "description_zh": "展厅里一张长长的花岗岩桌上插着数百枝鲜花；观众可以带走一枝，但离开美术馆后必须满足两个条件。", "idea_en": "A gift with conditions: the museum's content is released into the city through strangers.", "idea_zh": "附带条件的礼物：美术馆的内容经由陌生人流入城市。", "protocol": "Take one flower; on leaving, make a detour from your intended route; give the flower to a stranger you feel would benefit from an unexpected act of kindness. The table is restocked through the exhibition.", "protocol_zh": "带走一枝花；离开时偏离原本的路线绕一段路；把花送给一位你觉得需要一次意外善意的陌生人。展期内桌上的花会不断补充。", "collective": "First shown at the 10th Biennale de Lyon in 2009 and restaged at the Brooklyn Museum, the NGV and elsewhere, the work has been carried out by visitors handing flowers to strangers in each host city; the result exists only as these unrecorded exchanges.", "collective_zh": "作品首展于 2009 年第十届里昂双年展，之后在布鲁克林博物馆、维多利亚国立美术馆等地重演，每座城市的观众都把花送给了陌生人；结果只以这些未被记录的交换存在。", "keywords": ["Biennale de Lyon", "gift", "flowers", "strangers", "Lewis Hyde"], "video": {"url": "https://www.youtube.com/watch?v=VUcEDVZQigw", "platform": "youtube", "id": "VUcEDVZQigw", "thumbnail": "https://i.ytimg.com/vi/VUcEDVZQigw/maxresdefault.jpg", "embeddable": true}, "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/e/ed/The_Moving_Garden_%28Xe_Biennale_de_Lyon%29_%284104299446%29.jpg/960px-The_Moving_Garden_%28Xe_Biennale_de_Lyon%29_%284104299446%29.jpg", "https://content.ngv.vic.gov.au/col-images/api/EXHI039447/1280"], "source_url": "https://www.ngv.vic.gov.au/essay/lee-mingwei-the-moving-garden-2009/", "paper": {}}, {"id": "francis-alys--dont-cross-the-bridge", "creator_ids": ["francis-alys"], "title": "Don't Cross the Bridge Before You Get to the River", "year": 2008, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "On 12 August 2008 a line of children in Tarifa, each carrying a boat made from a shoe, walked into the sea toward Morocco while a second line of children in Tangier walked toward Spain.", "description_zh": "2008 年 8 月 12 日，塔里法的一列孩子各自拿着用鞋子做的小船走进大海、朝向摩洛哥，而丹吉尔的另一列孩子朝向西班牙走去。", "idea_en": "Children's play as a rule that stitches two continents together on the horizon.", "idea_zh": "孩子的游戏成为一条规则，在海平线上把两块大陆缝在一起。", "protocol": "On each shore children form a single file and wade out holding shoe-boats; the two lines, one leaving Europe and one leaving Africa, are meant to meet on the horizon.", "protocol_zh": "两岸的孩子各排成一列，捧着鞋船涉水前行；一列从欧洲出发，一列从非洲出发，两列在海平线上“相遇”。", "collective": "Children from Tarifa and Tangier performed the action, filmed simultaneously on both sides of the Strait of Gibraltar with Fundación Montenmedio Arte.", "collective_zh": "塔里法和丹吉尔的孩子完成了这次行动，在直布罗陀海峡两岸同时拍摄，合作方为 Montenmedio 艺术基金会。", "keywords": ["Strait of Gibraltar", "children", "shoe boats", "Tarifa", "Tangier"], "video": {"url": "https://www.youtube.com/watch?v=zUXo-Butrf0", "platform": "youtube", "id": "zUXo-Butrf0", "thumbnail": "https://i.ytimg.com/vi/zUXo-Butrf0/maxresdefault.jpg", "embeddable": true}, "source_url": "https://francisalys.com/dont-cross-the-bridge-before-you-get-to-the-river/", "images": [], "paper": {}, "also": []}, {"id": "improv-everywhere--frozen-grand-central", "creator_ids": ["improv-everywhere"], "title": "Frozen Grand Central", "year": 2008, "field": "social", "sub": "performance", "also": ["network"], "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "artwork", "description": "On 26 January 2008, 207 volunteers froze in place at the same moment in the main concourse of Grand Central Terminal and held still for five minutes among commuters.", "description_zh": "2008 年 1 月 26 日，207 名志愿者在纽约中央车站大厅同一时刻定格，在通勤人群中静止五分钟。", "idea_en": "One synchronised instruction, sent to a volunteer crowd, creates a public anomaly that strangers must interpret.", "idea_zh": "发给一群志愿者的一条同步指令，制造出陌生人必须自行解读的公共异象。", "protocol": "Volunteers recruited online gather nearby, synchronise watches, drift into the concourse, freeze in whatever pose they are in at the signal, stay frozen for five minutes and then resume as if nothing happened.", "protocol_zh": "网上招募的志愿者在附近集合、对表，分散进入大厅，信号一到就以当时的姿势定格，保持五分钟，然后若无其事地继续走动。", "collective": "207 'agents' took part; the video of commuters' reactions became one of the most-watched early YouTube videos, and according to Charlie Todd the prank has been recreated by fans in about 100 cities.", "collective_zh": "207 名“特工”参与；记录通勤者反应的视频成为早期 YouTube 上观看次数最多的视频之一，据查理·托德说，这一恶作剧已被粉丝在约 100 座城市重演。", "keywords": ["Grand Central Terminal", "flash mob", "Charlie Todd", "YouTube", "freeze"], "video": {"url": "https://www.youtube.com/watch?v=jwMj3PJDxuo", "platform": "youtube", "id": "jwMj3PJDxuo", "thumbnail": "https://i.ytimg.com/vi/jwMj3PJDxuo/maxresdefault.jpg", "embeddable": true}, "images": ["https://improveverywhere.com/wp-content/uploads/2008/01/frozen_grand_central-copy.jpg"], "source_url": "https://improveverywhere.com/2008/01/31/frozen-grand-central/", "paper": {}}, {"id": "sol-lewitt--wall-drawing-retrospective", "creator_ids": ["sol-lewitt"], "title": "Sol LeWitt: A Wall Drawing Retrospective (MASS MoCA)", "year": 2008, "field": "score", "sub": "execution", "mechanisms": ["instruction", "co-authorship", "time"], "substrate": "body", "kind": "series", "description": "A long-term installation of 105 LeWitt wall drawings from 1969 to 2007 on nearly an acre of walls in Building 7 at MASS MoCA, North Adams. LeWitt planned it before his death in 2007; others drew all of it.", "description_zh": "在北亚当斯 MASS MoCA 第 7 号楼近一英亩的墙面上长期陈列 105 件勒维特墙绘，时间跨度从 1969 年到 2007 年。勒维特在 2007 年去世前规划了这个展览，全部墙绘由他人绘制。", "idea_en": "A retrospective of a dead artist can be newly made by the living, from instructions alone.", "idea_zh": "一位已故艺术家的回顾展，可以只凭指令由在世的人重新做出来。", "protocol": "Each drawing's certificate, diagram and written instructions from the LeWitt estate and Yale University Art Gallery guide the drafters; walls were built to LeWitt's specifications, and damaged drawings are replaced or redrawn under the estate's supervision.", "protocol_zh": "每件墙绘的证书、示意图和文字指令（由勒维特遗产和耶鲁大学美术馆提供）指导绘图员工作；墙体按勒维特的规格建造，受损的墙绘在遗产方监督下更换或重画。", "collective": "Over six months, more than 60 artists and art students drew the 105 works, led by LeWitt's senior drafters, in a collaboration of MASS MoCA, Yale University Art Gallery and the Williams College Museum of Art. Drafters' decisions, from line spacing to endpoints, differ from earlier installations of the same drawings.", "collective_zh": "在勒维特资深绘图员带领下，60 多名艺术家和艺术学生用六个月完成了这 105 件作品，由 MASS MoCA、耶鲁大学美术馆和威廉姆斯学院美术馆合作实施。从线距到终点，绘图员的决定都与同一作品以往的安装不同。", "keywords": ["MASS MoCA", "Yale University Art Gallery", "retrospective", "drafters", "North Adams"], "video": {"url": "https://www.youtube.com/watch?v=c4cgB4vJ2XY", "platform": "youtube", "id": "c4cgB4vJ2XY", "thumbnail": "https://i.ytimg.com/vi/c4cgB4vJ2XY/maxresdefault.jpg", "embeddable": true}, "images": ["https://massmoca.org/wp-content/uploads/2015/10/detail-full-width-slw2.jpg", "https://massmoca.org/wp-content/uploads/2016/01/sol_lewitt_1180-1.jpg"], "paper": {"url": "https://www.cahiersdartinstitute.org/catalogues/sol-lewitt-wall-drawings/description", "title": "Sol LeWitt Wall Drawings Catalogue Raisonné", "venue": "Cahiers d'Art Institute"}, "source_url": "https://massmoca.org/sol-lewitt/", "also": []}, {"id": "tania-bruguera--tatlins-whisper-5", "creator_ids": ["tania-bruguera"], "title": "Tatlin's Whisper #5", "year": 2008, "field": "social", "sub": "performance", "mechanisms": ["constraint", "participation"], "substrate": "body", "kind": "artwork", "description": "Two mounted police officers rode into Tate Modern's Turbine Hall and used crowd-control techniques on the visitors, herding and dispersing them as if managing a protest.", "description_zh": "两名骑警骑马进入泰特现代美术馆涡轮大厅，用人群管控手段对待观众，像处理抗议人群一样驱赶、驱散他们。", "idea_en": "The audience becomes the material: a crowd experiences, in its own bodies, the rules used to control crowds.", "idea_zh": "观众成为材料：人群用自己的身体经历用来管控人群的规则。", "protocol": "Real mounted police officers apply standard crowd-control manoeuvres to whoever is in the hall; visitors are not told it is a performance and respond as they choose.", "protocol_zh": "真正的骑警对大厅里的所有人施行标准的人群管控动作；观众事先不被告知这是表演，由他们自行反应。", "collective": "Tate visitors were pushed, grouped and scattered by the horses; the crowd's compliance and resistance formed the work, which Tate later acquired as a performance with instructions.", "collective_zh": "泰特的观众被马匹推挤、聚拢和驱散；人群的服从与抵抗构成了作品，泰特后来以附带指令的表演形式收藏了它。", "keywords": ["Tate Modern", "Turbine Hall", "mounted police", "crowd control", "arte de conducta"], "video": {"url": "https://www.youtube.com/watch?v=x7L1s_GWn3o", "platform": "youtube", "id": "x7L1s_GWn3o", "thumbnail": "https://i.ytimg.com/vi/x7L1s_GWn3o/maxresdefault.jpg", "embeddable": true}, "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/.width-600_LEMha4R.jpg"], "source_url": "https://www.tate.org.uk/art/artworks/bruguera-tatlins-whisper-5-t12989", "paper": {}, "also": []}, {"id": "ai-weiwei--fairytale", "creator_ids": ["ai-weiwei"], "title": "Fairytale (童话)", "year": 2007, "field": "social", "sub": "collective-action", "also": ["network"], "mechanisms": ["participation", "circulation"], "substrate": "body", "kind": "artwork", "description": "Ai Weiwei brought 1,001 mainland Chinese citizens, chosen through an open call on his blog, to Kassel for documenta 12, and placed 1,001 Qing dynasty chairs throughout the exhibition.", "description_zh": "艾未未通过博客公开征集，选出 1001 名中国大陆公民带到卡塞尔参加第十二届文献展，并在展场各处放置了 1001 把清代椅子。", "idea_en": "The participants' journey, not an object, is the sculpture.", "idea_zh": "作品不是物件，而是参与者的旅程。", "protocol": "Anyone in mainland China could apply through the blog by answering a questionnaire of about 100 questions; the project paid for visas, travel and lodging; participants spent about a week in Kassel in one of five groups, free to act as they wished.", "protocol_zh": "中国大陆任何人都可以通过博客报名，填写约 100 个问题的问卷；项目承担签证、旅费和住宿；参与者分五批在卡塞尔停留约一周，行动完全自由。", "collective": "More than 3,000 people applied within days; 1,001 travelled in five groups, many leaving China for the first time, and their experiences were recorded in a film and in the questionnaires.", "collective_zh": "几天之内就有 3000 多人报名；1001 人分五批出行，其中许多人第一次离开中国，他们的经历记录在一部影片和问卷里。", "keywords": ["documenta 12", "Kassel", "blog", "open call", "social sculpture", "Qing chairs"], "video": {"url": "https://www.youtube.com/watch?v=B1cYkK0cVEA", "platform": "youtube", "id": "B1cYkK0cVEA", "thumbnail": "https://i.ytimg.com/vi/B1cYkK0cVEA/maxresdefault.jpg", "embeddable": true}, "images": ["https://slought.org/media/files/fairytale-3.jpg?w=828&h=485&c=1"], "source_url": "https://slought.org/resources/fairytale_project", "paper": {}}, {"id": "roman-ondak--measuring-the-universe", "creator_ids": ["roman-ondak"], "title": "Measuring the Universe", "year": 2007, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "An empty white gallery where attendants mark each visitor's height on the wall, with their first name and the date; over months the marks build into a dense band around the room.", "description_zh": "一间空白的展厅，工作人员在墙上标出每位观众的身高，写上名字和日期；几个月后，这些记号在房间四周积成一条浓密的带。", "idea_en": "Borrow a family ritual, repeat it for thousands of strangers, and the crowd draws the work.", "idea_zh": "借用一个家庭仪式，对成千上万名陌生人重复它，人群就画出了作品。", "protocol": "Visitors who wish to take part stand against the wall; an attendant marks their height and writes their first name and the date of the visit. After the exhibition the walls are repainted white.", "protocol_zh": "愿意参与的观众靠墙站好；工作人员标出他们的身高，写下名字和参观日期。展览结束后墙面重新刷白。", "collective": "Shown at the Pinakothek der Moderne in Munich (2007), MoMA (2009), the Stedelijk (2010–11), Tate St Ives (2011) and Parramatta (2014). At MoMA the marks of thousands of visitors formed a thick black band; the pattern at each venue reflects who came.", "collective_zh": "曾在慕尼黑现代绘画陈列馆（2007）、MoMA（2009）、阿姆斯特丹市立博物馆（2010–11）、泰特圣艾夫斯（2011）和帕拉马塔（2014）展出。在 MoMA，数千名观众的记号连成一条粗黑的带；每个场馆的图案都反映了来过的人。", "keywords": ["height", "visitors", "MoMA", "Tate St Ives", "collective drawing"], "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/romanmeasuringuniverse.width-600.jpg"], "source_url": "https://www.tate.org.uk/research/publications/performance-at-tate/case-studies/roman-ondak-measuring-universe", "video": {}, "paper": {}}, {"id": "alexander-galloway--the-exploit", "creator_ids": ["alexander-galloway", "eugene-thacker"], "title": "The Exploit: A Theory of Networks", "year": 2007, "field": "theory", "sub": "systems", "mechanisms": ["constraint", "governance"], "substrate": "text", "kind": "publication", "description": "Book (University of Minnesota Press, 2007) arguing that networks create their own forms of control, both centralised and dispersed, and that resistance must work through 'exploits': holes found inside the protocol itself.", "description_zh": "一本书（明尼苏达大学出版社，2007），认为网络会产生自身特有的控制形式，既集中又分散；抵抗必须通过“漏洞利用”进行，也就是在协议内部找到的缺口。", "idea_en": "To change a network, use its own rules against it.", "idea_zh": "要改变一个网络，就用它自己的规则反过来对付它。", "protocol": "The authors describe networks as topologies governed by protocol, and the exploit as a practice that follows the rules exactly while turning them to unintended ends.", "protocol_zh": "作者把网络描述为由协议支配的拓扑结构，而“漏洞利用”是一种严格遵守规则、却把规则引向意外用途的实践。", "collective": "The book gave hacktivists, tactical-media groups and software artists a vocabulary for working inside network protocols rather than outside them.", "collective_zh": "这本书为黑客行动者、战术媒体团体和软件艺术家提供了一套在网络协议内部、而非外部工作的词汇。", "keywords": ["networks", "exploit", "hacking", "biopolitics", "Electronic Mediations"], "images": ["https://covers.openlibrary.org/b/isbn/9780816650446-L.jpg"], "paper": {"url": "https://www.upress.umn.edu/book-division/books/the-exploit", "venue": "University of Minnesota Press, Electronic Mediations 21, 2007", "title": "The Exploit: A Theory of Networks"}, "source_url": "https://www.upress.umn.edu/book-division/books/the-exploit", "video": {}, "also": []}, {"id": "francis-alys--bridge-puente", "creator_ids": ["francis-alys"], "title": "Bridge/Puente", "year": 2006, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "Fishermen in Havana and in Key West each formed a line of boats heading out to sea toward the other shore, so that from each coast the line seemed to continue to the horizon as a floating bridge.", "description_zh": "哈瓦那和基韦斯特的渔民各自排出一列驶向对岸的船队，从两岸望去，船线仿佛一直延伸到海平线，成为一座漂浮的桥。", "idea_en": "Two crowds build one impossible line from opposite sides of a political border.", "idea_zh": "两群人从政治边界的两侧，共同搭建一条不可能完成的线。", "protocol": "Starting at the water's edge, each boat rows out and anchors a few metres behind the previous one, pointing toward the opposite coast, until the line reaches the horizon; the same rule runs simultaneously on both shores.", "protocol_zh": "从水边开始，每条船驶出并停泊在前一条船后方几米处，船头指向对岸，直到船线延伸至海平线；两岸同时执行同一条规则。", "collective": "Fishing communities in Cuba and Florida carried out the action in 2006 with Taiyana Pimentel and Cuauhtémoc Medina; it responded to the legal question of whether Cuban migrants caught at sea count as having reached land.", "collective_zh": "2006 年，古巴和佛罗里达的渔民社群与泰亚娜·皮门特尔和夸乌特莫克·梅迪纳一起完成了这次行动；它回应的是一个法律问题：在海上被截获的古巴移民是否算已登陆。", "keywords": ["Havana", "Key West", "boats", "border", "migration"], "video": {"url": "https://www.youtube.com/watch?v=lSjs5O1VuNg", "platform": "youtube", "id": "lSjs5O1VuNg", "thumbnail": "https://i.ytimg.com/vi/lSjs5O1VuNg/hqdefault.jpg", "embeddable": true}, "source_url": "https://francisalys.com/bridge-puente/", "images": [], "paper": {}, "also": []}, {"id": "claire-bishop--participation", "creator_ids": ["claire-bishop"], "title": "Participation", "year": 2006, "field": "theory", "sub": "participation", "mechanisms": ["participation", "instruction"], "substrate": "text", "kind": "publication", "description": "Anthology edited by Bishop (Whitechapel Gallery and MIT Press, Documents of Contemporary Art, 2006) that collects theory, artists' statements and curatorial debates on art that makes spectators into participants.", "description_zh": "Bishop 主编的文集（白教堂画廊与 MIT Press 合作的“当代艺术文献”丛书，2006），收录关于“让观众成为参与者”之艺术的理论、艺术家文本与策展辩论。", "idea_en": "Participation has a history and a theory: read the rules artists wrote for audiences side by side.", "idea_zh": "参与有它的历史和理论：把艺术家为观众写下的规则放在一起读。", "protocol": "The book gathers texts in which artists define what participants may do, from Lygia Clark, Hélio Oiticica and Joseph Beuys to Thomas Hirschhorn and Rirkrit Tiravanija, next to theory by Eco, Barthes, Rancière and Guattari.", "protocol_zh": "书中汇集了艺术家界定参与者可以做什么的文本，从 Lygia Clark、Hélio Oiticica、Joseph Beuys 到 Thomas Hirschhorn、Rirkrit Tiravanija，并与 Eco、Barthes、Rancière、Guattari 的理论并置。", "collective": "It became a standard course reader on participatory art and included the first English translation of Rancière's 'Problems and Transformations in Critical Art'.", "collective_zh": "它成为参与式艺术课程的标准读本，并收录了 Rancière《批判艺术的问题与转变》的第一个英译本。", "keywords": ["participatory art", "Whitechapel", "Documents of Contemporary Art", "Rancière", "anthology"], "images": ["https://covers.openlibrary.org/b/isbn/9780262524643-L.jpg"], "paper": {"url": "https://shop.whitechapelgallery.org/products/participation", "venue": "Whitechapel Gallery / MIT Press, 2006", "title": "Participation"}, "source_url": "https://shop.whitechapelgallery.org/products/participation", "video": {}, "also": []}, {"id": "florian-cramer--words-made-flesh", "creator_ids": ["florian-cramer"], "title": "Words Made Flesh: Code, Culture, Imagination", "year": 2005, "field": "theory", "sub": "systems", "mechanisms": ["instruction", "constraint"], "substrate": "text", "kind": "publication", "description": "Book-length essay written at the Piet Zwart Institute in Rotterdam and published online in 2005, tracing the idea of executable language from magic and combinatory poetry to Fluxus scores and computer code.", "description_zh": "在鹿特丹 Piet Zwart Institute 写成、2005 年在网上发表的长篇论文，追溯“可执行语言”的观念：从魔法和组合诗歌到激浪派乐谱和计算机代码。", "idea_en": "A score, a spell and a program share one property: words that make things happen when executed.", "idea_zh": "乐谱、咒语和程序有一个共同点：它们是被执行时会让事情发生的文字。", "protocol": "Cramer shows that instructions have a long cultural history outside computing, and that the same text can be read as description or run as action, by people or by machines.", "protocol_zh": "Cramer 指出，指令在计算之外有很长的文化历史；同一段文本既可以被当作描述来读，也可以被人或机器当作行动来执行。", "collective": "Distributed free online and through the Internet Archive, the text became a common reference in software-art and code-poetry teaching.", "collective_zh": "该文本通过网络和互联网档案馆免费流通，成为软件艺术和代码诗歌教学中常用的参考文献。", "keywords": ["software art", "executable code", "Fluxus", "combinatory poetry", "Piet Zwart Institute"], "images": ["https://archive.org/services/img/WordsMadeFlesh"], "paper": {"url": "https://archive.org/details/WordsMadeFlesh", "venue": "Piet Zwart Institute, Rotterdam, 2005", "title": "Words Made Flesh: Code, Culture, Imagination"}, "source_url": "https://www.netzliteratur.net/cramer/wordsmadefleshpdf.pdf", "video": {}, "also": []}, {"id": "francis-alys--barrenderos", "creator_ids": ["francis-alys"], "title": "Barrenderos (Sweepers)", "year": 2004, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "A line of Mexico City street sweepers pushed the rubbish of a street ahead of their brooms, street after street, until the accumulated mass could no longer be moved.", "description_zh": "一排墨西哥城的街道清洁工用扫帚把街上的垃圾一路向前推，一条街接一条街，直到堆积的垃圾再也推不动。", "idea_en": "A work that ends when the shared load becomes too heavy: the rule contains its own stopping condition.", "idea_zh": "当共同的负担重到推不动时作品结束：规则自带终止条件。", "protocol": "Sweepers form a line across the street and push everything in front of them forward without removing it; they continue from street to street until the pile stops moving.", "protocol_zh": "清洁工横跨街道排成一排，把前方的一切向前推而不清走；从一条街推到下一条街，直到垃圾堆停下。", "collective": "Municipal sweepers in the historic centre of Mexico City performed the action, filmed with Julien Devaux; the growing wall of rubbish records their joint effort and its limit.", "collective_zh": "墨西哥城历史中心的市政清洁工完成了这次行动，由朱利安·德沃拍摄；不断增高的垃圾墙记录了他们的共同努力及其极限。", "keywords": ["Mexico City", "sweepers", "labour", "rubbish", "futility"], "video": {"url": "https://www.youtube.com/watch?v=rPU7UEL5Dks", "platform": "youtube", "id": "rPU7UEL5Dks", "thumbnail": "https://i.ytimg.com/vi/rPU7UEL5Dks/hqdefault.jpg", "embeddable": true}, "source_url": "https://francisalys.com/barrenderos/", "images": [], "paper": {}, "also": []}, {"id": "grant-kester--conversation-pieces", "creator_ids": ["grant-kester"], "title": "Conversation Pieces: Community and Communication in Modern Art", "year": 2004, "field": "theory", "sub": "participation", "mechanisms": ["participation", "co-authorship"], "substrate": "text", "kind": "publication", "description": "Book (University of California Press, 2004) on 'dialogical' art, where artists set up long-term exchanges with communities and the conversation itself becomes the work.", "description_zh": "一本书（加州大学出版社，2004），讨论“对话性”艺术：艺术家与社区建立长期交流，交流本身成为作品。", "idea_en": "Design the conversation, not the object: the work is what people say and decide together.", "idea_zh": "设计的是对话而非物件：作品就是人们共同说出和决定的内容。", "protocol": "Kester describes projects in which the artist frames a dialogue among groups that rarely meet (for example officials, workers and residents) and the outcome is decided in that exchange.", "protocol_zh": "Kester 描述了这样的项目：艺术家为很少相遇的群体（例如官员、劳动者和居民）搭建对话框架，结果在交流中决定。", "collective": "The book, reissued in an updated edition in 2013, became a key reference for collaborative and community-based art, offering an alternative to judging such work by its visual form.", "collective_zh": "该书于 2013 年推出增订版，成为协作式与社区艺术的重要参考，提供了一种不以视觉形式评判此类作品的思路。", "keywords": ["dialogical art", "community art", "collaboration", "UC Press", "WochenKlausur"], "images": ["https://covers.openlibrary.org/b/isbn/9780520238398-L.jpg"], "paper": {"url": "https://www.ucpress.edu/books/conversation-pieces/paper", "venue": "University of California Press, 2004", "title": "Conversation Pieces: Community and Communication in Modern Art"}, "source_url": "https://www.ucpress.edu/books/conversation-pieces/paper", "video": {}, "also": []}, {"id": "francis-alys--guards", "creator_ids": ["francis-alys"], "title": "Guards", "year": 2004, "field": "social", "sub": "collective-action", "mechanisms": ["instruction", "chance", "constraint"], "substrate": "body", "kind": "artwork", "description": "Sixty-four Coldstream Guards were dropped off one by one around the City of London and walked until they found each other, gradually assembling into a marching square.", "description_zh": "64 名冷溪近卫团士兵被逐一放在伦敦金融城各处，各自行走直到遇见彼此，逐渐聚成一个行进的方阵。", "idea_en": "A decentralised rule for self-assembly: meet, fall into step, keep searching.", "idea_zh": "一条去中心化的自组织规则：相遇、并步、继续寻找。", "protocol": "Each guard enters the City alone and walks in full ceremonial dress; on meeting another guard they fall into step and search together; when the 8 × 8 square is complete it marches to the nearest bridge, where the guards break step and disperse.", "protocol_zh": "每名士兵身着礼服独自进入金融城行走；遇到另一名士兵就并步同行、一起寻找；当 8×8 的方阵完整时，方阵走向最近的桥，上桥后士兵们散步、解散。", "collective": "Sixty-four guards carried out the rule early one Sunday morning in July 2004 in the empty Square Mile; the convergence was filmed by Rafael Ortega for Artangel's Seven Walks commission.", "collective_zh": "2004 年 7 月的一个周日清晨，64 名士兵在空荡荡的金融城执行了这条规则；拉斐尔·奥尔特加为 Artangel 委托的《七次行走》拍下了这次汇合。", "keywords": ["Artangel", "Seven Walks", "London", "Coldstream Guards", "self-assembly"], "video": {"url": "https://www.youtube.com/watch?v=Q2CrQJz8uYc", "platform": "youtube", "id": "Q2CrQJz8uYc", "thumbnail": "https://i.ytimg.com/vi/Q2CrQJz8uYc/hqdefault.jpg", "embeddable": true}, "images": ["https://media.artangel.org.uk/images/2005sw_01.width-1200.jpg"], "source_url": "https://www.artangel.org.uk/artwork/guards/", "paper": {}, "also": []}, {"id": "alexander-galloway--protocol", "creator_ids": ["alexander-galloway"], "title": "Protocol: How Control Exists after Decentralization", "year": 2004, "field": "theory", "sub": "systems", "mechanisms": ["constraint", "governance"], "substrate": "text", "kind": "publication", "description": "Book (MIT Press, 2004) arguing that the internet is organised not by freedom but by protocols such as TCP/IP and DNS, which distribute control into technical standards; it also discusses net art and hacking as practices that work inside protocol.", "description_zh": "一本书（MIT Press，2004），认为互联网并非由自由组织，而是由 TCP/IP、DNS 等协议组织，控制被分散到技术标准之中；书中也讨论了在协议内部工作的网络艺术与黑客实践。", "idea_en": "Protocol is how control works when there is no centre: design the protocol and you design the behaviour.", "idea_zh": "协议是没有中心时控制的运作方式：设计协议，就是设计行为。", "protocol": "Galloway defines protocol as a set of voluntary technical rules that every node must follow to connect; its power lies in making behaviour standard while leaving each node apparently free.", "protocol_zh": "Galloway 把协议定义为每个节点为了连接都必须遵守的一组自愿技术规则；它的力量在于让行为标准化，同时让每个节点看起来是自由的。", "collective": "The book became the main theory text for net art, tactical media and later crypto and protocol art, and is cited by artists who treat standards and smart contracts as their medium.", "collective_zh": "这本书成为网络艺术、战术媒体以及后来加密与协议艺术的主要理论文本，被把标准和智能合约当作媒介的艺术家广泛引用。", "keywords": ["protocol", "TCP/IP", "control society", "net art", "tactical media"], "images": ["https://covers.openlibrary.org/b/isbn/9780262072472-L.jpg"], "paper": {"url": "https://direct.mit.edu/books/book/2528/ProtocolHow-Control-Exists-after-Decentralization", "doi": "10.7551/mitpress/5658.001.0001", "venue": "MIT Press, Leonardo Book Series, 2004", "title": "Protocol: How Control Exists after Decentralization"}, "source_url": "https://direct.mit.edu/books/book/2528/ProtocolHow-Control-Exists-after-Decentralization", "video": {}, "also": []}, {"id": "sol-lewitt--wall-drawing-1136", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #1136", "year": 2004, "field": "score", "sub": "execution", "mechanisms": ["instruction", "constraint"], "substrate": "body", "kind": "artwork", "description": "A late acrylic wall painting: a wide curved band of coloured stripes weaves across three walls of vertical stripes in the same seven colours. It is painted by a team following LeWitt's specifications for colour order and band width.", "description_zh": "一件晚期丙烯墙绘：一条由彩色条纹组成的宽弧带穿过三面墙的竖条纹，两者用同样的七种颜色。由团队按照勒维特规定的颜色顺序和条带宽度绘制。", "idea_en": "Even a work that looks free and gestural can be fully specified and handed to others.", "idea_zh": "即使看起来自由、有手势感的作品，也可以被完全写成规格交给别人。", "protocol": "LeWitt's instructions and diagram fix the sequence of colours and the width of the bands for the vertical stripes and the curving band; painters mask and paint the walls in acrylic to match. The work is sold and shown as a certificate plus instructions.", "protocol_zh": "勒维特的指令和示意图规定了竖条纹与弯曲条带的颜色顺序和宽度；画工按此贴胶带遮挡、用丙烯涂刷墙面。作品以证书加指令的形式出售和展出。", "collective": "Owned jointly by Tate and the National Galleries of Scotland through ARTIST ROOMS, it has been painted by different teams at different venues (among them the Turner Contemporary, Margate), fitted each time to the shape of the room.", "collective_zh": "通过 ARTIST ROOMS 由泰特美术馆和苏格兰国家美术馆共同收藏，曾由不同团队在不同场馆（包括马盖特的特纳当代美术馆）绘制，每次都要适应房间的形状。", "keywords": ["wall drawing", "acrylic", "ARTIST ROOMS", "Tate", "National Galleries of Scotland"], "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/.width-600_MrG187b.jpg"], "source_url": "https://www.tate.org.uk/art/artworks/lewitt-wall-drawing-1136-ar00165", "video": {}, "paper": {}, "also": []}, {"id": "francis-alys--when-faith-moves-mountains", "creator_ids": ["francis-alys"], "title": "Cuando la fe mueve montañas (When Faith Moves Mountains)", "year": 2002, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "On 11 April 2002, 500 volunteers with shovels formed a single line at the foot of a 500-metre sand dune in Ventanilla outside Lima and moved it about 10 centimetres from its original position.", "description_zh": "2002 年 4 月 11 日，500 名拿着铲子的志愿者在利马郊外文塔尼亚一座长 500 米的沙丘脚下排成一条线，把沙丘从原位推移了约 10 厘米。", "idea_en": "Maximum effort, minimum result: a crowd's coordinated labour as a political image.", "idea_zh": "最大的努力，最小的结果：人群协调一致的劳动本身就是政治图像。", "protocol": "Volunteers stand shoulder to shoulder in one line along the base of the dune; each shovels sand a short distance forward, the line advances step by step, and the action ends when the whole dune has been displaced by a few centimetres.", "protocol_zh": "志愿者沿沙丘底部肩并肩排成一条线；每人把沙向前铲一小段，整条线一步步推进，直到整座沙丘被整体挪动几厘米为止。", "collective": "About 500 volunteers, mostly students from Lima, carried out the action in one day, made with Cuauhtémoc Medina and Rafael Ortega; the movement of the dune is invisible, and the work survives as film, photographs and the participants' accounts.", "collective_zh": "约 500 名志愿者（大多是利马的学生）在一天之内完成了这次行动，合作者为夸乌特莫克·梅迪纳和拉斐尔·奥尔特加；沙丘的位移肉眼看不出，作品以影片、照片和参与者的讲述留存。", "keywords": ["Lima", "Ventanilla", "dune", "volunteers", "shovels", "Cuauhtémoc Medina"], "video": {"url": "https://www.youtube.com/watch?v=D2nccQcd8xQ", "platform": "youtube", "id": "D2nccQcd8xQ", "thumbnail": "https://i.ytimg.com/vi/D2nccQcd8xQ/hqdefault.jpg", "embeddable": true}, "images": ["https://www.guggenheim.org/wp-content/uploads/2002/01/2002.59_ph_web-1.jpg"], "source_url": "https://www.guggenheim.org/artwork/11412", "paper": {}, "also": []}, {"id": "francis-alys--the-modern-procession", "creator_ids": ["francis-alys"], "title": "The Modern Procession", "year": 2002, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "circulation"], "substrate": "body", "kind": "artwork", "description": "On 23 June 2002 a religious-style procession carried replicas of MoMA's icons, and the artist Kiki Smith, from Manhattan across the Queensboro Bridge to the museum's temporary home in Queens.", "description_zh": "2002 年 6 月 23 日，一支宗教游行式的队伍抬着 MoMA 馆藏名作的复制品和艺术家琪琪·史密斯，从曼哈顿经皇后区大桥走到博物馆在皇后区的临时馆址。", "idea_en": "Moving a museum as a ritual: the collection travels on the shoulders of the public.", "idea_zh": "把搬迁博物馆变成仪式：藏品由公众扛在肩上迁移。", "protocol": "Participants carry palanquins with replicas of Les Demoiselles d'Avignon, Duchamp's Bicycle Wheel and Giacometti's Standing Woman along a fixed route, at the slow pace set by a brass band, from MoMA on 53rd Street to MoMA QNS.", "protocol_zh": "参与者抬着载有《亚维农少女》、杜尚《自行车轮》和贾科梅蒂《站立的女人》复制品的轿子，按固定路线、随铜管乐队定下的慢速，从 53 街的 MoMA 走到 MoMA QNS。", "collective": "Some one hundred participants walked for about three hours with the Banda de Santa Cecilia, commissioned with the Public Art Fund; the procession marked MoMA's temporary move to Queens.", "collective_zh": "约一百名参与者随圣塞西莉亚乐队走了约三个小时，由公共艺术基金会联合委托；这次游行标记了 MoMA 暂迁皇后区。", "keywords": ["MoMA", "Public Art Fund", "procession", "Queens", "Kiki Smith"], "video": {"url": "https://www.youtube.com/watch?v=2wrVA7sH9-0", "platform": "youtube", "id": "2wrVA7sH9-0", "thumbnail": "https://i.ytimg.com/vi/2wrVA7sH9-0/hqdefault.jpg", "embeddable": true}, "images": ["https://www.publicartfund.org/wp-content/uploads/2019/06/AlysF_0058_horizontal.jpg"], "source_url": "https://www.publicartfund.org/exhibitions/view/the-modern-procession/", "paper": {}, "also": []}, {"id": "john-cage--organ-aslsp-halberstadt", "creator_ids": ["john-cage"], "title": "ORGAN²/ASLSP (Halberstadt performance)", "year": 2001, "field": "score", "sub": "execution", "mechanisms": ["instruction", "time", "participation"], "substrate": "body", "kind": "artwork", "description": "A performance of Cage's organ piece \"As Slow As Possible\" in the St. Burchardi church in Halberstadt, Germany, planned to last 639 years, from 2001 to 2640; a chord changes only every few months or years.", "description_zh": "在德国哈尔伯施塔特圣布尔夏迪教堂演出凯奇的管风琴作品《尽可能慢》，计划持续 639 年，从 2001 年到 2640 年；和弦每隔数月甚至数年才变换一次。", "idea_en": "A score that only says 'as slow as possible' can hand a single performance to many generations.", "idea_zh": "一份只写着“尽可能慢”的乐谱，可以把一场演出交给许多代人。", "protocol": "Cage's 1987 score leaves the tempo to the performers with the instruction \"as slow as possible\"; the Halberstadt organizers set the length at 639 years and a timetable of note changes, which volunteers carry out by adding or removing pipes and weights on a purpose-built organ.", "protocol_zh": "凯奇 1987 年的乐谱只给出“尽可能慢”的速度指示，交由演奏者决定；哈尔伯施塔特的组织者将演出长度定为 639 年，并制定了音符变换的时间表，由志愿者在专门建造的管风琴上增减音管和配重来执行。", "collective": "The performance began on 5 September 2001 with a long rest; the foundation behind it is funded partly by people who sponsor individual years, and each sound change, such as those on 5 February and 5 August 2024, draws crowds to the church to watch a new chord begin.", "collective_zh": "演出于 2001 年 9 月 5 日以一段漫长的休止开始；背后的基金会部分依靠认捐单个年份的人资助，每次换音（例如 2024 年 2 月 5 日和 8 月 5 日）都会吸引人群来到教堂，看一个新和弦开始鸣响。", "keywords": ["As Slow As Possible", "Halberstadt", "639 years", "organ", "long durations"], "video": {"url": "https://www.youtube.com/watch?v=L1a1CpaBovQ", "platform": "youtube", "id": "L1a1CpaBovQ", "thumbnail": "https://i.ytimg.com/vi/L1a1CpaBovQ/maxresdefault.jpg", "embeddable": true}, "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/ORGAN%C2%B2ASLSP_Orgel.jpg/960px-ORGAN%C2%B2ASLSP_Orgel.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Halberstadt-aslsp-gesamt.jpg/960px-Halberstadt-aslsp-gesamt.jpg"], "source_url": "https://en.wikipedia.org/wiki/As_Slow_as_Possible", "paper": {}, "also": []}, {"id": "jeremy-deller--the-battle-of-orgreave", "creator_ids": ["jeremy-deller"], "title": "The Battle of Orgreave", "year": 2001, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "instruction"], "substrate": "body", "kind": "artwork", "description": "A re-enactment, on the original site in South Yorkshire, of the 1984 confrontation between striking miners and police at the Orgreave coking plant, performed by historical re-enactment societies together with former miners and police officers.", "description_zh": "在南约克郡原址重演 1984 年罢工矿工与警察在奥格里夫炼焦厂的冲突，由历史重演协会与当年的矿工和警察共同完成。", "idea_en": "Re-enactment as a protocol for a community to replay and reclaim its own history.", "idea_zh": "把历史重演当作一种协议，让一个社群重演并重新拥有自己的历史。", "protocol": "The battle is restaged in the order recorded by witnesses and archives, directed by re-enactment specialist Howard Giles; former strikers and police take roles, sometimes on the side opposite to the one they were on in 1984.", "protocol_zh": "按照目击者和档案记录的顺序重演这场冲突，由历史重演专家霍华德·贾尔斯指挥；当年的罢工者和警察参与演出，有时站在与 1984 年相反的一方。", "collective": "More than 800 participants, including former miners and police from the original events, restaged the battle in June 2001; Mike Figgis filmed it for Artangel and Channel 4, and the archive entered Tate's collection.", "collective_zh": "2001 年 6 月，800 多名参与者（包括当年事件中的矿工和警察）重演了这场冲突；迈克·菲吉斯为 Artangel 和第四频道拍摄了影片，相关档案入藏泰特。", "keywords": ["Artangel", "re-enactment", "miners' strike", "Orgreave", "Mike Figgis"], "images": ["https://media.artangel.org.uk/images/2001tboo_02_863899d9.width-1200.jpg", "https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/.width-600_iE66Qp4.jpg"], "source_url": "https://www.artangel.org.uk/project/the-battle-of-orgreave/", "video": {}, "paper": {}, "also": []}, {"id": "nicolas-bourriaud--relational-aesthetics", "creator_ids": ["nicolas-bourriaud"], "title": "Relational Aesthetics", "year": 1998, "field": "theory", "sub": "participation", "mechanisms": ["participation", "exchange"], "substrate": "text", "kind": "publication", "description": "Book first published in French as Esthétique relationnelle (Les presses du réel, 1998; English 2002) that describes 1990s art whose material is human relations: shared meals, meetings, services and temporary social spaces.", "description_zh": "一本书，法文原版《Esthétique relationnelle》由 Les presses du réel 于 1998 年出版（英文版 2002 年），描述 1990 年代以人际关系为材料的艺术：共餐、聚会、服务和临时社交空间。", "idea_en": "The artwork can be a situation: a set of conditions under which people meet and interact.", "idea_zh": "作品可以是一个情境：一组让人们相遇和互动的条件。", "protocol": "Bourriaud describes artworks as 'social interstices': the artist sets up a situation with loose rules of use, and visitors complete it by how they gather, eat, talk or exchange.", "protocol_zh": "Bourriaud 把作品描述为“社会间隙”：艺术家设定一个带有宽松使用规则的情境，观众通过聚集、进食、交谈或交换的方式完成它。", "collective": "The book named a generation (Rirkrit Tiravanija, Liam Gillick, Philippe Parreno and others) and became one of the most cited and most debated texts on participatory art.", "collective_zh": "这本书命名了一代艺术家（Rirkrit Tiravanija、Liam Gillick、Philippe Parreno 等），成为参与式艺术领域被引用和争论最多的文本之一。", "keywords": ["relational aesthetics", "Rirkrit Tiravanija", "social interstice", "1990s", "Les presses du réel"], "images": ["https://covers.openlibrary.org/b/isbn/9782840660606-L.jpg", "https://www.lespressesdureel.com/EN/img/ouvrage/12797/_f.jpg"], "paper": {"url": "https://www.lespressesdureel.com/EN/ouvrage.php?id=12797&menu=0", "venue": "Les presses du réel, Dijon, 1998", "title": "Esthétique relationnelle / Relational Aesthetics"}, "source_url": "https://www.lespressesdureel.com/EN/ouvrage.php?id=12762&menu=0", "video": {}, "also": []}, {"id": "erwin-wurm--one-minute-sculptures", "creator_ids": ["erwin-wurm"], "title": "One Minute Sculptures", "year": 1997, "field": "score", "sub": "public-instructions", "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "series", "description": "An ongoing series of drawn or written instructions that tell a visitor how to pose with everyday objects, such as buckets, chairs or a plinth, and hold the pose for one minute.", "description_zh": "一个持续进行的系列：画出或写出的指令告诉观众如何与水桶、椅子或基座等日常物品摆出姿势，并保持一分钟。", "idea_en": "The sculpture is the instruction; any visitor who follows it for sixty seconds is the material.", "idea_zh": "雕塑就是那条指令；任何照做六十秒的观众就是材料。", "protocol": "Wurm supplies props and a sketch or a phrase, for example \"be a dog\" or \"Hold your breath and think of Spinoza\". The participant performs the pose and tries to hold it for 60 seconds.", "protocol_zh": "沃姆提供道具和一张草图或一句话，比如“做一只狗”或“屏住呼吸，想一想斯宾诺莎”。参与者摆出这个姿势，并尽量保持 60 秒。", "collective": "Museum visitors at Tate Modern, the MAK Center in Los Angeles and many other venues have performed the instructions, each body producing a different, short-lived version; Wurm also photographs anonymous participants as editions.", "collective_zh": "泰特现代美术馆、洛杉矶 MAK 中心和许多其他场馆的观众都执行过这些指令，每个身体都做出一个不同的、短暂的版本；沃姆也把匿名参与者拍成摄影作品。", "keywords": ["sculpture", "instruction drawing", "sixty seconds", "Tate"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/One_Minute_Sculpture%2C_Be_a_dog%2C_Erwin_Wurm.jpg/960px-One_Minute_Sculpture%2C_Be_a_dog%2C_Erwin_Wurm.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/One_Minute_Sculpture%2C_Hold_your_breath_and_think_of_Spinoza%2C_Erwin_Wurm.jpg/960px-One_Minute_Sculpture%2C_Hold_your_breath_and_think_of_Spinoza%2C_Erwin_Wurm.jpg", "https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/.width-600_d3p677p.jpg"], "source_url": "https://www.tate.org.uk/visit/tate-modern/display/performer-and-participant/erwin-wurm", "also": [], "video": {}, "paper": {}}, {"id": "christian-marclay--graffiti-composition", "creator_ids": ["christian-marclay"], "title": "Graffiti Composition", "year": 1996, "field": "score", "sub": "public-instructions", "mechanisms": ["participation", "co-authorship", "chance"], "substrate": "body", "kind": "score", "description": "Posters of blank sheet music pasted around Berlin during the 1996 Sonambiente festival; Marclay photographed what passers-by wrote, tore or pasted over them, and published 150 images as a score for musicians (portfolio, 2002).", "description_zh": "1996 年 Sonambiente 声音艺术节期间，空白五线谱海报被贴满柏林街头；马克雷拍下路人在上面写的、撕的、覆盖的痕迹，选出 150 张作为给音乐家的乐谱出版（作品集，2002）。", "idea_en": "Let the street write the notation, then let musicians play what the street wrote.", "idea_zh": "让街道来写乐谱，再让音乐家演奏街道写下的东西。", "protocol": "Paste blank staff paper in public places as an open invitation to mark it. Photograph the results, select 150 sheets, and give them to musicians to interpret in any way.", "protocol_zh": "把空白五线谱贴在公共场所，作为一个开放的邀请，任人涂写。拍下结果，挑出 150 张，交给音乐家自由演绎。", "collective": "Passers-by added notes, scribbles, tears and other flyers to the posters (reported as more than 5,000). Musicians have since performed the portfolio, for example five guitarists led by Elliott Sharp, with Melvin Gibbs, Mary Halvorson, Lee Ranaldo and Vernon Reid, at MoMA in 2006.", "collective_zh": "路人在海报上添加音符、涂鸦、撕痕，或把别的传单贴上去（据报道海报超过 5,000 张）。此后音乐家多次演奏这套作品集，例如 2006 年在 MoMA，由 Elliott Sharp 带领 Melvin Gibbs、Mary Halvorson、Lee Ranaldo 和 Vernon Reid 五位吉他手演出。", "keywords": ["graphic score", "Sonambiente", "Berlin", "sheet music", "MoMA"], "images": ["https://whitneymedia.org/assets/artwork/28280/2006_51_151_cropped.jpg", "https://www.moma.org/media/W1siZiIsIjExNDAzMyJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=2c9064adde4b8174"], "source_url": "https://www.moma.org/collection/works/87778", "also": [], "video": {}, "paper": {}}, {"id": "yoko-ono--wish-tree", "creator_ids": ["yoko-ono"], "title": "Wish Tree", "year": 1996, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation", "circulation"], "substrate": "body", "kind": "series", "description": "A living tree native to the site, with paper tags and pencils: visitors write a wish and tie it to a branch. Wish Trees have been planted at MoMA, the Hirshhorn, Tate Modern and many other sites, and the collected wishes are sent to Ono's Imagine Peace Tower in Iceland.", "description_zh": "一棵当地原生的活树，配有纸签和铅笔：观众写下愿望，系在树枝上。许愿树曾种在 MoMA、赫希洪博物馆、泰特现代美术馆等许多地方，收集到的愿望被寄往小野洋子在冰岛的“想象和平塔”。", "idea_en": "A simple ritual rule, repeated at many sites, gathers a global archive of private hopes.", "idea_zh": "一条简单的仪式性规则在多地重复，汇集成一个全球性的私人愿望档案。", "protocol": "Wish Piece (1996): 'Make a wish / Write it down on a piece of paper / Fold it and tie it around a branch of a Wish Tree / Ask your friends to do the same / Keep wishing / Until the branches are covered with wishes.'", "protocol_zh": "《许愿之作》（1996）：“许一个愿／把它写在一张纸上／折好，系在许愿树的树枝上／请你的朋友也这样做／不停许愿／直到树枝挂满愿望。”", "collective": "Visitors at each host institution cover the branches; staff periodically harvest the tags and send them to the Imagine Peace Tower on Viðey, where they are kept. The Hirshhorn's Wish Tree for Washington, DC (2007) is in its permanent collection; MoMA's tree was installed in 2010.", "collective_zh": "各地观众把树枝挂满；工作人员定期收下纸签，寄往维泽岛上的想象和平塔保存。赫希洪博物馆的《华盛顿许愿树》（2007）为其永久收藏；MoMA 的许愿树于 2010 年种下。", "keywords": ["Imagine Peace Tower", "MoMA", "Hirshhorn", "wishes", "participation"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Yoko_Ono_Wish_Tree_B.JPG/960px-Yoko_Ono_Wish_Tree_B.JPG", "https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/For_Yoko_Ono%27s_wish_tree_at_MoMA.JPG/960px-For_Yoko_Ono%27s_wish_tree_at_MoMA.JPG", "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Cards_for_Hirshhorn_Wish_Tree.JPG/960px-Cards_for_Hirshhorn_Wish_Tree.JPG"], "source_url": "https://en.wikipedia.org/wiki/Wish_Tree_for_Washington,_DC", "video": {}, "paper": {}}, {"id": "sol-lewitt--wall-drawing-797", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #797", "year": 1995, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "circulation", "co-authorship"], "substrate": "body", "kind": "artwork", "description": "A wall drawing written for four drafters who copy each other's line in turn, from the top of the wall to the bottom. The small errors of each copy accumulate into a rippling field of black, red, yellow and blue lines.", "description_zh": "一件写给四名绘图员的墙绘：他们轮流临摹上一个人画的线，从墙顶一直画到墙底。每次临摹的微小偏差不断累积，形成黑、红、黄、蓝线条起伏的一片。", "idea_en": "A relay of imperfect copies turns human error into the drawing.", "idea_zh": "一场不完美的临摹接力，把人的误差变成了作品。", "protocol": "'The first drafter has a black marker and makes an irregular horizontal line near the top of the wall. Then the second drafter tries to copy it (without touching it) using a red marker. The third drafter does the same, using a yellow marker. The fourth drafter does the same using a blue marker. Then the second drafter followed by the third and fourth copies the last line drawn until the bottom of the wall is reached.'", "protocol_zh": "“第一名绘图员用黑色马克笔在墙顶附近画一条不规则的横线。第二名绘图员用红色马克笔试着临摹它（不能碰到它）。第三名用黄色、第四名用蓝色照做。然后第二、第三、第四名依次临摹最后画的那条线，直到墙底。”", "collective": "Conceived with student participation in mind and first drawn in 1995 by four Amherst College sculpture students at the Mead Art Museum. At MASS MoCA the head drafter based the first line on the Berkshire hills; each copied line took ten to twenty minutes.", "collective_zh": "构思时就考虑了学生参与，1995 年由阿默斯特学院的四名雕塑专业学生在 Mead 美术馆首次绘制。在 MASS MoCA，首席绘图员以伯克希尔山脉的轮廓画出第一条线；每条临摹线要花十到二十分钟。", "keywords": ["wall drawing", "copying", "relay", "Amherst College", "marker"], "images": ["https://massmoca.org/wp-content/uploads/2015/12/797-1.jpg"], "source_url": "https://massmoca.org/event/walldrawing797/", "video": {}, "paper": {}}, {"id": "hans-ulrich-obrist--do-it", "creator_ids": ["hans-ulrich-obrist"], "title": "do it", "year": 1993, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "co-authorship", "participation"], "substrate": "text", "kind": "series", "description": "An exhibition made only of artists' written instructions, begun in Paris in 1993 by Hans Ulrich Obrist with Christian Boltanski and Bertrand Lavier; each venue realises the instructions anew and the show is dismantled afterwards.", "description_zh": "一个只由艺术家书面指令构成的展览，1993 年由汉斯·乌尔里希·奥布里斯特与克里斯蒂安·波尔坦斯基、贝尔特朗·拉维耶在巴黎发起；每个场馆都重新实现这些指令，展后拆除。", "idea_en": "Ship an exhibition as a book of scores and let every host make its own version.", "idea_zh": "把一个展览作为一本乐谱寄出去，让每个接待方做出自己的版本。", "protocol": "Artists send instructions instead of objects. The host institution, its staff and local public interpret and carry them out; the resulting works are not kept after the show, and each new venue starts again from the texts.", "protocol_zh": "艺术家寄来的是指令而不是物件。接待机构、它的员工和本地公众去解读并执行这些指令；展后作品不保留，每个新场馆都从文本重新开始。", "collective": "The first twelve instructions were translated into nine languages and circulated as a book. Organised as a touring show by Independent Curators International, do it had been staged in at least 50 locations by about 2013, from Australia and China to Mexico and Uruguay, and grew to hundreds of instruction sets; in 2020 a do it (home) edition invited people to realise instructions at home.", "collective_zh": "最初的十二份指令被译成九种语言，以书的形式流传。由独立策展人国际（ICI）作为巡回展组织，截至 2013 年前后已在至少 50 个地点上演，从澳大利亚、中国到墨西哥、乌拉圭；指令数量增加到数百份。2020 年的 do it (home) 版本邀请人们在家中实现指令。", "keywords": ["exhibition as score", "Independent Curators International", "Christian Boltanski", "Bertrand Lavier", "do it (home)"], "images": ["https://curatorsintl.org/images/Scan_130107_0015_WEB.jpg?w=2000"], "source_url": "https://curatorsintl.org/exhibitions/18072-do-it-2013", "video": {}, "paper": {}}, {"id": "gillian-wearing--signs", "creator_ids": ["gillian-wearing"], "title": "Signs that say what you want them to say and not Signs that say what someone else wants you to say", "year": 1992, "field": "social", "sub": "performance", "also": ["score"], "mechanisms": ["instruction", "participation", "co-authorship"], "substrate": "body", "kind": "series", "description": "Wearing stopped strangers in London streets, asked each to write whatever they were thinking on a sheet of white card, and photographed them holding it.", "description_zh": "韦英在伦敦街头拦下陌生人，请他们在一张白卡纸上写下此刻所想，再拍下他们手持卡纸的照片。", "idea_en": "Give the subject the caption, and the portrait becomes a self-authored statement.", "idea_zh": "把图注交给被拍摄者，肖像就变成本人写下的声明。", "protocol": "Any passer-by who agrees writes their own message on a blank card, without suggestions from the artist, and is photographed holding it; each photo is titled with the words on the card.", "protocol_zh": "任何同意参与的路人都在空白卡片上写下自己的话，艺术家不作提示，然后手持卡片拍照；每张照片都以卡片上的文字命名。", "collective": "Hundreds of strangers took part in 1992–93, writing confessions and slogans such as 'I'M DESPERATE'; their words, not the artist's, became the titles and content of the series.", "collective_zh": "1992 至 1993 年，数百名陌生人参与，写下诸如“我很绝望”这样的告白和口号；是他们的话语而非艺术家的话语，成为这一系列的标题和内容。", "keywords": ["photography", "London", "strangers", "confession", "captions"], "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/.width-600_KZdenDd.jpg"], "source_url": "https://www.tate.org.uk/art/artworks/wearing-signs-that-say-what-you-want-them-to-say-and-not-signs-that-say-what-someone-else-66092", "video": {}, "paper": {}}, {"id": "rirkrit-tiravanija--untitled-free", "creator_ids": ["rirkrit-tiravanija"], "title": "untitled 1992 (free)", "year": 1992, "field": "social", "sub": "performance", "mechanisms": ["participation", "exchange"], "substrate": "body", "kind": "artwork", "description": "At 303 Gallery in New York Tiravanija moved the contents of the gallery office into the exhibition space and turned the office into a kitchen where he cooked Thai curry and served it free to anyone who came.", "description_zh": "在纽约 303 画廊，提拉瓦尼把画廊办公室的物品搬进展厅，把办公室改成厨房，烹制泰式咖喱，免费招待任何来访者。", "idea_en": "A standing offer (free food, open door) whose social consequences are the artwork.", "idea_zh": "一个长期有效的邀请（免费食物、敞开的门），它引发的社交后果就是作品。", "protocol": "The gallery's back office is exposed and its kitchen runs during opening hours; curry and rice are cooked daily and given free to every visitor; in MoMA's collection the work can be re-activated with food prepared in the museum's kitchen and served daily.", "protocol_zh": "画廊后台办公区完全敞开，厨房在开放时间运作；每天煮咖喱和米饭，免费分给每位观众；在 MoMA 的收藏中，这件作品可以用博物馆厨房每天制作的食物重新激活。", "collective": "Visitors ate, talked and lingered, turning the gallery into a canteen; the work was re-staged at David Zwirner (2007) and at MoMA (2011), where a free vegetarian curry lunch was served every day.", "collective_zh": "观众在这里吃饭、交谈、逗留，把画廊变成食堂；作品后来在大卫·卓纳画廊（2007）和 MoMA（2011）重演，MoMA 每天免费供应素咖喱午餐。", "keywords": ["relational aesthetics", "303 Gallery", "MoMA", "curry", "hospitality"], "images": ["https://static-assets.artlogic.net/w_1010,h_580,c_limit/exhibit-e/5576fee507a72c0678771e53/f36044447a144ab67d93d0d816faa5d8.jpeg"], "source_url": "https://www.303gallery.com/gallery-exhibitions/rirkrit-tiravanija2", "video": {}, "paper": {}, "also": []}, {"id": "felix-gonzalez-torres--placebo", "creator_ids": ["felix-gonzalez-torres"], "title": "\"Untitled\" (Placebo)", "year": 1991, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "A floor carpet of silver-wrapped candies with an ideal weight of 1,000–1,200 lb; visitors may take candies, and the carpet is replenished.", "description_zh": "一片铺在地面上的银色包装糖果，理想重量 1,000–1,200 磅；观众可以拿走糖果，糖果地毯会被补充。", "idea_en": "Scale a take-away rule to a whole floor and the audience becomes the force that erodes it.", "idea_zh": "把“可以拿走”的规则放大到整个地面，观众就成了侵蚀它的力量。", "protocol": "Candies individually wrapped in silver cellophane, endless supply; ideal weight 1,000–1,200 lb; dimensions vary with installation. Visitors may take a candy; the owner may replenish.", "protocol_zh": "单独包在银色玻璃纸里的糖果，无限供应；理想重量 1,000–1,200 磅；尺寸随安装而变。观众可以拿走糖果，收藏者可以补充。", "collective": "Across an exhibition the public removes the carpet piece by piece while staff refill it, so its extent depends on attendance and on the institution's choices. MoMA, which owns one version, and other venues such as MUAC in Mexico City have installed it at different sizes.", "collective_zh": "展期内，公众一颗颗把地毯拿走，工作人员再补上，所以它的面积取决于观众数量和机构的选择。收藏了该作品的 MoMA，以及墨西哥城 MUAC 等场馆，都以不同的尺寸展出过它。", "keywords": ["candy", "endless supply", "MoMA", "placebo", "AIDS"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/%22Untitled%22_%28Placebo%29%2C_Felix_Gonzalez-Torres%2C_MoMA_1.jpg/960px-%22Untitled%22_%28Placebo%29%2C_Felix_Gonzalez-Torres%2C_MoMA_1.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/%22Untitled%22_%28Placebo%29%2C_Felix_Gonzalez-Torres%2C_MUAC_1.jpg/960px-%22Untitled%22_%28Placebo%29%2C_Felix_Gonzalez-Torres%2C_MUAC_1.jpg", "https://www.moma.org/media/W1siZiIsIjIzNDkxNSJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=b1d940ba7279b937"], "source_url": "https://www.moma.org/collection/works/80932", "video": {}, "paper": {}}, {"id": "felix-gonzalez-torres--portrait-of-ross-in-la", "creator_ids": ["felix-gonzalez-torres"], "title": "\"Untitled\" (Portrait of Ross in L.A.)", "year": 1991, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "A pile of multicoloured wrapped candies with an ideal weight of 175 lb, placed in a gallery corner; visitors may take a piece, and the owner replenishes the pile.", "description_zh": "一堆彩色包装的糖果，理想重量 175 磅，堆在展厅角落；观众可以拿走一颗，收藏者负责补充。", "idea_en": "A portrait that shrinks when people take part and returns when the owner follows the rule.", "idea_zh": "一幅肖像：人们参与时它变小，收藏者按规则补充时它又回来。", "protocol": "Candies in variously coloured wrappers, endless supply; ideal weight 175 lb; dimensions vary with installation. Visitors are allowed to take candy, and the owner may replenish the work, following the artist's certificate and the Foundation's guidelines.", "protocol_zh": "彩色包装糖果，无限供应；理想重量 175 磅；尺寸随安装而变。观众可以拿走糖果，收藏者依照艺术家证书和基金会的准则补充作品。", "collective": "Each visitor who takes a candy reduces the pile; each installation team decides its shape and when to replenish, so every display looks different. The ideal weight is usually read as that of Ross Laycock, the artist's partner, who died of AIDS-related complications in 1991.", "collective_zh": "每位拿走糖果的观众都让糖堆变小；每个布展团队决定糖堆的形状和补充时机，所以每次展出都不一样。理想重量通常被理解为艺术家的伴侣罗斯·莱科克的体重，他于 1991 年死于艾滋病并发症。", "keywords": ["candy spill", "endless supply", "ideal weight", "Art Institute of Chicago", "AIDS"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/%22Untitled%22_%28Portrait_of_Ross_in_L.A.%29%2C_Felix_Gonzalez-Torres%2C_Art_Institute.jpg/960px-%22Untitled%22_%28Portrait_of_Ross_in_L.A.%29%2C_Felix_Gonzalez-Torres%2C_Art_Institute.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/%22Untitled%22_%28Portrait_of_Ross_in_L.A%29_in_the_Art_Institute_of_Chicago.jpg/960px-%22Untitled%22_%28Portrait_of_Ross_in_L.A%29_in_the_Art_Institute_of_Chicago.jpg"], "source_url": "https://www.artic.edu/artworks/152961/untitled-portrait-of-ross-in-l-a", "video": {}, "paper": {}}, {"id": "felix-gonzalez-torres--death-by-gun", "creator_ids": ["felix-gonzalez-torres"], "title": "\"Untitled\" (Death by Gun)", "year": 1990, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "participation", "circulation"], "substrate": "text", "kind": "artwork", "description": "A stack of identical offset sheets on the floor, each reproducing Time magazine's portraits of the 460 people killed by gunfire in the United States in the week of 1–7 May 1989; visitors take sheets and the stack is refilled.", "description_zh": "地上一叠相同的胶印纸，每张都复制了《时代》杂志刊登的 1989 年 5 月 1 日至 7 日一周内在美国被枪杀的 460 人的肖像；观众把纸拿走，纸堆再被补足。", "idea_en": "A monument that works by being carried away, sheet by sheet, into other people's rooms.", "idea_zh": "一座靠被拿走来运作的纪念碑，一张张被带进别人的房间。", "protocol": "Print on paper, endless copies, shown as a stack on the floor (about nine inches high). The public may take sheets to keep, display or pass on; the owner reprints and replenishes the stack.", "protocol_zh": "纸上印刷，无限复本，以纸堆形式放在地面（约九英寸高）。公众可以拿走纸张保存、展示或转送他人；收藏者重新印刷并补足纸堆。", "collective": "Visitors carry the sheets out of the museum, so the work is distributed into homes and offices while the stack in the gallery is kept whole by staff. The piece belongs to MoMA and was shown in the Hammer Museum's 2014 exhibition Take It or Leave It.", "collective_zh": "观众把纸带出美术馆，作品因此散布到各家各户和办公室，而展厅里的纸堆由工作人员维持完整。作品为 MoMA 收藏，曾在汉默博物馆 2014 年的展览“Take It or Leave It”中展出。", "keywords": ["paper stack", "endless copies", "gun violence", "Time magazine", "MoMA"], "images": ["https://static-assets.artlogic.net/w_1200,h_1200,c_limit/exhibit-e/5b844b306aa72cea5f8b4567/87dbed26f781ae96dbefa0e60264f652.jpeg", "https://static-assets.artlogic.net/w_1200,h_1200,c_limit/exhibit-e/5b844b306aa72cea5f8b4567/724adc7d9d645a940c9c743f96667012.jpeg"], "source_url": "https://www.felixgonzalez-torresfoundation.org/works/untitled-death-by-gun", "video": {}, "paper": {}}, {"id": "benjamin-buchloh--aesthetic-of-administration", "creator_ids": ["benjamin-buchloh"], "title": "Conceptual Art 1962–1969: From the Aesthetic of Administration to the Critique of Institutions", "year": 1990, "field": "theory", "sub": "systems", "also": ["social"], "mechanisms": ["contract", "instruction"], "substrate": "text", "kind": "publication", "description": "Essay in October (Winter 1990) that reads Conceptual art through its use of administrative forms: certificates, statements, lists, legal contracts and instructions.", "description_zh": "发表于《October》（1990 年冬季号）的文章，从行政形式的角度解读观念艺术：证书、声明、清单、法律契约与指令。", "idea_en": "Paperwork is a medium: certificates and contracts can carry the whole work.", "idea_zh": "文书本身就是媒介：证书和契约可以承载整件作品。", "protocol": "Buchloh argues that artists such as LeWitt, Kosuth, Weiner and Haacke replaced craft with the procedures of bureaucracy, so that the work consists of rules, documents and institutional relations.", "protocol_zh": "Buchloh 认为 LeWitt、Kosuth、Weiner 和 Haacke 等艺术家以官僚程序取代了手艺，作品因此由规则、文件和机构关系构成。", "collective": "The essay framed later readings of certificates, receipts and artist contracts as art, the lineage that curators and writers now connect to smart-contract art.", "collective_zh": "这篇文章影响了后来把证书、收据和艺术家契约视为艺术的解读，策展人和作者如今把这一脉络与智能合约艺术联系起来。", "keywords": ["Conceptual art", "October", "institutional critique", "certificates", "administration"], "paper": {"url": "https://www.jstor.org/stable/778941", "doi": "10.2307/778941", "venue": "October 55 (Winter 1990), MIT Press", "title": "Conceptual Art 1962–1969: From the Aesthetic of Administration to the Critique of Institutions"}, "source_url": "https://doi.org/10.2307/778941", "video": {}, "images": []}, {"id": "roy-ascott--telematic-embrace", "creator_ids": ["roy-ascott"], "title": "Is There Love in the Telematic Embrace?", "year": 1990, "field": "theory", "sub": "systems", "also": ["network"], "mechanisms": ["participation", "co-authorship", "circulation"], "substrate": "text", "kind": "publication", "description": "Essay in Art Journal (Autumn 1990) in which Ascott describes telematic art: works made by many participants linked through computer networks, with meaning produced in their exchanges.", "description_zh": "发表于《Art Journal》（1990 年秋季号）的文章。Ascott 在其中描述远程通信艺术：由通过计算机网络相连的众多参与者共同完成、意义在其交流中产生的作品。", "idea_en": "On a network, authorship is distributed: the artist sets up the link, the participants make the work.", "idea_zh": "在网络上，作者身份是分布式的：艺术家搭建连接，参与者完成作品。", "protocol": "The artist provides a networked context and a few rules for contribution; participants at distant nodes add, transform and pass on material, and no single author controls the result.", "protocol_zh": "艺术家提供一个网络化的情境和少量参与规则；远方节点上的参与者添加、改写并传递素材，没有哪个单一作者能控制结果。", "collective": "The essay draws on Ascott's own networked projects, such as La Plissure du Texte (1983), in which participants in several cities wrote a fairy tale together; it became a founding text for telematic and net art and titles his collected writings, Telematic Embrace (2003).", "collective_zh": "文章基于 Ascott 自己的网络项目，例如 La Plissure du Texte（1983），多个城市的参与者在其中共同写作一则童话；它成为远程通信艺术与网络艺术的奠基文本，也成为他文集《Telematic Embrace》（2003）的书名。", "keywords": ["telematic art", "distributed authorship", "Art Journal", "networks", "La Plissure du Texte"], "images": ["https://covers.openlibrary.org/b/isbn/9780520222946-L.jpg"], "paper": {"url": "https://www.jstor.org/stable/777114", "doi": "10.1080/00043249.1990.10792697", "venue": "Art Journal 49, no. 3 (Autumn 1990), pp. 241–247", "title": "Is There Love in the Telematic Embrace?"}, "source_url": "https://doi.org/10.1080/00043249.1990.10792697", "video": {}}, {"id": "suzanne-lacy--the-crystal-quilt", "creator_ids": ["suzanne-lacy"], "title": "The Crystal Quilt", "year": 1987, "field": "social", "sub": "collective-action", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "artwork", "description": "On Mother's Day, 10 May 1987, 430 Minnesota women over 60 sat at tables arranged as a quilt in the Crystal Court of Minneapolis's IDS Center and talked about ageing, while their hand movements changed the quilt's pattern.", "description_zh": "1987 年母亲节（5 月 10 日），430 名 60 岁以上的明尼苏达女性坐在明尼阿波利斯 IDS 中心水晶庭中排成被面图案的桌旁，谈论衰老，她们的手部动作不断改变被面的图案。", "idea_en": "A choreographic score for hands turns a public conversation into a changing image seen from above.", "idea_zh": "一份写给双手的编舞乐谱，把公共对话变成从上方俯看、不断变化的图像。", "protocol": "Women sit four to a table on a quilt-patterned floor designed by Miriam Schapiro; they discuss set topics about ageing; every ten minutes a loon cry or thunderclap signals them to change the position of their hands, changing the pattern.", "protocol_zh": "女性四人一桌，坐在米里亚姆·夏皮罗设计的被面图案地面上；她们讨论关于衰老的指定话题；每隔十分钟，一声潜鸟叫或雷声提示她们改变双手的位置，从而改变图案。", "collective": "430 women took part, the culmination of the three-year Whisper Minnesota project with workshops across the state; the performance was broadcast live on PBS and is now in the collections of Tate and the Walker Art Center.", "collective_zh": "430 名女性参与了表演，这是为期三年、在全州开展工作坊的“低语明尼苏达”项目的高潮；表演在 PBS 现场直播，现收藏于泰特和沃克艺术中心。", "keywords": ["IDS Center", "Minneapolis", "ageing", "women", "PBS", "Miriam Schapiro"], "images": ["https://walker-web.imgix.net/cms/cq272dpi.jpg", "https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/.width-600_pZmNnxv.jpg"], "source_url": "https://www.walkerart.org/reader/suzanne-lacy-the-crystal-quilt-mothers-day-1987/", "video": {}, "paper": {}, "also": []}, {"id": "joseph-beuys--7000-eichen", "creator_ids": ["joseph-beuys"], "title": "7000 Eichen – Stadtverwaldung statt Stadtverwaltung (7000 Oaks)", "year": 1982, "field": "social", "sub": "collective-action", "mechanisms": ["participation", "time", "currency"], "substrate": "body", "kind": "artwork", "description": "For documenta 7 Beuys piled 7,000 basalt steles in front of the Fridericianum in Kassel; each stone left the pile only when an oak was planted with it somewhere in the city.", "description_zh": "第七届卡塞尔文献展上，博伊斯在弗里德里希阿鲁姆博物馆前堆起 7000 根玄武岩石柱；只有当城市某处种下一棵橡树并配上一根石柱时，石头才会离开石堆。", "idea_en": "A counter you can see: the pile shrinks only as the public plants and pays.", "idea_zh": "一个看得见的计数器：只有公众种树、出资，石堆才会变小。", "protocol": "Every oak is planted next to one basalt stele taken from the pile on Friedrichsplatz; the pile may shrink only by planting. Each tree-and-stone unit is funded by a sponsor (500 Deutsche Mark per unit), and the city must agree to each site.", "protocol_zh": "每棵橡树旁立一根取自弗里德里希广场石堆的玄武岩石柱；石堆只能通过种树来减少。每组“树加石”由一位资助人出资（每组 500 德国马克），每个种植地点都需市政同意。", "collective": "Citizens, schools, companies and donors adopted trees between 1982 and 1987; the 7,000th oak was planted on 12 June 1987 at documenta 8, after Beuys's death, by his son Wenzel next to the first tree. The project cost around three million marks and turned Kassel's streets into a distributed sculpture; Dia Art Foundation later continued it in New York.", "collective_zh": "1982 至 1987 年间，市民、学校、企业和捐助者认领树木；博伊斯去世后，第 7000 棵橡树于 1987 年 6 月 12 日第八届文献展期间由他的儿子文策尔种在第一棵树旁边。项目总花费约三百万马克，把卡塞尔的街道变成一件分布式雕塑；迪亚艺术基金会后来在纽约延续了这件作品。", "keywords": ["social sculpture", "documenta 7", "Kassel", "trees", "basalt", "sponsorship"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Kassel-Documenta_13-116-Beuys-Basalt_und_Eiche-2012-gje.jpg/960px-Kassel-Documenta_13-116-Beuys-Basalt_und_Eiche-2012-gje.jpg", "https://upload.wikimedia.org/wikipedia/commons/b/bd/Kassel-beuys-7000-eichen-wegmann-v-o.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/7000_Eichen-Stelen_07_2015-06-13.jpg/960px-7000_Eichen-Stelen_07_2015-06-13.jpg"], "source_url": "https://www.7000eichen.de/index.php?id=32", "video": {}, "paper": {}, "also": []}, {"id": "anna-halprin--planetary-dance", "creator_ids": ["anna-halprin"], "title": "Planetary Dance", "year": 1981, "field": "score", "sub": "event-scores", "also": ["social"], "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "A community dance ritual built around a movement score called the Earth Run, created in 1981 on Mount Tamalpais in California and performed each year by groups around the world.", "description_zh": "一个社区舞蹈仪式，以名为“地球奔跑”的动作乐谱为核心，1981 年在加州塔玛佩斯山创作，此后每年由世界各地的群体表演。", "idea_en": "A score simple enough for any community to adopt, with one shared core and a local theme.", "idea_zh": "一份任何社区都能采用的简单乐谱：共同的核心加上本地的主题。", "protocol": "In the Earth Run, participants declare their intentions one by one, rising from kneeling; then they form three concentric circles moving in different directions, choosing to run, jog, walk or stand still. Each community adds its own preparation, theme and reflection.", "protocol_zh": "在“地球奔跑”中，参与者从跪姿站起、逐一说出自己的意愿；然后组成三个同心圆，朝不同方向移动，每人可以选择跑、慢跑、走或静止。每个社区加入自己的准备、主题和反思。", "collective": "Created with James Hurd Nixon and Russell Bass after a series of murders on Mount Tamalpais, the dance grew out of the larger Circle the Earth workshops. Communities in dozens of countries have performed it, each adapting the theme while sharing the Earth Run.", "collective_zh": "这支舞是在塔玛佩斯山连环凶杀案之后，与 James Hurd Nixon 和 Russell Bass 一起创作的，源于更大规模的“环绕地球”工作坊。数十个国家的社区都表演过它，各自调整主题，但共享“地球奔跑”。", "keywords": ["Earth Run", "Mount Tamalpais", "community ritual", "movement score", "RSVP Cycles"], "images": ["https://bioneers.org/wp-content/uploads/2020/11/PD_EarthAlive-2-scaled.jpg", "https://npr.brightspotcdn.com/dims4/default/fdab2d9/2147483647/strip/true/crop/6144x3226+0+435/resize/1200x630!/quality/90/?url=http%3A%2F%2Fnpr-brightspot.s3.amazonaws.com%2Flegacy%2Fsites%2Fkalw%2Ffiles%2FPlanetary%20Dance%20Gen.jpg"], "source_url": "https://planetarydance.org/the-story/", "video": {}, "paper": {}}, {"id": "mierle-laderman-ukeles--touch-sanitation", "creator_ids": ["mierle-laderman-ukeles"], "title": "Touch Sanitation Performance", "year": 1979, "field": "social", "sub": "performance", "mechanisms": ["participation", "constraint", "time"], "substrate": "body", "kind": "artwork", "description": "Over eleven months in 1979–1980 Ukeles visited all 59 sanitation districts of New York and shook the hand of every sanitation worker, saying to each: 'Thank you for keeping New York City alive.'", "description_zh": "1979 至 1980 年的十一个月里，尤克里斯走遍纽约全部 59 个环卫区，与每一位环卫工人握手，并对每个人说：“谢谢你让纽约活着。”", "idea_en": "A ritual with a completeness rule: the work is finished only when every member of the workforce has been reached.", "idea_zh": "一场带有完整性规则的仪式：只有触及整个劳动群体的每一位成员，作品才算完成。", "protocol": "The artist must meet every one of the Department's workers in person, on every shift and in every district, perform the same handshake and the same sentence, and map the route as she goes.", "protocol_zh": "艺术家必须在每个班次、每个区亲自见到环卫局的每一名工人，完成同样的握手、说同样的话，并在行进中绘制路线图。", "collective": "About 8,500 sanitation employees took part in the handshake ritual; crossing the city ten times, Ukeles also recorded the workers' own accounts of stigma, which became part of the work's archive.", "collective_zh": "约 8500 名环卫员工参与了握手仪式；尤克里斯十次横穿城市，也记录下工人讲述的被歧视经历，这些记录成为作品档案的一部分。", "keywords": ["maintenance art", "New York City Department of Sanitation", "handshake", "labour", "ritual"], "video": {"url": "https://www.youtube.com/watch?v=EiRGoKG5kIw", "platform": "youtube", "id": "EiRGoKG5kIw", "thumbnail": "https://i.ytimg.com/vi/EiRGoKG5kIw/maxresdefault.jpg", "embeddable": true}, "images": ["https://static1.squarespace.com/static/5fd14a8ad4328f0b6168fcaa/5fd156d29a9e5443ac6aa99d/5fd9260587ec920669422967/1762444542733/Ukeles%2C%2BTouch%2BSanitation%2BPerformance_%2B_Handshake%2Band%2BThanking%2BRitual_.jpg?format=1500w"], "source_url": "https://www.sanitationfoundation.org/blog/portrait-of-an-artist-mierle-laderman-ukeles", "paper": {}, "also": []}, {"id": "guy-debord--game-of-war", "creator_ids": ["guy-debord"], "title": "Le Jeu de la Guerre (The Game of War / Kriegspiel)", "year": 1977, "field": "score", "sub": "constraints", "also": ["social"], "mechanisms": ["constraint", "instruction"], "substrate": "text", "kind": "game", "description": "A two-player strategy game on a board of 25 by 20 squares, modelled on Clausewitzian warfare, in which armies must stay connected to their arsenals through lines of communication.", "description_zh": "一款双人战略游戏，棋盘为 25×20 格，以克劳塞维茨式战争为模型，军队必须通过交通线与自己的兵工厂保持连接。", "idea_en": "A rule set about supply lines: units that lose contact with their network cannot act.", "idea_zh": "一套关于补给线的规则：与网络失去联系的单位就无法行动。", "protocol": "Each side has arsenals, forts, infantry, cavalry, artillery and relay units; lines of communication radiate from arsenals and relays; a unit cut off from them is paralysed; each turn allows up to five moves and one attack.", "protocol_zh": "双方各有兵工厂、堡垒、步兵、骑兵、炮兵和通讯单位；交通线从兵工厂和通讯单位辐射出去；被切断联系的单位陷入瘫痪；每回合最多移动五个单位、发动一次进攻。", "collective": "Debord conceived the game in the 1950s and patented it in 1965; in 1977 he and Gérard Lebovici published the rules in French and English and had a few copies of the board made; in 1987 he and Alice Becker-Ho published a record of a complete game, and in 2008 the Radical Software Group released a networked version played online.", "collective_zh": "德波在 1950 年代构思了这款游戏，1965 年申请专利；1977 年他与热拉尔·勒博维奇以法英双语出版规则，并制作了少量棋盘；1987 年他与爱丽丝·贝克-何出版了一整局对弈的记录；2008 年激进软件小组发布了可在线对弈的网络版本。", "keywords": ["Kriegspiel", "Situationist International", "Clausewitz", "Alice Becker-Ho", "Radical Software Group"], "images": ["https://upload.wikimedia.org/wikipedia/en/c/ca/A_Game_of_War.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Le_Jeu_de_la_Guerre_board.svg/960px-Le_Jeu_de_la_Guerre_board.svg.png"], "source_url": "https://www.r-s-g.org/kriegspiel/about.php", "video": {}, "paper": {}}, {"id": "collective-actions--appearance", "creator_ids": ["collective-actions"], "title": "Appearance (Poiavlenie) and Trips Out of Town", "year": 1976, "field": "social", "sub": "performance", "mechanisms": ["participation", "contract", "time"], "substrate": "body", "kind": "series", "description": "In the first action of Collective Actions, invited spectators waited in a snowy field in Izmailovsky Park until two organisers emerged from the woods, crossed the field and handed them certificates of presence.", "description_zh": "在“集体行动”小组的第一次行动中，受邀观众在伊兹梅洛沃公园的雪地里等待，直到两名组织者从树林中走出、穿过田野，向他们发放在场证明。", "idea_en": "The audience's waiting and attention are the event; a signed document certifies that they took part.", "idea_zh": "观众的等待和注意力就是事件；一份签名文件证明他们参与其中。", "protocol": "Viewers are invited in advance to travel to an empty field outside the city at a set time, without knowing what will happen; minimal events take place at the edge of perception; participants receive or sign documents and later write accounts that are collected in the 'Trips Out of Town' volumes.", "protocol_zh": "观众事先受邀在约定时间前往城外的空旷田野，不知道会发生什么；极少量的事件在感知的边缘发生；参与者领取或签署文件，之后写下讲述，收入《出城之旅》文集。", "collective": "About thirty people attended Appearance on 13 March 1976; the group went on to stage many more actions over the following decades for a regular circle of viewer-participants, whose narratives fill the samizdat volumes of Trips Out of Town.", "collective_zh": "1976 年 3 月 13 日约有三十人参加了《出现》；此后几十年，小组为一批固定的观众兼参与者组织了许多次行动，他们的讲述构成了地下出版物《出城之旅》的主体。", "keywords": ["Moscow Conceptualism", "Andrei Monastyrski", "samizdat", "Izmailovsky Park", "documentation"], "video": {"url": "https://www.youtube.com/watch?v=mj4y3pEEN4E", "platform": "youtube", "id": "mj4y3pEEN4E", "thumbnail": "https://i.ytimg.com/vi/mj4y3pEEN4E/maxresdefault.jpg", "embeddable": true}, "images": ["https://static.wixstatic.com/media/73e10e_c14f5ab94dd54961b7488215a8dcffc8~mv2.jpg"], "source_url": "https://www.collectiveactionsgroup.org/en/aboutca", "paper": {}, "also": []}, {"id": "mierle-laderman-ukeles--maintenance-art-one-hour", "creator_ids": ["mierle-laderman-ukeles"], "title": "I Make Maintenance Art One Hour Every Day", "year": 1976, "field": "social", "sub": "collective-action", "also": ["score"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "Ukeles invited the 300 maintenance workers of 55 Water Street, the building housing the Whitney's downtown branch, to declare one hour of their daily shift to be art.", "description_zh": "尤克里斯邀请水街 55 号（惠特尼美术馆下城分馆所在大楼）的 300 名维护工人，把每天班次中的一个小时宣布为艺术。", "idea_en": "Art by declaration: the same labour, relabelled by its workers for one hour a day.", "idea_zh": "以宣告成立的艺术：同样的劳动，由工人自己每天改称一小时为艺术。", "protocol": "Each worker chooses which hour of the eight-hour shift counts as maintenance art and wears a button during it; Ukeles photographs each worker with a Polaroid and each worker labels the photo 'maintenance work' or 'maintenance art'.", "protocol_zh": "每名工人自己选择八小时班次中的哪一个小时算作维护艺术，并在这一小时佩戴徽章；尤克里斯用宝丽来为每名工人拍照，由工人把照片标注为“维护工作”或“维护艺术”。", "collective": "About 300 workers on day and night shifts took part over six weeks (16 September – 20 October 1976), producing 720 Polaroids with their own labels; the installation entered the Whitney's collection in 2017.", "collective_zh": "约 300 名日班和夜班工人在六周内（1976 年 9 月 16 日至 10 月 20 日）参与，产生了 720 张由他们自己标注的宝丽来照片；这件装置于 2017 年入藏惠特尼美术馆。", "keywords": ["maintenance art", "Whitney", "Polaroid", "labour", "declaration"], "images": ["https://whitneymedia.org/assets/artwork/56140/2017_164a-b_cropped.jpg"], "source_url": "https://whitney.org/collection/works/56140", "video": {}, "paper": {}}, {"id": "sol-lewitt--wall-drawing-289", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #289", "year": 1976, "field": "score", "sub": "execution", "mechanisms": ["instruction", "constraint"], "substrate": "body", "kind": "artwork", "description": "White crayon lines on four black walls with a six-inch pencil grid: lines radiate from the centre, the midpoints of the sides and the corners to points the drafters choose. It is one of the last of LeWitt's 'location' drawings.", "description_zh": "四面黑墙上画有六英寸铅笔网格，白色蜡笔线从中心、各边中点和四角放射到绘图员选定的点上。这是勒维特“定位”系列墙绘的最后几件之一。", "idea_en": "An instruction can set a drawing problem that the person executing it has to solve.", "idea_zh": "一条指令可以提出一道绘图题，让执行的人去解。", "protocol": "'A 6-inch (15 cm) grid covering each of the four black walls. White lines to points on the grids. Fourth wall: twenty-four lines from the center, twelve lines from the midpoint of each of the sides, twelve lines from each corner. (The length of the lines and their placement are determined by the drafter.)'", "protocol_zh": "“一张 6 英寸（15 厘米）网格覆盖四面黑墙。白线画到网格上的点。第四面墙：从中心画二十四条线，从每边中点各画十二条，从每个角各画十二条。（线的长度和位置由绘图员决定。）”", "collective": "First installed at the Detroit Institute of Arts and, fourth wall only, at MoMA in 1978; owned by the Whitney Museum. At MASS MoCA drafters test each line with red string before drawing it in crayon, deciding the endpoints themselves.", "collective_zh": "首次安装于底特律美术馆，1978 年在 MoMA 只展出第四面墙；现为惠特尼美术馆收藏。在 MASS MoCA，绘图员先用红绳试放每一条线，再用蜡笔画出，终点由他们自己决定。", "keywords": ["wall drawing", "location drawing", "Whitney Museum", "white crayon", "MASS MoCA"], "images": ["https://massmoca.org/wp-content/uploads/2015/12/289-1.jpg"], "source_url": "https://massmoca.org/event/walldrawing289/", "video": {}, "paper": {}, "also": []}, {"id": "brian-eno--oblique-strategies", "creator_ids": ["brian-eno", "peter-schmidt"], "title": "Oblique Strategies", "year": 1975, "field": "score", "sub": "constraints", "mechanisms": ["instruction", "chance", "constraint"], "substrate": "text", "kind": "score", "description": "A boxed deck of cards, each printed with a short prompt, to be drawn at random when a creative process stalls; first published in 1975 and reissued in several editions.", "description_zh": "一盒卡片，每张印有一句简短的提示，在创作卡住时随机抽取；1975 年首次出版，此后多次再版。", "idea_en": "A deck of rules turns chance into a working method that anyone can pick up.", "idea_zh": "一副规则卡把偶然变成任何人都能拿来用的工作方法。", "protocol": "When stuck, draw a card and follow it, however obscure, for example \"Use an old idea\" or \"Consider different fading systems\". The deck is sold to anyone; Eno and Schmidt do not see how it is used.", "protocol_zh": "卡住时抽一张卡并照做，哪怕它很隐晦，比如“用一个旧点子”或“考虑不同的淡出方式”。这副卡片面向所有人出售，伊诺和施密特并不知道它会被怎样使用。", "collective": "Musicians, writers and designers have used the deck in their own work; Eno used it in studio sessions, including with David Bowie, and the publisher names Coldplay and Damon Albarn among users. Each draw produces a different decision in a different project.", "collective_zh": "音乐人、作家和设计师在各自的工作中使用这副卡片；伊诺在录音室里用过它，包括与大卫·鲍伊合作时，出版方还提到酷玩乐队和戴蒙·阿尔本也在使用。每一次抽卡都在不同的项目里带来不同的决定。", "keywords": ["card deck", "creative constraint", "David Bowie", "chance"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Oblique_Strategies_deck%2C_PO_Box%2C_The_Barbican%2C_London%2C_UK.jpg/960px-Oblique_Strategies_deck%2C_PO_Box%2C_The_Barbican%2C_London%2C_UK.jpg", "https://enoshop.co.uk/cdn/shop/files/Oblique-Image1.png?v=1743069911"], "source_url": "https://www.enoshop.co.uk/product/oblique-strategies.html", "also": [], "video": {}, "paper": {}}, {"id": "sol-lewitt--wall-drawing-260", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #260: On Black Walls, All Two-Part Combinations of White Arcs from Corners and Sides, and White Straight, Not-Straight, and Broken Lines", "year": 1975, "field": "score", "sub": "execution", "mechanisms": ["instruction", "constraint"], "substrate": "body", "kind": "artwork", "description": "A room-size drawing in white crayon on black walls that works through every two-part combination of arcs and lines inside a grid. The title is the complete instruction.", "description_zh": "一件房间尺度的墙绘：在黑墙上用白色蜡笔，在网格中穷尽弧线与直线的所有两两组合。标题本身就是完整的指令。", "idea_en": "When the title is the whole rule, anyone with the title can rebuild the work.", "idea_zh": "当标题就是全部规则，拿到标题的人就能重建作品。", "protocol": "'On black walls, all two-part combinations of white arcs from corners and sides, and white straight, not straight, and broken lines.' A team of trained drafters lays out the grid and draws each combination by hand in crayon on painted walls.", "protocol_zh": "“在黑墙上，白色弧线（从角和边出发）与白色直线、非直线、断线的所有两两组合。”一组受过训练的绘图员先打网格，再用蜡笔在刷好的墙上逐个手绘每种组合。", "collective": "MoMA owns the instructions; the drawing was carried out by a team of assistants for the 1978 LeWitt retrospective and again for 'Focus: Sol LeWitt' (2008–09), covering about 1,500 square feet. LeWitt compared his role to a composer's and the drafters' to musicians'.", "collective_zh": "MoMA 收藏的是这份指令；1978 年勒维特回顾展和 2008—09 年“聚焦：索尔·勒维特”展时，都由一组助手按指令绘制，面积约 1500 平方英尺。勒维特把自己的角色比作作曲家，把绘图员比作演奏者。", "keywords": ["wall drawing", "MoMA", "crayon", "black wall", "combinations"], "images": ["https://www.moma.org/media/W1siZiIsIjEzNzQwNiJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=6d06c886172651c2"], "source_url": "https://www.moma.org/collection/works/79898", "video": {}, "paper": {}, "also": []}, {"id": "sol-lewitt--wall-drawing-273", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #273: Lines to Points on a Grid", "year": 1975, "field": "score", "sub": "execution", "mechanisms": ["instruction", "chance"], "substrate": "body", "kind": "artwork", "description": "Seven walls with a pencil grid, each carrying red, yellow and blue crayon lines drawn from corners, sides or centre to points on the grid. LeWitt fixed the starting points; the drafters decide how many lines and where they end.", "description_zh": "七面墙上画有铅笔网格，每面墙上的红、黄、蓝蜡笔线从角、边中点或中心画到网格上的点。勒维特规定起点；画多少条、终点落在哪里由绘图员决定。", "idea_en": "Fix where lines start and leave where they end to the person drawing.", "idea_zh": "规定线从哪里出发，把线停在哪里交给画的人。", "protocol": "'A 6-inch (15 cm) grid covering the walls. Lines from corners, sides, and center of the walls to random points on the grid.' Red lines come from the midpoints of the sides, blue from the corners, yellow from the centre, combined differently on each of the seven walls; 'the number of lines and their length are determined by the draftsman.'", "protocol_zh": "“一张 6 英寸（15 厘米）的网格覆盖墙面。线条从墙的角、边和中心画到网格上的随机点。”红线出自各边中点，蓝线出自四角，黄线出自中心，七面墙各有不同组合；“线的数量和长度由绘图员决定”。", "collective": "Every installation is a new set of choices by a new team of drafters, so no two versions match. SFMOMA owns the work and publishes a family activity inviting the public to draw their own version from the instructions.", "collective_zh": "每次安装都是新一组绘图员的一组新选择，所以没有两个版本相同。旧金山现代艺术博物馆收藏此作，并推出家庭活动，邀请公众按指令画出自己的版本。", "keywords": ["wall drawing", "location drawing", "SFMOMA", "grid", "drafters' choice"], "images": ["https://d1hhug17qm51in.cloudfront.net/www-media/2026/08/19121212/FC.512_10N_LEWITT_512_V1R3-web.jpg"], "source_url": "https://www.sfmoma.org/artwork/FC.512/", "video": {}, "paper": {}, "also": []}, {"id": "marina-abramovic--rhythm-0", "creator_ids": ["marina-abramovic"], "title": "Rhythm 0", "year": 1974, "field": "social", "sub": "performance", "mechanisms": ["instruction", "participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "For six hours at Studio Morra in Naples, Abramović stood still beside a table of 72 objects, from a rose and honey to scissors, a scalpel and a loaded gun, which the audience could use on her as they wished.", "description_zh": "在那不勒斯莫拉工作室的六个小时里，阿布拉莫维奇静立在一张摆着 72 件物品的桌旁，从玫瑰、蜂蜜到剪刀、手术刀和一把上膛的枪，观众可以随意用它们作用于她。", "idea_en": "Hand the audience total permission and a fixed set of tools, and the crowd writes the piece.", "idea_zh": "给观众全部许可和一套固定工具，作品就由人群写成。", "protocol": "Written instruction on the wall: 'There are 72 objects on the table that one can use on me as desired. Performance. I am the object. During this period I take full responsibility.' Duration fixed at six hours (8 pm to 2 am); the artist does not react.", "protocol_zh": "墙上的书面指令：“桌上有 72 件物品，任何人都可以随意用在我身上。表演。我是客体。在此期间我承担全部责任。”时长固定为六小时（晚 8 点至凌晨 2 点）；艺术家不作任何反应。", "collective": "The audience began gently and grew aggressive: they cut off her clothes, cut her skin and at one point held the loaded gun to her head, until a protective faction intervened. When the six hours ended and she moved toward them, the audience left.", "collective_zh": "观众一开始很温和，随后变得越来越具攻击性：剪掉她的衣服、划破她的皮肤，一度把上膛的枪抵在她头上，直到另一派观众出面保护。六小时结束、她走向人群时，观众纷纷离开。", "keywords": ["Naples", "Studio Morra", "72 objects", "audience agency", "violence"], "video": {"url": "https://www.youtube.com/watch?v=xTBkbseXfOQ", "platform": "youtube", "id": "xTBkbseXfOQ", "thumbnail": "https://i.ytimg.com/vi/xTBkbseXfOQ/maxresdefault.jpg", "embeddable": true}, "source_url": "https://en.wikipedia.org/wiki/Rhythm_0", "images": [], "paper": {}, "also": []}, {"id": "lygia-clark--baba-antropofagica", "creator_ids": ["lygia-clark"], "title": "Baba Antropofágica (Anthropophagic Drool)", "year": 1973, "field": "social", "sub": "performance", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "A group kneels around one person lying on the floor; each has a spool of coloured thread in the mouth and pulls out the saliva-soaked thread onto the body below until it is covered in a web.", "description_zh": "一群人跪在一名躺在地上的人周围；每人嘴里含一卷彩色线，把被唾液浸湿的线一点点拉出、铺在下方的身体上，直到身体被一张网覆盖。", "idea_en": "A collective body produced by a simple bodily instruction shared by the group.", "idea_zh": "一条由全体共享的简单身体指令，造出一个集体的身体。", "protocol": "One volunteer lies down with eyes closed; the others take thread spools into their mouths and unwind the thread onto the volunteer; when the spools are empty the group lifts the web off together.", "protocol_zh": "一名志愿者闭眼躺下；其他人把线轴含进嘴里，把线拉出铺到志愿者身上；线轴用完后，全体一起把这张网揭下。", "collective": "Clark devised it with her students at the Sorbonne in Paris, where she taught from 1972; it has been re-enacted by groups in museums and workshops, and each performance produces a different web.", "collective_zh": "克拉克与她自 1972 年起在巴黎索邦大学教授的学生一起创作了这件作品；此后在美术馆和工作坊中被不同群体重演，每次都织出不同的网。", "keywords": ["Sorbonne", "proposition", "body", "saliva", "Neo-Concretism", "anthropophagy"], "video": {"url": "https://www.youtube.com/watch?v=r42tfsD0DKY", "platform": "youtube", "id": "r42tfsD0DKY", "thumbnail": "https://i.ytimg.com/vi/r42tfsD0DKY/hqdefault.jpg", "embeddable": true}, "images": ["https://portal.lygiaclark.org.br/public/upload/thumb/2021-10-21/816cfcd5d99dd68a28eee2286be107c8[1024x685].jpeg"], "source_url": "https://portal.lygiaclark.org.br/en/archive/66151/anthropophagic-slobber-rj-2011", "paper": {}, "also": []}, {"id": "allan-kaprow--routine", "creator_ids": ["allan-kaprow"], "title": "Routine", "year": 1973, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "participation", "constraint"], "substrate": "body", "kind": "score", "description": "A five-part score for pairs of participants using mirrors and telephones, realised at the Portland Center for the Visual Arts in December 1973 and later published as an activity booklet (1975).", "description_zh": "一份五段式乐谱，由两人一组的参与者用镜子和电话完成；1973 年 12 月在波特兰视觉艺术中心实现，1975 年以“活动手册”形式出版。", "idea_en": "Repeat an everyday gesture between two people until communication breaks down, and notice what you were doing.", "idea_zh": "让两个人反复做一个日常动作，直到交流失效，从而察觉自己在做什么。", "protocol": "Part 1 of the programme: \"standing somewhere / facing a friend holding a large mirror / trying to catch one's reflection ... moving apart again and again / repeating process / until it's no longer possible to see oneself.\" Parts 2 and 4 use the telephone, part 5 both.", "protocol_zh": "节目单第一部分：“站在某处／面对一位举着大镜子的朋友／试着看到自己的倒影……一次又一次地后退／重复这一过程／直到再也看不见自己。”第二、四部分使用电话，第五部分两者都用。", "collective": "About twenty pairs of participants carried out the programme during Kaprow's three-day residency, bracketed by a briefing and a review; each pair's realisation stayed private. Kaprow also made an instructional film and published the booklet so others could perform it.", "collective_zh": "在卡普罗为期三天的驻留中，约二十对参与者执行了这份节目单，前有“简报”、后有“回顾”；每一对的实现都是私下进行的。卡普罗还拍了一部教学影片并出版了手册，让别人也能来做。", "keywords": ["activity", "Portland Center for the Visual Arts", "mirror", "telephone", "The Scores Project"], "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/gri_980063_b24_f09_053_mm.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/gri_980063_b24_f09_009_mm.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/11/", "title": "11. Allan Kaprow: Routine (1973–75)", "venue": "The Scores Project, Getty Research Institute, 2025"}, "source_url": "https://www.getty.edu/publications/scores/11/", "also": [], "video": {}, "collections": ["the-scores-project"]}, {"id": "joseph-beuys--direct-democracy-office", "creator_ids": ["joseph-beuys"], "title": "Büro der Organisation für direkte Demokratie durch Volksabstimmung", "year": 1972, "field": "social", "sub": "performance", "mechanisms": ["participation", "governance", "time"], "substrate": "body", "kind": "artwork", "description": "At documenta 5 Beuys ran the office of his Organisation for Direct Democracy through Referendum inside the exhibition and talked with visitors about politics every day for the 100 days of the show.", "description_zh": "第五届卡塞尔文献展期间，博伊斯在展厅里开设“全民公决直接民主组织”的办公室，在展览的 100 天里每天与观众讨论政治。", "idea_en": "An exhibition slot turned into a public office whose content is the visitors' conversation.", "idea_zh": "把一个展位变成公共办公室，内容就是观众的谈话。", "protocol": "The office is open for the full run of the exhibition (30 June – 8 October 1972); any visitor may enter and debate direct democracy with the artist; the blackboards, leaflets and a closing boxing match 'for direct democracy' on the last day are the only fixed elements.", "protocol_zh": "办公室在展览全程（1972 年 6 月 30 日至 10 月 8 日）开放；任何观众都可以进来与艺术家辩论直接民主；固定元素只有黑板、传单，以及最后一天一场“为直接民主而战”的拳击赛。", "collective": "Thousands of documenta visitors passed through; a documented day in July 1972 counted 811 visitors, of whom 35 joined the discussion. The work consisted of these exchanges and ended with Beuys's staged boxing match against student Abraham David Christian on 8 October.", "collective_zh": "数以千计的文献展观众从办公室经过；1972 年 7 月某一天的记录显示有 811 名访客，其中 35 人参与讨论。作品就是这些交流，并以 10 月 8 日博伊斯与学生亚伯拉罕·大卫·克里斯蒂安的表演性拳击赛收尾。", "keywords": ["documenta 5", "direct democracy", "social sculpture", "discussion", "office"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/1972%2C_Umberto_Mariani%2C_Joseph_Beuys%2C_Jean_Pierre_Van_Tieghem%2C_Documenta_5%2C_Kassel.jpg/960px-1972%2C_Umberto_Mariani%2C_Joseph_Beuys%2C_Jean_Pierre_Van_Tieghem%2C_Documenta_5%2C_Kassel.jpg"], "source_url": "https://de.wikipedia.org/wiki/Organisation_f%C3%BCr_direkte_Demokratie_durch_Volksabstimmung", "video": {}, "paper": {}, "also": []}, {"id": "pauline-oliveros--sonic-meditations", "creator_ids": ["pauline-oliveros"], "title": "Sonic Meditations", "year": 1971, "field": "score", "sub": "public-instructions", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "A set of text scores (published 1974) for listening, breathing and sounding together, which any group can perform without musical training.", "description_zh": "一组文字乐谱（1974 年出版），关于共同聆听、呼吸与发声，任何团体无需音乐训练即可演出。", "idea_en": "Make listening to each other the instruction, and a room of strangers becomes one instrument.", "idea_zh": "把“彼此聆听”写成指令，一屋子陌生人就成了一件乐器。", "protocol": "Each meditation is a short verbal instruction; in the Tuning Meditation, participants alternate between singing a tone they imagine, matching a tone sung by someone else, and offering a new tone no one else is singing.", "protocol_zh": "每一首冥想都是一段简短的文字指令；在《调音冥想》中，参与者交替地唱出自己想象的音、与别人正在唱的音对齐，以及唱出一个没有人在唱的新音。", "collective": "Oliveros developed the pieces from 1971 with a women's ensemble in California; museums and festivals such as the Blanton Museum of Art and The Met Cloisters now stage the Tuning Meditation with their visitors, and the resulting chord changes with each crowd.", "collective_zh": "奥利维罗斯自 1971 年起与加州的一个女性乐团共同发展这些作品；如今布兰顿美术馆、大都会博物馆修道院分馆等机构和艺术节带着观众演出《调音冥想》，每一群人唱出的和声都不同。", "keywords": ["Deep Listening", "Tuning Meditation", "text score", "sonic awareness"], "video": {"url": "https://www.youtube.com/watch?v=wlxUpqsdlHM", "platform": "youtube", "id": "wlxUpqsdlHM", "thumbnail": "https://i.ytimg.com/vi/wlxUpqsdlHM/maxresdefault.jpg", "embeddable": true}, "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Pauline_Oliveros_-SonicActs_-SonicActs2012.jpg/960px-Pauline_Oliveros_-SonicActs_-SonicActs2012.jpg"], "source_url": "https://www.newyorker.com/culture/culture-desk/listening-as-activism-the-sonic-meditations-of-pauline-oliveros", "paper": {}, "also": []}, {"id": "sol-lewitt--wall-drawing-118", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #118: 50 randomly placed points connected by straight lines", "year": 1971, "field": "score", "sub": "execution", "mechanisms": ["instruction", "chance"], "substrate": "body", "kind": "artwork", "description": "A wall drawing that LeWitt wrote for students of the School of the Museum of Fine Arts, Boston, in 1971 instead of giving a lecture. Fifty points placed by the drafters are all connected to one another, so each version produces a different dense web.", "description_zh": "1971 年勒维特受邀在波士顿美术馆学院演讲，他没有讲课，而是写下这件墙绘让学生来画。绘图员自己放置五十个点并把它们两两相连，每个版本都会形成一张不同的密网。", "idea_en": "A one-sentence rule with a random step: the same text yields a different drawing every time.", "idea_zh": "一句话的规则里含有一个随机步骤：同样的文字，每次都画出不同的图。", "protocol": "'On a wall surface, any continuous stretch of wall, using a hard pencil, place fifty points at random. The points should be evenly distributed over the area of the wall. All of the points should be connected by straight lines.'", "protocol_zh": "“在一面墙上任意一段连续的墙面，用硬铅笔随机放置五十个点。点应均匀分布在墙面上。所有的点都用直线相连。”", "collective": "First executed by students in Boston without the artist present. The drafters choose where the points go, and because every point connects to every other, small choices change the whole web. The Art Institute of Chicago received the work in 2023.", "collective_zh": "首次由波士顿的学生在艺术家不在场的情况下完成。点的位置由绘图员决定，而每个点都要与其他所有点相连，所以细小的选择会改变整张网。芝加哥艺术博物馆于 2023 年获赠此作。", "keywords": ["wall drawing", "random points", "students", "Boston", "Art Institute of Chicago"], "paper": {"url": "https://www.cahiersdartinstitute.org/catalogues/sol-lewitt-wall-drawings/description", "title": "Sol LeWitt Wall Drawings Catalogue Raisonné", "venue": "Cahiers d'Art Institute"}, "source_url": "https://www.artic.edu/artworks/196148/wall-drawing-118-50-randomly-placed-points-connected-by-straight-lines", "video": {}, "images": [], "also": []}, {"id": "hans-haacke--moma-poll", "creator_ids": ["hans-haacke"], "title": "MoMA Poll", "year": 1970, "field": "social", "sub": "performance", "also": ["network"], "mechanisms": ["participation", "governance"], "substrate": "body", "kind": "artwork", "description": "In MoMA's Information exhibition, visitors answered a political question about Governor Nelson Rockefeller, a MoMA trustee, by dropping ballots into one of two transparent boxes.", "description_zh": "在 MoMA 的“信息”展中，观众通过把选票投入两个透明箱子之一，回答一个关于纳尔逊·洛克菲勒州长（也是 MoMA 理事）的政治问题。", "idea_en": "A live poll in which the museum's own audience produces the evidence, visible as it accumulates.", "idea_zh": "一次现场投票，由美术馆自己的观众产生证据，并随累积而清晰可见。", "protocol": "Question on the wall: 'Would the fact that Governor Rockefeller has not denounced President Nixon's Indochina policy be a reason for your not voting for him in November?' Each visitor may drop a ballot in the YES or the NO box; ballots are colour-coded by ticket type; the running count stays visible.", "protocol_zh": "墙上的问题：“洛克菲勒州长没有谴责尼克松总统的印度支那政策，这一事实会不会成为你十一月不投票给他的理由？”每位观众可以把选票投进“是”或“否”的箱子；选票按门票类型用颜色区分；累计结果始终可见。", "collective": "Visitors voted throughout the exhibition; by the end there were roughly twice as many Yes ballots as No ballots, a public verdict gathered inside an institution Rockefeller helped run.", "collective_zh": "观众在整个展期内投票；展览结束时，“是”的选票约为“否”的两倍，这是在洛克菲勒参与管理的机构内部收集到的公开裁决。", "keywords": ["MoMA", "Information (1970)", "poll", "Nelson Rockefeller", "institutional critique"], "images": ["https://guernica.museoreinasofia.es/sites/default/files/styles/large/public/documento/FF-033%281%29.jpg?itok=4_Ta5ADH", "http://dataphys.org/list/images/uploads/2015/02/haacke1.jpg"], "source_url": "https://guernica.museoreinasofia.es/en/document/moma-poll", "video": {}, "paper": {}}, {"id": "jack-burnham--software", "creator_ids": ["jack-burnham"], "title": "Software: Information Technology: Its New Meaning for Art", "year": 1970, "field": "theory", "sub": "systems", "mechanisms": ["instruction", "participation"], "substrate": "text", "kind": "publication", "description": "Exhibition and catalogue curated by Burnham at the Jewish Museum, New York (16 September – 8 November 1970), that showed conceptual artists and computer systems side by side, treating 'software' as instructions carried out by machines or by visitors.", "description_zh": "Burnham 在纽约犹太博物馆策划的展览及其画册（1970 年 9 月 16 日至 11 月 8 日），把观念艺术家与计算机系统并置，把“软件”理解为由机器或观众执行的指令。", "idea_en": "An exhibition can be a program: instructions that visitors and machines execute together.", "idea_zh": "展览本身可以是一段程序：由观众和机器共同执行的指令。", "protocol": "Works were framed as 'software': sets of instructions written by the artist and run by a computer or by the public, such as Hans Haacke's Visitor's Profile, which tabulated visitors' answers to a questionnaire, and Ted Nelson's hypertext catalogue Labyrinth.", "protocol_zh": "作品被当作“软件”来呈现：由艺术家写下、由计算机或公众执行的指令组，例如 Hans Haacke 的 Visitor's Profile（统计观众填写的问卷）和 Ted Nelson 的超文本目录 Labyrinth。", "collective": "Visitors' answers and actions supplied the content of several works; the show, which also travelled to the Smithsonian, is remembered as the first major US museum exhibition to bring the computer into the gallery.", "collective_zh": "观众的回答和操作构成了多件作品的内容；该展随后巡回至史密森尼学会，被视为美国第一个把计算机带进展厅的大型博物馆展览。", "keywords": ["Jewish Museum", "1970", "Hans Haacke", "Ted Nelson", "information art"], "images": ["https://monoskop.org/images/5/5b/Software-catalogue.jpg"], "paper": {"url": "https://monoskop.org/Software_(exhibition)", "venue": "The Jewish Museum, New York, 1970 (exhibition catalogue)", "title": "Software: Information Technology: Its New Meaning for Art"}, "source_url": "https://www.fondation-langlois.org/html/e/page.php?NumPage=541", "video": {}, "also": []}, {"id": "tom-marioni--act-of-drinking-beer", "creator_ids": ["tom-marioni"], "title": "The Act of Drinking Beer with Friends Is the Highest Form of Art", "year": 1970, "field": "social", "sub": "performance", "mechanisms": ["participation", "time"], "substrate": "body", "kind": "artwork", "description": "Marioni invited friends to drink beer with him at the Oakland Museum and declared the gathering the artwork; it has continued as a weekly salon in San Francisco for decades.", "description_zh": "马里奥尼邀请朋友在奥克兰博物馆和他一起喝啤酒，并宣布这场聚会就是艺术作品；此后几十年，它作为每周一次的沙龙在旧金山延续。", "idea_en": "A recurring social ritual declared as art; its residue (bottles, debris) is the only object.", "idea_zh": "被宣布为艺术的定期社交仪式；它的残留物（酒瓶、杂物）是唯一的实物。", "protocol": "The artist invites friends to drink beer and talk at a set time and place; nothing else is required; the empty bottles and debris are left in place and can be exhibited.", "protocol_zh": "艺术家邀请朋友在约定的时间和地点喝啤酒、聊天；除此之外没有任何要求；空瓶和杂物原地保留，可以展出。", "collective": "Sixteen friends attended the first event at the Oakland Museum in 1970; by 1973 the gatherings had become weekly salons, held on Wednesdays for decades; SFMOMA showed and acquired the debris installation FREE BEER in 1979.", "collective_zh": "1970 年奥克兰博物馆的首次活动有 16 位朋友参加；到 1973 年聚会变成每周一次的沙龙，此后几十年都在周三举行；旧金山现代艺术博物馆于 1979 年展出并收藏了由残留物构成的装置《免费啤酒》。", "keywords": ["Museum of Conceptual Art", "Oakland Museum", "SFMOMA", "salon", "beer"], "video": {"url": "https://www.youtube.com/watch?v=6ieR8cCoGQY", "platform": "youtube", "id": "6ieR8cCoGQY", "thumbnail": "https://i.ytimg.com/vi/6ieR8cCoGQY/maxresdefault.jpg", "embeddable": true}, "images": ["https://fac.coloradocollege.edu/wp-content/uploads/2018/02/Beer-bottles.jpg"], "source_url": "https://www.sfmoma.org/artwork/99.70.A-E/", "paper": {}, "also": []}, {"id": "cornelius-cardew--scratch-orchestra", "creator_ids": ["cornelius-cardew"], "title": "A Scratch Orchestra: Draft Constitution", "year": 1969, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["participation", "governance", "instruction"], "substrate": "body", "kind": "organization", "description": "A constitution, published in The Musical Times in June 1969, for an orchestra open to anyone, founded in London by Cornelius Cardew, Michael Parsons and Howard Skempton.", "description_zh": "1969 年 6 月发表于《音乐时报》的一份章程，为一个向所有人开放的乐团而写；该乐团由科尼利厄斯·卡迪尤、迈克尔·帕森斯和霍华德·斯凯普顿在伦敦创办。", "idea_en": "Write the orchestra's constitution as the score: membership, categories of activity and who proposes the next concert.", "idea_zh": "把乐团章程当作乐谱来写：成员资格、活动类别，以及由谁提议下一场音乐会。", "protocol": "A Scratch Orchestra is \"a large number of enthusiasts pooling their resources (not primarily material resources) and assembling for action (music-making, performance, edification)\"; members keep a notebook of their own accompaniments, and concerts are built from Scratch Music, Popular Classics, Improvisation Rites, compositions and research projects, with members taking turns to plan them.", "protocol_zh": "Scratch Orchestra 是“大量爱好者汇集各自的资源（主要不是物质资源），为行动（演奏、表演、自我教化）而聚集”；每位成员记录自己的伴奏笔记，音乐会由“Scratch 音乐”“流行经典”“即兴仪式”、作品和研究项目组成，由成员轮流策划。", "collective": "Artists, students and non-musicians joined, performing in halls and at outdoor sites across Britain; the orchestra's internal debates became part of its history when, in the early 1970s, many members turned to political music and the group split.", "collective_zh": "艺术家、学生和非音乐人纷纷加入，在英国各地的礼堂和户外场所演出；乐团内部的争论也成了它历史的一部分——20 世纪 70 年代初，许多成员转向政治音乐，团体随之分裂。", "keywords": ["Scratch Orchestra", "Musical Times", "Improvisation Rites", "Michael Parsons", "Howard Skempton"], "video": {"url": "https://www.youtube.com/watch?v=CudcmB4_OTw", "platform": "youtube", "id": "CudcmB4_OTw", "thumbnail": "https://i.ytimg.com/vi/CudcmB4_OTw/hqdefault.jpg", "embeddable": true}, "paper": {"url": "https://doi.org/10.2307/951759", "doi": "10.2307/951759", "venue": "The Musical Times, June 1969", "title": "A Scratch Orchestra: Draft Constitution"}, "source_url": "https://en.wikipedia.org/wiki/Scratch_Orchestra", "images": []}, {"id": "david-katzive--art-by-telephone", "creator_ids": ["david-katzive"], "title": "Art by Telephone", "year": 1969, "field": "score", "sub": "execution", "mechanisms": ["instruction", "participation"], "substrate": "text", "kind": "artwork", "description": "An exhibition at the Museum of Contemporary Art Chicago (1 November–14 December 1969) in which artists in the US and Europe phoned in instructions for works that museum staff then made; the catalogue was an LP of the calls.", "description_zh": "芝加哥当代艺术博物馆的一场展览（1969 年 11 月 1 日至 12 月 14 日）：美国和欧洲的艺术家打电话口述作品的指令，再由馆方员工制作出来；展览图录是一张记录这些通话的黑胶唱片。", "idea_en": "Restrict the channel to a phone call and the museum becomes the artist's hands.", "idea_zh": "把沟通渠道限定为一通电话，美术馆就成了艺术家的手。", "protocol": "Artists communicate their proposal to the curator by telephone only; drawings, blueprints and written descriptions are avoided. MCA staff carry out the works from the spoken instructions. The idea takes Moholy-Nagy's 1922 'telephone pictures' as its starting point.", "protocol_zh": "艺术家只能通过电话向策展人传达方案，避免使用图纸、蓝图和书面描述。芝加哥当代艺术博物馆员工根据口头指令完成作品。这个构想以莫霍利-纳吉 1922 年的“电话绘画”为起点。", "collective": "Staff produced a Sol LeWitt wall drawing from his oral instructions and poured cement down a slope for Robert Smithson; visitors filled Arman's Plexiglas container with their own trash, and dialled Wolf Vostell's changing phone numbers for instructions for one-minute happenings. The exhibition was restaged as Art by Telephone... Recalled from 2012.", "collective_zh": "员工根据索尔·勒维特的口头指令画出一幅墙绘，并为罗伯特·史密森把水泥倒下山坡；观众把自己的垃圾投进阿尔曼的有机玻璃容器，还拨打沃尔夫·福斯特尔不断更换的电话号码，获取“一分钟偶发”的指令。该展自 2012 年起以 Art by Telephone... Recalled 之名重演。", "keywords": ["telephone", "MCA Chicago", "exhibition as score", "LP catalogue", "Jan van der Marck"], "images": ["https://mcachicago.org/wp-content/uploads/image/IIARY2TY/original.jpg"], "source_url": "https://mcachicago.org/exhibitions/1969/art-by-telephone", "also": [], "video": {}, "paper": {}}, {"id": "john-baldessari--commissioned-paintings", "creator_ids": ["john-baldessari"], "title": "Commissioned Paintings", "year": 1969, "field": "score", "sub": "execution", "mechanisms": ["instruction", "contract", "co-authorship"], "substrate": "body", "kind": "series", "description": "A series of paintings of a hand pointing at things, each painted by a different amateur painter from Baldessari's photographs, with \"A PAINTING BY\" and the painter's name lettered below by a sign painter.", "description_zh": "一组画着一只手指向各种东西的绘画，每幅都由一位不同的业余画家根据巴尔代萨里拍的照片画成，下方由招牌画师写上“A PAINTING BY”加画者的名字。", "idea_en": "Author the procedure, not the painting, and put the maker's name on the work.", "idea_zh": "只写流程，不画画，并把制作者的名字写在作品上。", "protocol": "A friend points at things Baldessari finds interesting; the pointing is photographed; amateur painters are commissioned to copy the photographs in paint; a sign painter adds the caption \"A PAINTING BY\" followed by the painter's name.", "protocol_zh": "一位朋友指向巴尔代萨里觉得有意思的东西；这一指被拍成照片；委托业余画家把照片画成油画；再请招牌画师加上说明文字“A PAINTING BY”和画者的名字。", "collective": "Each commissioned painter brought their own skill and style, so the series varies from canvas to canvas while no stroke is Baldessari's. It answered Al Held's remark that conceptual art was 'just pointing at things'.", "collective_zh": "每位受托画家都带来自己的技术和风格，所以这组画每张都不一样，而没有一笔出自巴尔代萨里本人。它回应了阿尔·赫尔德“观念艺术不过是指着东西”的说法。", "keywords": ["authorship", "amateur painters", "conceptual art", "pointing"], "images": ["https://res.cloudinary.com/smimagebank/image/upload/w_1200,c_limit,f_jpg,fl_progressive/v1586025521/sprueth_magers_John_Baldessari_The_Commissioned_Paintings_9033.jpg", "https://res.cloudinary.com/smimagebank/image/upload/w_1200,c_limit,f_jpg,fl_progressive/v1586025526/sprueth_magers_John_Baldessari_The_Commissioned_Paintings_9034.jpg"], "source_url": "https://spruethmagers.com/exhibitions/john-baldessari-the-commissioned-paintings-cologne/", "also": [], "video": {}, "paper": {}}, {"id": "frederic-rzewski--les-moutons-de-panurge", "creator_ids": ["frederic-rzewski"], "title": "Les Moutons de Panurge", "year": 1969, "field": "score", "sub": "constraints", "mechanisms": ["constraint", "participation", "chance"], "substrate": "body", "kind": "score", "description": "A piece for any number of musicians playing a 65-note melody additively (1, 1–2, 1–2–3 …), with optional non-musicians making noise alongside.", "description_zh": "一首为任意数量乐手而作的作品：以累加方式演奏一段 65 个音的旋律（1、1—2、1—2—3……），也可加入非音乐人同时制造噪音。", "idea_en": "A rule that punishes mistakes by keeping them turns an ensemble's errors into the form of the piece.", "idea_zh": "一条把错误保留下来的规则，让乐团的失误成为作品的形式。", "protocol": "All players read the same melody, adding one note on each pass and then subtracting; the score instructs: \"Stay together as long as you can, but if you get lost, stay lost.\"", "protocol_zh": "所有演奏者读同一段旋律，每一轮加一个音，之后再逐轮减去；乐谱指示：“尽可能保持在一起，但如果你迷失了，就继续迷失下去。”", "collective": "Performed by conservatories, bands and ensembles such as A Far Cry and eighth blackbird, sometimes with the audience as the non-musician section; the moment players drift apart and the resulting counterpoint differ in each performance.", "collective_zh": "音乐学院、乐队以及 A Far Cry、eighth blackbird 等乐团都演出过它，有时由观众充当非音乐人声部；乐手何时走散、形成怎样的对位，每一次都不同。", "keywords": ["additive process", "error", "Musica Elettronica Viva", "audience participation"], "video": {"url": "https://www.youtube.com/watch?v=NJ-ZVkVvgrI", "platform": "youtube", "id": "NJ-ZVkVvgrI", "thumbnail": "https://i.ytimg.com/vi/NJ-ZVkVvgrI/maxresdefault.jpg", "embeddable": true}, "source_url": "https://en.wikipedia.org/wiki/Frederic_Rzewski", "images": [], "paper": {}, "also": []}, {"id": "sol-lewitt--sentences-on-conceptual-art", "creator_ids": ["sol-lewitt"], "title": "Sentences on Conceptual Art", "year": 1969, "field": "theory", "sub": "systems", "also": ["score"], "mechanisms": ["instruction", "constraint"], "substrate": "text", "kind": "publication", "description": "Thirty-five numbered statements first printed in the magazine 0 to 9 (no. 5, January 1969) and then in the first issue of Art-Language (May 1969), extending LeWitt's argument that ideas alone can be works of art.", "description_zh": "三十五条编号语句，首先刊于杂志《0 to 9》第 5 期（1969 年 1 月），随后刊于《Art-Language》创刊号（1969 年 5 月），延续了 LeWitt“观念本身即可成为艺术作品”的论点。", "idea_en": "Once the process is set, let it run: follow the rules even when the result surprises you.", "idea_zh": "过程一旦设定就让它运行：即使结果出乎意料，也按规则走下去。", "protocol": "The sentences state that the artist should not change the idea mid-course, that the process is mechanical once begun, and that 'the idea becomes a machine that makes the art'; perception of the work is left to each viewer.", "protocol_zh": "这些语句规定：艺术家不应在中途改变观念；过程一旦开始便是机械的；“观念成为制造艺术的机器”；对作品的感知则留给每位观者。", "collective": "Reprinted in most Conceptual art anthologies, the sentences are read as a rulebook by artists who write systems for others to run, from wall-drawing assistants to generative and smart-contract artists.", "collective_zh": "这组语句被大多数观念艺术文集收录，被那些为他人编写可执行系统的艺术家当作规则手册来读：从墙绘助手到生成艺术和智能合约艺术家。", "keywords": ["Conceptual art", "0 to 9", "Art-Language", "rules", "process"], "images": ["https://wiels.org/uploads/resized/uploads/355769/Sol-LeWitts-Sentences-on-Conceptual-Art-Manuscript-and-Draft-Material-196869_58f02840803f2ddfa28c8dbfb30a044c.jpg"], "paper": {"url": "https://monoskop.org/images/3/3d/LeWitt_Sol_1969_1999_Sentences_on_Conceptual_Art.pdf", "venue": "0 to 9, no. 5 (January 1969); Art-Language 1, no. 1 (May 1969)", "title": "Sentences on Conceptual Art"}, "source_url": "https://wiels.org/en/events/sol-lewitts-sentences-on-conceptual-art-manuscript-and-draft-material-1968-69", "video": {}}, {"id": "alison-knowles--identical-lunch", "creator_ids": ["alison-knowles"], "title": "The Identical Lunch", "year": 1969, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "score", "description": "A score based on the lunch Knowles ate at the same New York diner many days a week, which friends and later audiences repeat and document.", "description_zh": "一份乐谱，来自诺尔斯每周多天在纽约同一家小餐馆吃的同一份午餐，朋友们和后来的观众照做并记录下来。", "idea_en": "A daily habit written down as a score becomes a shared experiment in repetition.", "idea_zh": "把日常习惯写成乐谱，就成了一场关于重复的共同实验。", "protocol": "The score reads: \"a tunafish sandwich on wheat toast with lettuce and butter, no mayo and a large glass of buttermilk was and is eaten many days of each week at the same place at about the same time.\" Performers eat the lunch and record how each time differs.", "protocol_zh": "乐谱写道：“一份金枪鱼三明治，全麦吐司，加生菜和黄油，不要蛋黄酱，配一大杯酪乳，过去和现在都在每周许多天、在同一地点、大约同一时间被吃掉。”表演者吃下这份午餐，并记录每一次的不同。", "collective": "Knowles collected friends' realizations, receipts and diagrams in Journal of the Identical Lunch (1971); Philip Corner wrote a book of his versions (1973), George Maciunas made a symphony version, and the University of Chicago's Logan Center staged an Identical Lunch Symphony with the public in 2012.", "collective_zh": "诺尔斯把朋友们的实现、收据和图表收入《相同午餐日志》（1971）；菲利普·科纳把自己的版本写成一本书（1973），乔治·马修纳斯做了一个“交响曲”版本，2012 年芝加哥大学洛根艺术中心与公众一起上演了《相同午餐交响曲》。", "keywords": ["Fluxus", "food", "repetition", "Philip Corner", "Riss Restaurant"], "video": {"url": "https://www.youtube.com/watch?v=d-MSbtR-90M", "platform": "youtube", "id": "d-MSbtR-90M", "thumbnail": "https://i.ytimg.com/vi/d-MSbtR-90M/hqdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/posters/AlisonKnowles_IdenticalLunchSymphony_1.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/grl_91-b35085_01_cover_th.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/r32814_890164_b264_002_th.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/09/", "venue": "The Scores Project (Getty Research Institute, 2025)", "title": "Alison Knowles: The Identical Lunch (late 1960s–early ’70s)"}, "source_url": "https://www.getty.edu/publications/scores/09/", "also": [], "collections": ["the-scores-project"]}, {"id": "sol-lewitt--wall-drawing-11", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #11", "year": 1969, "field": "score", "sub": "execution", "mechanisms": ["instruction", "constraint"], "substrate": "body", "kind": "artwork", "description": "An early pencil wall drawing: a wall split into four parts, each filled with three of the four basic line directions laid over one another. It was first drawn at Paula Cooper Gallery in 1969 by Jerry Orter, the artist Adrian Piper and LeWitt.", "description_zh": "一件早期铅笔墙绘：墙面分成四份，每份叠画四种基本线条方向中的三种。1969 年首次在 Paula Cooper 画廊由 Jerry Orter、艺术家 Adrian Piper 和勒维特本人绘制。", "idea_en": "A four-word vocabulary of line directions is enough to generate a whole family of works that other hands can draw.", "idea_zh": "只用四种线条方向组成的“词汇”，就能生成一整套可以交给别人画的作品。", "protocol": "'A wall divided horizontally and vertically into four equal parts. Within each part, three of the four kinds of lines are superimposed.' Drafters work in hard black pencil, spacing the lines by bundles of taped leads.", "protocol_zh": "“一面墙横竖各分为四等份。每一份中叠画四种线条中的三种。”绘图员用硬黑铅笔作画，用胶带捆在一起的铅芯来控制线距。", "collective": "The first drafters included Adrian Piper, then LeWitt's assistant and later a major conceptual artist. For the MASS MoCA retrospective (2008) it was redrawn by the LeWitt studio team; the drawing now belongs to Yale University Art Gallery.", "collective_zh": "首批绘图员中有 Adrian Piper，她当时是勒维特的助手，后来成为重要的观念艺术家。在 MASS MoCA 回顾展（2008）中由勒维特工作室团队重新绘制；作品现藏耶鲁大学美术馆。", "keywords": ["wall drawing", "Adrian Piper", "pencil", "permutation", "Yale University Art Gallery"], "images": ["https://massmoca.org/wp-content/uploads/2015/12/11-1.jpg"], "source_url": "https://massmoca.org/event/walldrawing11/", "video": {}, "paper": {}, "also": []}, {"id": "karlheinz-stockhausen--aus-den-sieben-tagen", "creator_ids": ["karlheinz-stockhausen"], "title": "Aus den sieben Tagen", "year": 1968, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "constraint"], "substrate": "body", "kind": "score", "description": "Fifteen short text compositions written in May 1968, which Stockhausen called intuitive music: instead of notes, each gives the players a mood, an image or a way of playing.", "description_zh": "1968 年 5 月写成的十五首短小文字作品，施托克豪森称之为“直觉音乐”：它们不给音符，而是给演奏者一种情绪、一个意象或一种演奏方式。", "idea_en": "A sentence can be a full score if it changes how the players listen.", "idea_zh": "只要能改变演奏者的聆听方式，一句话也可以是完整的乐谱。", "protocol": "Each piece is a text for an ensemble; the whole of Unbegrenzt reads: \"play a sound with the certainty that you have an infinite amount of time and space.\" Players respond to the text and to each other, without notation.", "protocol_zh": "每首作品都是写给乐团的一段文字；《无限》全文是：“演奏一个音，确信你拥有无限的时间和空间。”演奏者回应文字、也彼此回应，不借助任何记谱。", "collective": "Stockhausen's own group recorded the pieces in 1969; later ensembles, from electronic improvisers to the zeitkratzer ensemble with Keiji Haino and a 2022 performance in Prague released by Supraphon, produce performances that share no common material.", "collective_zh": "施托克豪森自己的乐团在 1969 年录制了这些作品；后来的乐团——从电子即兴乐手，到与灰野敬二合作的 zeitkratzer，再到 Supraphon 发行的 2022 年布拉格演出——所演出的版本之间没有任何共同的音乐材料。", "keywords": ["intuitive music", "text score", "Unbegrenzt", "1968"], "video": {"url": "https://www.youtube.com/watch?v=e_reft1hEJ4", "platform": "youtube", "id": "e_reft1hEJ4", "thumbnail": "https://i.ytimg.com/vi/e_reft1hEJ4/maxresdefault.jpg", "embeddable": true}, "source_url": "https://en.wikipedia.org/wiki/Aus_den_sieben_Tagen", "images": [], "paper": {}, "also": []}, {"id": "lawrence-weiner--statements", "creator_ids": ["lawrence-weiner"], "title": "Statements / Declaration of Intent", "year": 1968, "field": "score", "sub": "execution", "mechanisms": ["instruction", "contract"], "substrate": "text", "kind": "publication", "description": "Weiner's first book, published by Seth Siegelaub and the Louis Kellner Foundation in 1968: 24 short statements describing materials and processes, each a complete work. It came with his rule that the receiver decides whether a work is built at all.", "description_zh": "韦纳的第一本书，1968 年由 Seth Siegelaub 与 Louis Kellner 基金会出版：24 条描述材料和过程的简短陈述，每条都是一件完整作品。与之配套的是他的规则：作品是否要被建造，由接收者决定。", "idea_en": "Publish the work as language and let whoever holds it choose to build it, have it built, or leave it unbuilt.", "idea_zh": "把作品以语言发布，由持有者选择自己建、请人建，或者不建。", "protocol": "Declaration of Intent: '1. The artist may construct the piece. 2. The piece may be fabricated. 3. The piece need not be built. Each being equal and consistent with the intent of the artist the decision as to condition rests with the receiver upon the occasion of receivership.'", "protocol_zh": "《意图声明》：“1. 艺术家可以建造作品。2. 作品可以被制作。3. 作品不必被建造。三者同等并都符合艺术家的意图，作品处于何种状态，由接收者在接收之时决定。”", "collective": "Collectors, curators, sign painters and readers realise the statements in different forms: painted on walls, installed as objects, or kept only as text. The book itself was printed in an edition of 1,000 and circulated in place of an exhibition of objects.", "collective_zh": "收藏者、策展人、招牌画工和读者以不同形式实现这些陈述：刷在墙上、做成实物，或只保留为文字。这本书本身印了 1000 册，代替实物展览流通。", "keywords": ["Seth Siegelaub", "Declaration of Intent", "language", "receiver", "artist's book"], "images": ["https://static1.squarespace.com/static/60e820d70025154c9413112f/641483492b47ac67ecd62a35/6407b37ef991f15f62312bb0/1787831117470/DSC04467.jpg?format=1500w", "https://upload.wikimedia.org/wikipedia/commons/thumb/a/af/Wandmalerei_Stein_auf_Stein_auf_gefallenen_Stein_%28Lawrence_Weiner_1983%29_04.jpg/960px-Wandmalerei_Stein_auf_Stein_auf_gefallenen_Stein_%28Lawrence_Weiner_1983%29_04.jpg"], "paper": {"url": "https://toninieditore.com/shop-studio-bruno-tonini/p/lawrence-weiner-statements", "title": "Statements (New York: Louis Kellner Foundation / Seth Siegelaub, 1968)", "venue": "Artist's book"}, "source_url": "https://en.wikipedia.org/wiki/Lawrence_Weiner", "video": {}, "also": []}, {"id": "christian-wolff--stones", "creator_ids": ["christian-wolff"], "title": "Stones (from Prose Collection)", "year": 1968, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "constraint"], "substrate": "body", "kind": "score", "description": "A short prose score from Wolff's Prose Collection (1968–71) for any number of people making sounds with stones.", "description_zh": "沃尔夫《散文集》（1968—1971）中的一首短小文字乐谱，写给任意数量用石头发声的人。", "idea_en": "A few sentences and a handful of stones are enough for a group to make a piece together.", "idea_zh": "几句话加一把石头，就足够让一群人共同完成一首作品。", "protocol": "\"Make sounds with stones, draw sounds out of stones\", using stones of different sizes and kinds, mostly striking stones with stones but also on other surfaces; the score ends: \"Do not break anything.\"", "protocol_zh": "“用石头发出声音，从石头里引出声音”，使用不同大小和种类的石头，主要是石头敲石头，也可以敲在其他表面上；乐谱最后一句是：“不要打破任何东西。”", "collective": "Performed by new-music ensembles, students and non-musicians; the stones gathered for each performance, and how the players listen to one another, make every version sound different.", "collective_zh": "现代音乐乐团、学生和非音乐人都演出过它；每次演出收集到的石头不同，演奏者彼此聆听的方式不同，每个版本听起来都不一样。", "keywords": ["Prose Collection", "text score", "stones", "non-musicians"], "video": {"url": "https://www.youtube.com/watch?v=5lNfOox76EY", "platform": "youtube", "id": "5lNfOox76EY", "thumbnail": "https://i.ytimg.com/vi/5lNfOox76EY/hqdefault.jpg", "embeddable": true}, "source_url": "https://en.wikipedia.org/wiki/Christian_Wolff_(composer)", "images": [], "paper": {}, "also": []}, {"id": "jack-burnham--systems-esthetics", "creator_ids": ["jack-burnham"], "title": "Systems Esthetics", "year": 1968, "field": "theory", "sub": "systems", "mechanisms": ["constraint", "participation"], "substrate": "text", "kind": "publication", "description": "Essay in Artforum (September 1968) arguing that art was shifting from making objects to organising systems: relations between people, materials, information and institutions over time.", "description_zh": "发表于《Artforum》（1968 年 9 月）的文章，认为艺术正从制造物体转向组织系统：人、材料、信息与机构之间随时间变化的关系。", "idea_en": "The artwork is not the object but the system of relations it sets in motion.", "idea_zh": "作品不是物体，而是它所启动的关系系统。", "protocol": "Burnham borrows from systems theory and cybernetics: a work is a set of components and the rules of their interaction, and the artist designs those relations instead of a finished form.", "protocol_zh": "Burnham 借用系统论和控制论：作品是一组组成部分及其相互作用的规则，艺术家设计的是这些关系，而不是一个完成的形式。", "collective": "The essay gave critics and artists (Hans Haacke among them) a language for process, ecological and information-based work, and is now a standard reference for software, network and protocol art.", "collective_zh": "这篇文章为评论家和艺术家（包括 Hans Haacke）提供了讨论过程、生态与信息类作品的语言，如今是软件、网络与协议艺术的标准参考文献。", "keywords": ["systems theory", "cybernetics", "post-formalism", "Artforum", "Hans Haacke"], "images": ["https://www.artforum.com/wp-content/uploads/2012/08/article00_large-23.jpg"], "paper": {"url": "https://www.artforum.com/features/systems-esthetics-201372/", "venue": "Artforum 7, no. 1 (September 1968), pp. 30–35", "title": "Systems Esthetics"}, "source_url": "https://www.artforum.com/features/systems-esthetics-201372/", "video": {}, "also": []}, {"id": "valie-export--tapp-und-tastkino", "creator_ids": ["valie-export"], "title": "TAPP und TASTKINO (Tap and Touch Cinema)", "year": 1968, "field": "social", "sub": "performance", "mechanisms": ["participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "EXPORT strapped a small box with a curtain over her naked chest and walked through city streets while Peter Weibel invited passers-by through a megaphone to reach into this 'cinema' and touch her.", "description_zh": "艾丝波尔把一个带帘子的小盒子绑在裸露的胸前走上街头，彼得·魏贝尔用扩音器邀请路人把手伸进这座“电影院”触摸她。", "idea_en": "Expanded cinema as a public rule: the audience must decide, face to face, whether to 'watch'.", "idea_zh": "作为公共规则的扩展电影：观众必须面对面地决定要不要“观看”。", "protocol": "The box is the screen; anyone who accepts the invitation may put both hands through the curtain while looking the artist in the eye; the 'screening' lasts a short fixed time and then passes to the next viewer.", "protocol_zh": "盒子就是银幕；任何接受邀请的人都可以把双手伸进帘子，同时直视艺术家的眼睛；每场“放映”持续一段固定的短时间，然后轮到下一位观众。", "collective": "Passers-by in several European cities between 1968 and 1971 either took up or refused the invitation; their hesitation, embarrassment and choices became the content of the piece.", "collective_zh": "1968 至 1971 年间，欧洲多个城市的路人或接受、或拒绝了邀请；他们的犹豫、尴尬与选择成为作品的内容。", "keywords": ["Expanded Cinema", "Peter Weibel", "feminism", "Vienna", "public space"], "video": {"url": "https://www.youtube.com/watch?v=qTpNxAjdo6w", "platform": "youtube", "id": "qTpNxAjdo6w", "thumbnail": "https://i.ytimg.com/vi/qTpNxAjdo6w/maxresdefault.jpg", "embeddable": true}, "images": ["https://foundation.generali.at/media/public/images/JPG23export_GF000.max-483x515.format-jpeg.jpegquality-80_SUdJyE2.jpg"], "source_url": "https://foundation.generali.at/en/collection/artworks/gf0002080000-1999-tapp-und-tastkino", "paper": {}, "also": []}, {"id": "cornelius-cardew--the-great-learning", "creator_ids": ["cornelius-cardew"], "title": "The Great Learning", "year": 1968, "field": "score", "sub": "constraints", "mechanisms": ["instruction", "participation", "constraint"], "substrate": "body", "kind": "score", "description": "A seven-part work (1968–71) setting Ezra Pound's translation of a Confucian text, written largely for untrained performers who sing, speak, drum and whistle by verbal and graphic rules.", "description_zh": "一部七段式作品（1968—1971），以埃兹拉·庞德翻译的儒家文本为词，主要写给未受训练的表演者，他们依照文字与图形规则歌唱、念诵、击鼓和吹哨。", "idea_en": "Rules for listening to your neighbours can make a crowd of amateurs converge on a shared sound.", "idea_zh": "关于聆听身边人的规则，能让一群业余者汇聚成共同的声音。", "protocol": "In Paragraph 7, each singer chooses a starting note and sings a line of text on it a set number of times, then for each new line takes a note they can hear another singer holding; the choir drifts from a cluster toward a few shared pitches.", "protocol_zh": "在第七段中，每位歌者自选起始音，把一行文字按规定次数唱出，此后每一行都改用自己听到的另一位歌者正在唱的音；合唱从音簇逐渐漂向少数几个共同的音高。", "collective": "The Scratch Orchestra, many of whose members were not trained musicians, performed and recorded parts of it (Deutsche Grammophon, 1971); choirs such as Helsingin kamarikuoro and community groups still perform Paragraph 7, and the pitches it settles on differ every time.", "collective_zh": "Scratch Orchestra（许多成员并非受过训练的音乐人）演出并录制了其中的段落（德意志留声机，1971）；如今赫尔辛基室内合唱团等合唱团和社区团体仍在演出第七段，每一次最终汇聚的音高都不同。", "keywords": ["Confucius", "Ezra Pound", "Paragraph 7", "Scratch Orchestra", "choir"], "video": {"url": "https://www.youtube.com/watch?v=9fO_HbjkZrA", "platform": "youtube", "id": "9fO_HbjkZrA", "thumbnail": "https://i.ytimg.com/vi/9fO_HbjkZrA/maxresdefault.jpg", "embeddable": true}, "source_url": "https://www.newmusicnewcollege.org/cardew.html", "images": [], "paper": {}, "also": []}, {"id": "sol-lewitt--wall-drawing-1", "creator_ids": ["sol-lewitt"], "title": "Wall Drawing #1: Drawing Series II 18 (A & B)", "year": 1968, "field": "score", "sub": "execution", "mechanisms": ["instruction", "contract"], "substrate": "body", "kind": "artwork", "description": "LeWitt's first wall drawing, made directly on the wall of Paula Cooper Gallery in New York in October 1968 for a benefit exhibition against the Vietnam War. Two 48-inch squares of graphite lines follow one permutation from his Drawing Series II.", "description_zh": "勒维特的第一件墙绘，1968 年 10 月为一场反越战义展直接画在纽约 Paula Cooper 画廊的墙上。两个 48 英寸见方的石墨线条方块，采用他《素描系列 II》中的一种排列。", "idea_en": "Move the drawing off the paper and onto any wall, so that it can be redrawn anywhere by anyone who follows the system.", "idea_zh": "把素描从纸上搬到任何一面墙上，只要照着系统来，任何人在任何地方都能重画。", "protocol": "The drawing is defined by a system: lines in four directions (vertical, horizontal, diagonal left, diagonal right) layered in a fixed combination within divided squares, in hard graphite directly on the wall. The owner holds the certificate and diagram; the physical drawing is painted out after each showing and redrawn for the next.", "protocol_zh": "作品由一个系统定义：四个方向（竖、横、左斜、右斜）的线条按固定组合叠画在分格方块中，用硬石墨直接画在墙上。收藏者持有证书和示意图；每次展出后墙绘被刷掉，下次再重画。", "collective": "First drawn at the Paula Cooper benefit organised by Lucy Lippard and Robert Huot; now owned by SFMOMA (Doris and Donald Fisher Collection), which must have it redrawn each time it is installed. Every installation is a new hand-made instance of the same instruction.", "collective_zh": "首次绘制于由 Lucy Lippard 和 Robert Huot 组织的 Paula Cooper 义展；现藏旧金山现代艺术博物馆（Doris 与 Donald Fisher 收藏），每次展出都必须请人重画。每一次安装都是同一指令的一个新的手绘实例。", "keywords": ["wall drawing", "Paula Cooper Gallery", "Drawing Series II", "certificate", "graphite"], "images": ["https://d1hhug17qm51in.cloudfront.net/www-media/2026/08/20201534/FC.474_01_H02-web.jpg"], "paper": {"url": "https://www.cahiersdartinstitute.org/catalogues/sol-lewitt-wall-drawings/description", "title": "Sol LeWitt Wall Drawings Catalogue Raisonné", "venue": "Cahiers d'Art Institute"}, "source_url": "https://www.sfmoma.org/artwork/FC.474/", "video": {}, "also": []}, {"id": "allan-kaprow--fluids", "creator_ids": ["allan-kaprow"], "title": "Fluids", "year": 1967, "field": "score", "sub": "event-scores", "also": ["social"], "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "score", "description": "A happening in which volunteers built large rectangular enclosures of ice blocks at sites across Pasadena and Los Angeles and left them to melt; the score has been reinvented in Los Angeles, London, Berlin and elsewhere.", "description_zh": "一场偶发艺术：志愿者在帕萨迪纳和洛杉矶各处用冰块砌起大型长方形围墙，然后任其融化；这份乐谱后来在洛杉矶、伦敦、柏林等地被重新实现。", "idea_en": "A short score, many builders, and a material that erases the result.", "idea_zh": "一份简短的乐谱、许多建造者，以及一种会抹掉结果的材料。", "protocol": "\"During three days, about twenty rectangular enclosures of ice blocks (measuring about 30 feet long, 10 wide and 8 high) are built throughout the city. Their walls are unbroken. They are left to melt.\"", "protocol_zh": "“在三天之内，于城市各处用冰块砌起大约二十个长方形围墙（约 30 英尺长、10 英尺宽、8 英尺高）。墙面不留缺口。然后任其融化。”", "collective": "Teams of volunteers did the building in 1967 for Kaprow's Pasadena Art Museum exhibition. In April 2008 LACMA coordinated a reinvention at sites across Los Angeles, and Tate Modern staged it on the Southbank and Millennium Bridge the same year; each group chose its own sites and way of working.", "collective_zh": "1967 年，志愿者小组为卡普罗在帕萨迪纳美术馆的展览完成搭建。2008 年 4 月，洛杉矶郡艺术博物馆在洛杉矶多个地点协调了一次“再发明”；同年泰特现代美术馆在南岸和千禧桥上再次上演。每一组人都自己选址、自己决定做法。", "keywords": ["happening", "ice", "reinvention", "LACMA", "Tate Modern"], "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/img6432.width-600_QuDmopo.jpg"], "source_url": "https://www.lacma.org/art/exhibition/fluids-happening-allan-kaprow", "video": {}, "paper": {}}, {"id": "john-cage--musicircus", "creator_ids": ["john-cage"], "title": "Musicircus", "year": 1967, "field": "score", "sub": "constraints", "also": ["social"], "mechanisms": ["participation", "chance", "constraint"], "substrate": "body", "kind": "score", "description": "An event in which many invited musicians and performers play at the same time in one large space while the audience walks freely among them.", "description_zh": "一场活动：许多受邀的音乐人和表演者在同一个大空间里同时演出，观众在他们之间自由走动。", "idea_en": "Write only the conditions for a gathering and let simultaneity compose the piece.", "idea_zh": "只写下聚集的条件，让“同时发生”来完成作曲。", "protocol": "Cage's rule is an invitation: many performers agree to perform whatever they choose, simultaneously and in the same space, without coordination; the audience moves through the space and makes its own mix.", "protocol_zh": "凯奇的规则就是一份邀请：许多表演者同意在同一空间里同时演出各自选择的内容，彼此不作协调；观众在空间里走动，自己完成混音。", "collective": "The first Musicircus took place at the University of Illinois in November 1967; later versions, such as the English National Opera's in 2012 and many university and festival stagings, bring together choirs, bands, dancers and soloists, so each edition sounds like the local musical community at that moment.", "collective_zh": "第一次《音乐马戏团》于 1967 年 11 月在伊利诺伊大学举行；此后如 2012 年英国国家歌剧院的版本以及许多大学和艺术节的演出，把合唱团、乐队、舞者与独奏者聚在一起，每一版都像是当地音乐群体在那一刻的声音快照。", "keywords": ["simultaneity", "happening", "University of Illinois", "invitation"], "video": {"url": "https://www.youtube.com/watch?v=HBR8OAA-5p8", "platform": "youtube", "id": "HBR8OAA-5p8", "thumbnail": "https://i.ytimg.com/vi/HBR8OAA-5p8/maxresdefault.jpg", "embeddable": true}, "source_url": "https://newmusicusa.org/nmbx/the-circus-of-life-as-music/", "images": [], "paper": {}}, {"id": "sol-lewitt--paragraphs-on-conceptual-art", "creator_ids": ["sol-lewitt"], "title": "Paragraphs on Conceptual Art", "year": 1967, "field": "theory", "sub": "systems", "also": ["score"], "mechanisms": ["instruction", "constraint"], "substrate": "text", "kind": "publication", "description": "Essay published in the Summer 1967 issue of Artforum in which LeWitt defines Conceptual art: the idea is the most important part of the work, and its execution follows a plan fixed in advance.", "description_zh": "1967 年夏季号《Artforum》上发表的文章。LeWitt 在其中界定观念艺术：观念是作品最重要的部分，执行只是按照事先确定的计划进行。", "idea_en": "Write the plan first; once it exists, the idea becomes a machine that makes the art.", "idea_zh": "先写下计划；计划一旦存在，观念就成了制造艺术的机器。", "protocol": "All planning and decisions are made beforehand and 'the execution is a perfunctory affair'; the artist fixes a premise and a system, and anyone following it produces the work without new aesthetic choices.", "protocol_zh": "所有计划和决定都事先完成，“执行只是例行公事”；艺术家确定前提和系统，任何人照做都能完成作品，无需再做审美选择。", "collective": "The text became the working manifesto for instruction-based practice: LeWitt's own wall drawings are still executed by drafters and museum teams from his written instructions, and later instruction, score and code-based artists cite it as a starting point.", "collective_zh": "这篇文章成为指令式创作的工作宣言：LeWitt 自己的墙绘至今仍由绘图员和博物馆团队根据他的书面指令执行，后来的指令、乐谱与代码艺术家也常以它为起点。", "keywords": ["Conceptual art", "Artforum", "instructions", "idea as machine", "wall drawings"], "images": ["https://www.artforum.com/wp-content/uploads/2018/04/article00_large-51.jpg"], "paper": {"url": "https://www.artforum.com/features/paragraphs-on-conceptual-art-211354/", "venue": "Artforum 5, no. 10 (Summer 1967)", "title": "Paragraphs on Conceptual Art"}, "source_url": "https://www.artforum.com/features/paragraphs-on-conceptual-art-211354/", "video": {}}, {"id": "cornelius-cardew--treatise", "creator_ids": ["cornelius-cardew"], "title": "Treatise", "year": 1967, "field": "score", "sub": "constraints", "mechanisms": ["constraint", "chance", "co-authorship"], "substrate": "text", "kind": "score", "description": "A 193-page graphic score of lines, circles, numbers and fragments of notation, written 1963–67, with no instructions on how to play it.", "description_zh": "一份 193 页的图形乐谱，由线条、圆形、数字和零碎的记谱符号组成，写于 1963—1967 年，没有任何演奏说明。", "idea_en": "A score without a key forces each group to agree on its own reading.", "idea_zh": "没有图例的乐谱，迫使每个团体自行商定读法。", "protocol": "Cardew gives only the graphics: performers decide which pages to play, which instruments to use and what each sign means, usually by agreeing on rules among themselves before or during rehearsal.", "protocol_zh": "卡迪尤只给出图形：演奏者自行决定演奏哪些页、用什么乐器、每个符号代表什么，通常在排练前或排练中彼此商定规则。", "collective": "Improvisers, rock musicians, electronic musicians and chamber groups have performed it; the London Experimental Ensemble played the whole score in about two hours at Iklectik, London, in January 2017, while other groups use only a few pages.", "collective_zh": "即兴乐手、摇滚乐手、电子音乐人和室内乐团都演出过它；2017 年 1 月，伦敦实验乐团在伦敦 Iklectik 用约两小时演奏了全部乐谱，其他团体则只取其中几页。", "keywords": ["graphic score", "AMM", "interpretation", "193 pages"], "video": {"url": "https://www.youtube.com/watch?v=9XPtMY-unCo", "platform": "youtube", "id": "9XPtMY-unCo", "thumbnail": "https://i.ytimg.com/vi/9XPtMY-unCo/maxresdefault.jpg", "embeddable": true}, "images": ["https://socks-studio.com/img/blog/Treatise-01.jpg", "https://socks-studio.com/img/blog/Treatise-02.jpg"], "source_url": "https://en.wikipedia.org/wiki/Treatise_(music)", "paper": {}, "also": []}, {"id": "yoko-ono--mend-piece", "creator_ids": ["yoko-ono"], "title": "Mend Piece", "year": 1966, "field": "score", "sub": "public-instructions", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "artwork", "description": "A table of broken cups and saucers with glue, tape and string; visitors mend the fragments and place the repaired objects on shelves. First shown as Mending Piece I at Indica Gallery, London, in 1966.", "description_zh": "一张桌子上放着碎杯碟，以及胶水、胶带和绳子；观众把碎片修补起来，把修好的器物放到架子上。1966 年以《修补之作 I》之名首次在伦敦 Indica 画廊展出。", "idea_en": "Hand the audience broken things and a rule about care; the repaired shelf becomes a collective portrait.", "idea_zh": "把破碎的东西和一条关于用心的规则交给观众；摆满修补物的架子就成了一幅集体肖像。", "protocol": "'Mend carefully. Think of mending the world at the same time.' Visitors choose fragments and materials, mend them in any way, and leave the result on display.", "protocol_zh": "“仔细修补。同时想着修补世界。”观众自选碎片和材料，用任何方法修补，并把结果留在展场。", "collective": "Restaged many times, e.g. the Andrea Rosen Gallery version (1966/2015) at rennie museum, Vancouver, and 'Mend Piece for London' at Whitechapel Gallery (2021). The shelves fill with unpredictable hybrid objects made by thousands of strangers.", "collective_zh": "曾多次重现，例如在温哥华 rennie 博物馆展出的 Andrea Rosen 画廊版本（1966/2015），以及白教堂画廊的《为伦敦修补》（2021）。架子上摆满了成千上万陌生人做出的、难以预料的拼合物件。", "keywords": ["Indica Gallery", "repair", "cups", "participation", "Whitechapel Gallery"], "images": ["https://renniemuseum.org/wp-content/uploads/2019/05/RennieCollection_OnoMendPiece_091.jpg", "https://www.whitechapelgallery.org/wp-content/uploads/2021/08/YokoOno_WebCrop_ToGo-scaled.jpg"], "source_url": "https://www.whitechapelgallery.org/exhibitions/yoko-ono-mend-piece-for-london/", "video": {}, "paper": {}, "also": []}, {"id": "yoko-ono--painting-to-hammer-a-nail", "creator_ids": ["yoko-ono"], "title": "Painting to Hammer a Nail", "year": 1966, "field": "score", "sub": "public-instructions", "mechanisms": ["instruction", "participation", "time"], "substrate": "body", "kind": "artwork", "description": "A white panel with a hammer hanging on a chain and a supply of nails: visitors complete the painting by hammering nails into it. Shown at Indica Gallery, London, in 1966; later versions include a cross-shaped panel.", "description_zh": "一块白色面板，旁边用链子挂着一把锤子，并备有钉子：观众把钉子敲进去来完成这幅画。1966 年在伦敦 Indica 画廊展出；后来的版本包括十字形面板。", "idea_en": "The painting is finished only by the accumulated marks of visitors.", "idea_zh": "这幅画只有靠观众不断累积的痕迹才能完成。", "protocol": "The instruction invites each visitor to hammer a nail into the panel. Nothing limits where the nail goes; the work records every visit until the surface is full.", "protocol_zh": "指令邀请每位观众往面板上敲一颗钉子。钉子敲在哪里不受限制；作品记录下每一次到访，直到画面被钉满。", "collective": "Visitors at each showing, among them John Lennon at the 1966 Indica preview, add nails, so each version ends with a different density and pattern. The outdoor Painting to Hammer a Nail In / Cross Version (2005) at the Österreichischer Skulpturenpark near Graz offers three wooden crosses to visitors' nails.", "collective_zh": "每次展出的观众都来敲钉，其中包括 1966 年在 Indica 预展上的约翰·列侬，因此每个版本最后钉子的密度和分布都不同。格拉茨附近奥地利雕塑公园的户外作品《敲钉之画／十字版》（2005）以三个木十字架承接观众的钉子。", "keywords": ["Indica Gallery", "hammer", "nails", "participation", "John Lennon"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/YokoOno_PaintingToHammerANailIn.jpg/960px-YokoOno_PaintingToHammerANailIn.jpg", "https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Ono_Painting_to_Hammer_a_Nail_In_-_Cross_Version_01.jpg/960px-Ono_Painting_to_Hammer_a_Nail_In_-_Cross_Version_01.jpg"], "source_url": "https://en.wikipedia.org/wiki/Yoko_Ono", "video": {}, "paper": {}, "also": []}, {"id": "george-maciunas--fluxkit", "creator_ids": ["george-maciunas"], "title": "Fluxkit", "year": 1965, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "circulation", "co-authorship"], "substrate": "text", "kind": "series", "description": "An attaché case, assembled by George Maciunas in 1965–66, divided into compartments holding printed scores and small boxed works by Fluxus artists, to be opened, handled and performed by its owner.", "description_zh": "一只由乔治·马修纳斯于 1965—1966 年组装的公文箱，内分格子，装着激浪派艺术家的印刷乐谱和小盒作品，供拥有者打开、把玩和执行。", "idea_en": "Package many artists' instructions as a kit, and ownership becomes a way of performing.", "idea_zh": "把众多艺术家的指令打包成一套工具，拥有它就成了一种演出方式。", "protocol": "Maciunas solicited ideas from artists including George Brecht, Alison Knowles, Takehisa Kosugi, Shigeko Kubota, Benjamin Patterson, Mieko Shiomi, Ben Vautier and Robert Watts, then designed and produced them as multiples; the owner decides which objects and cards to open, read or perform.", "protocol_zh": "马修纳斯向乔治·布雷希特、艾莉森·诺尔斯、小杉武久、久保田成子、本杰明·帕特森、盐见允枝子、本·沃蒂埃、罗伯特·沃茨等艺术家征集构想，再设计并制作成复数作品；拥有者自行决定打开、阅读或执行哪些物件和卡片。", "collective": "Advertised by Maciunas for $100, the kits were sold and given to collectors and friends; each surviving copy has a slightly different selection of contents, and MoMA's Silverman collection holds examples that curators and artists such as Knowles have opened and demonstrated.", "collective_zh": "马修纳斯曾以 100 美元的价格广告出售，这些套装卖给或送给藏家和朋友；每一件存世的套装内容都略有不同，纽约现代艺术博物馆的 Silverman 收藏中保存的套装曾由策展人和诺尔斯等艺术家打开演示。", "keywords": ["Fluxus edition", "multiple", "attaché case", "Silverman Collection"], "video": {"url": "https://www.youtube.com/watch?v=cPi0UyHB95U", "platform": "youtube", "id": "cPi0UyHB95U", "thumbnail": "https://i.ytimg.com/vi/cPi0UyHB95U/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/AR6153553_th.jpg"], "source_url": "https://www.moma.org/collection/works/126323", "paper": {}, "also": []}, {"id": "mieko-shiomi--spatial-poem", "creator_ids": ["mieko-shiomi"], "title": "Spatial Poem", "year": 1965, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation", "circulation"], "substrate": "post", "kind": "series", "description": "A mail project (1965–75) of nine text scores that Shiomi posted to people around the world; their reports of what they did came back by mail and were compiled into maps, objects and a book.", "description_zh": "一个邮寄项目（1965—1975），包含九份文字乐谱，盐见允枝子把它们寄给世界各地的人；他们寄回自己做了什么的报告，被汇编成地图、物件和一本书。", "idea_en": "Post the same instruction to a network and the replies form one poem spread across the globe.", "idea_zh": "把同一条指令寄给一个网络，回信就组成一首遍布全球的诗。", "protocol": "Spatial Poem No. 1 (Word Event): \"Write a word (or words) on the enclosed card and place it somewhere. Please tell me the word and the place, which will be edited on the world map.\" Later events asked for directions, times and disappearances, always with the place or time reported back.", "protocol_zh": "《空间诗》第 1 号（词事件）：“在附上的卡片上写一个词（或几个词），把它放在某处。请告诉我这个词和地点，它们将被编辑到世界地图上。”后来的事件要求报告方向、时间和消失，每次都要寄回地点或时间。", "collective": "Launched in 1965 to a Fluxus mailing list of over a hundred people, the project drew more than 230 collaborators who reported back from twenty-six countries; Shiomi pinned their words as flags on a world map for the Fluxus edition and published the complete results in Osaka in 1976.", "collective_zh": "项目于 1965 年寄给一份逾百人的激浪派通讯名单，最终有 230 多位合作者从 26 个国家寄回报告；盐见把他们的词做成小旗插在激浪派版本的世界地图上，并于 1976 年在大阪出版了全部结果。", "keywords": ["mail art", "Fluxus", "world map", "Word Event"], "video": {"url": "https://www.youtube.com/watch?v=1-6lpTPnK8c", "platform": "youtube", "id": "1-6lpTPnK8c", "thumbnail": "https://i.ytimg.com/vi/1-6lpTPnK8c/hqdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/posters/sequences--525-SpatialPoem_001.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/gri_91_b36111_001_mm_th.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/r2014747_890164_b47_f3_001_th.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/10/", "venue": "The Scores Project (Getty Research Institute, 2025)", "title": "Mieko Shiomi: Spatial Poem (1965–75)"}, "source_url": "https://www.getty.edu/publications/scores/10/commentary/", "collections": ["the-scores-project"]}, {"id": "yoko-ono--cut-piece", "creator_ids": ["yoko-ono"], "title": "Cut Piece", "year": 1964, "field": "score", "sub": "event-scores", "also": ["social"], "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "Ono sits still on stage with a pair of scissors in front of her; audience members come up one at a time and cut off a piece of her clothing to keep. First performed at Yamaichi Concert Hall, Kyoto, on 20 July 1964.", "description_zh": "小野洋子静坐在舞台上，面前放着一把剪刀；观众一个接一个上台，剪下她衣服的一小块带走。1964 年 7 月 20 日在京都山一音乐厅首演。", "idea_en": "Give the audience the tool and the permission, and their restraint or aggression becomes the piece.", "idea_zh": "把工具和许可交给观众，他们的克制或侵犯就成了作品。", "protocol": "The performer sits on stage with scissors; it is announced that members of the audience may come on stage, one at a time, to cut a small piece of the performer's clothing and take it with them. The performer stays silent and does not react.", "protocol_zh": "表演者带着剪刀坐在台上；宣布观众可以一次一人上台，剪下表演者衣服的一小块并带走。表演者保持沉默，不作反应。", "collective": "Ono performed it six times: Kyoto and Tokyo (1964), Carnegie Recital Hall, New York (1965, filmed by Albert and David Maysles), London (1966) and Paris (2003). Each audience cut differently, from hesitant small snips to aggressive cutting; other artists have restaged the score since.", "collective_zh": "小野洋子共演出六次：京都与东京（1964）、纽约卡内基独奏厅（1965，由梅索斯兄弟拍摄）、伦敦（1966）和巴黎（2003）。每一场观众的剪法都不同，从犹豫地剪下一小块到带有侵犯性的剪切；此后也有其他艺术家重演这份乐谱。", "keywords": ["performance", "scissors", "audience", "Maysles", "feminism"], "video": {"url": "https://www.youtube.com/watch?v=-Y7R7WmdyXI", "platform": "youtube", "id": "-Y7R7WmdyXI", "thumbnail": "https://i.ytimg.com/vi/-Y7R7WmdyXI/maxresdefault.jpg", "embeddable": true}, "images": ["https://media.tate.org.uk/aztate-prd-ew-dg-wgtail-st1-ctr-data/images/ID_56_YO_2_copy_small.width-420.format-jpeg.jpg", "https://mayslesfilms.com/wp-content/uploads/2014/02/10-cut-piece.jpg"], "source_url": "https://en.wikipedia.org/wiki/Cut_Piece_1964", "paper": {}}, {"id": "yoko-ono--grapefruit", "creator_ids": ["yoko-ono"], "title": "Grapefruit", "year": 1964, "field": "score", "sub": "public-instructions", "mechanisms": ["instruction", "participation"], "substrate": "text", "kind": "publication", "description": "A small self-published book of more than 150 instruction pieces in five sections (Music, Painting, Event, Poetry, Object), issued in Tokyo on 4 July 1964 in an edition of 500. Each page is a work that the reader performs, in action or in the mind.", "description_zh": "一本自费出版的小书，收录 150 多件指令作品，分为音乐、绘画、事件、诗歌、物件五部分，1964 年 7 月 4 日在东京出版，印 500 册。每一页都是一件由读者执行的作品，或付诸行动，或在脑中完成。", "idea_en": "A book can be a portable exhibition that readers stage themselves.", "idea_zh": "一本书可以是一场便携的展览，由读者自己来上演。", "protocol": "Short imperatives addressed to the reader, e.g. Cloud Piece: 'Imagine the clouds dripping. Dig a hole in your garden to put them in.' No one checks execution; the reader decides whether, where and how to carry out each piece.", "protocol_zh": "写给读者的简短祈使句，例如《云之作》：“想象云在滴落。在你的花园里挖一个洞把它们装进去。”没有人检查执行情况；每件作品做不做、在哪里做、怎么做，都由读者决定。", "collective": "Readers since 1964 have performed, adapted and republished the pieces; expanded editions followed in many languages, and museums, including Tate Modern in 2024, installed instructions from it for visitors to carry out.", "collective_zh": "自 1964 年以来，读者们执行、改编并再版这些作品；此后出现多种语言的扩充版，包括泰特现代美术馆（2024）在内的美术馆也把书中的指令布置出来让观众执行。", "keywords": ["Wunternaum Press", "artist's book", "instruction", "Fluxus", "Cloud Piece"], "images": ["https://www.moma.org/media/W1siZiIsIjM0NjM0MSJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=dcc16cd0a4637452", "https://d23eqwv5slm408.cloudfront.net/api/file/k97FqoRQRYs4im9VyvpC/convert?fit=clip&h=618&quality=100&w=824&compress=true&fit=clip"], "paper": {"url": "https://www.moma.org/collection/works/128103", "title": "Grapefruit (Tokyo: Wunternaum Press, 1964)", "venue": "Artist's book"}, "source_url": "https://www.moma.org/collection/works/128103", "video": {}, "also": []}, {"id": "terry-riley--in-c", "creator_ids": ["terry-riley"], "title": "In C", "year": 1964, "field": "score", "sub": "constraints", "mechanisms": ["constraint", "instruction", "participation"], "substrate": "body", "kind": "score", "description": "A one-page score of 53 short melodic patterns that any number of musicians play in order, each deciding when to move on, over a steady pulse on the note C.", "description_zh": "一页乐谱，写着 53 个短小的旋律片段；任意数量的乐手依次演奏，各自决定何时进入下一个，底下是持续的 C 音脉冲。", "idea_en": "Fixed order plus free timing turns an ensemble into a slowly shifting cloud of patterns.", "idea_zh": "固定的顺序加上自由的时机，让乐团变成一片缓慢漂移的音型之云。", "protocol": "\"Any number of any kind of instruments can play.\" Each player repeats each pattern as many times as they like before moving to the next, stays within a few patterns of the others, and the piece ends when everyone has reached the last pattern.", "protocol_zh": "“任何数量、任何种类的乐器都可以演奏。”每位乐手自行决定每个片段重复多少次再进入下一个，与其他人保持在相近的几个片段之内，所有人都奏到最后一个片段时乐曲结束。", "collective": "Premiered at the San Francisco Tape Music Center in November 1964; since then it has been played by rock bands, orchestras, school groups, the Malian and European musicians of Africa Express and ensembles such as BL!NDMAN and Third Coast Percussion, and the length and texture change with every group.", "collective_zh": "1964 年 11 月在旧金山磁带音乐中心首演；此后摇滚乐队、管弦乐团、学校团体、Africa Express 的马里与欧洲音乐人，以及 BL!NDMAN、Third Coast Percussion 等乐团都演奏过它，每个团体演出的时长和质感都不同。", "keywords": ["minimalism", "53 patterns", "pulse", "San Francisco Tape Music Center"], "video": {"url": "https://www.youtube.com/watch?v=GEfo7DRg9TQ", "platform": "youtube", "id": "GEfo7DRg9TQ", "thumbnail": "https://i.ytimg.com/vi/GEfo7DRg9TQ/hqdefault.jpg", "embeddable": true}, "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Terry_Riley_In_C_Carnegie_Hall.jpg/960px-Terry_Riley_In_C_Carnegie_Hall.jpg", "https://upload.wikimedia.org/wikipedia/commons/3/32/Incipit_of_Terry_Riley%27s_In_C.png"], "source_url": "https://en.wikipedia.org/wiki/In_C", "paper": {}, "also": []}, {"id": "helio-oiticica--parangole", "creator_ids": ["helio-oiticica"], "title": "Parangolés", "year": 1964, "field": "social", "sub": "performance", "mechanisms": ["participation", "circulation"], "substrate": "body", "kind": "series", "description": "Capes, banners and tents of layered fabric, plastic and matting that are completed only when a person wears them and dances; Oiticica made them with dancers from the Mangueira samba school.", "description_zh": "由多层布料、塑料和草席做成的斗篷、旗帜和帐篷，只有当人穿上并舞动时才算完成；奥迪塞卡与芒格拉桑巴学校的舞者一起创作了它们。", "idea_en": "Sculpture that needs a wearer: the viewer becomes the moving support of the work.", "idea_zh": "需要穿戴者的雕塑：观众成为作品移动的支撑。", "protocol": "A Parangolé is not displayed on a stand but handed to a participant, who puts it on and moves; the unfolding of colour and text depends on the wearer's dance.", "protocol_zh": "《帕兰戈莱》不放在展台上展示，而是交给参与者，由其穿上并移动；色彩与文字如何展开取决于穿戴者的舞蹈。", "collective": "At the opening of Opinião 65 at the Museum of Modern Art of Rio de Janeiro in 1965, Oiticica's friends from Mangueira arrived to dance in the capes and were refused entry; they danced outside with the public, and the capes have since been worn by visitors in exhibitions.", "collective_zh": "1965 年里约热内卢现代艺术博物馆“意见 65”展开幕时，奥迪塞卡在芒格拉的朋友前来穿着斗篷跳舞却被拒之门外；他们在馆外与公众一起跳舞，此后展览中的观众也常穿上这些斗篷。", "keywords": ["Mangueira", "samba", "Opinião 65", "MAM Rio", "Neo-Concretism", "capes"], "images": ["https://mam.rio/wp-content/uploads/2020/12/2016-65-16-687x1024.jpg", "https://upload.wikimedia.org/wikipedia/commons/a/ae/Gerardo_Mosquera_wearing_H%C3%A9lio_Oiticica%27s_parangol%C3%A9_Da_adversidade_vivemos.JPG"], "source_url": "https://mam.rio/historia/parangole-em-opiniao-65/", "video": {}, "paper": {}, "also": []}, {"id": "la-monte-young--an-anthology-of-chance-operations", "creator_ids": ["la-monte-young", "jackson-mac-low"], "title": "An Anthology of Chance Operations", "year": 1963, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "chance", "co-authorship"], "substrate": "text", "kind": "publication", "description": "A book of scores, texts and plans of action by 27 artists and composers, edited by La Monte Young, designed by George Maciunas and co-published by Young and Jackson Mac Low in 1963.", "description_zh": "一本汇集27 位艺术家和作曲家的乐谱、文本与行动计划的书，由拉蒙特·杨编辑、乔治·马修纳斯设计，1963 年由杨与杰克逊·马克·洛共同出版。", "idea_en": "Publish instructions as a book, and every reader becomes a possible performer.", "idea_zh": "把指令印成书，每位读者都成了潜在的表演者。", "protocol": "The anthology prints works as instructions for others to carry out: one of Mac Low's texts, for example, \"may be used in any way as a score for solo or group readings, musical or dramatic performances, looking, smelling, anything else &/or nothing at all.\"", "protocol_zh": "这本选集把作品印成交给他人执行的指令：例如马克·洛的一篇文字写道，它“可以以任何方式用作独奏或集体朗读、音乐或戏剧表演、观看、嗅闻、任何其他事情和／或什么都不做的乐谱”。", "collective": "Contributors included George Brecht, John Cage, Simone Forti, Dick Higgins, Yoko Ono, Nam June Paik, Terry Riley, Christian Wolff and Young; fundraising concerts at the Living Theatre preceded it, and its scores have been performed ever since, including the 2021 program Meaningless Work, Get to Work, curated by Sarah Cooper and Tashi Wada and documented in the Getty's Scores Project.", "collective_zh": "撰稿人包括乔治·布雷希特、约翰·凯奇、西蒙娜·福尔蒂、迪克·希金斯、小野洋子、白南准、特里·莱利、克里斯蒂安·沃尔夫和杨本人；出版前曾在生活剧场举办筹款音乐会，此后书中的乐谱不断被演出，包括 2021 年由 Sarah Cooper 与 Tashi Wada 策划、收录于盖蒂《乐谱计划》的演出“Meaningless Work, Get to Work”。", "keywords": ["artist's book", "Fluxus", "George Maciunas", "Living Theatre", "chance operations"], "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/r611559_94_b19099_001_th.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/AA-mockup-p3-ologyof_th.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/05/", "venue": "The Scores Project (Getty Research Institute, 2025)", "title": "La Monte Young, ed.: An Anthology of Chance Operations (1962–63)"}, "source_url": "https://en.wikipedia.org/wiki/An_Anthology_of_Chance_Operations", "video": {}, "also": [], "collections": ["the-scores-project"]}, {"id": "lygia-clark--caminhando", "creator_ids": ["lygia-clark"], "title": "Caminhando (Walking)", "year": 1963, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation"], "substrate": "text", "kind": "score", "description": "An instruction anyone can carry out: make a Möbius strip from paper and cut along its length with scissors, choosing a new path each time around, until the strip is too narrow to cut.", "description_zh": "一条任何人都能执行的指令：用纸做一条莫比乌斯环，用剪刀沿长度方向剪下去，每一圈都选择一条新路径，直到纸条窄到无法再剪。", "idea_en": "The artwork moves from object to act: it exists only while someone is doing it.", "idea_zh": "作品从物件转为行为：只有有人在做的时候它才存在。", "protocol": "Take a strip of paper, twist it once and glue the ends into a Möbius strip; pierce it and cut continuously along its length without crossing an earlier cut; the work ends when no path is left.", "protocol_zh": "取一条纸，扭转一次、把两端粘成莫比乌斯环；在纸上戳一个口，沿长度方向连续剪，不得与之前的剪口相交；无路可剪时作品结束。", "collective": "Clark published the proposition so that viewers could make it themselves; it has since been performed by museum visitors and in workshops worldwide, including at MoMA's 2014 retrospective.", "collective_zh": "克拉克把这个提议公开，让观众自己去做；此后世界各地的美术馆观众和工作坊参与者都执行过它，包括 MoMA 2014 年的回顾展。", "keywords": ["Möbius strip", "proposition", "Neo-Concretism", "participation", "scissors"], "video": {"url": "https://www.youtube.com/watch?v=3sP-uT5DQLM", "platform": "youtube", "id": "3sP-uT5DQLM", "thumbnail": "https://i.ytimg.com/vi/3sP-uT5DQLM/maxresdefault.jpg", "embeddable": true}, "images": ["http://www.bauhaus-imaginista.org/images/20243.jpg?w=2000&h=2000"], "source_url": "https://www.bauhaus-imaginista.org/articles/3822/walking-on-a-mobius-strip/", "paper": {}}, {"id": "allan-kaprow--push-and-pull", "creator_ids": ["allan-kaprow"], "title": "Push and Pull: A Furniture Comedy for Hans Hofmann", "year": 1963, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation", "co-authorship"], "substrate": "body", "kind": "artwork", "description": "Two furnished rooms, made for a touring exhibition on Hans Hofmann and his students, that visitors were invited to rearrange as they wished.", "description_zh": "为汉斯·霍夫曼及其学生的巡回展制作的两间布置好的房间，观众可以随意重新摆放其中的家具。", "idea_en": "Turn a painter's composition rule into a room that strangers compose together.", "idea_zh": "把画家的构图法则变成一间由陌生人一起“构图”的房间。", "protocol": "Kaprow's instruction: \"Anyone can find or make one or more rooms of any shape, size, proportion, and color -- then furnish them perhaps, maybe paint some things or everything. Everyone else can come in and, if the room(s) are furnished, they also can arrange them, accommodating themselves as they see fit.\"", "protocol_zh": "卡普罗的指令大意是：任何人都可以找到或搭建一个或几个任意形状、大小、比例和颜色的房间，也许放进家具，也许把一些东西或全部东西刷上颜色；其他所有人都可以进来，如果房间里有家具，也可以按自己的意思重新摆放。", "collective": "Visitors moved the furniture, cooperating or competing with each other, so the rooms kept changing. The score has been re-realised by later groups, such as Push and Pull Redfern in Sydney.", "collective_zh": "观众搬动家具，时而合作时而较劲，房间因此不停变化。后来的团体也重新实现过这份乐谱，比如悉尼的 Push and Pull Redfern。", "keywords": ["Hans Hofmann", "furniture", "push and pull", "environment"], "video": {"url": "https://www.youtube.com/watch?v=GFCfecGIsTQ", "platform": "youtube", "id": "GFCfecGIsTQ", "thumbnail": "https://i.ytimg.com/vi/GFCfecGIsTQ/hqdefault.jpg", "embeddable": true}, "source_url": "http://www.medienkunstnetz.de/works/push-and-pull/", "images": [], "paper": {}}, {"id": "george-brecht--water-yam", "creator_ids": ["george-brecht"], "title": "Water Yam", "year": 1963, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "chance"], "substrate": "text", "kind": "series", "description": "A Fluxus box, designed and published by George Maciunas, holding George Brecht's event scores printed on small cards.", "description_zh": "一只激浪派盒子，由乔治·马修纳斯设计出版，装着印在小卡片上的乔治·布雷希特的事件乐谱。", "idea_en": "Put instructions in a box of cards so the owner can shuffle, pick and perform them.", "idea_zh": "把指令装进一盒卡片，让拥有者洗牌、抽取并执行。", "protocol": "Each card states an event in a few words, for example \"Word Event\": \"EXIT\"; owners and performers decide how, when and where to realize each one, and the cards can be read in any order.", "protocol_zh": "每张卡片用寥寥数语写下一个事件，例如《词事件》：“EXIT（出口）”；拥有者和表演者自行决定如何、何时、在何处实现，卡片可以按任意顺序阅读。", "collective": "Brecht kept adding cards to later editions; Fluxus members performed the events at festivals across Europe from 1962, and museums, students and ensembles still use the box as a repertoire, each choosing different cards.", "collective_zh": "布雷希特在后来的版本中不断增加卡片；自 1962 年起，激浪派成员在欧洲各地的艺术节上演出这些事件，今天博物馆、学生和乐团仍把这只盒子当作曲目库，每次挑选的卡片都不同。", "keywords": ["event score", "Fluxus edition", "George Maciunas", "cards"], "video": {"url": "https://www.youtube.com/watch?v=oeCIvEjOMYg", "platform": "youtube", "id": "oeCIvEjOMYg", "thumbnail": "https://i.ytimg.com/vi/oeCIvEjOMYg/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.moma.org/media/W1siZiIsIjI0MjAyMiJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=43e20d278e220ea0", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/water-yam-grid_th.jpg"], "source_url": "https://www.moma.org/collection/works/126322", "paper": {}, "also": []}, {"id": "alison-knowles--make-a-salad", "creator_ids": ["alison-knowles"], "title": "#2—Proposition (Make a Salad)", "year": 1962, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "An event score from October 1962 whose whole text is \"Make a salad\"; performed with audiences who then eat the result.", "description_zh": "一份 1962 年 10 月的事件乐谱，全文只有“做一份沙拉”；与观众一起演出，之后大家一起吃掉成果。", "idea_en": "The simplest instruction scales from one bowl to a crowd, and the work can be eaten.", "idea_zh": "最简单的指令可以从一只碗放大到一群人，而作品可以被吃掉。", "protocol": "The score says only \"Make a salad.\" Ingredients, scale, sound and number of helpers are left to each performance.", "protocol_zh": "乐谱只写“做一份沙拉”。用什么食材、多大规模、发出什么声音、多少人帮忙，都留给每一次演出决定。", "collective": "First performed at the Festival of Misfits at the Institute of Contemporary Arts in London in 1962; at Tate Modern in 2008 helpers threw vegetables, oil and vinegar from the bridge onto a tarpaulin in the Turbine Hall, where they were mixed with a rake and served to the audience.", "collective_zh": "1962 年在伦敦当代艺术学院的“怪人艺术节”首演；2008 年在泰特现代美术馆，助手们从涡轮大厅的天桥上把蔬菜、油和醋抛到下面的防水布上，用耙子拌匀后分给观众。", "keywords": ["Fluxus", "food", "Festival of Misfits", "Tate Modern"], "video": {"url": "https://www.youtube.com/watch?v=lmqvnIXnmyM", "platform": "youtube", "id": "lmqvnIXnmyM", "thumbnail": "https://i.ytimg.com/vi/lmqvnIXnmyM/hqdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/ART545952_th.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/r2015409_94_b22032_001_th.jpg"], "source_url": "https://en.wikipedia.org/wiki/Make_a_Salad", "paper": {}, "also": [], "collections": ["the-scores-project"]}, {"id": "raymond-queneau--cent-mille-milliards-de-poemes", "creator_ids": ["raymond-queneau"], "title": "Cent mille milliards de poèmes", "year": 1961, "field": "score", "sub": "constraints", "mechanisms": ["constraint", "chance", "co-authorship"], "substrate": "text", "kind": "artwork", "description": "A book of ten sonnets whose pages are cut into fourteen strips, one per line, so that readers can combine lines from different sonnets into 10^14 possible poems.", "description_zh": "一本由十首十四行诗组成的书，每页被剪成十四条，每条一行，读者可以把不同诗中的诗行组合成 10^14 首可能的诗。", "idea_en": "Write the constraint so tightly that every reader's combination is a valid poem.", "idea_zh": "把约束写得足够严密，读者任意组合出来的都是一首成立的诗。", "protocol": "All ten sonnets share the same rhyme sounds and syntax, so any line can follow any line from another sonnet. The reader turns strips independently; each choice of fourteen strips is a new poem that Queneau never read.", "protocol_zh": "十首十四行诗押同样的韵、用相同的句法，所以任何一行都可以接在另一首诗的下一行后面。读者独立翻动每一条；每种十四条的组合都是一首奎诺本人从未读过的新诗。", "collective": "Readers assemble the poems; with 10^14 combinations, almost every reading produces a poem no one has read before. The book, designed by Robert Massin and published by Gallimard, led to the founding of Oulipo with François Le Lionnais, and has been translated and turned into online generators.", "collective_zh": "诗由读者拼成；共有 10^14 种组合，几乎每次阅读都会得到一首从未有人读过的诗。此书由罗伯特·马森设计、伽利玛出版社出版，促成奎诺与弗朗索瓦·勒利奥内创立 Oulipo，此后被翻译并做成了在线生成器。", "keywords": ["Oulipo", "combinatorial poetry", "sonnet", "Gallimard", "Robert Massin"], "images": ["https://upload.wikimedia.org/wikipedia/commons/a/ad/Queneau_sonnets.jpg"], "source_url": "https://en.wikipedia.org/wiki/A_Hundred_Thousand_Billion_Poems", "also": [], "video": {}, "paper": {}}, {"id": "simone-forti--dance-constructions", "creator_ids": ["simone-forti"], "title": "Dance Constructions (Huddle, Slant Board and others)", "year": 1961, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "participation", "constraint"], "substrate": "body", "kind": "series", "description": "Task-based pieces from 1960–61 for small groups, such as Huddle, in which seven to nine performers take turns climbing over the group's own tightly embracing bodies, and Slant Board, in which performers move across an inclined plywood ramp using ropes.", "description_zh": "1960–61 年为小组创作的任务型作品，例如《抱团》：七到九名表演者轮流爬过大家紧紧抱在一起的身体；又如《斜板》：表演者借助绳索在倾斜的胶合板上移动。", "idea_en": "Give a group one physical task and the dance emerges from how their bodies solve it together.", "idea_zh": "给一群人一个身体任务，舞蹈就出现在他们如何一起解决它之中。", "protocol": "Huddle: seven to nine people stand in a tight cluster; one at a time, a performer climbs over the top of the group and rejoins it, and the next begins. Slant Board: three or four performers move up, down and across a steep board holding onto ropes, for about ten minutes.", "protocol_zh": "《抱团》：七到九人紧紧围成一团；每次一人从团顶爬过去再回到团里，接着下一个人开始。《斜板》：三到四名表演者抓着绳子在陡板上上下左右移动，持续约十分钟。", "collective": "Performed first in 1961 in New York lofts, the works have been re-performed by many groups. MoMA acquired them in 2015 as its first historical dance works; the acquisition includes Forti's teaching of new performers, and licences allow Huddle to be staged in several places at once.", "collective_zh": "这些作品 1961 年首先在纽约的阁楼里演出，此后被许多群体重演。MoMA 于 2015 年收藏了它们，这是该馆首次收藏历史舞蹈作品；收藏包含福尔蒂向新表演者的传授，授权方式也允许《抱团》同时在多个地方上演。", "keywords": ["Huddle", "Slant Board", "task", "MoMA", "dance acquisition"], "images": ["https://www.moma.org/media/W1siZiIsIjQ2MDY5NyJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=3aa0665e122cca7c"], "paper": {"url": "https://doi.org/10.1080/01472526.2021.2024724", "doi": "10.1080/01472526.2021.2024724", "venue": "Dance Chronicle", "title": "Making the Museum Dance: Simone Forti's Huddle (1961) and its Acquisition by the Museum of Modern Art"}, "source_url": "https://www.moma.org/collection/works/200115", "video": {}}, {"id": "yoko-ono--instruction-paintings", "creator_ids": ["yoko-ono"], "title": "Instruction Paintings (Instructions for Paintings)", "year": 1961, "field": "score", "sub": "public-instructions", "mechanisms": ["instruction", "participation"], "substrate": "text", "kind": "series", "description": "Paintings that exist as instructions. At AG Gallery, New York, in 1961 Ono showed more than fifteen that were completed by the artist, by visitors or by the environment; at Sogetsu Art Center, Tokyo, in May 1962 she showed only the instructions, handwritten in Japanese by Toshi Ichiyanagi.", "description_zh": "以指令形式存在的绘画。1961 年在纽约 AG 画廊，小野洋子展出了十五件以上由艺术家、观众或环境来完成的作品；1962 年 5 月在东京草月会馆，她只展出由一柳慧用日文手写的指令。", "idea_en": "Replace the painting with the instruction, and let the viewer finish it with their feet, hands or mind.", "idea_zh": "用指令取代画本身，让观众用脚、用手或在脑中把它完成。", "protocol": "Each work is a short instruction; in Painting to Be Stepped On, for example, a scrap of canvas lies on the floor and becomes complete as footprints accumulate. Ono had the Sogetsu instructions written in another person's hand so the work would not depend on her own.", "protocol_zh": "每件作品都是一条简短指令；例如在《被踩踏的绘画》中，一块画布放在地上，随着脚印累积而完成。草月会馆的指令由别人代写，以免作品依赖她本人的笔迹。", "collective": "Visitors walked on, added to or imagined the paintings; Ono communicated most of the AG Gallery instructions by word of mouth. The 1962 Tokyo show made the instruction alone the exhibited work, a step toward conceptual art.", "collective_zh": "观众在画上行走、添加，或在脑中想象它们；AG 画廊的大部分指令由小野口头传达。1962 年东京的展览只展出指令本身，是走向观念艺术的一步。", "keywords": ["AG Gallery", "Sogetsu Art Center", "Toshi Ichiyanagi", "Painting to Be Stepped On", "instruction"], "paper": {"url": "https://www.printedmatter.org/catalog/18180", "title": "Instructions for Paintings: May 24, 1962", "venue": "Galeria 56, Budapest (1993)"}, "source_url": "https://www.tate.org.uk/whats-on/tate-modern/yoko-ono/exhibition-guide", "video": {}, "images": [], "also": []}, {"id": "allan-kaprow--yard", "creator_ids": ["allan-kaprow"], "title": "Yard", "year": 1961, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["participation", "instruction"], "substrate": "body", "kind": "artwork", "description": "An environment of hundreds of used car tyres heaped in the sculpture garden of the Martha Jackson Gallery, New York, for visitors to walk on, climb and throw around; it has since been remade many times.", "description_zh": "在纽约玛莎·杰克逊画廊的雕塑花园里堆满数百个旧轮胎，观众可以在上面行走、攀爬、把轮胎扔来扔去；此后被多次重做。", "idea_en": "An environment is a score: the materials and the permission to move them are the work.", "idea_zh": "环境就是乐谱：材料和“可以搬动它们”的许可就是作品。", "protocol": "Fill a yard with tyres and let visitors walk on, climb, rearrange and interact with them. Kaprow treated Yard as a score to be re-realised in each new space, adapted to the site.", "protocol_zh": "用轮胎填满一个院子，让观众在上面走、爬、重新摆放、随意互动。卡普罗把《院子》当作一份乐谱，在每个新空间里根据场地重新实现。", "collective": "Visitors rearranged the tyres continuously, so the heap never held one form. Later reinventions, for example at The Hepworth Wakefield's The Calder (2014) and at MACRO in Rome (2024), were staged by other teams and invited artists, dancers and musicians to intervene.", "collective_zh": "观众不断搬动轮胎，轮胎堆从来没有固定的形态。后来的“再发明”由其他团队完成，比如赫普沃斯韦克菲尔德美术馆的 The Calder（2014）和罗马 MACRO（2024），还邀请艺术家、舞者和音乐人介入。", "keywords": ["environment", "tyres", "Martha Jackson Gallery", "reinvention"], "images": ["https://hepworth-wakefield-live.s3.amazonaws.com/wp-content/uploads/2017/08/71586-0008-1024x683.jpg", "https://www.moussemagazine.it/wp-content/uploads/2024/09/Allan-Kaprow_Yard_Ph-Agnese-Bedini-DSL-Studio-IMG_9411-768x512.jpg"], "source_url": "https://hepworthwakefield.org/whats-on/allan-kaprow-yard-19612014/", "video": {}, "paper": {}}, {"id": "la-monte-young--compositions-1960", "creator_ids": ["la-monte-young"], "title": "Compositions 1960", "year": 1960, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "chance"], "substrate": "body", "kind": "series", "description": "A series of word scores written in 1960, such as #7 (two notes held for a long time), #10 (draw a straight line and follow it) and #5 (release butterflies in the performance area).", "description_zh": "1960 年写成的一系列文字乐谱，例如第 7 号（长时间保持两个音）、第 10 号（画一条直线并沿着它走）、第 5 号（在演出区域放飞蝴蝶）。", "idea_en": "One sentence can hand a whole performance to whoever reads it.", "idea_zh": "一句话就能把整场演出交给读到它的人。", "protocol": "Each composition is a single instruction on a card, for example #7: B and F sharp, \"to be held for a long time\", and #10 (to Bob Morris): \"Draw a straight line and follow it.\" Any performer may realize them.", "protocol_zh": "每首作品都是卡片上的一句指令，例如第 7 号：B 与升 F，“保持很长时间”；第 10 号（献给鲍勃·莫里斯）：“画一条直线并沿着它走。”任何表演者都可以实现它们。", "collective": "Nam June Paik realized #10 at the 1962 Fluxus festival in Wiesbaden by dragging his ink-soaked head along a strip of paper (later titled Zen for Head); #7 has been realized in versions lasting a minute or two, as by the ensemble EEMT, and in sustained performances lasting hours.", "collective_zh": "1962 年威斯巴登激浪派艺术节上，白南准把头浸上墨汁，沿着一条长纸拖行来实现第 10 号（后称《头的禅》）；第 7 号既有 EEMT 乐团那样一两分钟的版本，也有持续数小时的长音演出。", "keywords": ["word score", "Fluxus", "Nam June Paik", "Zen for Head", "sustained tones"], "video": {"url": "https://www.youtube.com/watch?v=tJu4W45DyNo", "platform": "youtube", "id": "tJu4W45DyNo", "thumbnail": "https://i.ytimg.com/vi/tJu4W45DyNo/hqdefault.jpg", "embeddable": true}, "images": ["https://www.moma.org/media/W1siZiIsIjE5MDAwNSJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=97b1609717ca406f", "https://www.moma.org/media/W1siZiIsIjIxNTgzMyJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=c3e958423752d310"], "source_url": "https://www.moma.org/collection/works/127631", "paper": {}, "also": []}, {"id": "george-brecht--motor-vehicle-sundown", "creator_ids": ["george-brecht"], "title": "Motor Vehicle Sundown (Event)", "year": 1960, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "chance", "participation"], "substrate": "body", "kind": "score", "description": "An event for any number of cars, dedicated to John Cage: at sundown, drivers perform shuffled instruction cards with headlights, horns, wipers, doors and engines.", "description_zh": "一件写给任意数量汽车的事件作品，献给约翰·凯奇：日落时分，司机们按洗过的指令卡操作车灯、喇叭、雨刷、车门和引擎。", "idea_en": "Turn a parking lot into an orchestra by dealing every driver a shuffled hand of actions.", "idea_zh": "给每位司机发一手洗乱的动作卡，停车场就成了乐团。", "protocol": "Any number of motor vehicles are arranged outdoors; the instruction cards are shuffled together and dealt to the drivers, who begin at an agreed time, preferably at sundown, and carry out their cards in sequence at a steady count.", "protocol_zh": "任意数量的机动车停放在户外；所有指令卡洗在一起分发给司机，司机们在约定时间（最好是日落时）开始，按稳定的节拍依次执行手中的卡片。", "collective": "Performed by Fluxus artists, by ensembles such as Vienna's die reihe and by musicians in the 2021 program Meaningless Work, Get to Work; the pattern of lights and horns depends on the cars available and on how the cards fall.", "collective_zh": "激浪派艺术家、维也纳的 die reihe 乐团以及 2021 年“Meaningless Work, Get to Work”演出中的音乐人都演出过它；灯光与喇叭的组合取决于现场有哪些车，以及卡片如何分配。", "keywords": ["cars", "event score", "John Cage", "sundown"], "video": {"url": "https://www.youtube.com/watch?v=LDNU0nqw-Ow", "platform": "youtube", "id": "LDNU0nqw-Ow", "thumbnail": "https://i.ytimg.com/vi/LDNU0nqw-Ow/hqdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/posters/MotorVehicleSundownEvent_Various.jpg"], "source_url": "https://www.getty.edu/publications/scores/05/", "paper": {}, "also": [], "collections": ["the-scores-project"]}, {"id": "benjamin-patterson--paper-piece", "creator_ids": ["benjamin-patterson"], "title": "Paper Piece", "year": 1960, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "A score written in 1960 for performers with sheets and bags of paper, who make sounds by shaking, tearing, crumpling and popping them.", "description_zh": "一份 1960 年的乐谱，写给手持纸张和纸袋的表演者，他们通过抖动、撕扯、揉皱和拍爆纸袋来发声。", "idea_en": "Precise rules for a cheap, universal material let almost any group perform.", "idea_zh": "为一种廉价而随处可得的材料写下精确规则，几乎任何团体都能演出。", "protocol": "The score fixes the number of sheets and paper bags per performer, with \"quality, size and shape varied\", and names each technique (shake, break, tear, crumple, rub, pop) to be used in sequence.", "protocol_zh": "乐谱规定每位表演者使用的纸张和纸袋数量，要求“质地、尺寸与形状各异”，并逐一命名依次使用的技法（抖、折断、撕、揉、擦、拍爆）。", "collective": "Fluxus artists performed it in Amsterdam in 1963 and in Nice in 1964; at some performances paper was dumped on the audience's heads, and ensembles such as Musikfabrik and EEMT still perform it, each with different paper and different noise.", "collective_zh": "激浪派艺术家曾于 1963 年在阿姆斯特丹、1964 年在尼斯演出；有的演出把纸倒在观众头上，Musikfabrik、EEMT 等乐团至今仍在演出，每次用的纸不同，发出的声响也不同。", "keywords": ["Fluxus", "paper", "noise", "Wiesbaden"], "video": {"url": "https://www.youtube.com/watch?v=6lgRJe7R8Hs", "platform": "youtube", "id": "6lgRJe7R8Hs", "thumbnail": "https://i.ytimg.com/vi/6lgRJe7R8Hs/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/posters/FXM0570_Paper_Piece_by_Ben_Patterson_1964.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/AR6153517_th.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/r2012418_890164_b39_f33_017_th.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/04/", "venue": "The Scores Project (Getty Research Institute, 2025)", "title": "Benjamin Patterson: Paper Piece (1960)"}, "source_url": "https://www.getty.edu/publications/scores/04/", "also": [], "collections": ["the-scores-project"]}, {"id": "allan-kaprow--18-happenings-in-6-parts", "creator_ids": ["allan-kaprow"], "title": "18 Happenings in 6 Parts", "year": 1959, "field": "score", "sub": "public-instructions", "also": ["social"], "mechanisms": ["instruction", "participation", "constraint"], "substrate": "body", "kind": "artwork", "description": "An evening at the Reuben Gallery in New York, October 1959, in which three rooms of plastic-sheet walls hosted simultaneous actions, and the audience moved between rooms on printed instructions.", "description_zh": "1959 年 10 月在纽约鲁本画廊的一场演出：三个用塑料布隔出的房间里同时进行各种动作，观众按照印好的指令卡在房间之间移动。", "idea_en": "Hand the audience a timetable and they become part of the choreography.", "idea_zh": "把一张时间表交给观众，他们就成了编舞的一部分。", "protocol": "Guests received a programme and three stapled cards: \"The performance is divided into six parts... Each part contains three happenings which occur at once. The beginning and end of each will be signaled by a bell.\" The cards also told each guest when to change seats and which room to move to.", "protocol_zh": "观众拿到一份节目单和三张订在一起的卡片：“演出分为六个部分……每部分包含三个同时发生的偶发事件，开始和结束以铃声为号。”卡片还规定每位观众何时换座、换到哪个房间。", "collective": "Invited guests followed the cards, so no one saw all eighteen happenings and each person's version of the work differed; performers including Kaprow's friends carried out the scripted actions. The piece gave the 'happening' its name.", "collective_zh": "受邀观众照卡片行动，因此没有人看全十八个事件，每个人看到的作品都不一样；包括卡普罗朋友在内的表演者执行写好的动作。“偶发艺术”一词由此得名。", "keywords": ["happening", "Reuben Gallery", "instruction cards", "audience"], "images": ["https://www.moma.org/media/W1siZiIsIjMwMjA4MCJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDIwMDB4MjAwMFx1MDAzZSJdXQ.jpg?sha=2fb4df5afdc0e236"], "source_url": "https://www.moma.org/collection/works/associatedworks/173008", "video": {}, "paper": {}}, {"id": "george-brecht--drip-music", "creator_ids": ["george-brecht"], "title": "Drip Music (Drip Event)", "year": 1959, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "participation"], "substrate": "body", "kind": "score", "description": "An event score, first drafted in 1959 and printed in Water Yam, in which water drips into an empty vessel.", "description_zh": "一份事件乐谱，1959 年起草，后收入《水山药》：让水滴落进一个空容器。", "idea_en": "An ordinary sound, framed by an instruction, becomes a piece anyone can stage.", "idea_zh": "一个普通的声音，被一句指令框定后，就成了任何人都能上演的作品。", "protocol": "The card reads: \"For single or multiple performance. A source of dripping water and an empty vessel are arranged so that the water falls into the vessel.\" A second version reads simply: \"Dripping.\"", "protocol_zh": "卡片上写着：“可单人或多人演出。安排一个滴水的水源和一个空容器，使水落入容器中。”第二个版本只有一个词：“滴水。”", "collective": "A convention grew up in which a performer climbs a ladder and pours water from a pitcher into a bowl, as Dick Higgins did at The Kitchen in 1979; students in Kobe in 2015 and countless others have staged their own versions, and a video search for the title returns hundreds of them.", "collective_zh": "演出逐渐形成一种惯例：表演者爬上梯子，从水罐往下面的碗里倒水，迪克·希金斯 1979 年在 The Kitchen 就是这样演的；2015 年神户的学生以及无数其他人都上演过自己的版本，按标题搜索视频能找到数以百计的演出。", "keywords": ["event score", "Fluxus", "water", "Dick Higgins"], "video": {"url": "https://www.youtube.com/watch?v=oGIlPBgUg9U", "platform": "youtube", "id": "oGIlPBgUg9U", "thumbnail": "https://i.ytimg.com/vi/oGIlPBgUg9U/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/posters/HigginsPerformance1979.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/posters/GeorgeBrechtDripMusic-by-MidoriKubota-2015nov2.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/r32814_890164_127_003_th.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/06/", "venue": "The Scores Project (Getty Research Institute, 2025)", "title": "George Brecht: Drip Music (Drip Event) (1959–62)"}, "source_url": "https://www.getty.edu/publications/scores/06/", "also": [], "collections": ["the-scores-project"]}, {"id": "john-cage--concert-for-piano-and-orchestra", "creator_ids": ["john-cage"], "title": "Concert for Piano and Orchestra", "year": 1958, "field": "score", "sub": "constraints", "mechanisms": ["chance", "instruction", "constraint"], "substrate": "body", "kind": "score", "description": "An indeterminate concert piece in which the pianist and each orchestral player choose which pages of their parts to play, and the conductor's arms act as a clock rather than a beat.", "description_zh": "一首不确定性的协奏作品：钢琴家和每位乐手自行选择演奏各自分谱中的哪些页，指挥的双臂像时钟一样计时，而不是打拍子。", "idea_en": "Give every player a separate rulebook and let the ensemble's overlap be unplanned.", "idea_zh": "给每位演奏者一本独立的规则手册，让整体的叠合不经计划。", "protocol": "Parts are independent: the piano solo is a book of graphs in many different notations, any number of the orchestral parts may be used, and performers may play any amount of their material; the conductor moves the arms like clock hands to vary the passage of time.", "protocol_zh": "各声部彼此独立：钢琴独奏是一册使用多种不同记谱法的图谱，管弦乐分谱可以任意取用，演奏者可以演奏自己材料中的任意部分；指挥像时钟指针一样移动双臂，改变时间流逝的速度。", "collective": "At the premiere at New York's Town Hall on 15 May 1958 the audience whistled and jeered; David Tudor prepared his own fixed realization of the solo, and every ensemble since has had to make its own decisions, as the Getty Research Institute's Scores Project documents with Tudor's worksheets.", "collective_zh": "1958 年 5 月 15 日在纽约市政厅首演时，观众吹口哨、起哄；大卫·都铎为独奏部分制作了自己的固定版本，此后每个乐团都必须自己做出决定，盖蒂研究所的《乐谱计划》用都铎的工作稿记录了这一过程。", "keywords": ["indeterminacy", "David Tudor", "Town Hall", "graphic notation"], "video": {"url": "https://www.youtube.com/watch?v=KgmGGbiYnDY", "platform": "youtube", "id": "KgmGGbiYnDY", "thumbnail": "https://i.ytimg.com/vi/KgmGGbiYnDY/maxresdefault.jpg", "embeddable": true}, "images": ["https://www.getty.edu/publications/scores/_assets/images/figures/posters/cage-flipbook.jpg", "https://www.getty.edu/publications/scores/_assets/images/figures/thumbnails/gri_980039_b176_f01_001_mm_th.jpg"], "paper": {"url": "https://www.getty.edu/publications/scores/02/", "venue": "The Scores Project (Getty Research Institute, 2025)", "title": "John Cage: Concert for Piano and Orchestra (1958)"}, "source_url": "https://www.getty.edu/publications/scores/02/", "also": [], "collections": ["the-scores-project"]}, {"id": "guy-debord--derive", "creator_ids": ["guy-debord"], "title": "Théorie de la dérive (Theory of the Dérive)", "year": 1956, "field": "social", "sub": "collective-action", "also": ["score", "theory"], "mechanisms": ["instruction", "chance", "constraint"], "substrate": "body", "kind": "score", "description": "Debord's text sets out the dérive: small groups drifting rapidly through a city, letting its atmospheres, rather than errands, decide their path, and comparing notes afterwards.", "description_zh": "德波的文章阐述了“漂移”：小组在城市中快速穿行，让城市的氛围而不是日常事务决定路线，事后再比对各自的观察。", "idea_en": "A walking protocol for groups that turns a city into a field of experiment.", "idea_zh": "一套给群体的行走协议，把城市变成实验场。", "protocol": "Drift in several small groups of two or three people who share the same awareness; groups change composition between dérives; beyond about ten people the dérive splits; the average duration is one day, between two periods of sleep; impressions are cross-checked between groups.", "protocol_zh": "分成几个两三人的小组漂移，组员具有相同的意识水平；每次漂移之间更换组员；超过十人左右漂移就会分裂；平均时长为一天，即两段睡眠之间；各组之间交叉核对印象。", "collective": "Letterists and Situationists practised dérives in Paris in the 1950s and mapped them in psychogeographic guides such as The Naked City (1957); the text, published in Les Lèvres nues no. 9 (1956) and reprinted in Internationale situationniste no. 2 (1958), is still used by artists and walking groups.", "collective_zh": "1950 年代，字母主义者和情境主义者在巴黎实践漂移，并在《裸城》（1957）等心理地理指南中绘出路线；这篇文章发表于《裸唇》第 9 期（1956），再刊于《情境主义国际》第 2 期（1958），至今仍被艺术家和行走团体使用。", "keywords": ["Situationist International", "psychogeography", "dérive", "Paris", "walking"], "images": ["https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Internationale_situationniste_n%C2%BA1.jpg/960px-Internationale_situationniste_n%C2%BA1.jpg"], "paper": {"url": "https://libcom.org/article/theory-derive-guy-debord", "title": "Theory of the Dérive", "venue": "Les Lèvres nues no. 9 (1956); Internationale situationniste no. 2 (1958)"}, "source_url": "https://en.wikipedia.org/wiki/D%C3%A9rive", "video": {}}, {"id": "john-cage--4-33", "creator_ids": ["john-cage"], "title": "4′33″", "year": 1952, "field": "score", "sub": "event-scores", "mechanisms": ["instruction", "chance", "participation"], "substrate": "body", "kind": "score", "description": "A score in three movements, each marked tacet, for any instrument or combination of instruments; the performers make no intended sound for four minutes and thirty-three seconds.", "description_zh": "一份分为三个乐章、每个乐章都标注“tacet”（休止）的乐谱，适用于任何乐器或乐器组合；演奏者在四分三十三秒内不发出任何有意的声音。", "idea_en": "Frame a stretch of time and let whatever the room and the audience produce become the music.", "idea_zh": "框定一段时间，让房间和观众自己发出的声音成为音乐。", "protocol": "The score lets any performer or ensemble play; each of the three movements is marked \"tacet\" and the performer signals only its beginning and end. Nothing else is prescribed; the content is left to ambient sound.", "protocol_zh": "任何演奏者或乐团都可以演出；三个乐章都标注“tacet”，演奏者只示意每个乐章的开始与结束。其余一概不作规定，内容交给环境声音。", "collective": "David Tudor gave the first performance at Woodstock, New York, on 29 August 1952; since then pianists, orchestras such as the BBC Symphony Orchestra (Barbican, 2004) and amateur groups have performed it, and each performance consists of the coughs, rain, traffic and restlessness of that particular audience and room.", "collective_zh": "1952 年 8 月 29 日，大卫·都铎在纽约州伍德斯托克首演此作；此后钢琴家、BBC 交响乐团（2004 年巴比肯中心）等乐团以及业余团体不断演出，每一次的内容都是当场观众和房间里的咳嗽、雨声、车流与骚动。", "keywords": ["silence", "tacet", "David Tudor", "indeterminacy", "Woodstock"], "video": {"url": "https://www.youtube.com/watch?v=yoAbXwr3qkg", "platform": "youtube", "id": "yoAbXwr3qkg", "thumbnail": "https://i.ytimg.com/vi/yoAbXwr3qkg/hqdefault.jpg", "embeddable": true}, "images": ["https://upload.wikimedia.org/wikipedia/commons/8/89/4%2733%27_%28John_Cage%29_Original_Cover.webp"], "source_url": "https://en.wikipedia.org/wiki/4%E2%80%B233%E2%80%B3", "paper": {}, "also": []}, {"id": "john-cage--imaginary-landscape-no-4", "creator_ids": ["john-cage"], "title": "Imaginary Landscape No. 4 (March No. 2)", "year": 1951, "field": "score", "sub": "constraints", "mechanisms": ["chance", "instruction"], "substrate": "body", "kind": "score", "description": "A piece for twelve radios and twenty-four performers plus a conductor: at each radio one player turns the tuning dial and the other the volume, following times and settings fixed by chance.", "description_zh": "一首为十二台收音机、二十四名演奏者和一名指挥而作的作品：每台收音机由一人调频、一人调音量，按照由偶然决定的时间和数值操作。", "idea_en": "Script the hands on the dials precisely and let the broadcasts of the day fill in the sound.", "idea_zh": "精确规定调节旋钮的双手，让当天的广播填满声音。", "protocol": "Cage used chance operations derived from the I Ching to fix, for each pair of players, the wavelengths, volume levels and durations; the score controls the actions but not what the stations are broadcasting.", "protocol_zh": "凯奇用源自《易经》的偶然操作，为每对演奏者确定频率、音量和时值；乐谱控制的是动作，而不是电台正在播出的内容。", "collective": "First performed at Columbia University's McMillin Theater on 2 May 1951 with Cage conducting; every later performance, from student ensembles to groups such as DIY Space for London, picks up different programmes, so the same score sounds different in each city and hour.", "collective_zh": "1951 年 5 月 2 日在哥伦比亚大学麦克米林剧场首演，由凯奇指挥；此后每一次演出，从学生乐团到伦敦 DIY Space 这样的团体，接收到的节目都不同，同一份乐谱在不同城市、不同时刻听起来都不一样。", "keywords": ["radio", "I Ching", "chance operations", "Columbia University"], "video": {"url": "https://www.youtube.com/watch?v=yV-kWU1Z5u8", "platform": "youtube", "id": "yV-kWU1Z5u8", "thumbnail": "https://i.ytimg.com/vi/yV-kWU1Z5u8/maxresdefault.jpg", "embeddable": true}, "source_url": "https://en.wikipedia.org/wiki/Imaginary_Landscape_No._4_(March_No._2)", "images": [], "paper": {}, "also": []}, {"id": "laszlo-moholy-nagy--telephone-pictures", "creator_ids": ["laszlo-moholy-nagy"], "title": "Telephone Pictures (EM 1, EM 2, EM 3)", "year": 1923, "field": "score", "sub": "execution", "mechanisms": ["instruction"], "substrate": "text", "kind": "series", "description": "Three porcelain-enamel paintings on steel with the same geometric composition at three sizes, produced by an enamel sign factory in Weimar from Moholy-Nagy's specifications. He later wrote that he placed the order by telephone.", "description_zh": "三件钢板珐琅画，同一几何构图、三种尺寸，由魏玛一家珐琅招牌厂按照莫霍利-纳吉给出的规格制作。他后来写道，这批作品是通过电话下单的。", "idea_en": "If a picture can be dictated, the artist's job is the specification, not the hand.", "idea_zh": "如果一幅画可以口述出来，艺术家的工作就是写规格，而不是动手。", "protocol": "Moholy-Nagy drew the composition on graph paper and used the factory's colour chart; he dictated the positions and colours to the factory supervisor, who held the same chart and paper. The factory, not the artist, made the three versions (large, medium, small).", "protocol_zh": "莫霍利-纳吉把构图画在坐标纸上，并使用工厂的色卡；他把位置和颜色报给手里有同样色卡和坐标纸的工厂主管。三个版本（大、中、小）由工厂而不是艺术家制作。", "collective": "Enamel workers at the factory fabricated the paintings from the specification. The telephone story has been questioned (his first wife Lucia Moholy recalled that he visited the factory in person), but the works were shown in 1924 at Der Sturm in Berlin as proof that a picture could be made from transmitted instructions.", "collective_zh": "工厂的珐琅工人按照规格制作了这些画。“电话下单”的说法有争议（他的第一任妻子露西亚·莫霍利回忆说他亲自去过工厂），但这些作品于 1924 年在柏林 Der Sturm 画廊展出，证明一幅画可以凭传递的指令制作出来。", "keywords": ["Bauhaus", "enamel", "telephone", "graph paper", "Der Sturm", "EM 1"], "images": ["https://www.moma.org/media/W1siZiIsIjQwNDI4NCJdLFsicCIsImNvbnZlcnQiLCItcXVhbGl0eSA5MCAtcmVzaXplIDUxMng1MTJcdTAwM2UiXV0.jpg?sha=ebb5d75b7d58fa96"], "source_url": "https://www.moma.org/collection/works/147626", "video": {}, "paper": {}, "also": []}, {"id": "marcel-duchamp--unhappy-readymade", "creator_ids": ["marcel-duchamp"], "title": "Unhappy Readymade", "year": 1919, "field": "score", "sub": "execution", "also": ["social"], "mechanisms": ["instruction", "chance", "time"], "substrate": "post", "kind": "artwork", "description": "A wedding present sent by letter from Buenos Aires: Duchamp told his sister Suzanne and her husband Jean Crotti in Paris to hang a geometry textbook on their balcony. Wind, rain and sun then worked on the book; only Suzanne's photograph and her painting of it survive.", "description_zh": "一份从布宜诺斯艾利斯寄出的结婚礼物：杜尚写信让在巴黎的妹妹苏珊娜和她的丈夫让·克罗蒂把一本几何教科书挂在阳台上。之后风、雨和阳光替他完成作品；留下来的只有苏珊娜拍的照片和她据此画的一幅画。", "idea_en": "Mail the rule, let others build it and let the weather finish it.", "idea_zh": "把规则寄出去，让别人搭建，让天气完成。", "protocol": "By letter, Duchamp instructed the couple to hang a geometry book outside by strings, 'so that its pages would be torn apart and its text would be erased by the elements' (Philadelphia Museum of Art). He did not touch the object; the recipients built it and the weather 'chose its own problems'.", "protocol_zh": "杜尚写信让这对夫妇用绳子把一本几何书挂在户外，“让书页被撕开、文字被风雨抹去”（费城艺术博物馆）。他本人没有碰这件物品；由收件人搭建，由天气“自己挑选题目”。", "collective": "Suzanne Duchamp and Jean Crotti carried out the instruction on their Paris balcony; Suzanne photographed the weathered book and painted Le Readymade malheureux de Marcel (1920). The only realisation that exists is theirs, known through her photograph.", "collective_zh": "苏珊娜·杜尚和让·克罗蒂在巴黎的阳台上执行了这一指令；苏珊娜拍下了被风雨侵蚀的书，并画了《马塞尔的不快乐的现成品》（1920）。唯一存在的实现是他们的版本，通过她的照片为人所知。", "keywords": ["readymade", "letter", "geometry book", "Suzanne Duchamp", "Jean Crotti", "weather"], "images": ["https://iiif.micr.io/drOqS/full/1200,/0/default.jpg"], "source_url": "https://philamuseum.org/collection/object/138592", "video": {}, "paper": {}}]};
